/**
 * End-to-end `appDataStore.write()` contracts on the FILE backend: the
 * staleness guard, and the sub-minute precision of `timeEntries[].minutes`.
 *
 * Both live here (rather than in a second .mjs file) because they exercise the
 * one real `tmp/app-data.json` path — tests in separate files run in parallel
 * workers and would clobber each other's workspace.
 *
 * Cardinal rule 1: `db/store.js` has two backends and any persisted change must
 * touch both. Production is Postgres, so this file cannot prove the Postgres
 * path — that one is validated separately with a rolled-back transaction
 * against production data (HANDOFF §4). What it DOES pin is the contract both
 * branches implement: a save carrying an out-of-date fingerprint is refused and
 * writes NOTHING.
 *
 * These tests share the real file-backend path (`tmp/app-data.json`), so any
 * pre-existing local workspace is snapshotted and restored around the run.
 */

const projectRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const localDataPath = path.join(projectRoot, 'tmp', 'app-data.json')
// `splitTimeEntry` writes an activity-log row, which on the file backend lives
// in this second file — snapshot/restore it for the same reason.
const localAuthPath = path.join(projectRoot, 'tmp', 'auth-state.json')

let savedContents = null
let savedAuthContents = null
let savedDatabaseUrl

function workspace(overrides = {}) {
  return {
    clients: [{ id: 'c1', name: 'Acme' }],
    employees: [{ id: 'emp-1', name: 'Lisa', role: 'bookkeeper' }],
    timeEntries: [{ id: 't1', minutes: 30, clientId: 'c1' }],
    checklists: [],
    checklistTemplates: [],
    recycledChecklists: [],
    plans: [],
    contacts: [],
    reimbursements: [],
    recurringReimbursements: [],
    timesheetLocks: [],
    weeklySubmissions: [],
    ...overrides,
  }
}

/**
 * Empty the two endpoint-managed invoice-confidence tables.
 *
 * They live in `tmp/auth-state.json`, which the outer `beforeEach` never
 * touches (it resets app-data only) — so without this every test in a run would
 * inherit the previous one's events and ratings, and the counts below would be
 * whatever order vitest happened to pick.
 */
async function clearInvoiceIntelligence() {
  const authState = existsSync(localAuthPath)
    ? JSON.parse(await readFile(localAuthPath, 'utf8'))
    : {}
  authState.invoiceReviewEvents = []
  authState.invoiceAiReviews = []
  await writeFile(localAuthPath, JSON.stringify(authState, null, 2))
}

beforeAll(async () => {
  // DATABASE_URL must be absent or the store would construct a Pool and take
  // the Postgres branch.
  savedDatabaseUrl = process.env.DATABASE_URL
  delete process.env.DATABASE_URL
  if (existsSync(localDataPath)) {
    savedContents = await readFile(localDataPath, 'utf8')
  }
  if (existsSync(localAuthPath)) {
    savedAuthContents = await readFile(localAuthPath, 'utf8')
  }
})

afterAll(async () => {
  if (savedDatabaseUrl !== undefined) {
    process.env.DATABASE_URL = savedDatabaseUrl
  }
  if (savedContents !== null) {
    await writeFile(localDataPath, savedContents)
  } else if (existsSync(localDataPath)) {
    await rm(localDataPath)
  }
  if (savedAuthContents !== null) {
    await writeFile(localAuthPath, savedAuthContents)
  } else if (existsSync(localAuthPath)) {
    await rm(localAuthPath)
  }
})

let store

beforeEach(async () => {
  store = new AppDataStore()
  expect(store.mode).toBe('file')
  // Boot it the way server.js does. Not optional: `initialize()` is what
  // creates the `tmp/` directory (the mkdir in store.js), and without it
  // write() throws ENOENT on any checkout that doesn't already have one.
  // Skipping this passed locally and failed the first CI run, because a clean
  // clone has no tmp/ — a test that depended on ambient machine state.
  await store.initialize()
  // Start from an empty workspace file. The baseline write below REPLACES the
  // whole workspace, and a bulk save now refuses to drop a stored client that
  // has time entries or invoices - which the previous test's leftovers (clients
  // with time, written by the test before this one) would otherwise trip.
  await rm(localDataPath, { force: true })
  // Baseline, unguarded (server-authoritative writes pass no expectedVersion).
  await store.write(workspace())
})

describe('bulk save staleness guard (file backend)', () => {
  it('accepts a save carrying the current fingerprint', async () => {
    const version = await store.computeWorkspaceVersion()
    await expect(
      store.write(workspace({ clients: [{ id: 'c1', name: 'Acme Renamed' }] }), {
        expectedVersion: version,
      }),
    ).resolves.toBeUndefined()

    const persisted = JSON.parse(await readFile(localDataPath, 'utf8'))
    expect(persisted.clients[0].name).toBe('Acme Renamed')
  })

  it('REFUSES a save carrying a fingerprint from before another change', async () => {
    // A tab loads and captures the fingerprint...
    const staleVersion = await store.computeWorkspaceVersion()
    // ...then something else lands (a second owner, an import, a timer save).
    await store.write(
      workspace({
        timeEntries: [
          { id: 't1', minutes: 30, clientId: 'c1' },
          { id: 't2', minutes: 45, clientId: 'c1' },
        ],
      }),
    )

    // The stale tab now autosaves its old snapshot — which is missing t2.
    await expect(
      store.write(workspace(), { expectedVersion: staleVersion }),
    ).rejects.toBeInstanceOf(StaleWorkspaceError)
  })

  it('writes NOTHING when it refuses — the wipe never happens', async () => {
    const staleVersion = await store.computeWorkspaceVersion()
    const imported = workspace({
      timeEntries: Array.from({ length: 50 }, (_, index) => ({
        id: `imported-${index}`,
        minutes: 60,
        clientId: 'c1',
      })),
    })
    await store.write(imported)

    // The stale snapshot carries only the single original entry. Before this
    // guard, this exact call is what erased the historical import.
    await expect(
      store.write(workspace(), { expectedVersion: staleVersion }),
    ).rejects.toThrow('stale_workspace')

    const persisted = JSON.parse(await readFile(localDataPath, 'utf8'))
    expect(persisted.timeEntries).toHaveLength(50)
  })

  it('reports the server-side current version on the refusal', async () => {
    const staleVersion = await store.computeWorkspaceVersion()
    await store.write(workspace({ clients: [{ id: 'c1', name: 'Moved On' }] }))
    const currentVersion = await store.computeWorkspaceVersion()

    await expect(
      store.write(workspace(), { expectedVersion: staleVersion }),
    ).rejects.toMatchObject({ currentVersion })
  })

  it('lets an unguarded write through — internal read-modify-write helpers are not gated', async () => {
    await store.write(workspace({ clients: [{ id: 'c1', name: 'Changed' }] }))

    // No expectedVersion => no guard at all. The internal read-modify-write
    // helpers (createStandardTemplate, copyTemplateToClient, …) write this way
    // and accept last-writer-wins. `read()`'s materializer write-back used to
    // as well — it now passes the fingerprint it read under (see the guarded
    // write-back suites at the bottom of this file).
    await expect(
      store.write(workspace({ clients: [{ id: 'c1', name: 'Materialized' }] })),
    ).resolves.toBeUndefined()

    const persisted = JSON.parse(await readFile(localDataPath, 'utf8'))
    expect(persisted.clients[0].name).toBe('Materialized')
  })

  it('is content-addressed: identical data hashes identically', async () => {
    // Worth pinning because it looks surprising — reverting the workspace
    // reverts the fingerprint. It is also harmless: a "stale" save whose
    // payload matches what is already stored writes the same bytes anyway.
    const original = await store.computeWorkspaceVersion()
    await store.write(workspace({ clients: [{ id: 'c1', name: 'Detour' }] }))
    expect(await store.computeWorkspaceVersion()).not.toBe(original)

    await store.write(workspace())
    expect(await store.computeWorkspaceVersion()).toBe(original)
  })

  it('moves the fingerprint after every accepted save', async () => {
    const first = await store.computeWorkspaceVersion()
    await store.write(workspace({ clients: [{ id: 'c1', name: 'Second' }] }), {
      expectedVersion: first,
    })
    const second = await store.computeWorkspaceVersion()
    expect(second).not.toBe(first)

    // Re-using the consumed fingerprint is refused — this is what stops a tab
    // from saving twice off one token.
    await expect(
      store.write(workspace(), { expectedVersion: first }),
    ).rejects.toBeInstanceOf(StaleWorkspaceError)
  })
})

/**
 * Sub-minute precision survives a real bulk save. `sanitizeAppData` runs at the
 * top of `write()` for BOTH backends, and the owner-tab autosave re-inserts
 * every time entry through it — so an integer coercion there rewrote the whole
 * table's durations on each save (confirmed in production: 501 of 673
 * session-backed rows stored round(session-sum) instead of the exact value).
 */
describe('time entry minutes precision (file backend)', () => {
  const entriesFrom = (persisted) =>
    Object.fromEntries(persisted.timeEntries.map((entry) => [entry.id, entry.minutes]))

  it('round-trips fractional minutes through a bulk save unchanged', async () => {
    await store.write(
      workspace({
        timeEntries: [
          // 14m 33s — the shape normalizeWorkSessions produces from `sessions`.
          { id: 't-frac', minutes: 14.55, clientId: 'c1' },
          // 45s. Must NOT become 1 minute.
          { id: 't-sub', minutes: 0.75, clientId: 'c1' },
          { id: 't-whole', minutes: 30, clientId: 'c1' },
        ],
      }),
    )

    const persisted = JSON.parse(await readFile(localDataPath, 'utf8'))
    expect(entriesFrom(persisted)).toEqual({
      't-frac': 14.55,
      't-sub': 0.75,
      't-whole': 30,
    })
  })

  it('survives repeated autosaves without drifting toward whole minutes', async () => {
    const exact = 872 / 60 // 14m 32s
    let payload = workspace({ timeEntries: [{ id: 't-1', minutes: exact, clientId: 'c1' }] })
    for (let i = 0; i < 5; i += 1) {
      await store.write(payload)
      payload = workspace({ timeEntries: JSON.parse(await readFile(localDataPath, 'utf8')).timeEntries })
    }

    const persisted = JSON.parse(await readFile(localDataPath, 'utf8'))
    expect(persisted.timeEntries[0].minutes).toBe(exact)
  })

  it('still floors bad values at 1 minute and clamps the ceiling', async () => {
    await store.write(
      workspace({
        timeEntries: [
          { id: 't-zero', minutes: 0, clientId: 'c1' },
          { id: 't-neg', minutes: -30, clientId: 'c1' },
          { id: 't-nan', minutes: 'not-a-number', clientId: 'c1' },
          { id: 't-huge', minutes: 5_000_000, clientId: 'c1' },
        ],
      }),
    )

    const persisted = JSON.parse(await readFile(localDataPath, 'utf8'))
    expect(entriesFrom(persisted)).toEqual({
      't-zero': 1,
      't-neg': 1,
      't-nan': 1,
      't-huge': 100000,
    })
  })
})

/**
 * `splitTimeEntry` — replacing an unsplit group holding entry with one billable
 * slice per client, atomically.
 *
 * What this pins (all real defects of the old client-side create-loop):
 *   - each slice keeps the block's `sessions` VERBATIM, so a split no longer
 *     blanks the clock-in/out on the Raw report;
 *   - the holding entry is gone, never left behind double-counting;
 *   - the split is written to the activity log;
 *   - a refused split (already split / gone / empty allocation) writes NOTHING;
 *   - the allocation mode is persisted on every slice.
 */
describe('splitTimeEntry (file backend)', () => {
  const SESSIONS = [
    { startAt: '2026-07-01T14:00:00.000Z', endAt: '2026-07-01T14:30:00.000Z' },
    { startAt: '2026-07-01T15:00:00.000Z', endAt: '2026-07-01T15:18:30.000Z' },
  ]

  const holdingEntry = (overrides = {}) => ({
    id: 'hold-1',
    employeeId: 'emp-1',
    clientId: '',
    isAdministrative: false,
    date: '2026-07-01',
    minutes: 48.5,
    category: 'General',
    description: 'Quarterly review call',
    billable: false,
    taskId: null,
    approvalStatus: 'approved',
    entryMethod: 'timer',
    startAt: SESSIONS[0].startAt,
    endAt: SESSIONS[1].endAt,
    sessions: SESSIONS,
    groupClientIds: ['c1', 'c2'],
    ...overrides,
  })

  const seedHolding = async (overrides = {}) => {
    await store.write(
      workspace({
        clients: [
          { id: 'c1', name: 'Acme' },
          { id: 'c2', name: 'Globex' },
        ],
        timeEntries: [holdingEntry(overrides)],
      }),
    )
  }

  const persisted = async () => JSON.parse(await readFile(localDataPath, 'utf8'))

  it('replaces the holding entry with one slice per client', async () => {
    await seedHolding()

    const result = await store.splitTimeEntry(
      'hold-1',
      [
        { clientId: 'c1', minutes: 24.25 },
        { clientId: 'c2', minutes: 24.25 },
      ],
      'owner-1',
      'grp-abc',
      'even',
    )

    expect(result.deletedId).toBe('hold-1')
    expect(result.created).toHaveLength(2)

    const data = await persisted()
    expect(data.timeEntries.find((entry) => entry.id === 'hold-1')).toBeUndefined()
    expect(data.timeEntries).toHaveLength(2)
    expect(data.timeEntries.map((entry) => entry.clientId).sort()).toEqual(['c1', 'c2'])
    // The block's minutes are fully accounted for, on the seconds grid.
    const totalSeconds = data.timeEntries.reduce(
      (sum, entry) => sum + Math.round(entry.minutes * 60),
      0,
    )
    expect(totalSeconds).toBe(Math.round(48.5 * 60))
  })

  it('copies the block sessions + envelope + description onto every slice', async () => {
    await seedHolding()

    const { created } = await store.splitTimeEntry(
      'hold-1',
      [
        { clientId: 'c1', minutes: 24.25 },
        { clientId: 'c2', minutes: 24.25 },
      ],
      'owner-1',
      'grp-abc',
      'even',
    )

    for (const slice of created) {
      // The whole point: a split no longer loses the original clock-in/out.
      expect(slice.sessions).toEqual(SESSIONS)
      expect(slice.startAt).toBe(SESSIONS[0].startAt)
      expect(slice.endAt).toBe(SESSIONS[1].endAt)
      expect(slice.description).toBe('Quarterly review call')
      expect(slice.date).toBe('2026-07-01')
      expect(slice.employeeId).toBe('emp-1')
      expect(slice.entryMethod).toBe('timer')
      expect(slice.billable).toBe(true)
      expect(slice.isAdministrative).toBe(false)
      expect(slice.groupId).toBe('grp-abc')
      expect(slice.groupClientIds).toEqual([])
      // Sessions are copied, not shared — mutating a slice can't corrupt a sibling.
      expect(slice.sessions).not.toBe(SESSIONS)
    }
  })

  it('queues every slice as pending — split allocations are typed time', async () => {
    await seedHolding()
    const { created } = await store.splitTimeEntry(
      'hold-1',
      [{ clientId: 'c1', minutes: 48.5 }],
      'owner-1',
      'grp-abc',
      'full',
    )
    // Mirrors createTimeEntry: `entryMethod === 'timer' && !groupId` auto-approves,
    // and a slice ALWAYS carries a groupId.
    expect(created.every((slice) => slice.approvalStatus === 'pending')).toBe(true)
  })

  it('inherits the manual reason when the block was a manual entry', async () => {
    await seedHolding({ entryMethod: 'manual', manualReason: 'Forgot to start the timer' })
    const { created } = await store.splitTimeEntry(
      'hold-1',
      [{ clientId: 'c1', minutes: 48.5 }],
      'owner-1',
      'grp-abc',
      'even',
    )
    expect(created[0].entryMethod).toBe('manual')
    expect(created[0].manualReason).toBe('Forgot to start the timer')
  })

  it('stores the allocation mode on each slice', async () => {
    await seedHolding()
    await store.splitTimeEntry(
      'hold-1',
      [
        { clientId: 'c1', minutes: 48.5 },
        { clientId: 'c2', minutes: 48.5 },
      ],
      'owner-1',
      'grp-full',
      'full',
    )
    const data = await persisted()
    expect(data.timeEntries.map((entry) => entry.groupAllocation)).toEqual(['full', 'full'])
  })

  it('records the split in the activity log', async () => {
    await seedHolding()
    // The activity log lives in its own file and is NOT reset between tests, so
    // measure the delta rather than the absolute count.
    const splitRows = async () => {
      if (!existsSync(localAuthPath)) return []
      const auth = JSON.parse(await readFile(localAuthPath, 'utf8'))
      return (auth.activityLog ?? []).filter((row) => row.action === 'time_entry_split')
    }
    const before = await splitRows()
    await store.splitTimeEntry(
      'hold-1',
      [
        { clientId: 'c1', minutes: 24.25 },
        { clientId: 'c2', minutes: 24.25 },
      ],
      'owner-1',
      'grp-abc',
      'even',
    )
    const after = await splitRows()
    expect(after).toHaveLength(before.length + 1)
    const logged = after[after.length - 1]
    expect(logged.userId).toBe('owner-1')
    expect(logged.target).toContain('Quarterly review call')
    expect(logged.target).toContain('2 clients')
  })

  it('writes NOTHING when the allocation is empty', async () => {
    await seedHolding()
    const before = await persisted()

    await expect(store.splitTimeEntry('hold-1', [], 'owner-1', 'grp-abc', 'even')).rejects.toThrow()
    await expect(
      store.splitTimeEntry('hold-1', [{ clientId: 'c1', minutes: 0 }], 'owner-1', 'grp-abc', 'even'),
    ).rejects.toThrow()

    expect(await persisted()).toEqual(before)
  })

  it('fails cleanly on a second split of the same block (no duplicates)', async () => {
    await seedHolding()
    await store.splitTimeEntry(
      'hold-1',
      [
        { clientId: 'c1', minutes: 24.25 },
        { clientId: 'c2', minutes: 24.25 },
      ],
      'owner-1',
      'grp-abc',
      'even',
    )
    const afterFirst = await persisted()

    await expect(
      store.splitTimeEntry(
        'hold-1',
        [
          { clientId: 'c1', minutes: 24.25 },
          { clientId: 'c2', minutes: 24.25 },
        ],
        'owner-1',
        'grp-def',
        'even',
      ),
    ).rejects.toMatchObject({ code: 'not_found' })

    expect(await persisted()).toEqual(afterFirst)
  })

  it('refuses an entry with neither a client nor group members', async () => {
    await store.write(
      workspace({
        clients: [{ id: 'c1', name: 'Acme' }],
        timeEntries: [holdingEntry({ id: 'orphan-1', clientId: '', groupClientIds: [] })],
      }),
    )
    const before = await persisted()

    await expect(
      store.splitTimeEntry(
        'orphan-1',
        [
          { clientId: 'c1', minutes: 24.25 },
          { clientId: 'c2', minutes: 24.25 },
        ],
        'owner-1',
        'g',
        'even',
      ),
    ).rejects.toMatchObject({ code: 'not_holding' })

    expect(await persisted()).toEqual(before)
  })
})

/**
 * `splitTimeEntry` on a REGULAR client entry — the firm owner's report that
 * editing time to split clients "will only let me if I pick one client".
 * Splitting used to be a group-timer-only path; ordinary time (including a
 * slice from an earlier split) can now be divided across clients too.
 *
 * What this pins beyond the holding-block suite above:
 *   - a regular entry splits and its sessions survive verbatim;
 *   - an APPROVED original becomes PENDING slices (same rule as any edit to an
 *     approved entry) and the original is gone;
 *   - the entry's own billable flag carries over — a split must not start
 *     billing internal time;
 *   - administrative time is refused (`not_splittable`), and a ONE-allocation
 *     "split" is refused (`single_allocation`) because that's the edit form's
 *     client dropdown, not a split;
 *   - a slice can be re-split.
 */
describe('splitTimeEntry on a regular client entry (file backend)', () => {
  const SESSIONS = [
    { startAt: '2026-07-02T13:00:00.000Z', endAt: '2026-07-02T13:40:00.000Z' },
    { startAt: '2026-07-02T14:00:00.000Z', endAt: '2026-07-02T14:20:30.000Z' },
  ]

  const regularEntry = (overrides = {}) => ({
    id: 'reg-1',
    employeeId: 'emp-1',
    clientId: 'c1',
    isAdministrative: false,
    date: '2026-07-02',
    minutes: 60.5,
    category: 'General',
    description: 'Month-end cleanup',
    billable: true,
    taskId: null,
    approvalStatus: 'approved',
    entryMethod: 'timer',
    startAt: SESSIONS[0].startAt,
    endAt: SESSIONS[1].endAt,
    sessions: SESSIONS,
    groupClientIds: [],
    ...overrides,
  })

  const seedRegular = async (overrides = {}) => {
    await store.write(
      workspace({
        clients: [
          { id: 'c1', name: 'Acme' },
          { id: 'c2', name: 'Globex' },
        ],
        timeEntries: [regularEntry(overrides)],
      }),
    )
  }

  const persisted = async () => JSON.parse(await readFile(localDataPath, 'utf8'))

  it('splits an ordinary client entry across clients, sessions intact', async () => {
    await seedRegular()

    const { created, deletedId } = await store.splitTimeEntry(
      'reg-1',
      [
        { clientId: 'c1', minutes: 30.25 },
        { clientId: 'c2', minutes: 30.25 },
      ],
      'owner-1',
      'grp-reg',
      'even',
    )

    expect(deletedId).toBe('reg-1')
    expect(created).toHaveLength(2)
    for (const slice of created) {
      expect(slice.sessions).toEqual(SESSIONS)
      expect(slice.startAt).toBe(SESSIONS[0].startAt)
      expect(slice.endAt).toBe(SESSIONS[1].endAt)
      expect(slice.description).toBe('Month-end cleanup')
      expect(slice.date).toBe('2026-07-02')
      expect(slice.employeeId).toBe('emp-1')
      expect(slice.groupId).toBe('grp-reg')
      expect(slice.groupAllocation).toBe('even')
    }

    const data = await persisted()
    expect(data.timeEntries.find((entry) => entry.id === 'reg-1')).toBeUndefined()
    expect(data.timeEntries.map((entry) => entry.clientId).sort()).toEqual(['c1', 'c2'])
    const totalSeconds = data.timeEntries.reduce(
      (sum, entry) => sum + Math.round(entry.minutes * 60),
      0,
    )
    expect(totalSeconds).toBe(Math.round(60.5 * 60))
  })

  it('sends an approved original back through approval as pending slices', async () => {
    await seedRegular({ approvalStatus: 'approved' })
    const { created } = await store.splitTimeEntry(
      'reg-1',
      [
        { clientId: 'c1', minutes: 30.25 },
        { clientId: 'c2', minutes: 30.25 },
      ],
      'owner-1',
      'grp-reg',
      'even',
    )
    expect(created.every((slice) => slice.approvalStatus === 'pending')).toBe(true)
  })

  it('carries the entry own billable flag over — internal time stays internal', async () => {
    await seedRegular({ billable: false })
    const { created } = await store.splitTimeEntry(
      'reg-1',
      [
        { clientId: 'c1', minutes: 30.25 },
        { clientId: 'c2', minutes: 30.25 },
      ],
      'owner-1',
      'grp-reg',
      'even',
    )
    expect(created.every((slice) => slice.billable === false)).toBe(true)
  })

  it('refuses administrative time — there is no client to divide', async () => {
    await store.write(
      workspace({
        clients: [
          { id: 'c1', name: 'Acme' },
          { id: 'c2', name: 'Globex' },
        ],
        timeEntries: [regularEntry({ id: 'admin-1', clientId: '', isAdministrative: true })],
      }),
    )
    const before = await persisted()

    await expect(
      store.splitTimeEntry(
        'admin-1',
        [
          { clientId: 'c1', minutes: 30.25 },
          { clientId: 'c2', minutes: 30.25 },
        ],
        'owner-1',
        'grp-reg',
        'even',
      ),
    ).rejects.toMatchObject({ code: 'not_splittable' })

    expect(await persisted()).toEqual(before)
  })

  it('refuses a one-allocation split — that is the edit form client dropdown', async () => {
    await seedRegular()
    const before = await persisted()

    await expect(
      store.splitTimeEntry('reg-1', [{ clientId: 'c2', minutes: 60.5 }], 'owner-1', 'g', 'even'),
    ).rejects.toMatchObject({ code: 'single_allocation' })

    expect(await persisted()).toEqual(before)
  })

  it('re-splits a slice from an earlier split', async () => {
    await seedRegular()
    const { created } = await store.splitTimeEntry(
      'reg-1',
      [
        { clientId: 'c1', minutes: 30.25 },
        { clientId: 'c2', minutes: 30.25 },
      ],
      'owner-1',
      'grp-reg',
      'even',
    )
    const slice = created[0]
    expect(slice.groupId).toBe('grp-reg')

    const second = await store.splitTimeEntry(
      slice.id,
      [
        { clientId: 'c1', minutes: 15.125 },
        { clientId: 'c2', minutes: 15.125 },
      ],
      'owner-1',
      'grp-reg-2',
      'even',
    )
    expect(second.deletedId).toBe(slice.id)
    expect(second.created).toHaveLength(2)
    // A fresh groupId replaces the old one, and the sessions still ride along.
    expect(second.created.every((row) => row.groupId === 'grp-reg-2')).toBe(true)
    expect(second.created[0].sessions).toEqual(SESSIONS)

    const data = await persisted()
    expect(data.timeEntries.find((entry) => entry.id === slice.id)).toBeUndefined()
    expect(data.timeEntries).toHaveLength(3)
  })

  it('leaves the holding-block path alone — a group block still splits', async () => {
    await store.write(
      workspace({
        clients: [
          { id: 'c1', name: 'Acme' },
          { id: 'c2', name: 'Globex' },
        ],
        timeEntries: [
          regularEntry({ id: 'hold-x', clientId: '', groupClientIds: ['c1', 'c2'], billable: false }),
        ],
      }),
    )
    const { created } = await store.splitTimeEntry(
      'hold-x',
      [
        { clientId: 'c1', minutes: 30.25 },
        { clientId: 'c2', minutes: 30.25 },
      ],
      'owner-1',
      'grp-hold',
      'even',
    )
    // A holding block parks `billable: false` until split; its slices bill.
    expect(created.every((slice) => slice.billable === true)).toBe(true)
  })
})

/**
 * EDIT THEN SPLIT — "still will not let me edit the time before I split it".
 *
 * The two halves have to compose: adjusting a session-backed entry's billed
 * duration must actually stick, and the split that follows must divide the
 * EDITED total rather than re-deriving the original from the untouched clock
 * spans. Both are exercised here through the same store calls the PATCH handler
 * and the split endpoint make, on the file backend, to the second.
 *
 * The minutes rule itself is `minutesAfterEntryEdit`, unit-tested in
 * lib/group-allocation.test.mjs; what this pins is that the store persists its
 * result and that `splitTimeEntry` divides what was persisted.
 */
describe('edit a session-backed entry, then split it (file backend)', () => {
  // A single 60-minute timer session. The number to watch: the split below
  // divides 45, not 60.
  const SESSIONS = [{ startAt: '2026-07-03T13:00:00.000Z', endAt: '2026-07-03T14:00:00.000Z' }]

  const seed = async (overrides = {}) => {
    await store.write(
      workspace({
        clients: [
          { id: 'c1', name: 'Acme' },
          { id: 'c2', name: 'Globex' },
        ],
        timeEntries: [
          {
            id: 'edit-1',
            employeeId: 'emp-1',
            clientId: 'c1',
            isAdministrative: false,
            date: '2026-07-03',
            minutes: 60,
            category: 'General',
            description: 'Bank rec',
            billable: true,
            taskId: null,
            approvalStatus: 'pending',
            entryMethod: 'timer',
            startAt: SESSIONS[0].startAt,
            endAt: SESSIONS[0].endAt,
            sessions: SESSIONS,
            groupClientIds: [],
            ...overrides,
          },
        ],
      }),
    )
  }

  const persisted = async () => JSON.parse(await readFile(localDataPath, 'utf8'))
  const entryById = async (id) => (await persisted()).timeEntries.find((e) => e.id === id)
  const seconds = (minutes) => Math.round(Number(minutes) * 60)

  it('keeps a typed duration that disagrees with the clock spans', async () => {
    await seed()
    // What the PATCH handler stores when the user typed 45 minutes: the billed
    // minutes change, the sessions stay verbatim as the audit trail.
    await store.updateTimeEntry('edit-1', { minutes: 45, sessions: SESSIONS })

    const saved = await entryById('edit-1')
    expect(saved.minutes).toBe(45)
    expect(saved.sessions).toEqual(SESSIONS)
  })

  it('divides the EDITED total across clients, to the second', async () => {
    await seed()
    await store.updateTimeEntry('edit-1', { minutes: 45, sessions: SESSIONS })

    const { created, deletedId } = await store.splitTimeEntry(
      'edit-1',
      [
        { clientId: 'c1', minutes: 20 },
        { clientId: 'c2', minutes: 25 },
      ],
      'owner-1',
      'grp-edit',
      'custom',
    )

    expect(deletedId).toBe('edit-1')
    expect(created.map((slice) => slice.minutes).sort((a, b) => a - b)).toEqual([20, 25])
    // The 60-minute clock is NOT what got divided.
    const totalSeconds = created.reduce((sum, slice) => sum + seconds(slice.minutes), 0)
    expect(totalSeconds).toBe(seconds(45))
    // Every slice still carries the clock-in/out of when the work happened.
    for (const slice of created) {
      expect(slice.sessions).toEqual(SESSIONS)
      expect(slice.startAt).toBe(SESSIONS[0].startAt)
      expect(slice.endAt).toBe(SESSIONS[0].endAt)
    }
  })

  it('survives seconds-exact edits — 45m 20s splits into 20m 20s + 25m', async () => {
    await seed()
    const edited = 45 + 20 / 60
    await store.updateTimeEntry('edit-1', { minutes: edited, sessions: SESSIONS })
    expect((await entryById('edit-1')).minutes).toBe(edited)

    const { created } = await store.splitTimeEntry(
      'edit-1',
      [
        { clientId: 'c1', minutes: 20 + 20 / 60 },
        { clientId: 'c2', minutes: 25 },
      ],
      'owner-1',
      'grp-edit-2',
      'custom',
    )
    const totalSeconds = created.reduce((sum, slice) => sum + seconds(slice.minutes), 0)
    expect(totalSeconds).toBe(seconds(edited))
  })

  it('keeps an edited SLICE at its typed minutes, split intact', async () => {
    // A 60-minute block already split 20/40. Retyping one slice's duration must
    // change that slice only — not blow it back up to the whole block.
    await store.write(
      workspace({
        clients: [
          { id: 'c1', name: 'Acme' },
          { id: 'c2', name: 'Globex' },
        ],
        timeEntries: [
          {
            id: 'slice-a',
            employeeId: 'emp-1',
            clientId: 'c1',
            date: '2026-07-03',
            minutes: 20,
            description: 'Bank rec',
            billable: true,
            approvalStatus: 'pending',
            entryMethod: 'timer',
            startAt: SESSIONS[0].startAt,
            endAt: SESSIONS[0].endAt,
            sessions: SESSIONS,
            groupId: 'grp-live',
            groupAllocation: 'custom',
          },
          {
            id: 'slice-b',
            employeeId: 'emp-1',
            clientId: 'c2',
            date: '2026-07-03',
            minutes: 40,
            description: 'Bank rec',
            billable: true,
            approvalStatus: 'pending',
            entryMethod: 'timer',
            startAt: SESSIONS[0].startAt,
            endAt: SESSIONS[0].endAt,
            sessions: SESSIONS,
            groupId: 'grp-live',
            groupAllocation: 'custom',
          },
        ],
      }),
    )

    await store.updateTimeEntry('slice-a', { minutes: 15, sessions: SESSIONS })

    expect((await entryById('slice-a')).minutes).toBe(15)
    expect((await entryById('slice-a')).sessions).toEqual(SESSIONS)
    // The sibling is untouched — an edit on one slice is not a re-division.
    expect((await entryById('slice-b')).minutes).toBe(40)
  })
})

/**
 * Decode the INSERT statements a fake pool recorded back into rows.
 *
 * The bulk save issues one `insert into <table> (cols) values (...)` per row
 * today and will issue multi-row `values (...), (...)` statements once it is
 * batched. A test that reads `statement.params[17]` is welded to the first
 * shape and to a column's position; this reads BOTH shapes and answers one
 * object per row, keyed by column name, in statement order and row order.
 *
 *   - a `$n` placeholder (with or without a `::cast`) becomes `params[n - 1]`,
 *     exactly as bound (a Date stays a Date, a jsonb stays its JSON string, a
 *     text[] stays an array, null stays null);
 *   - anything else (`now()`, `coalesce((select ...), $3)`) becomes its SQL
 *     text, with any `$n` inside it replaced by that parameter as JSON, so a
 *     column the statement fills itself is still visible and still pins the
 *     values it was handed.
 *
 * It throws on an INSERT that is not a plain VALUES list (an `insert ... select`),
 * so a statement it cannot read never silently decodes to nothing.
 */
const PLACEHOLDER = /^\$(\d+)(?:\s*::\s*[a-z_]+(?:\[\])?)?$/i

function splitTopLevel(text) {
  const parts = []
  let depth = 0
  let quoted = false
  let start = 0
  for (let at = 0; at < text.length; at += 1) {
    const char = text[at]
    if (quoted) {
      if (char === "'") quoted = false
    } else if (char === "'") {
      quoted = true
    } else if (char === '(') {
      depth += 1
    } else if (char === ')') {
      depth -= 1
    } else if (char === ',' && depth === 0) {
      parts.push(text.slice(start, at).trim())
      start = at + 1
    }
  }
  parts.push(text.slice(start).trim())
  return parts
}

/** The column list and the raw SQL of every value in every row, or null when `text` is no insert into `table`. */
function parseInsertStatement(text, table) {
  const head = new RegExp(`^insert\\s+into\\s+${table}\\s*\\(`, 'i').exec(text)
  if (!head) return null
  const columnsEnd = text.indexOf(')', head[0].length)
  const columns = text
    .slice(head[0].length, columnsEnd)
    .split(',')
    .map((column) => column.trim())
    .filter(Boolean)
  const values = /^\s*values\s*/i.exec(text.slice(columnsEnd + 1))
  if (!values) throw new Error(`insert into ${table} is not a VALUES insert: ${text.slice(0, 120)}`)
  const rows = []
  let at = columnsEnd + 1 + values[0].length
  for (;;) {
    if (text[at] !== '(') throw new Error(`insert into ${table}: expected a value list at ${at}`)
    let depth = 0
    let quoted = false
    let end = at
    for (; end < text.length; end += 1) {
      const char = text[end]
      if (quoted) {
        if (char === "'") quoted = false
      } else if (char === "'") {
        quoted = true
      } else if (char === '(') {
        depth += 1
      } else if (char === ')') {
        depth -= 1
        if (depth === 0) break
      }
    }
    const expressions = splitTopLevel(text.slice(at + 1, end))
    if (expressions.length !== columns.length) {
      throw new Error(
        `insert into ${table}: ${columns.length} columns but ${expressions.length} values in row ${rows.length + 1}`,
      )
    }
    rows.push(expressions)
    at = end + 1
    while (/\s/.test(text[at] ?? '')) at += 1
    if (text[at] !== ',') break
    at += 1
    while (/\s/.test(text[at] ?? '')) at += 1
  }
  return { columns, rows }
}

/** Every row the recorded statements inserted into `table`, in order, as { column: value }. */
function insertedRows(statements, table) {
  const decoded = []
  for (const statement of statements) {
    const parsed = parseInsertStatement(statement.text, table)
    if (!parsed) continue
    for (const expressions of parsed.rows) {
      const row = {}
      parsed.columns.forEach((column, index) => {
        const placeholder = PLACEHOLDER.exec(expressions[index])
        row[column] = placeholder
          ? statement.params[Number(placeholder[1]) - 1]
          : expressions[index].replace(/\$(\d+)/g, (_match, n) => JSON.stringify(statement.params[Number(n) - 1]))
      })
      decoded.push(row)
    }
  }
  return decoded
}

/**
 * A minimal stand-in for a `pg` Pool, enough to drive the POSTGRES branch of
 * `write()` without a database. Every statement is recorded so a test can
 * assert on what the transaction actually issued and in what order.
 *
 * `write()` only ever consumes the result of three queries â€” the users
 * pre-check, the (optional) version fingerprint, and the invoice-drafts
 * snapshot â€” so returning an empty row set for everything else is faithful.
 */
function fakePostgres({
  invoices = [],
  groupSlices = [],
  clientRows = [],
  userRows = [],
  createdAtRows = {},
  priorItemRows = [],
  priorChecklistRows = [],
  templateRows = [],
  templateStageRows = [],
  templateItemRows = [],
  versionResponses = null,
  recurringRows = [],
  aiReviewRows = [],
  aiReviewUpdateRowCount = 1,
  timeEntryRows = [],
  holdingRows = [],
  checklistRows = [],
  pushChecklistRows = [],
  pushItemRows = [],
  // Sub-step waits on another checklist's steps: the rows the split's
  // `position(<id> in sub_items::text)` read answers with.
  subWaiterRows = [],
  // Teach the fake the v3 instance index. Off by default so no other test
  // pays for it; the split-push tests turn it on.
  simulateChecklistUniqueness = false,
  // Does the v3 instance index already exist? Answers initialize()'s to_regclass probe.
  checklistIndexV3Exists = false,
  // { pattern, error, times? }: throw `error` on a statement matching `pattern`
  // (every match, or only the first `times` of them when `times` is given).
  failOn = null,
  // Stored clients that have time entries or invoices, as the bulk save's
  // history check would select them: { id, name, has_time, has_invoices }.
  clientsWithHistory = [],
} = {}) {
  const statements = []
  // The instance unique index
  // (template_id, coalesce(cycle_due_date, due_date), stage_index)
  //   where deleted_at is null and template_id is not null
  //     and pushed_to_checklist_id is null
  // simulated just far enough to refuse the wrong statement ORDER: a live row
  // is one whose pushed_to is null; a second live row on the same tuple raises
  // 23505, exactly as Postgres does (a unique index is never deferrable).
  let liveRows = pushChecklistRows.map((row) => ({
    id: row.id,
    template_id: row.template_id ?? null,
    cycle: row.cycle_due_date ?? row.due_date,
    stage_index: row.stage_index ?? 0,
    pushed_to: row.pushed_to_checklist_id ?? null,
    deleted: row.deleted_at ?? null,
  }))
  let liveRowsAtBegin = liveRows
  const simulateUniqueness = (trimmed, params) => {
    if (/^begin$/i.test(trimmed)) {
      liveRowsAtBegin = liveRows.map((row) => ({ ...row }))
    } else if (/^rollback$/i.test(trimmed)) {
      liveRows = liveRowsAtBegin
    } else if (/^update checklists\s+set pushed_at = now\(\), pushed_by = \$2, pushed_to_checklist_id = \$3/i.test(trimmed)) {
      const row = liveRows.find((entry) => entry.id === params[0])
      if (row) row.pushed_to = params[2]
    } else if (/^insert into checklists \(/i.test(trimmed)) {
      // One row per tuple, so a multi-row INSERT is checked against the rows
      // before it in the SAME statement too, as the real index does. Without
      // `on conflict do nothing` a clash raises 23505 (a unique index is never
      // deferrable); with it the clashing row is skipped and the rest land,
      // and the answer carries what landed (`rowCount`, and the ids for a
      // `returning id`) the way the bulk save reads it. Two clashes are real:
      // the primary key, and the instance index over live rows.
      const skipsConflicts = /\bon conflict do nothing\b/i.test(trimmed)
      const landed = []
      for (const row of insertedRows([{ text: trimmed, params }], 'checklists')) {
        const fresh = {
          id: row.id,
          template_id: row.template_id ?? null,
          cycle: row.cycle_due_date ?? row.due_date,
          stage_index: row.stage_index ?? 0,
          pushed_to: null,
          deleted: row.deleted_at ?? null,
        }
        const sameInstance = (live) =>
          fresh.template_id !== null &&
          fresh.deleted === null &&
          live.deleted === null &&
          live.template_id === fresh.template_id &&
          live.cycle === fresh.cycle &&
          live.stage_index === fresh.stage_index &&
          live.pushed_to === null
        const clash = liveRows.some((live) => live.id === fresh.id || sameInstance(live))
        if (clash) {
          if (skipsConflicts) continue
          throw Object.assign(
            new Error('duplicate key value violates unique constraint "checklists_template_instance_uniq_v3"'),
            { code: '23505' },
          )
        }
        liveRows = [...liveRows, fresh]
        landed.push(fresh.id)
      }
      if (skipsConflicts) return { rows: landed.map((id) => ({ id })), rowCount: landed.length }
    }
    return undefined
  }
  const record = (text, params) => {
    const trimmed = String(text).trim()
    statements.push({ text: trimmed, params })
    if (failOn && failOn.pattern.test(trimmed)) {
      // `times` (optional) limits how many matching statements throw; without
      // it every match throws, as before.
      if (failOn.times === undefined) throw failOn.error
      if (failOn.times > 0) {
        failOn.times -= 1
        throw failOn.error
      }
    }
    if (simulateChecklistUniqueness) {
      const simulated = simulateUniqueness(trimmed, params)
      if (simulated) return simulated
    }
    // The bulk save's "never delete a client who has history" read. FIRST, and
    // actually filtering by the kept ids ($1), for two reasons: its text names
    // `from invoices` and `from time_entries`, so the general invoice select
    // further down would otherwise swallow it and answer every invoice row; and
    // answering every stored client would make a test that proves the guard
    // spares a client still in the payload pass no matter what the store does.
    if (/^select c\.id, c\.name,[\s\S]*from clients c\s+where not \(c\.id = any\(\$1::text\[\]\)\)/i.test(trimmed)) {
      const kept = new Set(params?.[0] ?? [])
      return { rows: clientsWithHistory.filter((row) => !kept.has(row.id)) }
    }
    // The workspace fingerprint (lib/workspace-version.js) — read()'s
    // pre-capture and write()'s in-transaction re-check issue the same SQL.
    // `versionResponses` scripts the answers in order, so a test can make the
    // fingerprint MOVE between the capture and the check (i.e. simulate a
    // concurrent write landing mid-read). A FUNCTION answers from live state
    // instead, so a test can flip the "database" at an exact point in the
    // read and see which side of that point the captured version fell on.
    // Default: empty tables, stable value.
    if (/md5\(coalesce\(string_agg/i.test(trimmed) && /union all/i.test(trimmed)) {
      if (typeof versionResponses === 'function') return { rows: versionResponses() }
      return { rows: Array.isArray(versionResponses) ? (versionResponses.shift() ?? []) : [] }
    }
    // `findInvoiceByPayToken`'s narrow read. It has to come BEFORE the general
    // invoices select below, and it has to actually filter: answering every row
    // would make a test that proves one client's token cannot reach another
    // client's invoice pass no matter what the store does.
    if (/^select\b[\s\S]*\bfrom invoices where pay_token = \$1$/i.test(trimmed)) {
      const found = invoices.find((invoice) => invoice.pay_token === params?.[0])
      return { rows: found ? [found] : [] }
    }
    // `recordInvoicePayLinkOpened`'s single-row read, and for the same two
    // reasons: before the general invoices select, and actually filtering.
    // Answering every row would let a pay link for an invoice that is not there
    // file an open against somebody else's.
    // `confirmExpenseCoverage` reads the same row `for update` inside its transaction.
    if (/^select\b[\s\S]*\bfrom invoices where id = \$1( for update)?$/i.test(trimmed)) {
      const found = invoices.find((invoice) => invoice.id === params?.[0])
      return { rows: found ? [found] : [], rowCount: found ? 1 : 0 }
    }
    if (/^select\b[\s\S]*\bfrom invoices\b/i.test(trimmed)) {
      return { rows: invoices }
    }
    // read()'s template/stage/item selects — column-anchored so the bulk
    // save's bare `select id, created_at from checklist_templates` snapshot
    // (handled below) never matches these.
    if (/\bnext_due_date\b[\s\S]*from checklist_templates\b/i.test(trimmed)) {
      return { rows: templateRows }
    }
    if (/\boffset_days\b[\s\S]*from checklist_template_stages\b/i.test(trimmed)) {
      return { rows: templateStageRows }
    }
    if (/select id, template_id, label\b[\s\S]*from checklist_template_items\b/i.test(trimmed)) {
      return { rows: templateItemRows }
    }
    // `update invoices … returning id` — the void pass reads its OWN output to
    // decide which retainers to hand back, so the fake has to answer with the
    // rows it claims to have touched or that second statement never runs.
    // `getOrCreateInvoicePayToken`'s single statement. The fake reproduces the
    // `coalesce` rather than just echoing the candidate, because the ONE thing
    // worth proving about this method is that a second call gives back the
    // FIRST token — a token that changed would invalidate a link already in a
    // client's inbox.
    if (/^update invoices\b[\s\S]*\breturning pay_token$/i.test(trimmed)) {
      const found = invoices.find((invoice) => invoice.id === params?.[0])
      if (!found) return { rows: [] }
      found.pay_token = found.pay_token ?? params?.[1]
      return { rows: [{ pay_token: found.pay_token }] }
    }
    // `updateInvoice`'s own write, with its status guard REPRODUCED: the row
    // matches only while it still carries the status the save read ($8). A fake
    // that answered rowCount 1 regardless would let the guard be deleted and
    // every race test below keep passing.
    if (/^update invoices\s+set line_items[\s\S]*where id = \$1 and status = \$8$/i.test(trimmed)) {
      const found = invoices.find((invoice) => invoice.id === params?.[0])
      return found && found.status === params?.[7]
        ? { rows: [], rowCount: 1 }
        : { rows: [], rowCount: 0 }
    }
    // The void pass's RETURNING also carries the two checkout-session columns it
    // does not touch — the route expires those once the void commits.
    if (
      /^update invoices\b[\s\S]*\breturning id, stripe_checkout_session_id, stripe_card_session_id$/i.test(
        trimmed,
      )
    ) {
      return {
        rows: invoices.map((invoice) => ({
          id: invoice.id,
          stripe_checkout_session_id: invoice.stripe_checkout_session_id ?? null,
          stripe_card_session_id: invoice.stripe_card_session_id ?? null,
        })),
      }
    }
    if (/^update invoices\b[\s\S]*\breturning id$/i.test(trimmed)) {
      return { rows: invoices.map((invoice) => ({ id: invoice.id })) }
    }
    // `applyInvoicePayment`'s own write: absolute values from its plan, answered
    // with the row it wrote (`returning`). The row is REPLACED in `invoices`
    // rather than mutated - the fixtures are shared across tests - so a second
    // call decides on what the first one left.
    if (/^update invoices\s+set status = \$2[\s\S]*\breturning id, client_id\b/i.test(trimmed)) {
      const index = invoices.findIndex((invoice) => invoice.id === params?.[0])
      if (index === -1) return { rows: [], rowCount: 0 }
      const merged = {
        ...invoices[index],
        status: params[1],
        stripe_checkout_session_id: params[2],
        stripe_payment_intent_id: params[3],
        payment_method: params[4],
        paid_at: params[5],
        sent_at: params[6],
        stripe_card_session_id: params[7],
        ...(params.length > 8
          ? { line_items: JSON.parse(params[8]), subtotal: params[9], total: params[10] }
          : {}),
      }
      invoices[index] = merged
      return { rows: [merged], rowCount: 1 }
    }
    // The two statements that hand back the row they WROTE rather than
    // re-listing every invoice afterwards — `recordInvoiceSent` and
    // `recordInvoicePastDueNoticed`. The fake has to answer with the row AND a
    // rowCount, or the store reads its own write as a miss and returns null.
    //
    // The past-due marker's `@>` guard is REPRODUCED, not waved through: the
    // entire point of that statement is that a second container matches no row,
    // and a fake that answered anyway would let its removal pass CI. The row is
    // copied rather than mutated — these fixtures are shared across tests.
    if (/^update invoices\b[\s\S]*\breturning id, client_id\b/i.test(trimmed)) {
      const found = invoices.find((invoice) => invoice.id === params?.[0])
      if (!found) return { rows: [], rowCount: 0 }
      const guarded = /@> '\[\{"kind":"past-due"\}\]'::jsonb/i.test(trimmed)
      if (guarded && (found.email_log ?? []).some((entry) => entry?.kind === 'past-due')) {
        return { rows: [], rowCount: 0 }
      }
      const appended = JSON.parse(params?.[1] ?? '[]')
      const merged = { ...found, email_log: [...(found.email_log ?? []), ...appended] }
      return { rows: [merged], rowCount: 1 }
    }
    // `swapInvoiceCheckoutSession`. The fake answers with the row's value as it
    // stood BEFORE the write and then applies the new one, because the one
    // thing worth proving about this statement is exactly that: the caller has
    // to be handed the id it REPLACED, not one it read a round-trip earlier.
    if (/^with prev as \([\s\S]*update invoices[\s\S]*returning prev\.previous$/i.test(trimmed)) {
      const found = invoices.find((invoice) => invoice.id === params?.[0])
      if (!found || found.status === 'void') return { rows: [], rowCount: 0 }
      const column = /set stripe_card_session_id = \$2/i.test(trimmed)
        ? 'stripe_card_session_id'
        : 'stripe_checkout_session_id'
      const previous = found[column] ?? null
      found[column] = params?.[1]
      return { rows: [{ previous }], rowCount: 1 }
    }
    // The bulk save's created_at snapshots — one bare select per table in
    // CREATED_AT_PRESERVED_TABLES, taken before the wipe.
    const createdAtSnapshot = /^select id, created_at from (\w+)$/i.exec(trimmed)
    if (createdAtSnapshot) {
      return { rows: createdAtRows[createdAtSnapshot[1]] ?? [] }
    }
    // The sibling snapshot of what was already complete — and, since the wait
    // preservation, of what waiting state each row already carried.
    if (/^select id, done, completed_at[\s\S]*from checklist_items$/i.test(trimmed)) {
      return { rows: priorItemRows }
    }
    // The bulk save's push-stamp snapshot, taken before the wipe. What is
    // STORED here wins over whatever the payload carried, so a fake that
    // answered nothing would make every push stamp look like a new row's.
    // The split link (featreq-fbab3370) rides in the same snapshot.
    if (
      /^select id, cycle_due_date, pushed_at, pushed_by, pushed_from_checklist_id, pushed_to_checklist_id from checklists$/i.test(
        trimmed,
      )
    ) {
      return { rows: priorChecklistRows }
    }
    // `_refuseBillingMasterWrite`'s single-row lookup, and `createClient`'s
    // roster read for the bill-to rules. Both answer out of `clientRows` so one
    // fixture drives the read mapper and the guards alike. Anchored on their
    // exact column lists: without these two branches the Postgres half of every
    // master guard falls through to the empty default and is never exercised,
    // which is precisely the "passes CI, wrong in production" shape cardinal
    // rule 1 exists for.
    if (/^select name, is_billing_master from clients where id = \$1$/i.test(trimmed)) {
      const found = clientRows.find((row) => row.id === params?.[0])
      return { rows: found ? [found] : [], rowCount: found ? 1 : 0 }
    }
    if (/^select id, name, is_billing_master as "isBillingMaster"/i.test(trimmed)) {
      return {
        rows: clientRows.map((row) => ({
          id: row.id,
          name: row.name,
          isBillingMaster: row.is_billing_master === true,
          billToClientId: row.bill_to_client_id ?? null,
        })),
      }
    }
    // The bulk save's Stripe-customer snapshot, taken before the wipe. Answered
    // out of `clientRows` for the same reason the push stamps are: a fake that
    // returned nothing would make every stored id look absent, and the
    // stored-wins assertion would pass against a store that dropped the column.
    if (/^select id, stripe_customer_id from clients$/i.test(trimmed)) {
      return {
        rows: clientRows.map((row) => ({
          id: row.id,
          stripe_customer_id: row.stripe_customer_id ?? null,
        })),
      }
    }
    // The clients read inside read() — lets a test exercise the row mapper.
    if (/^select\b[\s\S]*\bfrom clients\b[\s\S]*order by name asc/i.test(trimmed)) {
      return { rows: clientRows }
    }
    // `getClientById` — the SAME column list, one row. Anchored on the head of
    // that list rather than on `from clients where id = $1`, which would also
    // swallow the bare `select 1 from clients where id = $1` existence checks.
    if (/^select id, name, contact, billing_mode\b[\s\S]*from clients where id = \$1$/i.test(trimmed)) {
      const found = clientRows.find((row) => row.id === params?.[0])
      return { rows: found ? [found] : [], rowCount: found ? 1 : 0 }
    }
    // The `for update` read `splitTimeEntry` starts with: the one source row.
    if (/^select\b[\s\S]*\bfrom time_entries where id = \$1 for update$/i.test(trimmed)) {
      const found = holdingRows.filter((row) => row.id === params?.[0])
      return { rows: found, rowCount: found.length }
    }
    // The split's task read: the source checklist's client and title, so the
    // share billed to another client can still name the task.
    if (/^select id, client_id, title from checklists where id = \$1$/i.test(trimmed)) {
      const found = checklistRows.filter((row) => row.id === params?.[0])
      return { rows: found, rowCount: found.length }
    }
    // `pushChecklistInstance`'s `for update` read of the row it is about to
    // push — anchored on its own column list (distinct from the split's task
    // read above) so the two never cross-match.
    if (
      /^select id, client_id, title, assignee_id, template_id, frequency, due_date,[\s\S]*from checklists[\s\S]*where id = \$1 and deleted_at is null and skipped_at is null[\s\S]*for update$/i.test(
        trimmed,
      )
    ) {
      const found = pushChecklistRows.find((row) => row.id === params?.[0])
      // `to_char(coalesce(cycle_due_date, due_date), 'YYYY-MM-DD') as
      // identity_date`: a fixture that does not script it gets the string the
      // database would produce from its (string) dates.
      const answered = found
        ? { identity_date: String(found.cycle_due_date ?? found.due_date), ...found }
        : null
      return { rows: answered ? [answered] : [], rowCount: answered ? 1 : 0 }
    }
    // `pushChecklistInstance`'s read of the row's current steps, used to
    // decide plain move / refuse / split. Anchored on `CHECKLIST_ITEM_SELECT_
    // COLUMNS` followed by the checklist_id where-clause this call alone uses.
    if (
      /^select id, checklist_id, label, done, sort_order[\s\S]*from checklist_items\s*where checklist_id = \$1\s*order by sort_order asc, id asc\s+for update$/i.test(
        trimmed,
      )
    ) {
      return { rows: pushItemRows, rowCount: pushItemRows.length }
    }
    // The split push's read of steps elsewhere whose sub-step waits mention the
    // checklist being split (their waits live in the sub_items jsonb).
    if (/^select id, sub_items from checklist_items\s+where position\(/i.test(trimmed)) {
      return { rows: subWaiterRows, rowCount: subWaiterRows.length }
    }
    // The `for update` read a split adjustment starts with.
    if (/^select\b[\s\S]*\bfrom time_entries where group_id\b/i.test(trimmed)) {
      return { rows: groupSlices, rowCount: groupSlices.length }
    }
    // The user-exists probe both rate-version upserts issue before writing.
    // An unknown id must never reach the insert — in Postgres the foreign key
    // would raise and the endpoint would 500 where it used to quietly no-op.
    // The fake answers "this person exists" by default so every other test
    // keeps its write; a test that supplies `userRows` gets the real
    // membership check, which is what proves the guard actually filters.
    if (/^select 1 from users where id = \$1$/i.test(trimmed)) {
      if (userRows.length === 0) return { rows: [{}], rowCount: 1 }
      const found = userRows.some((row) => row.id === params?.[0])
      return { rows: found ? [{}] : [], rowCount: found ? 1 : 0 }
    }
    // The bare id-validation query `setClientAssignedTeam` issues. Anchored to
    // the exact bare statement (no trailing `where`) so a reintroduced
    // `where role <> 'owner'` filter falls through to the empty default below
    // instead — the same empty-`valid` failure a live regression would cause.
    if (/^select id from users\s*$/i.test(trimmed)) {
      return { rows: userRows }
    }
    // Recurring reimbursements, for the covered-date tests — both the read
    // inside `read()` and the single-row read the update path starts with.
    if (/^select\b[\s\S]*\bfrom recurring_reimbursements\b/i.test(trimmed)) {
      return { rows: recurringRows, rowCount: recurringRows.length }
    }
    if (/^update recurring_reimbursements set[\s\S]*returning/i.test(trimmed)) {
      return { rows: recurringRows, rowCount: recurringRows.length }
    }
    // Invoice AI ratings. The answer path's guarded update needs a scriptable
    // rowCount: matching NO row is the re-rate race, and the store turns that
    // into a 409 rather than a silent success.
    if (/^select\b[\s\S]*\bfrom invoice_ai_reviews\b/i.test(trimmed)) {
      return { rows: aiReviewRows, rowCount: aiReviewRows.length }
    }
    if (/^update invoice_ai_reviews set questions/i.test(trimmed)) {
      return { rows: [], rowCount: aiReviewUpdateRowCount }
    }
    // The scope re-tag's validation read (featreq-8cec48db). Anchored on its
    // exact shape so a rewrite that stopped checking the client or the month
    // falls through to the empty default and fails loudly, rather than
    // silently trusting whatever entry ids a payload named.
    if (/^select id, client_id, to_char\(entry_date/i.test(trimmed)) {
      const wanted = new Set(params?.[0] ?? [])
      const rows = timeEntryRows.filter((row) => wanted.has(row.id))
      return { rows, rowCount: rows.length }
    }
    // Its client read: the invoice's own client — whose billing mode says
    // whether this panel exists on this invoice at all — and its subs, in one
    // statement. Anchored the same way, so dropping the billing mode from it
    // falls through to the empty default and refuses rather than passing.
    if (
      /^select id, billing_mode from clients where id = \$1 or bill_to_client_id = \$1$/i.test(
        trimmed,
      )
    ) {
      const owner = params?.[0]
      const rows = clientRows
        .filter((row) => row.id === owner || row.bill_to_client_id === owner)
        .map((row) => ({ id: row.id, billing_mode: row.billing_mode ?? null }))
      return { rows, rowCount: rows.length }
    }
    // `setClientHourlyRatePeriod`'s ONE atomic update: it appends the move to
    // the ledger from the row's own OLD pin (the right-hand side of a SET reads
    // the pre-update row) and moves the pin in the same statement. Anchored on
    // its opening so the migration's literal `set hourly_rate_period =
    // '2026-06'` backfill falls through to the default below and keeps its own
    // test honest. Emulated here — old pin into `from`, then the new pin — and
    // answered with a rowCount, or the store reads its own write as a miss and
    // hands the caller null.
    if (/^update clients set hourly_rate_history = coalesce\(hourly_rate_history/i.test(trimmed)) {
      const found = clientRows.find((row) => row.id === params?.[0])
      if (!found) return { rows: [], rowCount: 0 }
      const history = Array.isArray(found.hourly_rate_history) ? found.hourly_rate_history : []
      found.hourly_rate_history = [
        ...history,
        {
          from: found.hourly_rate_period ?? null,
          to: params?.[1],
          changedAt: params?.[2],
          changedBy: params?.[3] ?? null,
        },
      ]
      found.hourly_rate_period = params?.[1]
      return { rows: [{ id: found.id }], rowCount: 1 }
    }
    // The kept invoice note, snapshotted before the wipe. Answered out of
    // `clientRows` for the same reason the Stripe customer is: a fake that
    // answered nothing would make every stored note look absent and the
    // stored-wins assertion pass against a store that dropped the column.
    if (/^select id, invoice_note from clients$/i.test(trimmed)) {
      return {
        rows: clientRows.map((row) => ({ id: row.id, invoice_note: row.invoice_note ?? null })),
      }
    }
    // `setClientInvoiceNote`'s ONE targeted update, emulated against the fixture
    // rows and answered with a rowCount (or the store reads its own write as a
    // miss and hands the caller null).
    if (/^update clients set invoice_note = \$2, updated_at = now\(\) where id = \$1 returning id$/i.test(trimmed)) {
      const found = clientRows.find((row) => row.id === params?.[0])
      if (!found) return { rows: [], rowCount: 0 }
      found.invoice_note = params?.[1]
      return { rows: [{ id: found.id }], rowCount: 1 }
    }
    // The rate-history pin snapshot the bulk save takes before the wipe — the
    // same idiom as `priorStripeCustomerIds`. Anchored on its exact shape so a
    // rewrite that stopped reading it falls through to the empty default and
    // the test fails loudly rather than passing on a stale answer.
    if (/^select id, hourly_rate_period, hourly_rate_history from clients$/i.test(trimmed)) {
      return { rows: clientRows }
    }
    // initialize()'s probe for the v3 instance index.
    if (/^select to_regclass\('checklists_template_instance_uniq_v3'\) is null as missing$/i.test(trimmed)) {
      return { rows: [{ missing: !checklistIndexV3Exists }] }
    }
    return { rows: [] }
  }
  const client = {
    async query(text, params) {
      return record(text, params)
    },
    release() {},
  }
  const pool = {
    async connect() {
      return client
    },
    async query(text, params) {
      return record(text, params)
    },
  }
  const matching = (pattern) => statements.filter((s) => pattern.test(s.text))
  const indexOf = (pattern) => statements.findIndex((s) => pattern.test(s.text))
  return { pool, statements, matching, indexOf }
}

function postgresStore(fake) {
  const pgStore = new AppDataStore()
  pgStore.pool = fake.pool
  pgStore.mode = 'postgres'
  return pgStore
}

/**
 * `assignedEmployeeIds` no longer has a table behind it — it is an alias of
 * `assignedBookkeeperIds`, emitted identically by both backends so a UI reading
 * either name gets the same answer. This is the Postgres half; the file half
 * is in the invariant suite.
 */
describe('read() derives assignedEmployeeIds from the client row (postgres branch)', () => {
  const clientRow = {
    id: 'c1',
    name: 'Acme',
    contact: 'Pat',
    billing_mode: 'hourly',
    hourly_rate: 0,
    plan_id: null,
    plan_ids: [],
    contact_ids: [],
    assigned_bookkeeper_ids: ['emp-1', 'emp-2'],
    lifecycle_stage: 'active',
  }

  it('emits both names with the same value', async () => {
    const fake = fakePostgres({ clientRows: [clientRow] })
    const data = await postgresStore(fake).read()

    expect(data.clients[0].assignedBookkeeperIds).toEqual(['emp-1', 'emp-2'])
    expect(data.clients[0].assignedEmployeeIds).toEqual(['emp-1', 'emp-2'])
  })

  it('no longer selects from client_assignments', async () => {
    const fake = fakePostgres({ clientRows: [clientRow] })
    await postgresStore(fake).read()

    expect(fake.matching(/client_assignments/i)).toEqual([])
  })

  it('emits an empty team as an empty array on both names', async () => {
    const fake = fakePostgres({ clientRows: [{ ...clientRow, assigned_bookkeeper_ids: null }] })
    const data = await postgresStore(fake).read()

    expect(data.clients[0].assignedBookkeeperIds).toEqual([])
    expect(data.clients[0].assignedEmployeeIds).toEqual([])
  })
})

const existingInvoice = {
  id: 'inv-1',
  client_id: 'c1',
  period: '2026-08',
  number: 'INV-2026-08-001',
  status: 'sent',
  line_items: [{ kind: 'plan', label: 'August work', detail: 'Monthly service', amount: 250 }],
  subtotal: '250.00',
  total: '250.00',
  due_date: '2026-09-30',
  blurb: '',
  scope_flags: [],
  sent_at: new Date('2026-09-01T12:00:00.000Z'),
  paid_at: null,
  stripe_checkout_session_id: 'cs_ach_1',
  stripe_card_session_id: 'cs_card_1',
  stripe_payment_intent_id: null,
  payment_method: null,
  email_log: [],
  created_at: new Date('2026-08-01T12:00:00.000Z'),
}

/**
 * `invoices` is the one table the bulk save wipes without re-inserting from the
 * payload — the other fourteen appear in both lists, this one only in the
 * deletes. It replaces the empty `invoice_drafts` placeholder, and unlike that
 * placeholder it holds real money: the first invoice Brittany generates would
 * be erased by the next owner autosave if the restore were ever dropped.
 *
 * The delete itself cannot simply go away: `invoices.client_id` is
 * `on delete restrict`, so `delete from clients` refuses to run while any
 * invoice exists. `write()` therefore snapshots the rows and puts them back.
 */
describe('bulk save preserves invoices (postgres branch)', () => {
  it('re-inserts a pre-existing invoice that the wipe removed', async () => {
    const fake = fakePostgres({ invoices: [existingInvoice] })
    await postgresStore(fake).write(workspace())

    const restored = insertedRows(fake.statements, 'invoices')
    expect(restored).toHaveLength(1)
    // Every column restored verbatim — a SENT invoice must come back exactly
    // as it was, not regenerated from current data. `kind` sits between the
    // number and the status; a fixture written before that column existed
    // restores as 'monthly', which is what it is.
    expect(restored[0]).toMatchObject({
      id: 'inv-1',
      client_id: 'c1',
      period: '2026-08',
      number: 'INV-2026-08-001',
      kind: 'monthly',
      status: 'sent',
      created_at: existingInvoice.created_at,
      sent_at: existingInvoice.sent_at,
    })
  })

  it('still deletes first — the clients wipe cannot run past the FK otherwise', async () => {
    const fake = fakePostgres({ invoices: [existingInvoice] })
    await postgresStore(fake).write(workspace())

    const deleteAt = fake.indexOf(/^delete from invoices$/i)
    const clientsWipedAt = fake.indexOf(/^delete from clients$/i)
    expect(deleteAt).toBeGreaterThan(-1)
    expect(deleteAt).toBeLessThan(clientsWipedAt)
  })

  it('restores AFTER the clients are back, so the FK is satisfied', async () => {
    const fake = fakePostgres({ invoices: [existingInvoice] })
    await postgresStore(fake).write(workspace())

    const clientInsertAt = fake.indexOf(/^insert into clients/i)
    const restoreAt = fake.indexOf(/^insert into invoices/i)
    expect(clientInsertAt).toBeGreaterThan(-1)
    expect(restoreAt).toBeGreaterThan(clientInsertAt)
  })

  it('drops an invoice whose client is gone from the payload', async () => {
    const fake = fakePostgres({
      invoices: [existingInvoice, { ...existingInvoice, id: 'inv-2', client_id: 'deleted' }],
    })
    await postgresStore(fake).write(workspace())

    const restoredIds = insertedRows(fake.statements, 'invoices').map((row) => row.id)
    expect(restoredIds).toEqual(['inv-1'])
  })
  it('issues no restore at all when there were no invoices', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).write(workspace())

    expect(fake.matching(/^insert into invoices/i)).toHaveLength(0)
  })

  /**
   * The card session id is the newest column on this table, and a column added
   * to the restore's INSERT but not to its snapshot SELECT (or the other way
   * round) loses the id silently. Losing it means the card link a client is
   * holding can never be expired when they pay by bank transfer — two live ways
   * to pay one invoice, which is the exact thing the sibling expiry prevents.
   */
  it('carries both channels’ session ids through the wipe', async () => {
    const fake = fakePostgres({ invoices: [existingInvoice] })
    await postgresStore(fake).write(workspace())

    const snapshot = fake.matching(/^select[\s\S]*from invoices$/i)[0]
    expect(snapshot.text).toMatch(/stripe_card_session_id/)

    const restore = fake.matching(/^insert into invoices/i)[0]
    expect(restore.text).toMatch(/stripe_card_session_id/)
    const [restored] = insertedRows(fake.statements, 'invoices')
    expect(restored.stripe_checkout_session_id).toBe('cs_ach_1')
    expect(restored.stripe_card_session_id).toBe('cs_card_1')
  })

  /**
   * THE PAY TOKEN'S BULK-SAVE GUARD, and the reason it is worth its own test.
   *
   * `pay_token` is the invoice's permanent public address: it is what the Pay
   * button in every email the client has ever received points at. Leave it out
   * of the snapshot select OR out of the restore insert and the very next owner
   * autosave writes it back as NULL — every emailed link starts answering "this
   * payment link is not valid", the invoice looks perfectly healthy in the app,
   * and nothing anywhere says what happened. That is the `email_log` bug again,
   * on a column that collects money.
   */
  it('carries the durable pay token through the wipe', async () => {
    const fake = fakePostgres({ invoices: [{ ...existingInvoice, pay_token: 'tok_durable_1' }] })
    await postgresStore(fake).write(workspace())

    const snapshot = fake.matching(/^select[\s\S]*from invoices$/i)[0]
    expect(snapshot.text).toMatch(/pay_token/)

    const restore = fake.matching(/^insert into invoices \(/i)[0]
    expect(restore.text).toMatch(/pay_token/)
    expect(insertedRows(fake.statements, 'invoices')[0].pay_token).toBe('tok_durable_1')
  })

  // The other half of the same contract: a column in the mapper but not in the
  // select reads as `undefined` on the row and the mapper turns it into a
  // plausible empty value. For this column that value is "no link exists".
  it('selects pay_token on every invoice read', () => {
    expect(INVOICE_SELECT_COLUMNS).toMatch(/pay_token/)
  })
})

/**
 * `getOrCreateInvoicePayToken` — the durable pay link's name for one invoice.
 *
 * The link in an email outlives the Stripe Checkout session it used to carry by
 * weeks, so the token behind it has to be STABLE: minted once, and the same
 * answer forever after. A method that re-minted would silently invalidate every
 * link already sent, and the only symptom would be a client saying the button
 * does not work.
 */
describe('getOrCreateInvoicePayToken (file backend)', () => {
  async function seedInvoice(overrides = {}) {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices = [
      {
        id: 'inv-token',
        clientId: 'c1',
        period: '2026-08',
        number: 'INV-2026-08-001',
        status: 'sent',
        lineItems: [{ kind: 'plan', label: 'Monthly service', detail: '', amount: 100 }],
        subtotal: 100,
        total: 100,
        dueDate: '2026-09-15',
        blurb: '',
        scopeFlags: [],
        sentAt: '2026-08-05T00:00:00.000Z',
        paidAt: null,
        paymentMethod: null,
        stripeCheckoutSessionId: 'cs_ach',
        stripeCardSessionId: null,
        emailLog: [],
        createdAt: '2026-08-01T00:00:00.000Z',
        updatedAt: '2026-08-01T00:00:00.000Z',
        ...overrides,
      },
    ]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
  }

  it('mints a base64url token and persists it', async () => {
    await seedInvoice()
    const token = await store.getOrCreateInvoicePayToken('inv-token')

    expect(token).toMatch(/^[A-Za-z0-9_-]{20,64}$/)
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    expect(data.invoices[0].payToken).toBe(token)
  })

  // The whole point. A second call is a second send, and the client is holding
  // the link the FIRST one produced.
  it('gives back the same token on every later call', async () => {
    await seedInvoice()
    const first = await store.getOrCreateInvoicePayToken('inv-token')
    const second = await store.getOrCreateInvoicePayToken('inv-token')
    expect(second).toBe(first)
  })

  it('answers null for an invoice that does not exist', async () => {
    await seedInvoice()
    expect(await store.getOrCreateInvoicePayToken('inv-nope')).toBeNull()
    expect(await store.getOrCreateInvoicePayToken('')).toBeNull()
  })

  it('reads back through listInvoices, as null when nothing was minted', async () => {
    await seedInvoice()
    const before = (await store.listInvoices()).find((invoice) => invoice.id === 'inv-token')
    // Null, never undefined — the shape Postgres answers for a row written
    // before the column existed (cardinal rule 1).
    expect(before.payToken).toBeNull()

    const token = await store.getOrCreateInvoicePayToken('inv-token')
    const after = (await store.listInvoices()).find((invoice) => invoice.id === 'inv-token')
    expect(after.payToken).toBe(token)
  })

  /**
   * The token must survive the two writes that touch an invoice after it is
   * sent. `applyInvoicePayment` runs on every webhook and on every pay-link
   * click; `updateInvoice` runs whenever she edits the note. Either one
   * dropping the field would kill the emailed link mid-month.
   */
  it('survives a payment write and an edit', async () => {
    await seedInvoice()
    const token = await store.getOrCreateInvoicePayToken('inv-token')

    const paid = await store.applyInvoicePayment('inv-token', { checkoutSessionId: 'cs_new' })
    expect(paid.payToken).toBe(token)

    const edited = await store.updateInvoice('inv-token', { blurb: 'Thanks!' })
    expect(edited.payToken).toBe(token)
  })

  /**
   * "Void and regenerate" is how a month gets corrected, and it happens after
   * links have been emailed. The token must still RESOLVE — to the voided row,
   * so the client gets "this invoice was canceled" rather than a dead page.
   */
  it('survives a void, and still names the voided invoice', async () => {
    await seedInvoice({ status: 'draft', sentAt: null })
    const token = await store.getOrCreateInvoicePayToken('inv-token')

    await store.voidUnsentInvoicesForPeriod('2026-08')

    const found = await store.findInvoiceByPayToken(token)
    expect(found?.id).toBe('inv-token')
    expect(found?.status).toBe('void')
  })
})

/**
 * `findInvoiceByPayToken` — the only way into an invoice from the public route.
 *
 * It answers with the invoice whatever state it is in, because the ROUTE is what
 * decides which page a client sees and it needs the status to do it. What it
 * must never do is match loosely: one client's token reaching another client's
 * invoice would show a stranger a bill and let them pay it.
 */
describe('findInvoiceByPayToken (file backend)', () => {
  async function seedTwo() {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    const base = {
      period: '2026-08',
      status: 'sent',
      lineItems: [{ kind: 'plan', label: 'Monthly service', detail: '', amount: 100 }],
      subtotal: 100,
      total: 100,
      dueDate: '2026-09-15',
      blurb: '',
      scopeFlags: [],
      sentAt: '2026-08-05T00:00:00.000Z',
      paidAt: null,
      emailLog: [],
      createdAt: '2026-08-01T00:00:00.000Z',
      updatedAt: '2026-08-01T00:00:00.000Z',
    }
    data.invoices = [
      { ...base, id: 'inv-a', clientId: 'c1', number: 'INV-2026-08-001' },
      { ...base, id: 'inv-b', clientId: 'c1', number: 'INV-2026-08-002' },
    ]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
  }

  it('round-trips the token it just minted', async () => {
    await seedTwo()
    const token = await store.getOrCreateInvoicePayToken('inv-a')
    const found = await store.findInvoiceByPayToken(token)
    expect(found?.id).toBe('inv-a')
  })

  it('does not answer with another invoice', async () => {
    await seedTwo()
    const tokenA = await store.getOrCreateInvoicePayToken('inv-a')
    const tokenB = await store.getOrCreateInvoicePayToken('inv-b')
    expect(tokenB).not.toBe(tokenA)
    expect((await store.findInvoiceByPayToken(tokenB))?.id).toBe('inv-b')
  })

  // An un-minted invoice has `payToken: null`. An empty or missing token must
  // never match it — that would hand `/pay/` the first unsent invoice it found.
  it('answers null for an unknown, empty or missing token', async () => {
    await seedTwo()
    expect(await store.findInvoiceByPayToken('nope_nope_nope')).toBeNull()
    expect(await store.findInvoiceByPayToken('')).toBeNull()
    expect(await store.findInvoiceByPayToken('   ')).toBeNull()
    expect(await store.findInvoiceByPayToken(null)).toBeNull()
    expect(await store.findInvoiceByPayToken(undefined)).toBeNull()
  })
})

/**
 * The POSTGRES half of the same two methods — the branch production runs.
 *
 * The statement shape IS the contract here: `coalesce(pay_token, $2)` in ONE
 * statement is what makes two sends racing (or a send racing a click) safe. A
 * read-then-write would let the second one overwrite a token that had already
 * been emailed.
 */
describe('the pay token statements (postgres branch)', () => {
  const row = { ...existingInvoice, pay_token: null }

  it('mints with a single coalescing update', async () => {
    const fake = fakePostgres({ invoices: [{ ...row }] })
    const token = await postgresStore(fake).getOrCreateInvoicePayToken('inv-1')

    expect(token).toMatch(/^[A-Za-z0-9_-]{20,64}$/)
    const update = fake.matching(/^update invoices[\s\S]*returning pay_token$/i)[0]
    expect(update).toBeTruthy()
    expect(update.text).toMatch(/coalesce\(pay_token/)
    expect(update.params[0]).toBe('inv-1')
  })

  it('answers the STORED token when there already is one', async () => {
    const fake = fakePostgres({ invoices: [{ ...row, pay_token: 'tok_already_here' }] })
    expect(await postgresStore(fake).getOrCreateInvoicePayToken('inv-1')).toBe('tok_already_here')
  })

  it('answers null when the update matched no row', async () => {
    const fake = fakePostgres({ invoices: [{ ...row }] })
    expect(await postgresStore(fake).getOrCreateInvoicePayToken('inv-missing')).toBeNull()
  })

  it('looks an invoice up by the column, not by scanning', async () => {
    const fake = fakePostgres({ invoices: [{ ...row, pay_token: 'tok_lookup' }] })
    const found = await postgresStore(fake).findInvoiceByPayToken('tok_lookup')

    expect(found?.id).toBe('inv-1')
    expect(found?.payToken).toBe('tok_lookup')
    expect(fake.matching(/where pay_token = \$1/i)).toHaveLength(1)
  })

  it('answers null for a token no row carries', async () => {
    const fake = fakePostgres({ invoices: [{ ...row, pay_token: 'tok_lookup' }] })
    expect(await postgresStore(fake).findInvoiceByPayToken('tok_other')).toBeNull()
  })

  // The token is the invoice's permanent name; asking for it again is a read.
  // Bumping `updated_at` on every send, click and copy would make the column
  // say the invoice was edited when nothing about it changed.
  it('leaves updated_at alone when the token is already there', async () => {
    const fake = fakePostgres({ invoices: [{ ...row, pay_token: 'tok_already_here' }] })
    await postgresStore(fake).getOrCreateInvoicePayToken('inv-1')

    const update = fake.matching(/^update invoices[\s\S]*returning pay_token$/i)[0]
    expect(update.text).toMatch(
      /updated_at = case when pay_token is null then now\(\) else updated_at end/i,
    )
  })
})

/**
 * `swapInvoiceCheckoutSession` — point an invoice at a NEW Stripe session and
 * hand back the id it replaced, in one write.
 *
 * THE BUG THIS EXISTS FOR. The pay link mints a fresh session on every open and
 * the route expires the one it supersedes. Taking that id off a snapshot read
 * BEFORE the mint is a race: two opens a second apart both see S0, mint SA and
 * SB, both write (last wins), and both expire S0 — leaving SA live and the
 * invoice payable twice, by two Stripe sessions, for one bill.
 *
 * So the ANSWER is the contract: whatever this call replaced, and never what
 * the caller thought was there.
 */
describe('swapInvoiceCheckoutSession (file backend)', () => {
  async function seed(overrides = {}) {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices = [
      {
        id: 'inv-swap',
        clientId: 'c1',
        period: '2026-08',
        number: 'INV-2026-08-001',
        status: 'sent',
        lineItems: [{ kind: 'plan', label: 'Monthly service', detail: '', amount: 100 }],
        subtotal: 100,
        total: 100,
        dueDate: '2026-09-15',
        blurb: '',
        scopeFlags: [],
        sentAt: '2026-08-05T00:00:00.000Z',
        paidAt: null,
        stripeCheckoutSessionId: 'cs_S0',
        stripeCardSessionId: null,
        emailLog: [],
        createdAt: '2026-08-01T00:00:00.000Z',
        updatedAt: '2026-08-01T00:00:00.000Z',
        ...overrides,
      },
    ]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
  }

  it('stores the new id and returns the one it replaced', async () => {
    await seed()
    const result = await store.swapInvoiceCheckoutSession('inv-swap', {
      channel: 'ach',
      sessionId: 'cs_SA',
    })

    expect(result.previous).toBe('cs_S0')
    expect(result.invoice.stripeCheckoutSessionId).toBe('cs_SA')
    const stored = (await store.listInvoices()).find((invoice) => invoice.id === 'inv-swap')
    expect(stored.stripeCheckoutSessionId).toBe('cs_SA')
  })

  // The whole point, spelled out: two in a row hand back S0 and then SA. A
  // method that answered off a pre-read snapshot would say S0 twice, and the
  // caller would leave SA live.
  it('two swaps in a row return S0 then SA', async () => {
    await seed()
    const first = await store.swapInvoiceCheckoutSession('inv-swap', {
      channel: 'ach',
      sessionId: 'cs_SA',
    })
    const second = await store.swapInvoiceCheckoutSession('inv-swap', {
      channel: 'ach',
      sessionId: 'cs_SB',
    })

    expect(first.previous).toBe('cs_S0')
    expect(second.previous).toBe('cs_SA')
  })

  // Two channels, two columns. A card swap must not retire the bank-transfer
  // session the same invoice is still offering.
  it('keeps the two channels apart', async () => {
    await seed({ stripeCardSessionId: 'cs_card_0' })
    const result = await store.swapInvoiceCheckoutSession('inv-swap', {
      channel: 'card',
      sessionId: 'cs_card_1',
    })

    expect(result.previous).toBe('cs_card_0')
    expect(result.invoice.stripeCardSessionId).toBe('cs_card_1')
    expect(result.invoice.stripeCheckoutSessionId).toBe('cs_S0')
  })

  // The Postgres branch answers the invoice through `listInvoices`; the file
  // branch has to hand back the same normalized shape (kind, applied-to, the
  // original lines and the pay token all present), not the raw stored row — the
  // payment-link route returns this invoice to the screen.
  it('returns the invoice in the shape listInvoices answers, not the raw row', async () => {
    await seed()
    const result = await store.swapInvoiceCheckoutSession('inv-swap', {
      channel: 'ach',
      sessionId: 'cs_SA',
    })
    const listed = (await store.listInvoices()).find((invoice) => invoice.id === 'inv-swap')

    expect(result.invoice).toEqual(listed)
    expect(result.invoice.kind).toBe('monthly')
    expect(result.invoice.appliedToInvoiceId).toBeNull()
    expect(result.invoice.originalLineItems).toBeNull()
    expect(result.invoice.payToken).toBeNull()
  })

  // Null, not undefined — an invoice that has never had a session has nothing
  // to expire, and the caller branches on exactly this.
  it('returns null previous when the channel was empty', async () => {
    await seed({ stripeCheckoutSessionId: null })
    const result = await store.swapInvoiceCheckoutSession('inv-swap', {
      channel: 'ach',
      sessionId: 'cs_SA',
    })
    expect(result.previous).toBeNull()
  })

  // The same refusal `applyInvoicePayment` makes: a late write must not revive
  // an invoice that was voided while we were talking to Stripe.
  it('refuses a voided invoice, and an invoice that is not there', async () => {
    await seed({ status: 'void' })
    expect(
      await store.swapInvoiceCheckoutSession('inv-swap', { channel: 'ach', sessionId: 'cs_SA' }),
    ).toBeNull()
    expect(
      await store.swapInvoiceCheckoutSession('inv-nope', { channel: 'ach', sessionId: 'cs_SA' }),
    ).toBeNull()
    expect(await store.swapInvoiceCheckoutSession('inv-swap', { channel: 'ach' })).toBeNull()
  })
})

describe('swapInvoiceCheckoutSession (postgres branch)', () => {
  const row = { ...existingInvoice, stripe_checkout_session_id: 'cs_S0' }

  it('returns the replaced id, and twice in a row returns S0 then SA', async () => {
    const fake = fakePostgres({ invoices: [{ ...row }] })
    const pg = postgresStore(fake)

    const first = await pg.swapInvoiceCheckoutSession('inv-1', {
      channel: 'ach',
      sessionId: 'cs_SA',
    })
    const second = await pg.swapInvoiceCheckoutSession('inv-1', {
      channel: 'ach',
      sessionId: 'cs_SB',
    })

    expect(first.previous).toBe('cs_S0')
    expect(second.previous).toBe('cs_SA')
  })

  /**
   * The statement shape IS the fix. `for update` inside the CTE takes the row
   * lock before the update reads it, so two concurrent swaps serialize and the
   * second one's `previous` is the first one's new id. A subquery inside
   * RETURNING would not be safe — it may be planned against the updated row.
   */
  it('reads the previous value through a locking CTE, never a RETURNING subquery', async () => {
    const fake = fakePostgres({ invoices: [{ ...row }] })
    await postgresStore(fake).swapInvoiceCheckoutSession('inv-1', {
      channel: 'ach',
      sessionId: 'cs_SA',
    })

    const [statement] = fake.matching(/^with prev as \(/i)
    expect(statement).toBeTruthy()
    expect(statement.text).toMatch(/for update/i)
    expect(statement.text).toMatch(/returning prev\.previous/i)
    expect(statement.text).toMatch(/set stripe_checkout_session_id = \$2/i)
    // A void invoice is refused in the WHERE, so the refusal survives a race
    // with "Void & regenerate" rather than being decided by a stale read.
    expect(statement.text).toMatch(/invoices\.status <> 'void'/i)
  })

  it('writes the card column for the card channel', async () => {
    const fake = fakePostgres({ invoices: [{ ...row, stripe_card_session_id: 'cs_card_0' }] })
    const result = await postgresStore(fake).swapInvoiceCheckoutSession('inv-1', {
      channel: 'card',
      sessionId: 'cs_card_1',
    })

    expect(result.previous).toBe('cs_card_0')
    expect(fake.matching(/set stripe_card_session_id = \$2/i)).toHaveLength(1)
  })

  it('answers null when the update matched no row', async () => {
    const fake = fakePostgres({ invoices: [{ ...row }] })
    expect(
      await postgresStore(fake).swapInvoiceCheckoutSession('inv-missing', {
        channel: 'ach',
        sessionId: 'cs_SA',
      }),
    ).toBeNull()
  })
})

/**
 * `recordInvoicePayLinkOpened` — the evidence behind "they say they never got
 * the invoice".
 *
 * Two rules, both of which exist because this is a DURABLE link rather than a
 * one-shot one. It must not mark the invoice sent (opening a link is not a
 * send), and it must not write a line every time a client reloads while
 * deciding — a log with forty identical entries is a log nobody reads.
 */
describe('recordInvoicePayLinkOpened (file backend)', () => {
  async function seedInvoice(overrides = {}) {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices = [
      {
        id: 'inv-open',
        clientId: 'c1',
        period: '2026-08',
        number: 'INV-2026-08-001',
        status: 'sent',
        lineItems: [{ kind: 'plan', label: 'Monthly service', detail: '', amount: 100 }],
        subtotal: 100,
        total: 100,
        dueDate: '2026-09-15',
        blurb: '',
        scopeFlags: [],
        sentAt: '2026-08-05T00:00:00.000Z',
        paidAt: null,
        emailLog: [],
        createdAt: '2026-08-01T00:00:00.000Z',
        updatedAt: '2026-08-01T00:00:00.000Z',
        ...overrides,
      },
    ]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
  }

  it('files one tagged entry, and only one per day', async () => {
    await seedInvoice()
    await store.recordInvoicePayLinkOpened('inv-open')
    await store.recordInvoicePayLinkOpened('inv-open')
    await store.recordInvoicePayLinkOpened('inv-open')

    const stored = (await store.listInvoices()).find((invoice) => invoice.id === 'inv-open')
    const opens = stored.emailLog.filter((entry) => entry.kind === 'link')
    expect(opens).toHaveLength(1)
    expect(opens[0].ok).toBe(true)
    expect(opens[0].subject).toBe('Payment link opened')
  })

  // A tagged entry is not a send: `recordInvoiceSent` only moves the status and
  // the sent date for an UNtagged one, and the UI's `latestInvoiceSend` skips
  // tagged entries for the same reason.
  it('moves neither the status nor the sent date', async () => {
    await seedInvoice({ status: 'overdue', sentAt: '2026-08-05T00:00:00.000Z' })
    await store.recordInvoicePayLinkOpened('inv-open')

    const stored = (await store.listInvoices()).find((invoice) => invoice.id === 'inv-open')
    expect(stored.status).toBe('overdue')
    expect(stored.sentAt).toBe('2026-08-05T00:00:00.000Z')
  })

  it('leaves the real sends in the log beside it', async () => {
    await seedInvoice()
    await store.recordInvoiceSent('inv-open', { to: ['a@example.com'], subject: 'Invoice' })
    await store.recordInvoicePayLinkOpened('inv-open')

    const stored = (await store.listInvoices()).find((invoice) => invoice.id === 'inv-open')
    expect(stored.emailLog).toHaveLength(2)
    expect(stored.emailLog[0].kind).toBeUndefined()
    expect(stored.emailLog[1].kind).toBe('link')
  })

  it('answers null for an invoice that does not exist', async () => {
    await seedInvoice()
    expect(await store.recordInvoicePayLinkOpened('inv-nope')).toBeNull()
  })
})

/**
 * The same method on Postgres, where the COST is the point: this runs on every
 * load of a public pay link, and it used to open with a full `listInvoices()`
 * scan before handing off to `recordInvoiceSent`, which scanned twice more —
 * three passes over every invoice the firm has ever issued, to answer a
 * question one row wide.
 */
describe('recordInvoicePayLinkOpened (postgres branch)', () => {
  const invoiceReads = (fake) => fake.matching(/^select\b[\s\S]*\bfrom invoices\b/i)

  it('opens with one row by id, not a scan', async () => {
    const fake = fakePostgres({ invoices: [existingInvoice] })
    const opened = await postgresStore(fake).recordInvoicePayLinkOpened('inv-1')

    const reads = invoiceReads(fake)
    expect(reads[0].text).toMatch(/from invoices where id = \$1$/)
    expect(reads[0].params).toEqual(['inv-1'])
    // That read, plus the void pre-check inside `recordInvoiceSent` — one full
    // scan on this path where there were three.
    expect(reads.filter((read) => /order by number/i.test(read.text))).toHaveLength(1)
    expect(reads).toHaveLength(2)
    expect(opened.id).toBe('inv-1')
  })

  // Tagged `link`, so nothing downstream can read an open as a send.
  it('files the open as a tagged entry that marks nothing sent', async () => {
    const fake = fakePostgres({ invoices: [existingInvoice] })
    await postgresStore(fake).recordInvoicePayLinkOpened('inv-1')

    const update = fake.matching(/^update invoices/i)[0]
    expect(JSON.parse(update.params[1])[0]).toMatchObject({
      kind: 'link',
      ok: true,
      subject: 'Payment link opened',
    })
    expect(update.params[2]).toBe(false)
  })

  it('answers null for an invoice that is not there, and writes nothing', async () => {
    const fake = fakePostgres({ invoices: [existingInvoice] })
    expect(await postgresStore(fake).recordInvoicePayLinkOpened('inv-nope')).toBeNull()
    expect(fake.matching(/^update invoices/i)).toHaveLength(0)
  })

  it('files nothing a second time on the same day', async () => {
    // 16:00Z is noon or 11 am Eastern: the firm's day whatever the zone offset.
    const today = firmToday()
    const fake = fakePostgres({
      invoices: [
        {
          ...existingInvoice,
          email_log: [
            { kind: 'link', ok: true, subject: 'Payment link opened', at: `${today}T16:00:00.000Z` },
          ],
        },
      ],
    })
    await postgresStore(fake).recordInvoicePayLinkOpened('inv-1')

    expect(fake.matching(/^update invoices/i)).toHaveLength(0)
  })
})

/**
 * `client_assignments` was the second, non-authoritative copy of a client's
 * assigned team. `write()` used to delete every row and rebuild it from
 * `assignedEmployeeIds`, which no UI had updated since the Assigned-team
 * control writes `assignedBookkeeperIds` — so each bulk save re-asserted a
 * stale team. Nothing reads the table now; nothing may write it.
 */
describe('bulk save leaves client_assignments alone (postgres branch)', () => {
  it('issues no client_assignments statement at all', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).write(
      workspace({
        clients: [{ id: 'c1', name: 'Acme', assignedBookkeeperIds: ['emp-1'] }],
      }),
    )

    expect(fake.matching(/client_assignments/i)).toEqual([])
  })

  it('still persists the assigned team to the clients row', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).write(
      workspace({
        clients: [{ id: 'c1', name: 'Acme', assignedBookkeeperIds: ['emp-1'] }],
      }),
    )

    expect(insertedRows(fake.statements, 'clients')[0].assigned_bookkeeper_ids).toEqual(['emp-1'])
  })
})

/**
 * `applyInvoicePayment` — the ONE path a webhook can take into an invoice.
 *
 * It was deliberately unable to touch money at all. The card fee forces one
 * exception: a client who pays by card is charged the invoice plus a fee, and
 * the invoice of record has to show what actually arrived or History, the month
 * run and the QBO export all disagree with the bank. The rules that make that
 * exception safe are what this pins — it can only ADD, it recomputes the totals
 * itself rather than trusting a caller, and it cannot add the same fee twice.
 *
 * File backend; the Postgres statement shapes are pinned separately below.
 */
describe('applyInvoicePayment and the card fee (file backend)', () => {
  const feeLine = {
    kind: 'card-fee',
    label: 'Card processing fee',
    detail: 'Paid by card',
    amount: 3.3,
  }

  async function seedInvoice(overrides = {}) {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices = [
      {
        id: 'inv-card',
        clientId: 'c1',
        period: '2026-08',
        number: 'INV-2026-08-001',
        status: 'sent',
        lineItems: [{ kind: 'plan', label: 'Monthly service', detail: '', amount: 100 }],
        subtotal: 100,
        total: 100,
        dueDate: '2026-09-15',
        blurb: '',
        scopeFlags: [],
        sentAt: '2026-08-05T00:00:00.000Z',
        paidAt: null,
        paymentMethod: null,
        stripeCheckoutSessionId: 'cs_ach',
        stripeCardSessionId: 'cs_card',
        createdAt: '2026-08-01T00:00:00.000Z',
        updatedAt: '2026-08-01T00:00:00.000Z',
        ...overrides,
      },
    ]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
  }

  it('appends the fee and recomputes the total when a card payment lands', async () => {
    await seedInvoice()

    const updated = await store.applyInvoicePayment('inv-card', {
      status: 'paid',
      paymentMethod: 'card',
      paidAt: '2026-08-20T00:00:00.000Z',
      appendLines: [feeLine],
    })

    expect(updated.lineItems).toHaveLength(2)
    expect(updated.lineItems[1]).toMatchObject({ kind: 'card-fee', amount: 3.3 })
    // Recomputed from the lines, not handed in by the caller.
    expect(updated.total).toBe(103.3)
    expect(updated.subtotal).toBe(103.3)
    expect(updated.status).toBe('paid')
  })

  // One card payment fires both `checkout.session.completed` and
  // `payment_intent.succeeded`. Two fee lines would be an overcharge on the record.
  it('does not append a second fee when the second event arrives', async () => {
    await seedInvoice()
    await store.applyInvoicePayment('inv-card', { status: 'processing', appendLines: [feeLine] })
    const updated = await store.applyInvoicePayment('inv-card', {
      status: 'paid',
      appendLines: [feeLine],
    })

    expect(updated.lineItems.filter((line) => line.kind === 'card-fee')).toHaveLength(1)
    expect(updated.total).toBe(103.3)
  })

  it('leaves an ACH payment’s lines and totals exactly as they were', async () => {
    await seedInvoice()

    const updated = await store.applyInvoicePayment('inv-card', {
      status: 'processing',
      checkoutSessionId: 'cs_ach',
      paymentIntentId: 'pi_1',
    })

    expect(updated.lineItems).toHaveLength(1)
    expect(updated.total).toBe(100)
    expect(updated.subtotal).toBe(100)
  })

  it('records the card session without disturbing the ACH one', async () => {
    await seedInvoice({ stripeCardSessionId: null })

    const updated = await store.applyInvoicePayment('inv-card', {
      cardCheckoutSessionId: 'cs_card_new',
    })

    expect(updated.stripeCardSessionId).toBe('cs_card_new')
    expect(updated.stripeCheckoutSessionId).toBe('cs_ach')
  })

  /**
   * `statusChanged` — the fact the webhook's client emails turn on.
   *
   * "The invoice is now paid" and "the invoice just became paid" are different
   * statements, and only the second one earns a receipt. Stripe replays events,
   * so without this a client can be thanked twice for one payment.
   */
  it('reports that the status moved', async () => {
    await seedInvoice()
    const updated = await store.applyInvoicePayment('inv-card', { status: 'processing' })
    expect(updated.statusChanged).toBe(true)
  })

  it('reports that a replay of the same status moved nothing', async () => {
    await seedInvoice({ status: 'processing' })
    const updated = await store.applyInvoicePayment('inv-card', { status: 'processing' })
    expect(updated.statusChanged).toBe(false)
  })

  // It is a fact about the WRITE, not a column. It must never reach the API as
  // though it were part of the invoice, nor land in the stored record.
  it('keeps statusChanged out of the JSON and off the stored row', async () => {
    await seedInvoice()
    const updated = await store.applyInvoicePayment('inv-card', { status: 'processing' })

    expect(JSON.parse(JSON.stringify(updated))).not.toHaveProperty('statusChanged')
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    expect(data.invoices[0]).not.toHaveProperty('statusChanged')
  })

  // The narrow-by-design rule still holds: this is not a way to edit an invoice.
  it('refuses to append anything to a voided invoice', async () => {
    await seedInvoice({ status: 'void' })

    const result = await store.applyInvoicePayment('inv-card', {
      status: 'paid',
      appendLines: [feeLine],
    })

    expect(result).toBeNull()
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    const stored = data.invoices.find((entry) => entry.id === 'inv-card')
    expect(stored.status).toBe('void')
    expect(stored.lineItems).toHaveLength(1)
    expect(stored.total).toBe(100)
  })
})

/**
 * The same contract's POSTGRES statement shapes — the branch production runs.
 *
 * The one worth naming: the money columns must be ABSENT from the update unless
 * a line was actually appended. Writing them on every payment event would turn
 * this into a read-modify-write over the lines, and an edit made between the
 * read and the update would be silently reverted by a webhook.
 */
describe('applyInvoicePayment statement shape (postgres branch)', () => {
  const row = {
    ...existingInvoice,
    id: 'inv-1',
    status: 'sent',
    line_items: [{ kind: 'plan', label: 'Monthly service', detail: '', amount: 100 }],
    subtotal: '100.00',
    total: '100.00',
  }

  it('leaves line_items out of the update when nothing was appended', async () => {
    const fake = fakePostgres({ invoices: [row] })
    await postgresStore(fake).applyInvoicePayment('inv-1', {
      status: 'processing',
      checkoutSessionId: 'cs_ach_1',
    })

    const update = fake.matching(/^update invoices/i)[0]
    // The SET clause, not the `returning` list (which names every column).
    expect(update.text.split(/\breturning\b/i)[0]).not.toMatch(/line_items/)
    expect(update.text).toMatch(/stripe_card_session_id/)
  })

  it('writes the recomputed lines and totals when a fee was appended', async () => {
    const fake = fakePostgres({ invoices: [row] })
    await postgresStore(fake).applyInvoicePayment('inv-1', {
      status: 'paid',
      appendLines: [{ kind: 'card-fee', label: 'Card processing fee', detail: '', amount: 3.3 }],
    })

    const update = fake.matching(/^update invoices/i)[0]
    expect(update.text).toMatch(/line_items = \$9::jsonb/)
    expect(update.text).toMatch(/subtotal = \$10/)
    expect(update.text).toMatch(/total = \$11/)
    expect(JSON.parse(update.params[8])).toHaveLength(2)
    expect(update.params[9]).toBe(103.3)
    expect(update.params[10]).toBe(103.3)
  })

  it('surfaces the transition on this branch too', async () => {
    const fake = fakePostgres({ invoices: [row] })
    const updated = await postgresStore(fake).applyInvoicePayment('inv-1', { status: 'paid' })
    expect(updated.statusChanged).toBe(true)
  })
})

/**
 * Every field the Add-client form collects must survive `createClient` and come
 * back on the next read. Client creation moved off the debounced bulk save onto
 * `POST /api/clients`, and the first version of that endpoint inserted twelve
 * of the thirty-three columns `write()` writes â€” so the monthly/annual rate,
 * the estimated role hours, the invoice preferences and the entire team
 * selection were entered on the form and silently thrown away.
 *
 * File backend (cardinal rule 1: the Postgres branch is the one production
 * runs, and is validated separately against real data with a rolled-back
 * transaction â€” HANDOFF section 4). What this pins is the contract both
 * branches implement: nothing the form sends is dropped.
 */
describe('createClient keeps every field the Add-client form sends (file backend)', () => {
  // `plan-1` has to EXIST for this suite to be about `createClient` at all.
  // A read materializes and can write back through the bulk save, which
  // resolves every client's plan references against the plans in the payload
  // and drops the ones that do not resolve — on BOTH backends since Store-7.
  // Without this the suite would be asserting that a reference to a plan
  // nobody has survives, which is the outage of 2026-06-17 asked for by name.
  beforeEach(async () => {
    await store.write(workspace({ plans: [{ id: 'plan-1', name: 'Monthly bookkeeping' }] }))
  })

  // Exactly what the ClientBuilder onCreate call emits with every input filled
  // in. The monthly and annual fields are mutually exclusive on the form
  // itself, but the store must not drop either one.
  const formValues = {
    name: 'Northwind Traders',
    contact: 'Dana Reyes',
    billingMode: 'subscription',
    hourlyRate: 125,
    planIds: ['plan-1'],
    contactIds: ['contact-1'],
    monthlyRate: 900,
    annualRate: 4800,
    annualBillingMonth: 7,
    estimatedBookkeeperHours: 12.5,
    estimatedAccountantHours: 4,
    estimatedCfoHours: 1.5,
    paymentTerms: 'Net 15',
    footerNote: 'Thanks for your business.',
    invoiceShowTimeBreakdown: false,
    invoiceHideInternalHours: false,
    invoiceGroupByCategory: true,
    cardPaymentsEnabled: true,
    platformInvoicingOptOut: true,
    lifecycleStage: 'proposal',
    assignedEmployeeIds: ['emp-1'],
  }

  it('returns the created record with every field intact', async () => {
    const created = await store.createClient(formValues)
    expect(created).toMatchObject(formValues)
    expect(created.id).toMatch(/^client-/)
  })

  it('reads every field back after the create', async () => {
    const created = await store.createClient(formValues)
    const data = await store.read()
    const stored = data.clients.find((c) => c.id === created.id)
    expect(stored).toBeTruthy()
    expect(stored).toMatchObject(formValues)
  })

  it('does not coerce a chosen-false invoice preference back to true', async () => {
    const created = await store.createClient(formValues)
    const data = await store.read()
    const stored = data.clients.find((c) => c.id === created.id)
    expect(stored.invoiceShowTimeBreakdown).toBe(false)
    expect(stored.invoiceHideInternalHours).toBe(false)
    expect(stored.invoiceGroupByCategory).toBe(true)
    // Same rule for the card toggle: chosen-true must not read back as the
    // default false, or a client would silently lose the option she gave them.
    expect(stored.cardPaymentsEnabled).toBe(true)
    // And for the opt-out, where reading back false is worse than losing an
    // option: it puts a client who is billed elsewhere back into the month run.
    expect(stored.platformInvoicingOptOut).toBe(true)
  })

  it('keeps the team selection in the field that drives client visibility', async () => {
    const created = await store.createClient(formValues)
    const data = await store.read()
    const stored = data.clients.find((c) => c.id === created.id)
    // Both names, one value. `assignedBookkeeperIds` is what
    // `visibleClientIdSet` reads; `assignedEmployeeIds` is its alias.
    expect(stored.assignedBookkeeperIds).toEqual(['emp-1'])
    expect(stored.assignedEmployeeIds).toEqual(['emp-1'])
  })

  it('still refuses a nameless client', async () => {
    expect(await store.createClient({ ...formValues, name: '   ' })).toBeNull()
  })
})

/**
 * The same contract on the POSTGRES branch â€” and the branch that was actually
 * broken. The file backend spreads the whole incoming object onto the record,
 * so it never lost a field; the Postgres insert named its columns explicitly
 * and named only twelve of them, which is why the fields vanished in
 * production and nowhere else.
 *
 * Driven through a fake pool rather than a live database, so what it pins is
 * the statement `createClient` issues: every field the form sends reaches a
 * column.
 */
describe('createClient writes every form field to Postgres', () => {
  // Same payload as the file-backend suite above.
  const formValues = {
    name: 'Northwind Traders',
    contact: 'Dana Reyes',
    billingMode: 'subscription',
    hourlyRate: 125,
    planIds: ['plan-1'],
    contactIds: ['contact-1'],
    monthlyRate: 900,
    annualRate: 4800,
    annualBillingMonth: 7,
    estimatedBookkeeperHours: 12.5,
    estimatedAccountantHours: 4,
    estimatedCfoHours: 1.5,
    paymentTerms: 'Net 15',
    footerNote: 'Thanks for your business.',
    invoiceShowTimeBreakdown: false,
    invoiceHideInternalHours: false,
    invoiceGroupByCategory: true,
    cardPaymentsEnabled: true,
    platformInvoicingOptOut: true,
    lifecycleStage: 'proposal',
    assignedEmployeeIds: ['emp-1'],
  }

  it('binds every column the form fills', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).createClient(formValues)

    const inserts = insertedRows(fake.statements, 'clients')
    expect(inserts).toHaveLength(1)
    expect(inserts[0]).toMatchObject({
      name: 'Northwind Traders',
      contact: 'Dana Reyes',
      billing_mode: 'subscription',
      hourly_rate: 125,
      plan_ids: ['plan-1'],
      contact_ids: ['contact-1'],
      monthly_rate: 900,
      annual_rate: 4800,
      annual_billing_month: 7,
      estimated_bookkeeper_hours: 12.5,
      estimated_accountant_hours: 4,
      estimated_cfo_hours: 1.5,
      payment_terms: 'Net 15',
      footer_note: 'Thanks for your business.',
      invoice_show_time_breakdown: false,
      invoice_hide_internal_hours: false,
      invoice_group_by_category: true,
      card_payments_enabled: true,
      platform_invoicing_opt_out: true,
      lifecycle_stage: 'proposal',
    })
  })

  it('does not touch client_assignments — the team lives on the client row', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).createClient(formValues)

    expect(fake.matching(/client_assignments/i)).toEqual([])
  })

  it('puts the team the form picked where visibility actually reads it', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).createClient(formValues)

    // `assignedEmployeeIds` is what the Add-client form sends. It used to land
    // ONLY in client_assignments while this column went in empty, so the team
    // just picked could not see the client (2026-08-13).
    const bound = insertedRows(fake.statements, 'clients')[0]
    expect(bound.assigned_bookkeeper_ids).toEqual(['emp-1'])
  })

  it('unions both inbound names without duplicating', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).createClient({
      ...formValues,
      assignedEmployeeIds: ['emp-1', 'emp-2'],
      assignedBookkeeperIds: ['emp-2', 'emp-3'],
    })

    const bound = insertedRows(fake.statements, 'clients')[0]
    expect([...bound.assigned_bookkeeper_ids].sort()).toEqual(['emp-1', 'emp-2', 'emp-3'])
  })

  it('leaves an unfilled optional column null rather than 0', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).createClient({ name: 'Bare Co', contact: 'Someone' })

    const bound = insertedRows(fake.statements, 'clients')[0]
    expect(bound.monthly_rate).toBeNull()
    expect(bound.annual_rate).toBeNull()
    expect(bound.annual_billing_month).toBeNull()
    expect(bound.estimated_bookkeeper_hours).toBeNull()
    expect(bound.lifecycle_stage).toBe('active')
  })

  it('refuses an unsafe pay URL instead of persisting it', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).createClient({
      name: 'Sketchy Co',
      contact: 'Someone',
      quickbooksPayUrl: 'javascript:alert(1)',
    })

    expect(insertedRows(fake.statements, 'clients')[0].quickbooks_pay_url).toBe('')
  })
})

/**
 * `setChecklistTemplateActive` — the write behind the assistant's one Tier 0
 * config action ("turn a switched-off recurring checklist back on"). A
 * switched-off recipe is one of the two historical causes of "my recurring
 * checklist stopped appearing", and the materializer skips it silently.
 *
 * Cardinal rule 1: both backends. The file branch is exercised end-to-end
 * below; the Postgres branch is pinned by the statement it emits.
 */
const templateWorkspace = () =>
  workspace({
    checklistTemplates: [
      {
        id: 'tmpl-off',
        title: 'Annual Reports',
        clientId: 'c1',
        assigneeId: 'emp-1',
        frequency: 'annually',
        nextDueDate: '2026-12-01',
        active: false,
        viewerIds: [],
        editorIds: [],
        stages: [
          {
            id: 'stage-1',
            name: 'Stage 1',
            assigneeId: 'emp-1',
            offsetDays: 0,
            viewerIds: [],
            editorIds: [],
            items: [{ id: 'ti-1', label: 'File the report' }],
          },
        ],
      },
    ],
  })

describe('setChecklistTemplateActive (file backend)', () => {
  beforeEach(async () => {
    await store.write(templateWorkspace())
  })

  it('switches a recurring checklist back on and persists it', async () => {
    const updated = await store.setChecklistTemplateActive('tmpl-off', true)
    expect(updated).toMatchObject({ id: 'tmpl-off', active: true })

    const persisted = JSON.parse(await readFile(localDataPath, 'utf8'))
    expect(persisted.checklistTemplates[0].active).toBe(true)
  })

  it('switches one back off again — the change is reversible', async () => {
    await store.setChecklistTemplateActive('tmpl-off', true)
    await store.setChecklistTemplateActive('tmpl-off', false)

    const persisted = JSON.parse(await readFile(localDataPath, 'utf8'))
    expect(persisted.checklistTemplates[0].active).toBe(false)
  })

  it('returns null for an unknown id without touching the file', async () => {
    const before = await readFile(localDataPath, 'utf8')
    expect(await store.setChecklistTemplateActive('tmpl-nope', true)).toBeNull()
    expect(await readFile(localDataPath, 'utf8')).toBe(before)
  })
})

/**
 * An owner can appear on a client's assigned team. It grants nothing — owners
 * see every client regardless — but the Clients-page team column shows who
 * works the account, and dropping owners from it silently misreported the team.
 * Implicit grants no longer exist at all: since the 2026-09-04 team/visibility
 * split, `grantClientVisibility` writes nothing and the checklist backfill is
 * off the read path, so ONLY an owner's explicit pick puts anyone on this list.
 * Being handed a task still lets you see the client — that is computed at read
 * time now (docs/plans/team-visibility-split-2026-09.md).
 */
describe('setClientAssignedTeam (file backend)', () => {
  beforeEach(async () => {
    await store.write(
      workspace({
        clients: [{ id: 'c1', name: 'Acme', assignedBookkeeperIds: [] }],
        employees: [
          { id: 'emp-1', name: 'Lisa', role: 'bookkeeper' },
          { id: 'owner-1', name: 'Brittany', role: 'Owner' },
        ],
      }),
    )
  })

  it('keeps an owner the user explicitly picked', async () => {
    const updated = await store.setClientAssignedTeam('c1', ['emp-1', 'owner-1'])
    expect(updated.assignedBookkeeperIds).toEqual(['emp-1', 'owner-1'])
  })

  it('still drops an id that is nobody', async () => {
    const updated = await store.setClientAssignedTeam('c1', ['emp-1', 'ghost-9'])
    expect(updated.assignedBookkeeperIds).toEqual(['emp-1'])
  })

  it('keeps the alias in step with what it stored', async () => {
    await store.setClientAssignedTeam('c1', ['emp-1', 'owner-1'])
    const data = await store.read()
    const client = data.clients.find((c) => c.id === 'c1')
    expect(client.assignedEmployeeIds).toEqual(client.assignedBookkeeperIds)
  })
})

/**
 * `setClientAssignedTeam` — the Postgres branch specifically. This is the one
 * behavior change in the batch that lives ONLY in Postgres: the id-validation
 * query used to be `select id from users where role <> 'owner'`; it is now the
 * bare `select id from users`, so an explicitly picked owner survives.
 *
 * The file backend can't regress this — it validates against the local
 * `employees` array, which was never role-filtered — so only a statement-level
 * Postgres test catches a reintroduced filter. If it regressed, the id-validation
 * query would come back empty, `safe` would become `[]`, and the update would
 * wipe the client's team, silently revoking visibility for every assigned
 * non-owner.
 */
describe('setClientAssignedTeam (postgres branch)', () => {
  const userRows = [{ id: 'emp-1' }, { id: 'owner-1' }]

  it('keeps an explicitly picked owner in the bound params', async () => {
    const fake = fakePostgres({ userRows })
    await postgresStore(fake).setClientAssignedTeam('c1', ['emp-1', 'owner-1'])

    const updates = fake.matching(/^update clients set assigned_bookkeeper_ids/i)
    expect(updates).toHaveLength(1)
    expect(updates[0].params).toEqual(['c1', ['emp-1', 'owner-1']])
  })

  it('still drops an id that belongs to nobody', async () => {
    const fake = fakePostgres({ userRows })
    await postgresStore(fake).setClientAssignedTeam('c1', ['emp-1', 'ghost-9'])

    const updates = fake.matching(/^update clients set assigned_bookkeeper_ids/i)
    expect(updates[0].params).toEqual(['c1', ['emp-1']])
  })
})

describe('setChecklistTemplateActive (postgres branch)', () => {
  it('updates the single row instead of rewriting the workspace', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).setChecklistTemplateActive('tmpl-off', true)

    const updates = fake.matching(/^update checklist_templates\s+set active/i)
    expect(updates).toHaveLength(1)
    expect(updates[0].params).toEqual(['tmpl-off', true])
    // A one-flag fix must never take the bulk-save path.
    expect(fake.matching(/^delete from clients/i)).toHaveLength(0)
  })

  it('coerces a truthy/falsy flag to a real boolean for the column', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).setChecklistTemplateActive('tmpl-off', 0)
    expect(fake.matching(/^update checklist_templates\s+set active/i)[0].params).toEqual([
      'tmpl-off',
      false,
    ])
  })
})

/**
 * `adjustSplitGroup` — re-dividing a split that already exists.
 *
 * Splitting used to be one-way: once time was divided the amounts were frozen,
 * and the only way to change them was to delete every slice and retype the
 * time. That is the firm owner's "still will not let me adjust my time entry
 * without losing the client split I chose".
 *
 * What this pins:
 *   - the group is replaced wholesale and keeps its SAME group id, so the raw
 *     data still shows one split rather than a trail of abandoned ones;
 *   - the block's `sessions` and envelope survive the adjustment — re-dividing
 *     the billing never rewrites what the timer recorded;
 *   - the total is ALLOWED to change (an adjustment is a correction), and going
 *     down to a single client is allowed too, unlike creating a split;
 *   - the new slices re-enter the approval queue as pending;
 *   - a refused adjustment (unknown group / nothing allocated) writes NOTHING.
 */
describe('adjustSplitGroup (file backend)', () => {
  const SESSIONS = [
    { startAt: '2026-07-03T13:00:00.000Z', endAt: '2026-07-03T13:40:00.000Z' },
    { startAt: '2026-07-03T14:00:00.000Z', endAt: '2026-07-03T14:20:00.000Z' },
  ]

  const slice = (id, clientId, minutes, overrides = {}) => ({
    id,
    employeeId: 'emp-1',
    clientId,
    isAdministrative: false,
    date: '2026-07-03',
    minutes,
    category: 'General',
    description: 'Payroll cleanup',
    billable: true,
    taskId: null,
    approvalStatus: 'approved',
    entryMethod: 'timer',
    startAt: SESSIONS[0].startAt,
    endAt: SESSIONS[1].endAt,
    sessions: SESSIONS,
    groupId: 'grp-live',
    groupClientIds: [],
    groupAllocation: 'custom',
    taskLabel: 'Payroll',
    ...overrides,
  })

  const seedGroup = async (slices, extraEntries = []) => {
    await store.write(
      workspace({
        clients: [
          { id: 'c1', name: 'Acme' },
          { id: 'c2', name: 'Globex' },
          { id: 'c3', name: 'Initech' },
        ],
        timeEntries: [...slices, ...extraEntries],
      }),
    )
  }

  const persisted = async () => JSON.parse(await readFile(localDataPath, 'utf8'))
  const grouped = async () =>
    (await persisted()).timeEntries.filter((entry) => entry.groupId === 'grp-live')

  it('replaces the whole group with the new distribution, under the same group id', async () => {
    await seedGroup([slice('s1', 'c1', 30), slice('s2', 'c2', 30)])

    const result = await store.adjustSplitGroup(
      'grp-live',
      [
        { clientId: 'c1', minutes: 45 },
        { clientId: 'c2', minutes: 15 },
      ],
      'owner-1',
      'custom',
    )

    expect(result.deletedIds.sort()).toEqual(['s1', 's2'])
    expect(result.groupId).toBe('grp-live')
    const rows = await grouped()
    expect(rows).toHaveLength(2)
    // Same group id — the split stays ONE group in the raw data.
    expect(rows.every((row) => row.groupId === 'grp-live')).toBe(true)
    expect(rows.every((row) => row.groupAllocation === 'custom')).toBe(true)
    expect(
      Object.fromEntries(rows.map((row) => [row.clientId, row.minutes])),
    ).toEqual({ c1: 45, c2: 15 })
    // The old rows are gone, not left behind double-counting.
    expect((await persisted()).timeEntries.some((row) => row.id === 's1')).toBe(false)
  })

  it('carries the sessions, envelope and description across untouched', async () => {
    await seedGroup([slice('s1', 'c1', 30), slice('s2', 'c2', 30)])

    const { created } = await store.adjustSplitGroup(
      'grp-live',
      [
        { clientId: 'c1', minutes: 20 },
        { clientId: 'c3', minutes: 40 },
      ],
      'owner-1',
      'custom',
    )

    for (const row of created) {
      // The point of the group: the original clock-in/out is the audit trail
      // and an adjustment must not rewrite it.
      expect(row.sessions).toEqual(SESSIONS)
      expect(row.startAt).toBe(SESSIONS[0].startAt)
      expect(row.endAt).toBe(SESSIONS[1].endAt)
      expect(row.description).toBe('Payroll cleanup')
      expect(row.date).toBe('2026-07-03')
      expect(row.employeeId).toBe('emp-1')
      expect(row.entryMethod).toBe('timer')
      expect(row.taskLabel).toBe('Payroll')
      expect(row.billable).toBe(true)
      expect(row.isAdministrative).toBe(false)
      // Copied, not shared — editing one slice can't corrupt a sibling.
      expect(row.sessions).not.toBe(SESSIONS)
    }
    expect(created.map((row) => row.clientId)).toEqual(['c1', 'c3'])
  })

  it('lets the TOTAL change — an adjustment is a correction, not a re-division', async () => {
    await seedGroup([slice('s1', 'c1', 20), slice('s2', 'c2', 20), slice('s3', 'c3', 20)])

    await store.adjustSplitGroup(
      'grp-live',
      [
        { clientId: 'c1', minutes: 15 },
        { clientId: 'c2', minutes: 15 },
      ],
      'owner-1',
      'even',
    )

    const rows = await grouped()
    expect(rows.reduce((sum, row) => sum + row.minutes, 0)).toBe(30)
    // The sessions still say 60 minutes were worked — that record is untouched.
    expect(rows[0].sessions).toEqual(SESSIONS)
  })

  it('adjusts down to ONE client — pulling a client back out of a split', async () => {
    await seedGroup([slice('s1', 'c1', 30), slice('s2', 'c2', 30)])

    const { created } = await store.adjustSplitGroup(
      'grp-live',
      [{ clientId: 'c1', minutes: 60 }],
      'owner-1',
      'custom',
    )

    expect(created).toHaveLength(1)
    expect(created[0]).toMatchObject({ clientId: 'c1', minutes: 60, groupId: 'grp-live' })
    expect(await grouped()).toHaveLength(1)
  })

  it('sends every adjusted slice back through approval', async () => {
    // Seeded APPROVED — an edit to approved time has to be re-approved rather
    // than keep its old sign-off, and an adjustment is an edit.
    await seedGroup([slice('s1', 'c1', 30), slice('s2', 'c2', 30)])

    const { created } = await store.adjustSplitGroup(
      'grp-live',
      [
        { clientId: 'c1', minutes: 25 },
        { clientId: 'c2', minutes: 35 },
      ],
      'owner-1',
      'custom',
    )
    expect(created.every((row) => row.approvalStatus === 'pending')).toBe(true)
  })

  it('leaves every OTHER entry alone', async () => {
    const other = slice('other-1', 'c3', 10, { id: 'other-1', groupId: undefined })
    await seedGroup([slice('s1', 'c1', 30), slice('s2', 'c2', 30)], [other])

    await store.adjustSplitGroup('grp-live', [{ clientId: 'c1', minutes: 60 }], 'owner-1', 'custom')

    const untouched = (await persisted()).timeEntries.find((row) => row.id === 'other-1')
    expect(untouched).toMatchObject({ clientId: 'c3', minutes: 10 })
  })

  it('records the adjustment in the activity log, old total → new total', async () => {
    await seedGroup([slice('s1', 'c1', 30), slice('s2', 'c2', 30)])
    // The activity log lives in its own file and is NOT reset between tests, so
    // measure the delta rather than the absolute count.
    const adjustRows = async () => {
      if (!existsSync(localAuthPath)) return []
      const auth = JSON.parse(await readFile(localAuthPath, 'utf8'))
      return (auth.activityLog ?? []).filter((row) => row.action === 'time_entry_split_adjusted')
    }
    const before = await adjustRows()

    await store.adjustSplitGroup(
      'grp-live',
      [
        { clientId: 'c1', minutes: 45 },
        { clientId: 'c2', minutes: 45 },
      ],
      'owner-1',
      'full',
    )

    const after = await adjustRows()
    expect(after).toHaveLength(before.length + 1)
    const logged = after[after.length - 1]
    expect(logged.userId).toBe('owner-1')
    expect(logged.target).toContain('Payroll cleanup')
    expect(logged.target).toContain('2 clients')
    expect(logged.target).toContain('1h → 1.5h')
  })

  it('fails cleanly on an unknown group and writes NOTHING', async () => {
    await seedGroup([slice('s1', 'c1', 30), slice('s2', 'c2', 30)])
    const before = await persisted()

    await expect(
      store.adjustSplitGroup('grp-gone', [{ clientId: 'c1', minutes: 30 }], 'owner-1', 'custom'),
    ).rejects.toMatchObject({ code: 'not_found' })

    expect(await persisted()).toEqual(before)
  })

  it('refuses an empty allocation and writes NOTHING', async () => {
    await seedGroup([slice('s1', 'c1', 30), slice('s2', 'c2', 30)])
    const before = await persisted()

    await expect(
      store.adjustSplitGroup('grp-live', [], 'owner-1', 'custom'),
    ).rejects.toMatchObject({ code: 'invalid_allocation' })
    await expect(
      store.adjustSplitGroup('grp-live', [{ clientId: 'c1', minutes: 0 }], 'owner-1', 'custom'),
    ).rejects.toMatchObject({ code: 'invalid_allocation' })

    expect(await persisted()).toEqual(before)
  })
})

/**
 * The Postgres branch of the same call. Cardinal rule 1: both backends have to
 * implement the contract, and production is Postgres — so pin the statements
 * this branch issues (one delete of the whole group, one insert per new slice
 * carrying the SAME group id, and the audit row) rather than trusting that the
 * file-backend suite above covers it.
 */
describe('adjustSplitGroup (postgres branch)', () => {
  const row = (id, clientId, minutes) => ({
    id,
    user_id: 'emp-1',
    client_id: clientId,
    entry_date: new Date('2026-07-03T00:00:00.000Z'),
    minutes,
    category: 'General',
    description: 'Payroll cleanup',
    billable: true,
    entry_method: 'timer',
    manual_reason: null,
    started_at: new Date('2026-07-03T13:00:00.000Z'),
    ended_at: new Date('2026-07-03T14:00:00.000Z'),
    sessions: [{ startAt: '2026-07-03T13:00:00.000Z', endAt: '2026-07-03T14:00:00.000Z' }],
    task_label: 'Payroll',
  })

  it('deletes the group once and re-inserts it under the same group id', async () => {
    const fake = fakePostgres({ groupSlices: [row('s1', 'c1', 30), row('s2', 'c2', 30)] })
    const result = await postgresStore(fake).adjustSplitGroup(
      'grp-live',
      [
        { clientId: 'c1', minutes: 45 },
        { clientId: 'c3', minutes: 15 },
      ],
      'owner-1',
      'custom',
    )

    expect(fake.matching(/^select\b[\s\S]*for update$/i)).toHaveLength(1)
    const deletes = fake.matching(/^delete from time_entries where group_id/i)
    expect(deletes).toHaveLength(1)
    expect(deletes[0].params).toEqual(['grp-live'])

    const inserts = insertedRows(fake.statements, 'time_entries')
    expect(inserts).toHaveLength(2)
    // group_id ($18) is the same one, and it is set on every new slice.
    expect(inserts.map((row) => row.group_id)).toEqual(['grp-live', 'grp-live'])
    expect(inserts.map((row) => row.client_id)).toEqual(['c1', 'c3'])
    expect(inserts.map((row) => row.minutes)).toEqual([45, 15])
    // approval_status ($10): back in the queue.
    expect(inserts.map((row) => row.approval_status)).toEqual(['pending', 'pending'])
    // sessions ($17) carried across verbatim as JSON.
    expect(JSON.parse(inserts[0].sessions)).toEqual(row('s1', 'c1', 30).sessions)

    const audit = fake.matching(/^insert into activity_log/i)
    expect(audit).toHaveLength(1)
    expect(audit[0].params[2]).toBe('time_entry_split_adjusted')
    expect(audit[0].params[3]).toContain('1h → 1h')
    expect(fake.matching(/^commit$/i)).toHaveLength(1)
    expect(result.deletedIds).toEqual(['s1', 's2'])
  })

  it('rolls back and reports not_found when the group is gone', async () => {
    const fake = fakePostgres({ groupSlices: [] })
    await expect(
      postgresStore(fake).adjustSplitGroup(
        'grp-gone',
        [{ clientId: 'c1', minutes: 30 }],
        'owner-1',
        'custom',
      ),
    ).rejects.toMatchObject({ code: 'not_found' })

    expect(fake.matching(/^rollback$/i)).toHaveLength(1)
    expect(fake.matching(/^insert into time_entries/i)).toHaveLength(0)
    expect(fake.matching(/^commit$/i)).toHaveLength(0)
  })
})

/**
 * Split shares keep the source's task and clock in/out (Brittany, 2026-09-23:
 * split rows exported with no Clock in / Clock out and the task "Unassigned").
 *
 * What this pins, on BOTH backends (cardinal rule 1):
 *   - a share's minutes are its ALLOCATION even though it carries the whole
 *     block's start/stop. A 9.5-minute share of a 19-minute block reads back
 *     as 9.5, never 19 (the 08-14 day-total fix);
 *   - a checklist task stays on the share billed to its own client, and every
 *     other share carries the task's title as its free-text label, because a
 *     checklist belongs to one client and the endpoints refuse a cross-client
 *     task id;
 *   - an adjustment keeps doing the same for the new distribution.
 */
describe('split shares keep the task and clock in/out (file backend)', () => {
  const START = '2026-08-12T13:00:00.000Z'
  const STOP = '2026-08-12T13:19:00.000Z'
  const ENVELOPE = [{ startAt: START, endAt: STOP }]
  const CHECKLIST = {
    id: 'task-close',
    clientId: 'c1',
    title: 'Monthly close',
    assigneeId: 'emp-1',
    dueDate: '2026-08-31',
    items: [],
  }

  const persisted = async () => JSON.parse(await readFile(localDataPath, 'utf8'))

  const seed = async (timeEntries) => {
    await store.write(
      workspace({
        clients: [
          { id: 'c1', name: 'Acme' },
          { id: 'c2', name: 'Globex' },
          { id: 'c3', name: 'Initech' },
        ],
        checklists: [CHECKLIST],
        timeEntries,
      }),
    )
  }

  it('reads a 9.5-minute share of a 19-minute block back as 9.5, through a bulk save too', async () => {
    await seed([])
    const created = await store.createTimeEntry({
      employeeId: 'emp-1',
      clientId: 'c1',
      isAdministrative: false,
      date: '2026-08-12',
      minutes: 9.5,
      description: 'Month-end close for both books.',
      billable: true,
      taskId: null,
      taskLabel: 'Monthly close',
      entryMethod: 'manual',
      manualReason: 'Worked offline.',
      startAt: START,
      endAt: STOP,
      sessions: ENVELOPE,
      groupId: 'grp-manual',
    })
    expect(created.minutes).toBe(9.5)

    const stored = (await persisted()).timeEntries.find((entry) => entry.id === created.id)
    expect(stored.minutes).toBe(9.5)
    expect(stored.startAt).toBe(START)
    expect(stored.endAt).toBe(STOP)
    expect(stored.sessions).toEqual(ENVELOPE)
    expect(stored.taskLabel).toBe('Monthly close')

    // An owner tab's bulk save re-writes every entry; the share must survive it.
    const current = await store.read()
    await store.write(current)
    const afterSave = (await persisted()).timeEntries.find((entry) => entry.id === created.id)
    expect(afterSave.minutes).toBe(9.5)
    expect(afterSave.sessions).toEqual(ENVELOPE)
  })

  it('keeps a checklist task on its own client share and names it on the others', async () => {
    await seed([
      {
        id: 'reg-task',
        employeeId: 'emp-1',
        clientId: 'c1',
        isAdministrative: false,
        date: '2026-08-12',
        minutes: 19,
        category: 'General',
        description: 'Month-end close',
        billable: true,
        taskId: 'task-close',
        approvalStatus: 'approved',
        entryMethod: 'timer',
        startAt: START,
        endAt: STOP,
        sessions: ENVELOPE,
        groupClientIds: [],
      },
    ])

    const { created } = await store.splitTimeEntry(
      'reg-task',
      [
        { clientId: 'c1', minutes: 9.5 },
        { clientId: 'c2', minutes: 9.5 },
      ],
      'owner-1',
      'grp-task',
      'even',
    )

    const byClient = Object.fromEntries(created.map((share) => [share.clientId, share]))
    expect(byClient.c1.taskId).toBe('task-close')
    expect(byClient.c1.taskLabel).toBeUndefined()
    expect(byClient.c2.taskId).toBeNull()
    expect(byClient.c2.taskLabel).toBe('Monthly close')
    for (const share of created) {
      expect(share.minutes).toBe(9.5)
      expect(share.sessions).toEqual(ENVELOPE)
      expect(share.startAt).toBe(START)
    }
    const stored = (await persisted()).timeEntries.filter((entry) => entry.groupId === 'grp-task')
    expect(stored.map((entry) => [entry.clientId, entry.taskId, entry.taskLabel ?? null]).sort()).toEqual([
      ['c1', 'task-close', null],
      ['c2', null, 'Monthly close'],
    ])
  })

  it('carries a typed task name onto every share', async () => {
    await seed([
      {
        id: 'reg-label',
        employeeId: 'emp-1',
        clientId: 'c1',
        isAdministrative: false,
        date: '2026-08-12',
        minutes: 19,
        category: 'General',
        description: 'Payroll run',
        billable: true,
        taskId: null,
        taskLabel: 'Payroll',
        approvalStatus: 'approved',
        entryMethod: 'manual',
        manualReason: 'Worked offline.',
        startAt: START,
        endAt: STOP,
        sessions: ENVELOPE,
        groupClientIds: [],
      },
    ])
    const { created } = await store.splitTimeEntry(
      'reg-label',
      [
        { clientId: 'c1', minutes: 9.5 },
        { clientId: 'c2', minutes: 9.5 },
      ],
      'owner-1',
      'grp-label',
      'even',
    )
    for (const share of created) {
      expect(share.taskId).toBeNull()
      expect(share.taskLabel).toBe('Payroll')
    }
  })

  it('moves the checklist task with its client when a split is adjusted', async () => {
    const share = (id, clientId, overrides) => ({
      id,
      employeeId: 'emp-1',
      clientId,
      isAdministrative: false,
      date: '2026-08-12',
      minutes: 9.5,
      category: 'General',
      description: 'Month-end close',
      billable: true,
      approvalStatus: 'approved',
      entryMethod: 'timer',
      startAt: START,
      endAt: STOP,
      sessions: ENVELOPE,
      groupId: 'grp-adj',
      groupClientIds: [],
      groupAllocation: 'even',
      ...overrides,
    })
    // The first share (the adjustment's template) is the OTHER client's, so
    // the task has to be found on whichever share kept it.
    await seed([
      share('s2', 'c2', { taskId: null, taskLabel: 'Monthly close' }),
      share('s1', 'c1', { taskId: 'task-close' }),
    ])

    const { created } = await store.adjustSplitGroup(
      'grp-adj',
      [
        { clientId: 'c1', minutes: 12 },
        { clientId: 'c3', minutes: 7 },
      ],
      'owner-1',
      'custom',
    )
    const byClient = Object.fromEntries(created.map((each) => [each.clientId, each]))
    expect(byClient.c1.taskId).toBe('task-close')
    expect(byClient.c1.taskLabel).toBeUndefined()
    expect(byClient.c3.taskId).toBeNull()
    expect(byClient.c3.taskLabel).toBe('Monthly close')
    expect(byClient.c1.minutes).toBe(12)
    expect(byClient.c3.minutes).toBe(7)
    for (const each of created) expect(each.sessions).toEqual(ENVELOPE)
  })

  it('keeps each client its own task when an adjustment re-divides a split', async () => {
    // After splitting a timer block the owner set a DIFFERENT checklist on each
    // share. Re-dividing the minutes must not relabel one client's share with
    // the other client's task; only a newly added client gets a fallback.
    const share = (id, clientId, overrides) => ({
      id,
      employeeId: 'emp-1',
      clientId,
      isAdministrative: false,
      date: '2026-08-12',
      minutes: 9.5,
      category: 'General',
      description: 'Month-end close',
      billable: true,
      approvalStatus: 'approved',
      entryMethod: 'timer',
      startAt: START,
      endAt: STOP,
      sessions: ENVELOPE,
      groupId: 'grp-own',
      groupClientIds: [],
      groupAllocation: 'even',
      ...overrides,
    })
    await store.write(
      workspace({
        clients: [
          { id: 'c1', name: 'Acme' },
          { id: 'c2', name: 'Globex' },
          { id: 'c3', name: 'Initech' },
        ],
        checklists: [
          CHECKLIST,
          { ...CHECKLIST, id: 'task-payroll', clientId: 'c2', title: 'Payroll' },
        ],
        timeEntries: [
          share('s1', 'c1', { taskId: 'task-close' }),
          share('s2', 'c2', { taskId: 'task-payroll' }),
        ],
      }),
    )

    const { created } = await store.adjustSplitGroup(
      'grp-own',
      [
        { clientId: 'c1', minutes: 5 },
        { clientId: 'c2', minutes: 10 },
        { clientId: 'c3', minutes: 4 },
      ],
      'owner-1',
      'custom',
    )
    const byClient = Object.fromEntries(created.map((each) => [each.clientId, each]))
    expect(byClient.c1.taskId).toBe('task-close')
    expect(byClient.c1.taskLabel).toBeUndefined()
    expect(byClient.c2.taskId).toBe('task-payroll')
    expect(byClient.c2.taskLabel).toBeUndefined()
    // New to the split: the group's task (the first share that kept one), by name.
    expect(byClient.c3.taskId).toBeNull()
    expect(byClient.c3.taskLabel).toBe('Monthly close')
  })

  it('keeps a typed per-client task name through an adjustment', async () => {
    await seed([
      {
        id: 's1',
        employeeId: 'emp-1',
        clientId: 'c1',
        isAdministrative: false,
        date: '2026-08-12',
        minutes: 9.5,
        category: 'General',
        description: 'Month-end close',
        billable: true,
        taskId: null,
        taskLabel: 'Bank reconciliation',
        approvalStatus: 'approved',
        entryMethod: 'manual',
        manualReason: 'Worked offline.',
        startAt: START,
        endAt: STOP,
        sessions: ENVELOPE,
        groupId: 'grp-typed',
        groupClientIds: [],
        groupAllocation: 'even',
      },
      {
        id: 's2',
        employeeId: 'emp-1',
        clientId: 'c2',
        isAdministrative: false,
        date: '2026-08-12',
        minutes: 9.5,
        category: 'General',
        description: 'Month-end close',
        billable: true,
        taskId: null,
        taskLabel: 'Payroll',
        approvalStatus: 'approved',
        entryMethod: 'manual',
        manualReason: 'Worked offline.',
        startAt: START,
        endAt: STOP,
        sessions: ENVELOPE,
        groupId: 'grp-typed',
        groupClientIds: [],
        groupAllocation: 'even',
      },
    ])
    const { created } = await store.adjustSplitGroup(
      'grp-typed',
      [
        { clientId: 'c2', minutes: 12 },
        { clientId: 'c1', minutes: 7 },
      ],
      'owner-1',
      'custom',
    )
    const byClient = Object.fromEntries(created.map((each) => [each.clientId, each]))
    expect(byClient.c1.taskLabel).toBe('Bank reconciliation')
    expect(byClient.c2.taskLabel).toBe('Payroll')
  })
})

/**
 * The Postgres half of the same contract: what the split transaction inserts.
 * Insert parameters: $5 minutes, $9 task_id, $15 started_at, $16 ended_at,
 * $17 sessions, $21 task_label.
 */
describe('split shares keep the task and clock in/out (postgres branch)', () => {
  const START = '2026-08-12T13:00:00.000Z'
  const STOP = '2026-08-12T13:19:00.000Z'
  const CHECKLIST_ROW = { id: 'task-close', client_id: 'c1', title: 'Monthly close' }

  const sourceRow = (overrides = {}) => ({
    id: 'reg-task',
    user_id: 'emp-1',
    client_id: 'c1',
    entry_date: new Date('2026-08-12T00:00:00.000Z'),
    minutes: 19,
    category: 'General',
    description: 'Month-end close',
    billable: true,
    entry_method: 'timer',
    manual_reason: null,
    is_administrative: false,
    is_adhoc: false,
    started_at: new Date(START),
    ended_at: new Date(STOP),
    sessions: [{ startAt: START, endAt: STOP }],
    group_client_ids: [],
    task_label: null,
    task_id: 'task-close',
    ...overrides,
  })

  it('inserts a 9.5-minute share with the block span as 9.5 (createTimeEntry)', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).createTimeEntry({
      employeeId: 'emp-1',
      clientId: 'c1',
      isAdministrative: false,
      date: '2026-08-12',
      minutes: 9.5,
      description: 'Month-end close for both books.',
      billable: true,
      taskId: null,
      taskLabel: 'Monthly close',
      entryMethod: 'manual',
      manualReason: 'Worked offline.',
      startAt: START,
      endAt: STOP,
      sessions: [{ startAt: START, endAt: STOP }],
      groupId: 'grp-manual',
    })
    const [insert] = insertedRows(fake.statements, 'time_entries')
    expect(insert.minutes).toBe(9.5)
    expect(insert.started_at).toBe(START)
    expect(insert.ended_at).toBe(STOP)
    expect(JSON.parse(insert.sessions)).toEqual([{ startAt: START, endAt: STOP }])
    expect(insert.task_label).toBe('Monthly close')
  })

  it('splitTimeEntry keeps the checklist on its own client and names it on the others', async () => {
    const fake = fakePostgres({ holdingRows: [sourceRow()], checklistRows: [CHECKLIST_ROW] })
    await postgresStore(fake).splitTimeEntry(
      'reg-task',
      [
        { clientId: 'c1', minutes: 9.5 },
        { clientId: 'c2', minutes: 9.5 },
      ],
      'owner-1',
      'grp-task',
      'even',
    )

    expect(fake.matching(/^select id, client_id, title from checklists where id = \$1$/i)).toHaveLength(1)
    const inserts = insertedRows(fake.statements, 'time_entries')
    expect(inserts.map((row) => row.client_id)).toEqual(['c1', 'c2'])
    expect(inserts.map((row) => row.task_id)).toEqual(['task-close', null])
    expect(inserts.map((row) => row.task_label)).toEqual([null, 'Monthly close'])
    // Allocation minutes, whole-block span.
    expect(inserts.map((row) => row.minutes)).toEqual([9.5, 9.5])
    for (const each of inserts) {
      expect(each.started_at).toBe(START)
      expect(each.ended_at).toBe(STOP)
      expect(JSON.parse(each.sessions)).toEqual([{ startAt: START, endAt: STOP }])
    }
    expect(fake.matching(/^commit$/i)).toHaveLength(1)
  })

  it('splitTimeEntry carries a typed task name onto every share without a checklist read', async () => {
    const fake = fakePostgres({
      holdingRows: [sourceRow({ task_id: null, task_label: 'Payroll' })],
    })
    await postgresStore(fake).splitTimeEntry(
      'reg-task',
      [
        { clientId: 'c1', minutes: 9.5 },
        { clientId: 'c2', minutes: 9.5 },
      ],
      'owner-1',
      'grp-label',
      'even',
    )
    expect(fake.matching(/from checklists/i)).toHaveLength(0)
    const inserts = insertedRows(fake.statements, 'time_entries')
    expect(inserts.map((row) => row.task_id)).toEqual([null, null])
    expect(inserts.map((row) => row.task_label)).toEqual(['Payroll', 'Payroll'])
  })

  it('adjustSplitGroup finds the task on whichever share kept it', async () => {
    const groupRow = (id, clientId, overrides) =>
      sourceRow({ id, client_id: clientId, minutes: 9.5, ...overrides })
    const fake = fakePostgres({
      groupSlices: [
        groupRow('s2', 'c2', { task_id: null, task_label: 'Monthly close' }),
        groupRow('s1', 'c1', { task_id: 'task-close', task_label: null }),
      ],
      checklistRows: [CHECKLIST_ROW],
    })
    await postgresStore(fake).adjustSplitGroup(
      'grp-adj',
      [
        { clientId: 'c3', minutes: 7 },
        { clientId: 'c1', minutes: 12 },
      ],
      'owner-1',
      'custom',
    )
    const inserts = insertedRows(fake.statements, 'time_entries')
    expect(inserts.map((row) => row.client_id)).toEqual(['c3', 'c1'])
    expect(inserts.map((row) => row.task_id)).toEqual([null, 'task-close'])
    expect(inserts.map((row) => row.task_label)).toEqual(['Monthly close', null])
    expect(inserts.map((row) => row.minutes)).toEqual([7, 12])
  })

  it('adjustSplitGroup keeps each client its own task and falls back only for a new client', async () => {
    const groupRow = (id, clientId, overrides) =>
      sourceRow({ id, client_id: clientId, minutes: 9.5, ...overrides })
    const fake = fakePostgres({
      groupSlices: [
        groupRow('s1', 'c1', { task_id: 'task-close', task_label: null }),
        groupRow('s2', 'c2', { task_id: 'task-payroll', task_label: null }),
      ],
      checklistRows: [CHECKLIST_ROW, { id: 'task-payroll', client_id: 'c2', title: 'Payroll' }],
    })
    await postgresStore(fake).adjustSplitGroup(
      'grp-own',
      [
        { clientId: 'c2', minutes: 10 },
        { clientId: 'c1', minutes: 5 },
        { clientId: 'c3', minutes: 4 },
      ],
      'owner-1',
      'custom',
    )
    const inserts = insertedRows(fake.statements, 'time_entries')
    expect(inserts.map((row) => row.client_id)).toEqual(['c2', 'c1', 'c3'])
    expect(inserts.map((row) => row.task_id)).toEqual(['task-payroll', 'task-close', null])
    expect(inserts.map((row) => row.task_label)).toEqual([null, null, 'Monthly close'])
    expect(inserts.map((row) => row.minutes)).toEqual([10, 5, 4])
  })
})

/**
 * `recordInvoiceSent` — the append-only send log behind I4 (emailing an
 * invoice).
 *
 * Invoices sit deliberately outside the workspace bulk save, so they are seeded
 * straight into the file the store reads rather than through `write()`.
 *
 * File backend (cardinal rule 1: Postgres is the branch production runs, and is
 * validated separately against real data with a rolled-back transaction —
 * HANDOFF section 4). What this pins is the contract both branches implement: a
 * failed attempt is kept but never claims the invoice was sent, `sentAt` holds
 * the FIRST send because that is when the payment clock started, and the entry
 * records what was billed at the time.
 */
describe('recordInvoiceSent (file backend)', () => {
  const seedInvoice = {
    id: 'inv-1',
    clientId: 'c1',
    period: '2026-08',
    number: '1042',
    status: 'reviewed',
    lineItems: [{ kind: 'custom', label: 'Bookkeeping', detail: '', amount: 400 }],
    subtotal: 400,
    total: 400,
    dueDate: '2026-09-15',
    blurb: '',
    scopeFlags: [],
    sentAt: null,
    paidAt: null,
    paymentMethod: null,
    createdAt: '2026-08-01T00:00:00.000Z',
    updatedAt: '2026-08-01T00:00:00.000Z',
  }

  async function seed(overrides = {}) {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices = [{ ...seedInvoice, ...overrides }]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
  }

  it('logs a failed attempt without claiming the invoice was sent', async () => {
    await seed()
    const updated = await store.recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice 1042',
      ok: false,
      error: 'The domain is not verified.',
    })

    expect(updated.emailLog).toHaveLength(1)
    expect(updated.emailLog[0]).toMatchObject({
      ok: false,
      error: 'The domain is not verified.',
      to: ['ann@acme.com'],
    })
    // The two fields that would tell Brittany a failed send succeeded.
    expect(updated.sentAt).toBeNull()
    expect(updated.status).toBe('reviewed')
  })

  it('keeps every attempt and flips the status on a successful send', async () => {
    await seed()
    await store.recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice 1042',
      ok: true,
    })
    const second = await store.recordInvoiceSent('inv-1', {
      to: ['ann@acme.com', 'ap@acme.com'],
      subject: 'Invoice 1042',
      ok: true,
    })

    expect(second.emailLog).toHaveLength(2)
    expect(second.status).toBe('sent')
    expect(second.sentAt).toBe(second.emailLog[0].at)
    expect(second.emailLog[1].to).toEqual(['ann@acme.com', 'ap@acme.com'])
  })

  it('leaves an earlier sentAt alone on a re-send', async () => {
    // Seeded rather than sent twice in a row: two sends in the same millisecond
    // would make "kept the first" true by accident.
    await seed({
      status: 'sent',
      sentAt: '2026-08-09T12:00:00.000Z',
      emailLog: [
        { at: '2026-08-09T12:00:00.000Z', to: ['ann@acme.com'], subject: 'Invoice 1042', ok: true, total: 400 },
      ],
    })
    const updated = await store.recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice 1042',
      ok: true,
    })

    expect(updated.sentAt).toBe('2026-08-09T12:00:00.000Z')
    expect(updated.emailLog).toHaveLength(2)
  })

  it('records what was billed, so a later edit cannot rewrite what went out', async () => {
    await seed()
    await store.recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice 1042',
      ok: true,
    })

    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    const stored = data.invoices.find((entry) => entry.id === 'inv-1')
    expect(stored.emailLog[0].total).toBe(400)
  })

  /**
   * The payment-side emails ride the SAME append-only log, tagged with a
   * `kind`. That tag is what stops a webhook retry sending a second receipt —
   * and what stops a receipt being mistaken for the invoice going out.
   */
  it('tags a payment email and leaves sentAt and the status alone', async () => {
    await seed({ status: 'processing', sentAt: '2026-08-09T12:00:00.000Z' })
    const updated = await store.recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Receipt for invoice 1042',
      ok: true,
      kind: 'receipt',
    })

    expect(updated.emailLog[0].kind).toBe('receipt')
    expect(updated.emailLog[0].ok).toBe(true)
    expect(updated.status).toBe('processing')
    expect(updated.sentAt).toBe('2026-08-09T12:00:00.000Z')
  })

  // A receipt must never be the thing that starts the payment clock.
  it('does not stamp sentAt on an invoice that never actually went out', async () => {
    await seed()
    const updated = await store.recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Payment received',
      ok: true,
      kind: 'ack',
    })

    expect(updated.emailLog).toHaveLength(1)
    expect(updated.sentAt).toBeNull()
    expect(updated.status).toBe('reviewed')
  })

  it('leaves an ordinary invoice send untagged, exactly as before', async () => {
    await seed()
    const updated = await store.recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice 1042',
      ok: true,
    })

    expect(updated.emailLog[0]).not.toHaveProperty('kind')
    expect(updated.status).toBe('sent')
  })
})

/**
 * The Postgres statement behind the same contract. No NEW shape: the payment
 * emails reuse the existing `email_log` append verbatim, and the only thing
 * that changes is the boolean deciding whether this entry marks the invoice
 * sent — false for anything with a kind.
 */
describe('recordInvoiceSent statement shape (postgres branch)', () => {
  it('reuses the email_log append and refuses to call a receipt a send', async () => {
    const fake = fakePostgres({ invoices: [{ ...existingInvoice, status: 'processing' }] })
    await postgresStore(fake).recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Receipt for invoice INV-2026-08-001',
      ok: true,
      kind: 'receipt',
    })

    const update = fake.matching(/^update invoices/i)[0]
    expect(update.text).toMatch(/email_log = coalesce\(email_log, '\[\]'::jsonb\) \|\| \$2::jsonb/)
    expect(JSON.parse(update.params[1])[0]).toMatchObject({ kind: 'receipt', ok: true })
    // $3 is "this marks the invoice sent" — false for a payment email.
    expect(update.params[2]).toBe(false)
  })

  it('still marks a real invoice send as sent', async () => {
    const fake = fakePostgres({ invoices: [existingInvoice] })
    await postgresStore(fake).recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice INV-2026-08-001',
      ok: true,
    })

    const update = fake.matching(/^update invoices/i)[0]
    expect(update.params[2]).toBe(true)
    expect(JSON.parse(update.params[1])[0]).not.toHaveProperty('kind')
  })

  // The send statement hands back the row it WROTE. It used to re-list every
  // invoice the firm has ever issued to find that row again — a second full
  // scan, on a path the public pay link takes.
  it('returns the updated row off the statement, with no second read', async () => {
    const fake = fakePostgres({ invoices: [existingInvoice] })
    const updated = await postgresStore(fake).recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice INV-2026-08-001',
      ok: true,
    })

    expect(fake.matching(/^update invoices/i)[0].text).toMatch(
      /returning id, client_id, period, number, kind, status/,
    )
    expect(updated.id).toBe('inv-1')
    expect(updated.emailLog).toHaveLength(1)
    // The void pre-check before the write, and nothing after it.
    expect(fake.matching(/^select\b[\s\S]*\bfrom invoices\b/i)).toHaveLength(1)
  })

  // The provider's id is the join key every delivery event is matched on. An
  // entry written without it is an event we can never place.
  it('keeps the mail provider’s message id on the entry', async () => {
    const fake = fakePostgres({ invoices: [existingInvoice] })
    await postgresStore(fake).recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice INV-2026-08-001',
      ok: true,
      providerId: 'ee-abc-123',
    })

    const update = fake.matching(/^update invoices/i)[0]
    expect(JSON.parse(update.params[1])[0]).toMatchObject({ providerId: 'ee-abc-123' })
  })
})

/**
 * The past-due line moves to the FIRST SEND.
 *
 * Generation stamps `dueDate` from the day the draft was built, which is wrong
 * whenever the run is built early — September's 35 drafts were generated on the
 * 15th to be emailed on October 1, so their stored line fell two weeks before
 * the client had seen the bill. The first real send re-stamps it; nothing else
 * ever moves it again.
 */
describe('recordInvoiceSent re-stamps the past-due line (file backend)', () => {
  const seedInvoice = {
    id: 'inv-1',
    clientId: 'c1',
    period: '2026-09',
    number: '1043',
    status: 'reviewed',
    lineItems: [{ kind: 'custom', label: 'Bookkeeping', detail: '', amount: 400 }],
    subtotal: 400,
    total: 400,
    // The provisional date generation wrote: 30 days from the day the draft was
    // built, which is NOT the day it goes out.
    dueDate: '2026-10-15',
    blurb: '',
    scopeFlags: [],
    sentAt: null,
    paidAt: null,
    paymentMethod: null,
    createdAt: '2026-09-15T00:00:00.000Z',
    updatedAt: '2026-09-15T00:00:00.000Z',
  }

  async function seed(overrides = {}, clientOverrides = {}) {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices = [{ ...seedInvoice, ...overrides }]
    // The invoice's client, because the re-stamp reads its terms.
    data.clients = [
      {
        id: 'c1',
        name: 'Acme',
        contact: 'Pat',
        billingMode: 'hourly',
        hourlyRate: 0,
        paymentTerms: '',
        ...clientOverrides,
      },
    ]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
  }

  /** Whole days between two YYYY-MM-DD dates, counted independently of the store. */
  const gapDays = (from, to) =>
    Math.round(
      (Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / (24 * 60 * 60 * 1000),
    )

  /** `dateOnly` moved by whole days, for building a date relative to today. */
  const shiftDays = (dateOnly, days) =>
    new Date(Date.parse(`${dateOnly}T00:00:00Z`) + days * 24 * 60 * 60 * 1000)
      .toISOString()
      .slice(0, 10)

  it('sets the line to thirty days after the day it actually went out', async () => {
    // Seeded with the line a draft generated YESTERDAY would carry. Relative to
    // today rather than a fixed date, because a fixed one eventually IS today
    // plus thirty and the re-stamp becomes invisible.
    const provisional = shiftDays(firmToday(), 29)
    await seed({ dueDate: provisional })
    const updated = await store.recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice 1043',
      ok: true,
    })

    const sendDay = dateOnlyInZone(new Date(updated.emailLog[0].at))
    expect(gapDays(sendDay, updated.dueDate)).toBe(30)
    expect(updated.dueDate).not.toBe(provisional)
  })

  // THE RULE. Chasing a client does not buy them another thirty days.
  it('leaves the line alone on a re-send', async () => {
    await seed({
      status: 'sent',
      sentAt: '2026-10-01T12:00:00.000Z',
      dueDate: '2026-10-31',
      emailLog: [
        {
          at: '2026-10-01T12:00:00.000Z',
          to: ['ann@acme.com'],
          subject: 'Invoice 1043',
          ok: true,
          total: 400,
        },
      ],
    })
    const updated = await store.recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice 1043',
      ok: true,
    })

    expect(updated.dueDate).toBe('2026-10-31')
    expect(updated.emailLog).toHaveLength(2)
  })

  // A payment ack, a receipt or a pay-link open is not the invoice going out.
  it('never moves the line for a tagged entry', async () => {
    for (const kind of ['receipt', 'ack', 'link']) {
      await seed()
      const updated = await store.recordInvoiceSent('inv-1', {
        to: ['ann@acme.com'],
        subject: 'Payment received',
        ok: true,
        kind,
      })
      expect(updated.dueDate).toBe('2026-10-15')
      expect(updated.sentAt).toBeNull()
    }
  })

  it('never moves the line for a send that did not go out', async () => {
    await seed()
    const updated = await store.recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice 1043',
      ok: false,
      error: 'The domain is not verified.',
    })

    expect(updated.dueDate).toBe('2026-10-15')
  })

  /**
   * THE CLIENT'S OWN TERMS. Generation honors them; the re-stamp used to pass
   * null and flatten every client to the firm's thirty days — so a Net 45
   * client's first send moved their line FIFTEEN DAYS EARLIER than the invoice
   * they were holding, and the PDF printed "Net 45" over a 30-day date.
   */
  it('honors a longer window on the client record', async () => {
    await seed({}, { paymentTerms: 'Net 45' })
    const updated = await store.recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice 1043',
      ok: true,
    })

    const sendDay = dateOnlyInZone(new Date(updated.emailLog[0].at))
    expect(gapDays(sendDay, updated.dueDate)).toBe(45)
  })

  // `dueDateFromTerms` FLOORS at the firm's window, so a short "Net 15" buys
  // the client nothing — they are asked to pay on receipt like everyone else.
  it('never shortens the window below the firm’s thirty days', async () => {
    await seed({}, { paymentTerms: 'Net 15' })
    const updated = await store.recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice 1043',
      ok: true,
    })

    const sendDay = dateOnlyInZone(new Date(updated.emailLog[0].at))
    expect(gapDays(sendDay, updated.dueDate)).toBe(30)
  })

  // A bounce or a delivery receipt is the mail provider talking about a send
  // that already happened. It appends to the same log and must not touch the
  // date, the status or the sent stamp.
  it('leaves the line alone for a delivery event', async () => {
    await seed({ status: 'sent', sentAt: '2026-10-01T12:00:00.000Z', dueDate: '2026-10-31' })
    const updated = await store.recordInvoiceDeliveryEvent('inv-1', {
      event: 'bounced',
      providerId: 'ee-1',
      to: ['ann@acme.com'],
    })

    expect(updated.dueDate).toBe('2026-10-31')
    expect(updated.sentAt).toBe('2026-10-01T12:00:00.000Z')
    expect(updated.status).toBe('sent')
  })
})

/**
 * The Postgres half of the same rule. The condition that matters is in the SQL,
 * not in JS: `sent_at is null` reads the row's PRE-update value, so two sends
 * racing cannot both claim to be the first.
 */
describe('recordInvoiceSent past-due line (postgres branch)', () => {
  /** The statement with its indentation flattened, so an assertion can quote it. */
  const flat = (text) => String(text).replace(/\s+/g, ' ').trim()

  it('re-stamps due_date only under the first-send condition', async () => {
    const fake = fakePostgres({ invoices: [existingInvoice] })
    await postgresStore(fake).recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice INV-2026-08-001',
      ok: true,
    })

    const update = fake.matching(/^update invoices/i)[0]
    // `$5::date::text` is load-bearing, not tidiness. `invoices.due_date` is a
    // TEXT column, and `case … then <date> else <text> end` is rejected by
    // Postgres at PARSE time ("CASE types text and date cannot be matched") —
    // so without the second cast this statement fails for every invoice, and
    // every send in production fails with it. A bare `$5` does not work either
    // ("could not determine data type of parameter"). Confirmed against the
    // production database in a rolled-back transaction, 2026-09-15.
    expect(flat(update.text)).toContain(
      'due_date = case when $3::boolean and sent_at is null and $5::date is not null' +
        ' then $5::date::text else due_date end',
    )
    // $5 is the line this send would set: a date, thirty days out.
    expect(update.params[4]).toMatch(/^\d{4}-\d{2}-\d{2}$/)
  })

  // The client's terms, read through `getClientById` — one row, the same
  // column list `read()` uses. Passing null here floored every client at the
  // firm's thirty days, which is fifteen days of a Net 45 client's window.
  it('reads the client’s terms and lengthens the window', async () => {
    const fake = fakePostgres({
      invoices: [existingInvoice],
      clientRows: [{ id: 'c1', name: 'Acme', contact: 'Pat', billing_mode: 'hourly', hourly_rate: 0, payment_terms: 'Net 45' }],
    })
    await postgresStore(fake).recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice INV-2026-08-001',
      ok: true,
    })

    const update = fake.matching(/^update invoices/i)[0]
    const sendDay = JSON.parse(update.params[1])[0].at.slice(0, 10)
    const gap = Math.round(
      (Date.parse(`${update.params[4]}T00:00:00Z`) - Date.parse(`${sendDay}T00:00:00Z`)) /
        (24 * 60 * 60 * 1000),
    )
    expect(gap).toBe(45)
    expect(fake.matching(/from clients where id = \$1$/i).length).toBeGreaterThan(0)
  })

  // With $5 null the CASE cannot fire, so a payment email can never blank a
  // date that is already on the row.
  it('sends no date at all for a tagged entry', async () => {
    const fake = fakePostgres({ invoices: [{ ...existingInvoice, status: 'processing' }] })
    await postgresStore(fake).recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Receipt for invoice INV-2026-08-001',
      ok: true,
      kind: 'receipt',
    })

    const update = fake.matching(/^update invoices/i)[0]
    expect(update.params[4]).toBeNull()
  })

  it('sends no date for a failed attempt either', async () => {
    const fake = fakePostgres({ invoices: [existingInvoice] })
    await postgresStore(fake).recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice INV-2026-08-001',
      ok: false,
      error: 'refused',
    })

    const update = fake.matching(/^update invoices/i)[0]
    expect(update.params[4]).toBeNull()
  })
})

/**
 * ONE SEND MOMENT (featreq-29c6dac1). The send route decides a stamp once,
 * builds the email and the PDF from the invoice as the record will hold it
 * after this send (`invoiceAsSent`), and hands the SAME stamp to
 * `recordInvoiceSent`. server.js is not booted by tests, so this runs the same
 * three calls in the same order the route does, on the file backend: a first
 * send of an invoice built before its month ended and sent after it must give
 * one date on the email, the PDF and a later reprint of the stored row.
 */
describe('the send stamp: documents, record and reprint agree (file backend)', () => {
  const stamp = '2026-11-02T14:00:00.000Z'
  const seedInvoice = {
    id: 'inv-1',
    clientId: 'c1',
    period: '2026-10',
    kind: 'monthly',
    number: '1050',
    status: 'reviewed',
    lineItems: [{ kind: 'custom', label: 'Bookkeeping', detail: '', amount: 400 }],
    subtotal: 400,
    total: 400,
    // The provisional line generation wrote on Oct 20: thirty days out.
    dueDate: '2026-11-19',
    blurb: '',
    scopeFlags: [],
    sentAt: null,
    paidAt: null,
    paymentMethod: null,
    createdAt: '2026-10-20T15:00:00.000Z',
    updatedAt: '2026-10-20T15:00:00.000Z',
  }
  const clientRecord = {
    id: 'c1',
    name: 'Acme',
    contact: 'Pat',
    billingMode: 'hourly',
    hourlyRate: 0,
    paymentTerms: 'Net 45',
  }

  async function seed(overrides = {}) {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices = [{ ...seedInvoice, ...overrides }]
    data.clients = [clientRecord]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
  }

  /** Every text a client can read the dates from: the email and the PDF. */
  async function documentsFor(invoice) {
    const { html } = buildInvoiceEmail({ invoice, client: clientRecord })
    const raw = (await buildInvoicePdf({ invoice, client: clientRecord, compress: false })).toString(
      'latin1',
    )
    const runs = []
    for (const match of raw.matchAll(/\[([^\]]*)\]\s*TJ/g)) runs.push(match[1])
    for (const match of raw.matchAll(/<([0-9A-Fa-f]+)>\s*Tj/g)) runs.push(`<${match[1]}>`)
    const pdf = runs
      .map((run) =>
        [...run.matchAll(/<([0-9A-Fa-f]*)>/g)]
          .map((hex) => Buffer.from(hex[1], 'hex').toString('latin1'))
          .join(''),
      )
      .join('\n')
    return { html, pdf }
  }

  async function firstSend(overrides = {}) {
    await seed(overrides)
    const stored = (await store.listInvoices()).find((invoice) => invoice.id === 'inv-1')
    const sendInvoice = invoiceAsSent(stored, { client: clientRecord, stamp })
    const documents = await documentsFor(sendInvoice)
    const updated = await store.recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice 1050',
      ok: true,
      stamp,
    })
    return { stored, sendInvoice, documents, updated }
  }

  it('hands the builders the invoice as the record will hold it', async () => {
    const { stored, sendInvoice, updated } = await firstSend()

    expect(stored.sentAt).toBeNull()
    expect(sendInvoice.sentAt).toBe(stamp)
    expect(sendInvoice.dueDate).toBe('2026-12-17')
    // What the store then writes is exactly what the documents were built from.
    expect(updated.sentAt).toBe(stamp)
    expect(updated.dueDate).toBe(sendInvoice.dueDate)
    expect(updated.emailLog[0].at).toBe(stamp)
  })

  it('dates the email, the PDF and a later reprint the same day', async () => {
    const { documents, updated } = await firstSend()

    // Built Oct 20, sent Nov 2: a monthly October invoice prints the 31st.
    expect(invoiceDisplayDate(updated)).toBe('2026-10-31')
    expect(documents.html).toContain('October 31, 2026')
    expect(documents.pdf).toContain('October 31, 2026')
    expect(documents.html).not.toContain('October 20, 2026')
    expect(documents.pdf).not.toContain('October 20, 2026')
    // And the documents rebuilt from the stored row say the same thing.
    const reprint = await documentsFor(updated)
    expect(reprint.html).toContain('October 31, 2026')
    expect(reprint.pdf).toContain('October 31, 2026')
  })

  it('prints the due date the first send stores, not the provisional one', async () => {
    const { documents, updated } = await firstSend()

    // A Net 45 client is shown their own date: Nov 2 + 45 days.
    expect(updated.dueDate).toBe('2026-12-17')
    expect(documents.html).toContain('December 17, 2026')
    expect(documents.pdf).toContain('December 17, 2026')
    expect(documents.html).not.toContain('November 19, 2026')
    expect(documents.pdf).not.toContain('November 19, 2026')
  })

  // A period before the cutoff keeps its issue day, which is the SEND day —
  // the email used to say the day it was built.
  it('dates an August invoice built Aug 20 and sent Nov 2 November 2 everywhere', async () => {
    const { documents, updated } = await firstSend({
      period: '2026-08',
      createdAt: '2026-08-20T15:00:00.000Z',
      dueDate: '2026-09-19',
    })

    expect(invoiceDisplayDate(updated)).toBe('2026-11-02')
    for (const text of [documents.html, documents.pdf]) {
      expect(text).toContain('November 2, 2026')
      expect(text).not.toContain('August 20, 2026')
    }
  })

  it('dates a retainer on the day it was sent, not the day it was built', async () => {
    const { documents, updated } = await firstSend({ kind: 'retainer' })

    expect(invoiceDisplayDate(updated)).toBe('2026-11-02')
    for (const text of [documents.html, documents.pdf]) {
      expect(text).toContain('November 2, 2026')
      expect(text).not.toContain('October 20, 2026')
    }
  })

  it('moves nothing on a resend: same sentAt, same date, same due date', async () => {
    const sentAt = '2026-11-02T14:00:00.000Z'
    await seed({ status: 'sent', sentAt, dueDate: '2026-12-17' })
    const stored = (await store.listInvoices()).find((invoice) => invoice.id === 'inv-1')
    const sendInvoice = invoiceAsSent(stored, {
      client: clientRecord,
      stamp: '2026-11-09T09:00:00.000Z',
    })
    // Built exactly as stored.
    expect(sendInvoice).toBe(stored)
    const resendDocuments = await documentsFor(sendInvoice)
    const updated = await store.recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice 1050',
      ok: true,
      stamp: '2026-11-09T09:00:00.000Z',
    })

    expect(updated.sentAt).toBe(sentAt)
    expect(updated.dueDate).toBe('2026-12-17')
    expect(invoiceDisplayDate(updated)).toBe(invoiceDisplayDate(stored))
    expect(resendDocuments.html).toContain('October 31, 2026')
    expect(resendDocuments.pdf).toContain('October 31, 2026')
    expect(resendDocuments.html).toContain('December 17, 2026')
    // The log still records the moment of THIS send.
    expect(updated.emailLog.at(-1).at).toBe('2026-11-09T09:00:00.000Z')
  })

  it('stamps nothing when the provider refuses the email', async () => {
    await seed()
    const updated = await store.recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice 1050',
      ok: false,
      error: 'The domain is not verified.',
    })

    expect(updated.sentAt).toBeNull()
    expect(updated.status).toBe('reviewed')
    expect(updated.dueDate).toBe('2026-11-19')
    expect(invoiceDisplayDate(updated)).toBe('2026-10-20')
  })

  // Even if a stamp were passed, a send that did not go out never uses it.
  it('ignores a stamp on a failed attempt', async () => {
    await seed()
    const updated = await store.recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice 1050',
      ok: false,
      error: 'refused',
      stamp,
    })

    expect(updated.sentAt).toBeNull()
    expect(updated.dueDate).toBe('2026-11-19')
  })

  it('falls back to now for a stamp that is not a moment in time', async () => {
    await seed()
    const before = Date.now()
    const updated = await store.recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice 1050',
      ok: true,
      stamp: 'not a date',
    })

    expect(Date.parse(updated.sentAt)).toBeGreaterThanOrEqual(before)
  })

  it('invoiceAsSent re-stamps the line thirty days from the send day for a client with no longer terms', () => {
    const shaped = invoiceAsSent(
      { ...seedInvoice, dueDate: '2026-11-19' },
      { client: { paymentTerms: '' }, stamp },
    )
    // Thirty days from the SEND day, which is what recordInvoiceSent stores.
    expect(shaped.dueDate).toBe('2026-12-02')
    expect(shaped.sentAt).toBe(stamp)
  })
})

describe('the send stamp (postgres branch)', () => {
  const stamp = '2026-11-02T23:59:59.500Z'
  const flat = (text) => String(text).replace(/\s+/g, ' ').trim()

  it('writes exactly the stamp it was given as the first send’s sent_at and log time', async () => {
    const fake = fakePostgres({
      invoices: [{ ...existingInvoice, status: 'reviewed', sent_at: null }],
      clientRows: [
        { id: 'c1', name: 'Acme', contact: 'Pat', billing_mode: 'hourly', hourly_rate: 0, payment_terms: 'Net 45' },
      ],
    })
    await postgresStore(fake).recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice INV-2026-08-001',
      ok: true,
      stamp,
    })

    const update = fake.matching(/^update invoices/i)[0]
    // The statement is unchanged: sent_at and due_date are still decided from
    // the row's own pre-update value, so a resend can never move either.
    expect(flat(update.text)).toContain(
      'sent_at = case when $3::boolean then coalesce(sent_at, $4::timestamptz) else sent_at end',
    )
    expect(flat(update.text)).toContain(
      'due_date = case when $3::boolean and sent_at is null and $5::date is not null' +
        ' then $5::date::text else due_date end',
    )
    expect(update.params[3]).toBe(stamp)
    expect(JSON.parse(update.params[1])[0].at).toBe(stamp)
    // Net 45 from the stamp's UTC day, not from "now".
    expect(update.params[4]).toBe('2026-12-17')
  })

  it('passes the same stamp on a resend, and the SQL leaves sent_at and due_date to the row', async () => {
    const fake = fakePostgres({ invoices: [existingInvoice] })
    await postgresStore(fake).recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice INV-2026-08-001',
      ok: true,
      stamp,
    })

    const update = fake.matching(/^update invoices/i)[0]
    // `coalesce(sent_at, $4)` keeps the row's original value on a resend, and
    // `sent_at is null` keeps the due date: both are in the statement itself.
    expect(flat(update.text)).toContain('coalesce(sent_at, $4::timestamptz)')
    expect(flat(update.text)).toContain('and sent_at is null and $5::date is not null')
    expect(update.params[3]).toBe(stamp)
  })

  it('writes no sent_at and sends no date for a failed attempt', async () => {
    const fake = fakePostgres({ invoices: [existingInvoice] })
    await postgresStore(fake).recordInvoiceSent('inv-1', {
      to: ['ann@acme.com'],
      subject: 'Invoice INV-2026-08-001',
      ok: false,
      error: 'refused',
    })

    const update = fake.matching(/^update invoices/i)[0]
    // No stamp was passed (the route passes one only after the provider
    // accepts), and $3 is false so `sent_at` cannot be written either way.
    expect(update.params[2]).toBe(false)
    expect(update.params[4]).toBeNull()
  })
})

/**
 * `recordInvoicePastDueNoticed` — the marker that makes the owner's past-due
 * email arrive ONCE.
 *
 * Being past due is derived at read time (lib/invoice-overdue.js), so there is
 * no status to flip and nothing to un-flip when the invoice is paid. The only
 * thing that has to be remembered is "we already said something", and it is
 * remembered on the same append-only log the sends live on.
 */
describe('recordInvoicePastDueNoticed (file backend)', () => {
  const seedInvoice = {
    id: 'inv-1',
    clientId: 'c1',
    period: '2026-09',
    number: '1043',
    status: 'sent',
    lineItems: [{ kind: 'custom', label: 'Bookkeeping', detail: '', amount: 400 }],
    subtotal: 400,
    total: 400,
    dueDate: '2026-10-31',
    blurb: '',
    scopeFlags: [],
    sentAt: '2026-10-01T12:00:00.000Z',
    paidAt: null,
    paymentMethod: null,
    emailLog: [
      {
        at: '2026-10-01T12:00:00.000Z',
        to: ['ann@acme.com'],
        subject: 'Invoice 1043',
        ok: true,
        total: 400,
        providerId: 'ee-1',
      },
    ],
    createdAt: '2026-09-15T00:00:00.000Z',
    updatedAt: '2026-10-01T12:00:00.000Z',
  }

  async function seed(overrides = {}) {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices = [{ ...seedInvoice, ...overrides }]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
  }

  it('appends a tagged marker beside the send, naming the line it passed', async () => {
    await seed()
    const updated = await store.recordInvoicePastDueNoticed('inv-1', '2026-10-31')

    expect(updated.emailLog).toHaveLength(2)
    expect(updated.emailLog[1]).toMatchObject({
      kind: 'past-due',
      event: 'noticed',
      dueDate: '2026-10-31',
    })
    expect(Number.isNaN(new Date(updated.emailLog[1].at).getTime())).toBe(false)
    // The send it sits beside is untouched.
    expect(updated.emailLog[0].ok).toBe(true)
  })

  // THE RULE. `overdue` is a status nothing writes, and this must not be what
  // starts writing it.
  it('never changes the status or the dates', async () => {
    await seed()
    const updated = await store.recordInvoicePastDueNoticed('inv-1', '2026-10-31')

    expect(updated.status).toBe('sent')
    expect(updated.sentAt).toBe('2026-10-01T12:00:00.000Z')
    expect(updated.dueDate).toBe('2026-10-31')
  })

  // One email per invoice, ever — the hourly check asks this question every
  // hour until the invoice is paid. The ANSWER is what carries that rule: the
  // scheduler notifies on a truthy result, so a second call has to come back
  // null. Handing the invoice back made its `if (!marked) continue` unreachable.
  it('is idempotent: a second call returns null and appends nothing', async () => {
    await seed()
    const first = await store.recordInvoicePastDueNoticed('inv-1', '2026-10-31')
    const again = await store.recordInvoicePastDueNoticed('inv-1', '2026-10-31')

    expect(first).not.toBeNull()
    expect(again).toBeNull()
    const stored = (await store.listInvoices()).find((invoice) => invoice.id === 'inv-1')
    expect(stored.emailLog.filter((logged) => logged.kind === 'past-due')).toHaveLength(1)
  })

  it('falls back to the invoice\u2019s own due date when none is given', async () => {
    await seed()
    const updated = await store.recordInvoicePastDueNoticed('inv-1')

    expect(updated.emailLog[1].dueDate).toBe('2026-10-31')
  })

  it('refuses an invoice that is not there', async () => {
    await seed()
    expect(await store.recordInvoicePastDueNoticed('nope', '2026-10-31')).toBeNull()
    expect(await store.recordInvoicePastDueNoticed('', '2026-10-31')).toBeNull()
  })
})

describe('recordInvoicePastDueNoticed statement shape (postgres branch)', () => {
  /** Everything the statement WRITES — the clause ahead of `returning`. */
  const written = (text) => String(text).split(/\breturning\b/i)[0]

  it('appends to email_log and touches nothing else', async () => {
    const fake = fakePostgres({ invoices: [existingInvoice] })
    const marked = await postgresStore(fake).recordInvoicePastDueNoticed('inv-1', '2026-10-31')

    const update = fake.matching(/^update invoices/i)[0]
    expect(update.text).toMatch(/email_log = coalesce\(email_log, '\[\]'::jsonb\) \|\| \$2::jsonb/)
    // The two columns it is allowed to WRITE, and no third. Asked of the write
    // clause alone now that the statement hands the whole row back: every
    // column is named after `returning`, and none of them may appear before it.
    expect(written(update.text)).not.toMatch(/\bstatus\b/)
    expect(written(update.text)).not.toMatch(/\bdue_date\b/)
    expect(JSON.parse(update.params[1])[0]).toMatchObject({
      kind: 'past-due',
      event: 'noticed',
      dueDate: '2026-10-31',
    })
    // The row it wrote, off the statement that wrote it — no read afterwards.
    expect(marked?.id).toBe('inv-1')
    expect(fake.matching(/^select\b[\s\S]*\bfrom invoices\b/i)).toHaveLength(1)
  })

  // THE DE-DUP. Two containers run this scheduler and both wake on the hour, so
  // both can read the same unmarked invoice before either writes. The check has
  // to live in the WHERE, which is the only place one of them can lose it.
  it('makes the once-ever check part of the write itself', async () => {
    const fake = fakePostgres({ invoices: [existingInvoice] })
    await postgresStore(fake).recordInvoicePastDueNoticed('inv-1', '2026-10-31')

    const update = fake.matching(/^update invoices/i)[0]
    // `coalesce` is load-bearing: `null @> …` is NULL and `not NULL` matches
    // nothing, which would silence every invoice whose log column is still null.
    expect(written(update.text).replace(/\s+/g, ' ')).toContain(
      `and not (coalesce(email_log, '[]'::jsonb) @> '[{"kind":"past-due"}]'::jsonb)`,
    )
  })

  // The loser of that race: the row is already marked, the statement matches
  // nothing, and the store has to say so rather than hand back a truthy invoice
  // — the scheduler reads truthy as "you may email the owners".
  it('answers null when the guard matches no row', async () => {
    const alreadyNoticed = {
      ...existingInvoice,
      email_log: [
        { kind: 'past-due', event: 'noticed', at: '2026-10-31T12:00:00.000Z', dueDate: '2026-10-31' },
      ],
    }
    const fake = fakePostgres({ invoices: [alreadyNoticed] })
    const pgStore = postgresStore(fake)
    // Straight at the statement, with the pre-read's own early return taken out
    // of the way: this is the container that read the invoice a moment before
    // the other one marked it.
    pgStore.listInvoices = async () => [{ id: 'inv-1', emailLog: [] }]
    const marked = await pgStore.recordInvoicePastDueNoticed('inv-1', '2026-10-31')

    expect(marked).toBeNull()
    expect(alreadyNoticed.email_log.filter((entry) => entry.kind === 'past-due')).toHaveLength(1)
  })

  it('writes nothing at all for an invoice already noticed', async () => {
    const fake = fakePostgres({
      invoices: [
        {
          ...existingInvoice,
          email_log: [
            { kind: 'past-due', event: 'noticed', at: '2026-10-31T12:00:00.000Z', dueDate: '2026-10-31' },
          ],
        },
      ],
    })
    const marked = await postgresStore(fake).recordInvoicePastDueNoticed('inv-1', '2026-10-31')

    expect(marked).toBeNull()
    expect(fake.matching(/^update invoices/i)).toHaveLength(0)
  })
})

/**
 * `recordInvoiceDeliveryEvent` — what the mail provider did with an invoice
 * email, appended to the same log the sends live on.
 *
 * Two rules matter more than the shape. It NEVER touches the status: a bounce
 * does not un-send an invoice, it means the address is wrong and the bill still
 * stands. And it is idempotent on (providerId, event), because Resend retries a
 * webhook until it gets a 200 and the same bounce arrives several times.
 */
describe('recordInvoiceDeliveryEvent (file backend)', () => {
  const seedInvoice = {
    id: 'inv-1',
    clientId: 'c1',
    period: '2026-08',
    number: '1042',
    status: 'sent',
    lineItems: [{ kind: 'custom', label: 'Bookkeeping', detail: '', amount: 400 }],
    subtotal: 400,
    total: 400,
    dueDate: '2026-09-15',
    blurb: '',
    scopeFlags: [],
    sentAt: '2026-08-09T12:00:00.000Z',
    paidAt: null,
    paymentMethod: null,
    emailLog: [
      {
        at: '2026-08-09T12:00:00.000Z',
        to: ['ann@acme.com'],
        subject: 'Invoice 1042',
        ok: true,
        total: 400,
        providerId: 'ee-1',
      },
    ],
    createdAt: '2026-08-01T00:00:00.000Z',
    updatedAt: '2026-08-01T00:00:00.000Z',
  }

  async function seed(overrides = {}) {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices = [{ ...seedInvoice, ...overrides }]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
  }

  it('appends a delivery entry beside the send, tagged so it is not one', async () => {
    await seed()
    const updated = await store.recordInvoiceDeliveryEvent('inv-1', {
      event: 'delivered',
      at: '2026-08-09T12:00:04.000Z',
      providerId: 'ee-1',
      to: ['ann@acme.com'],
    })

    expect(updated.emailLog).toHaveLength(2)
    expect(updated.emailLog[1]).toEqual({
      kind: 'delivery',
      event: 'delivered',
      at: '2026-08-09T12:00:04.000Z',
      providerId: 'ee-1',
      to: ['ann@acme.com'],
      detail: '',
    })
    // The entry the send wrote is untouched.
    expect(updated.emailLog[0].ok).toBe(true)
  })

  // THE RULE. A mail provider must never be able to move money state.
  it('never changes the status, not even on a bounce', async () => {
    await seed()
    const updated = await store.recordInvoiceDeliveryEvent('inv-1', {
      event: 'bounced',
      providerId: 'ee-1',
      to: ['ann@acme.com'],
      detail: 'mailbox does not exist',
    })

    expect(updated.status).toBe('sent')
    expect(updated.sentAt).toBe('2026-08-09T12:00:00.000Z')
    expect(updated.emailLog[1].detail).toBe('mailbox does not exist')
  })

  it('is idempotent on (providerId, event) — a retried notice logs once', async () => {
    await seed()
    const entry = { event: 'bounced', providerId: 'ee-1', to: ['ann@acme.com'], detail: 'no such user' }
    await store.recordInvoiceDeliveryEvent('inv-1', entry)
    const again = await store.recordInvoiceDeliveryEvent('inv-1', entry)

    expect(again.emailLog.filter((logged) => logged.kind === 'delivery')).toHaveLength(1)
  })

  // A delayed notice followed by a delivered one is the normal happy path for
  // a greylisting server. Both are kept; they are different events.
  it('keeps two different events about the same message', async () => {
    await seed()
    await store.recordInvoiceDeliveryEvent('inv-1', { event: 'delayed', providerId: 'ee-1' })
    const updated = await store.recordInvoiceDeliveryEvent('inv-1', {
      event: 'delivered',
      providerId: 'ee-1',
    })

    expect(updated.emailLog.filter((logged) => logged.kind === 'delivery')).toHaveLength(2)
  })

  it('refuses an unnamed event and an invoice that is not there', async () => {
    await seed()
    expect(await store.recordInvoiceDeliveryEvent('inv-1', { event: '' })).toBeNull()
    expect(await store.recordInvoiceDeliveryEvent('nope', { event: 'delivered' })).toBeNull()
  })

  // Resend stamps its events with an ISO string; a missing or unusable one must
  // not produce an entry dated "Invalid Date".
  it('falls back to now when the provider’s timestamp is unusable', async () => {
    await seed()
    const updated = await store.recordInvoiceDeliveryEvent('inv-1', {
      event: 'delivered',
      at: 'whenever',
      providerId: 'ee-1',
    })

    expect(Number.isNaN(new Date(updated.emailLog[1].at).getTime())).toBe(false)
  })
})

/**
 * The Postgres statement behind the same contract. It appends in SQL, for the
 * reason `recordInvoiceSent` does — two events about one invoice can land at
 * once — and the statement must name no other column than the log and
 * `updated_at`.
 */
describe('recordInvoiceDeliveryEvent statement shape (postgres branch)', () => {
  it('appends to email_log and touches nothing else', async () => {
    const fake = fakePostgres({
      invoices: [
        {
          ...existingInvoice,
          email_log: [
            { at: '2026-09-01T12:00:00.000Z', to: ['ann@acme.com'], subject: 's', ok: true, providerId: 'ee-1' },
          ],
        },
      ],
    })
    await postgresStore(fake).recordInvoiceDeliveryEvent('inv-1', {
      event: 'complained',
      at: '2026-09-02T09:00:00.000Z',
      providerId: 'ee-1',
      to: ['ann@acme.com'],
      detail: 'marked as spam',
    })

    const update = fake.matching(/^update invoices/i)[0]
    expect(update.text).toMatch(/email_log = coalesce\(email_log, '\[\]'::jsonb\) \|\| \$2::jsonb/)
    // The two columns it is allowed to write, and no third.
    expect(update.text).not.toMatch(/\bstatus\b/)
    expect(update.text).not.toMatch(/\bsent_at\b/)
    expect(JSON.parse(update.params[1])[0]).toEqual({
      kind: 'delivery',
      event: 'complained',
      at: '2026-09-02T09:00:00.000Z',
      providerId: 'ee-1',
      to: ['ann@acme.com'],
      detail: 'marked as spam',
    })
  })

  it('writes nothing at all for a notice it has already logged', async () => {
    const fake = fakePostgres({
      invoices: [
        {
          ...existingInvoice,
          email_log: [
            { at: '2026-09-01T12:00:00.000Z', to: ['ann@acme.com'], subject: 's', ok: true, providerId: 'ee-1' },
            { kind: 'delivery', event: 'bounced', at: '2026-09-01T12:01:00.000Z', providerId: 'ee-1', to: [], detail: '' },
          ],
        },
      ],
    })
    await postgresStore(fake).recordInvoiceDeliveryEvent('inv-1', {
      event: 'bounced',
      providerId: 'ee-1',
    })

    expect(fake.matching(/^update invoices/i)).toHaveLength(0)
  })
})

/**
 * `recordInvoicePaymentFailure` — a client's payment attempt that did not go
 * through, remembered on the same log.
 *
 * The webhook moves the status back to `sent` separately; this entry is the
 * only trace that anyone tried, and it is what puts the invoice in the month
 * run's "Payment failed" tab. Same two rules as the delivery events: never a
 * status write, and idempotent — here on the PaymentIntent, because one intent
 * fails once no matter how many times Stripe retries the webhook.
 */
describe('recordInvoicePaymentFailure (file backend)', () => {
  const seedInvoice = {
    id: 'inv-1',
    clientId: 'c1',
    period: '2026-08',
    number: 'INV-2026-08-031',
    status: 'sent',
    lineItems: [{ kind: 'custom', label: 'Bookkeeping', detail: '', amount: 400 }],
    subtotal: 400,
    total: 400,
    dueDate: '2026-09-15',
    blurb: '',
    scopeFlags: [],
    sentAt: '2026-08-28T12:00:00.000Z',
    paidAt: null,
    paymentMethod: null,
    stripePaymentIntentId: 'pi_1',
    emailLog: [
      {
        at: '2026-08-28T12:00:00.000Z',
        to: ['ann@acme.com'],
        subject: 'Invoice INV-2026-08-031',
        ok: true,
        total: 400,
        providerId: 'ee-1',
      },
    ],
    createdAt: '2026-08-01T00:00:00.000Z',
    updatedAt: '2026-08-01T00:00:00.000Z',
  }

  async function seed(overrides = {}) {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices = [{ ...seedInvoice, ...overrides }]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
  }

  it('appends a payment entry beside the send, tagged so it is neither a send nor a delivery', async () => {
    await seed()
    const updated = await store.recordInvoicePaymentFailure('inv-1', {
      at: '2026-09-10T14:00:00.000Z',
      paymentIntentId: 'pi_1',
      detail: 'Microdeposit verification for this PaymentIntent has timed out.',
    })

    expect(updated.emailLog).toHaveLength(2)
    expect(updated.emailLog[1]).toEqual({
      kind: 'payment',
      event: 'failed',
      at: '2026-09-10T14:00:00.000Z',
      paymentIntentId: 'pi_1',
      detail: 'Microdeposit verification for this PaymentIntent has timed out.',
    })
    expect(updated.emailLog[0].ok).toBe(true)
  })

  // THE RULE. The status move is applyInvoicePayment's; this only remembers.
  it('never changes the status or the sent date', async () => {
    await seed()
    const updated = await store.recordInvoicePaymentFailure('inv-1', {
      paymentIntentId: 'pi_1',
      detail: 'returned by the bank',
    })

    expect(updated.status).toBe('sent')
    expect(updated.sentAt).toBe('2026-08-28T12:00:00.000Z')
  })

  it('is idempotent on the PaymentIntent — a retried webhook logs one attempt', async () => {
    await seed()
    const entry = { paymentIntentId: 'pi_1', detail: 'timed out' }
    await store.recordInvoicePaymentFailure('inv-1', entry)
    const again = await store.recordInvoicePaymentFailure('inv-1', entry)

    expect(again.emailLog.filter((logged) => logged.kind === 'payment')).toHaveLength(1)
  })

  // Two attempts, two intents: the client tried twice, and both count.
  it('keeps failures from two different attempts', async () => {
    await seed()
    await store.recordInvoicePaymentFailure('inv-1', { paymentIntentId: 'pi_1' })
    const updated = await store.recordInvoicePaymentFailure('inv-1', { paymentIntentId: 'pi_2' })

    expect(updated.emailLog.filter((logged) => logged.kind === 'payment')).toHaveLength(2)
  })

  it('refuses an invoice that is not there', async () => {
    await seed()
    expect(await store.recordInvoicePaymentFailure('nope', { paymentIntentId: 'pi_1' })).toBeNull()
  })

  it('falls back to now when the timestamp is unusable', async () => {
    await seed()
    const updated = await store.recordInvoicePaymentFailure('inv-1', {
      at: 'whenever',
      paymentIntentId: 'pi_1',
    })

    expect(Number.isNaN(new Date(updated.emailLog[1].at).getTime())).toBe(false)
  })
})

