/**
 * THE PROOF that a normal payment is never flagged. For ACH and for card, the
 * amount Stripe collects is what the Checkout session was minted with
 * (`buildCheckoutLineItems` / `buildCardCheckoutLineItems`), and the invoice
 * total the webhook compares against is the REAL store's answer after the real
 * apply - the card fee line appended and the totals recomputed by the store.
 * Cents-awkward totals are the point: a rounding difference between the two
 * would flag every payment of that size.
 */
describe('a normal payment compares EQUAL to the invoice it paid', () => {
  const client = { id: 'c1', name: 'Acme' }
  const sessionCents = (items) =>
    items.reduce((sum, item) => sum + item.price_data.unit_amount * item.quantity, 0)

  const scenarios = [
    ['a round total', [{ kind: 'custom', label: 'Bookkeeping', detail: '', amount: 400 }]],
    [
      'cents-awkward lines',
      [
        { kind: 'custom', label: 'Bookkeeping', detail: '', amount: 1234.56 },
        { kind: 'custom', label: 'Payroll', detail: '', amount: 99.99 },
        { kind: 'custom', label: 'Cleanup', detail: '', amount: 0.07 },
      ],
    ],
    [
      'a $0 courtesy line beside real work',
      [
        { kind: 'custom', label: 'Bookkeeping', detail: '', amount: 333.33 },
        { kind: 'custom', label: 'Courtesy', detail: '', amount: 0 },
      ],
    ],
    [
      'a credit carried from last month (collapses to one Stripe line)',
      [
        { kind: 'custom', label: 'Bookkeeping', detail: '', amount: 500.5 },
        { kind: 'adjustment', label: 'Credit', detail: '', amount: -120.25 },
      ],
    ],
    ['a large total', [{ kind: 'custom', label: 'Bookkeeping', detail: '', amount: 18765.43 }]],
  ]

  async function seedWith(lineItems) {
    const total = Math.round(lineItems.reduce((sum, line) => sum + line.amount * 100, 0)) / 100
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices = [
      {
        id: 'inv-eq',
        clientId: 'c1',
        period: '2026-08',
        number: 'INV-2026-08-077',
        status: 'sent',
        kind: 'monthly',
        lineItems,
        subtotal: total,
        total,
        dueDate: '2026-09-15',
        blurb: '',
        scopeFlags: [],
        sentAt: '2026-08-28T12:00:00.000Z',
        paidAt: null,
        paymentMethod: null,
        createdAt: '2026-08-01T00:00:00.000Z',
        updatedAt: '2026-08-01T00:00:00.000Z',
      },
    ]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
    return data.invoices[0]
  }

  it.each(scenarios)('ACH: %s', async (_name, lineItems) => {
    const invoice = await seedWith(lineItems)
    const collected = sessionCents(buildCheckoutLineItems(invoice, client))

    const processing = await store.applyInvoicePayment('inv-eq', {
      status: 'processing',
      paymentIntentId: 'pi_a',
    })
    expect(
      paymentAmountMismatch({
        eventType: 'checkout.session.completed',
        object: { amount_total: collected },
        invoice: processing,
      }),
    ).toBeNull()
    const paid = await store.applyInvoicePayment('inv-eq', { status: 'paid', paymentIntentId: 'pi_a' })
    expect(
      paymentAmountMismatch({
        eventType: 'payment_intent.succeeded',
        object: { amount_received: collected },
        invoice: paid,
      }),
    ).toBeNull()
  })

  it.each(scenarios)('card, fee line appended by the store: %s', async (_name, lineItems) => {
    const invoice = await seedWith(lineItems)
    const collected = sessionCents(buildCardCheckoutLineItems(invoice, client))
    const feeLines = [cardProcessingFeeLine(invoice)]

    // Both events of one card payment, in webhook order: the second one finds
    // the fee line already there and does not add it again.
    const processing = await store.applyInvoicePayment('inv-eq', {
      status: 'processing',
      paymentIntentId: 'pi_c',
      appendLines: feeLines,
    })
    expect(
      paymentAmountMismatch({
        eventType: 'checkout.session.completed',
        object: { amount_total: collected },
        invoice: processing,
      }),
    ).toBeNull()
    const paid = await store.applyInvoicePayment('inv-eq', {
      status: 'paid',
      paymentIntentId: 'pi_c',
      appendLines: feeLines,
    })
    expect(
      paymentAmountMismatch({
        eventType: 'payment_intent.succeeded',
        object: { amount_received: collected },
        invoice: paid,
      }),
    ).toBeNull()
  })

  it('a card paid on an OLD total is flagged against the total as it now stands', async () => {
    const invoice = await seedWith([{ kind: 'custom', label: 'Bookkeeping', detail: '', amount: 400 }])
    const collected = sessionCents(buildCardCheckoutLineItems(invoice, client))
    // The invoice was raised to 450 after the page was opened.
    const raised = await seedWith([{ kind: 'custom', label: 'Bookkeeping', detail: '', amount: 450 }])

    const paid = await store.applyInvoicePayment('inv-eq', {
      status: 'paid',
      paymentIntentId: 'pi_old',
      appendLines: [cardProcessingFeeLine(raised)],
    })
    expect(
      paymentAmountMismatch({
        eventType: 'payment_intent.succeeded',
        object: { amount_received: collected },
        invoice: paid,
      }),
    ).toEqual({ expectedCents: Math.round(paid.total * 100), receivedCents: collected })
  })
})

/**
 * Column parity between the invoice SELECT and the row mapper.
 *
 * This is the Postgres guard for the whole invoice read path, and it has to be
 * one, because nothing else can be: every test in this file runs the FILE
 * backend, and the file backend returns whatever it stored — it cannot notice a
 * missing column. The Postgres branch can, silently. `email_log` was left out
 * of the select for the life of the feature, so `mapInvoiceRow` read
 * `row.email_log` as `undefined`, mapped it to `[]`, and production served an
 * empty send log that the UI faithfully rendered as "never sent" while
 * `recordInvoiceSent` rebuilt the log from it and threw the earlier sends away.
 *
 * A missing column has no error to catch; the only thing to test is that the
 * two lists agree. The mapper is handed a recording Proxy so the check is on
 * what it actually reads rather than on a copy of the list that would drift.
 */
describe('listInvoices selects every column mapInvoiceRow reads', () => {
  it('has no column the mapper reads but the select omits', () => {
    const readColumns = new Set()
    mapInvoiceRow(
      new Proxy(
        {},
        {
          get(_target, key) {
            if (typeof key === 'string') readColumns.add(key)
            return undefined
          },
        },
      ),
    )

    const selected = new Set(
      INVOICE_SELECT_COLUMNS.split(',')
        .map((column) => column.trim())
        .filter(Boolean),
    )

    // Sanity: a mapper that read nothing would pass the real assertion.
    expect(readColumns.size).toBeGreaterThan(10)
    expect([...readColumns].filter((column) => !selected.has(column))).toEqual([])
    // Named outright, because this is the one that got out.
    expect(selected.has('email_log')).toBe(true)
  })
})

/**
 * The same parity guard on CLIENTS — and the same bug, found the same way.
 *
 * `stripe_customer_id` existed on the table and `setClientStripeCustomerId`
 * wrote it, but it was in NO select. So on Postgres `client.stripeCustomerId`
 * read `undefined` FOREVER: every send, every payment link and every click on a
 * pay link created a brand-new Stripe customer for the same company, and the
 * bank details a repeat payer had saved sat on a customer nobody was charging.
 * Nothing in the app looked wrong. The file backend keeps whatever it stored,
 * so no test in this file could have noticed.
 */
describe('read() selects every column mapClientRow reads', () => {
  it('has no column the mapper reads but the select omits', () => {
    const readColumns = new Set()
    mapClientRow(
      new Proxy(
        {},
        {
          get(_target, key) {
            if (typeof key === 'string') readColumns.add(key)
            return undefined
          },
        },
      ),
    )

    const selected = new Set(
      CLIENT_SELECT_COLUMNS.split(',')
        .map((column) => column.trim())
        .filter(Boolean),
    )

    // Sanity: a mapper that read nothing would pass the real assertion.
    expect(readColumns.size).toBeGreaterThan(20)
    expect([...readColumns].filter((column) => !selected.has(column))).toEqual([])
    // Named outright, because these two are the ones this commit is about.
    expect(selected.has('stripe_customer_id')).toBe(true)
    expect(selected.has('platform_invoicing_opt_out')).toBe(true)
  })

  it('maps an absent Stripe customer to null rather than undefined', () => {
    expect(mapClientRow({ id: 'c1', name: 'Acme' }).stripeCustomerId).toBeNull()
    expect(
      mapClientRow({ id: 'c1', name: 'Acme', stripe_customer_id: 'cus_123' }).stripeCustomerId,
    ).toBe('cus_123')
  })

  it('maps a row written before the opt-out column existed to false', () => {
    expect(mapClientRow({ id: 'c1', name: 'Acme' }).platformInvoicingOptOut).toBe(false)
    expect(
      mapClientRow({ id: 'c1', name: 'Acme', platform_invoicing_opt_out: true })
        .platformInvoicingOptOut,
    ).toBe(true)
  })
})

/**
 * THE CLIENTS HALF OF THE BULK-SAVE WIPE — two columns, two different rules.
 *
 * `platform_invoicing_opt_out` travels with the payload like every other client
 * setting: leave it out of the insert and the next owner autosave switches it
 * back off, and the month run bills a company that is invoiced elsewhere.
 *
 * `stripe_customer_id` is the opposite rule and the sharper one. It is
 * endpoint-owned (`setClientStripeCustomerId` is the only writer) and the
 * payload has NEVER carried it, so the STORED value must be snapshotted before
 * the wipe and written back verbatim. Without that the column is NULLed on
 * every autosave — the same shape as the `pay_token` bug, on the field that
 * decides which Stripe customer a repeat payer is.
 */
describe('the bulk save carries the clients columns it does not own', () => {
  it('snapshots the stored Stripe customer before the wipe and writes it back', async () => {
    const fake = fakePostgres({
      clientRows: [{ id: 'c1', name: 'Acme', stripe_customer_id: 'cus_stored' }],
    })
    await postgresStore(fake).write(workspace())

    expect(fake.matching(/^select id, stripe_customer_id from clients$/i)).toHaveLength(1)
    const insert = fake.matching(/^insert into clients \(/i)[0]
    expect(insert.text).toMatch(/stripe_customer_id/)
    expect(insertedRows(fake.statements, 'clients')[0].stripe_customer_id).toBe('cus_stored')
  })

  // The payload is not consulted AT ALL. A stale tab that somehow carried a
  // customer id must not be able to re-point a client at it.
  it('ignores a customer id in the payload in favor of the stored one', async () => {
    const fake = fakePostgres({
      clientRows: [{ id: 'c1', name: 'Acme', stripe_customer_id: 'cus_stored' }],
    })
    await postgresStore(fake).write(
      workspace({ clients: [{ id: 'c1', name: 'Acme', stripeCustomerId: 'cus_from_payload' }] }),
    )

    const bound = insertedRows(fake.statements, 'clients')[0]
    expect(bound.stripe_customer_id).toBe('cus_stored')
  })

  // A client this save is creating has no snapshot entry, and null is exactly
  // right: it has no Stripe customer yet.
  it('leaves a brand-new client’s customer id null', async () => {
    const fake = fakePostgres({ clientRows: [] })
    await postgresStore(fake).write(workspace())

    const bound = insertedRows(fake.statements, 'clients')[0]
    expect(bound.stripe_customer_id).toBeNull()
  })

  it('carries the platform-invoicing opt-out through the wipe', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).write(
      workspace({ clients: [{ id: 'c1', name: 'Acme', platformInvoicingOptOut: true }] }),
    )

    const insert = fake.matching(/^insert into clients \(/i)[0]
    expect(insert.text).toMatch(/platform_invoicing_opt_out/)
    expect(insertedRows(fake.statements, 'clients')[0].platform_invoicing_opt_out).toBe(true)
  })

  // The file backend's half of both contracts (cardinal rule 1). It re-writes
  // each record whole, so what matters is that a round trip through the bulk
  // save gives both fields back.
  it('keeps both fields across a file-backend save and read', async () => {
    await store.write(
      workspace({
        clients: [
          {
            id: 'c1',
            name: 'Acme',
            platformInvoicingOptOut: true,
            stripeCustomerId: 'cus_file',
          },
        ],
      }),
    )

    const stored = (await store.read()).clients.find((client) => client.id === 'c1')
    expect(stored.platformInvoicingOptOut).toBe(true)
    expect(stored.stripeCustomerId).toBe('cus_file')
  })
})

/**
 * The void guard on the two invoice WRITERS.
 *
 * "Void & regenerate" made a race real that used to be unreachable: a send or a
 * Stripe webhook can already be in the air when the invoice it names is voided.
 * Letting that late write land would flip a void row back to sent/paid — which
 * on Postgres collides with the live-per-(client, period) partial index (a 500
 * raised AFTER the email has gone out, taking the send log with it) and on the
 * file backend silently leaves the client with two live invoices for one month.
 *
 * Both writers therefore refuse a void row outright and change nothing.
 */
describe('invoice writers refuse a voided invoice (file backend)', () => {
  const voidInvoice = {
    id: 'inv-void',
    clientId: 'c1',
    period: '2026-08',
    number: 'INV-2026-08-001',
    status: 'void',
    lineItems: [{ kind: 'custom', label: 'Bookkeeping', detail: '', amount: 400 }],
    subtotal: 400,
    total: 400,
    dueDate: '2026-09-15',
    blurb: '',
    scopeFlags: [],
    sentAt: null,
    paidAt: null,
    paymentMethod: null,
    createdAt: '2026-08-01T00:00:00.000Z',
    updatedAt: '2026-08-01T00:00:00.000Z',
  }

  beforeEach(async () => {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices = [{ ...voidInvoice }]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
  })

  async function storedVoidInvoice() {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    return data.invoices.find((entry) => entry.id === 'inv-void')
  }

  it('recordInvoiceSent leaves it void and writes nothing', async () => {
    const result = await store.recordInvoiceSent('inv-void', {
      to: ['ann@acme.com'],
      subject: 'Invoice INV-2026-08-001',
      ok: true,
    })

    expect(result).toBeNull()
    const stored = await storedVoidInvoice()
    expect(stored.status).toBe('void')
    expect(stored.sentAt).toBeNull()
    expect(stored.emailLog).toBeUndefined()
    expect(stored.updatedAt).toBe('2026-08-01T00:00:00.000Z')
  })

  it('applyInvoicePayment leaves it void and writes nothing', async () => {
    const result = await store.applyInvoicePayment('inv-void', {
      status: 'paid',
      paymentIntentId: 'pi_123',
      paidAt: '2026-08-20T00:00:00.000Z',
    })

    expect(result).toBeNull()
    const stored = await storedVoidInvoice()
    expect(stored.status).toBe('void')
    expect(stored.paidAt).toBeNull()
    expect(stored.stripePaymentIntentId).toBeUndefined()
    expect(stored.updatedAt).toBe('2026-08-01T00:00:00.000Z')
  })
})

/**
 * `voidUnsentInvoicesForPeriod` — the voiding half of "Void & regenerate".
 *
 * The one thing this must never do is touch an invoice the client has already
 * seen. Everything else about the feature is recoverable (press Generate
 * again); rewriting a sent or paid invoice is not, so each protected status
 * gets its own row here rather than a single representative one.
 *
 * File backend, same reasoning as the block above: Postgres is what production
 * runs and is validated separately with a rolled-back transaction (HANDOFF §4);
 * what is pinned here is the contract both branches implement.
 */
describe('voidUnsentInvoicesForPeriod (file backend)', () => {
  function invoice(id, overrides = {}) {
    return {
      id,
      clientId: `c-${id}`,
      period: '2026-08',
      number: id,
      status: 'draft',
      lineItems: [{ kind: 'custom', label: 'Bookkeeping', detail: '', amount: 400 }],
      subtotal: 400,
      total: 400,
      dueDate: '2026-09-15',
      blurb: '',
      scopeFlags: [],
      sentAt: null,
      paidAt: null,
      paymentMethod: null,
      createdAt: '2026-08-01T00:00:00.000Z',
      updatedAt: '2026-08-01T00:00:00.000Z',
      ...overrides,
    }
  }

  async function seedInvoices(rows) {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices = rows
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
  }

  async function storedStatuses() {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    return Object.fromEntries(data.invoices.map((entry) => [entry.id, entry.status]))
  }

  it('voids the drafts and the reviewed invoices, and counts them', async () => {
    await seedInvoices([
      invoice('a', { status: 'draft' }),
      invoice('b', { status: 'reviewed' }),
      invoice('c', { status: 'draft' }),
    ])

    const result = await store.voidUnsentInvoicesForPeriod('2026-08')

    expect(result.voided).toBe(3)
    expect(result.ids.sort()).toEqual(['a', 'b', 'c'])
    expect(await storedStatuses()).toEqual({ a: 'void', b: 'void', c: 'void' })
  })

  it('never touches an invoice that has left the building', async () => {
    await seedInvoices([
      invoice('sent', { status: 'sent', sentAt: '2026-08-05T00:00:00.000Z' }),
      invoice('processing', { status: 'processing' }),
      invoice('paid', { status: 'paid', paidAt: '2026-08-06T00:00:00.000Z' }),
      invoice('overdue', { status: 'overdue' }),
      invoice('void', { status: 'void' }),
      invoice('draft', { status: 'draft' }),
    ])

    const result = await store.voidUnsentInvoicesForPeriod('2026-08')

    // Only the draft moved; the already-void row is not re-voided or counted.
    expect(result.voided).toBe(1)
    expect(result.ids).toEqual(['draft'])
    expect(await storedStatuses()).toEqual({
      sent: 'sent',
      processing: 'processing',
      paid: 'paid',
      overdue: 'overdue',
      void: 'void',
      draft: 'void',
    })
  })

  it('leaves every other month alone', async () => {
    await seedInvoices([
      invoice('july', { period: '2026-07', status: 'draft' }),
      invoice('august', { period: '2026-08', status: 'reviewed' }),
      invoice('september', { period: '2026-09', status: 'draft' }),
    ])

    const result = await store.voidUnsentInvoicesForPeriod('2026-08')

    expect(result.voided).toBe(1)
    expect(await storedStatuses()).toEqual({
      july: 'draft',
      august: 'void',
      september: 'draft',
    })
  })

  it('reports nothing voided for a month with no unsent invoices', async () => {
    await seedInvoices([invoice('sent', { status: 'sent' })])
    expect(await store.voidUnsentInvoicesForPeriod('2026-08')).toEqual({
      voided: 0,
      ids: [],
      clearing: 0,
      sessions: [],
    })
  })

  // "Void & regenerate" never voided a processing invoice (only draft/reviewed
  // are in its set); what it did NOT do was say so. It now counts them so the
  // month's result can name how many were left alone because a payment is
  // clearing.
  it('leaves an invoice with a clearing payment untouched, and reports it', async () => {
    await seedInvoices([
      invoice('clearing', { status: 'processing' }),
      invoice('draft', { status: 'draft' }),
      invoice('paid', { status: 'paid' }),
      // Another month's processing invoice is not this month's business.
      invoice('other-month', { period: '2026-07', status: 'processing' }),
    ])
    const before = await readFile(localDataPath, 'utf8')

    const result = await store.voidUnsentInvoicesForPeriod('2026-08')

    expect(result).toEqual({ voided: 1, ids: ['draft'], clearing: 1, sessions: [] })
    expect(await storedStatuses()).toEqual({
      clearing: 'processing',
      draft: 'void',
      paid: 'paid',
      'other-month': 'processing',
    })
    // The processing invoice's own row is byte-for-byte what it was.
    const after = JSON.parse(await readFile(localDataPath, 'utf8'))
    const was = JSON.parse(before)
    expect(after.invoices.find((row) => row.id === 'clearing')).toEqual(
      was.invoices.find((row) => row.id === 'clearing'),
    )
  })
})

/**
 * Single-client generation — `generateInvoicesForPeriod(period, { clientId })`,
 * behind the per-client "Email invoice" button offering to build the one
 * invoice that is missing.
 *
 * The point of the scope is blast radius: a click on one client's header must
 * not quietly create invoices for everyone else. The idempotence check is the
 * same rule the month run relies on — a second run must not rewrite a draft
 * that has already been edited.
 */
describe('generateInvoicesForPeriod with a single client (file backend)', () => {
  const period = '2026-08'

  async function seedBillableWorkspace() {
    await store.write(
      workspace({
        clients: [
          { id: 'c1', name: 'Acme', billingMode: 'hourly', hourlyRate: 100 },
          { id: 'c2', name: 'Globex', billingMode: 'hourly', hourlyRate: 100 },
          { id: 'c3', name: 'Initech', billingMode: 'hourly', hourlyRate: 100 },
        ],
        employees: [{ id: 'emp-1', name: 'Lisa', role: 'bookkeeper', billRate: 100 }],
        timeEntries: [
          {
            id: 't1',
            clientId: 'c1',
            employeeId: 'emp-1',
            date: `${period}-04`,
            minutes: 120,
            billable: true,
          },
          {
            id: 't2',
            clientId: 'c2',
            employeeId: 'emp-1',
            date: `${period}-05`,
            minutes: 60,
            billable: true,
          },
        ],
      }),
    )
    // Invoices live outside the bulk save, so start the period genuinely empty.
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices = []
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
  }

  it('creates that client’s invoice and nobody else’s', async () => {
    await seedBillableWorkspace()

    const result = await store.generateInvoicesForPeriod(period, { clientId: 'c1' })

    expect(result.created).toHaveLength(1)
    expect(result.created[0].clientId).toBe('c1')
    // c2 also has billable time this month and must still have no invoice.
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    expect(data.invoices.map((entry) => entry.clientId)).toEqual(['c1'])
  })

  it('is idempotent — a second run skips rather than rewriting', async () => {
    await seedBillableWorkspace()
    await store.generateInvoicesForPeriod(period, { clientId: 'c1' })

    const second = await store.generateInvoicesForPeriod(period, { clientId: 'c1' })

    expect(second.created).toHaveLength(0)
    expect(second.skipped).toEqual([{ clientId: 'c1', reason: 'already-generated' }])
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    expect(data.invoices).toHaveLength(1)
  })

  it('says why when the client has nothing to bill', async () => {
    await seedBillableWorkspace()

    // c3 has no time, no plan and no reimbursements this month.
    const result = await store.generateInvoicesForPeriod(period, { clientId: 'c3' })

    expect(result.created).toHaveLength(0)
    expect(result.skipped).toEqual([{ clientId: 'c3', reason: 'nothing-to-bill' }])
  })

  it('reports the existing invoice, not the lifecycle, when both apply', async () => {
    await seedBillableWorkspace()
    await store.generateInvoicesForPeriod(period, { clientId: 'c1' })
    // c1 is then moved back to prospect — the invoice it already has is still
    // the more useful answer than "not billable yet".
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.clients.find((entry) => entry.id === 'c1').lifecycleStage = 'proposal'
    await writeFile(localDataPath, JSON.stringify(data, null, 2))

    const result = await store.generateInvoicesForPeriod(period, { clientId: 'c1' })

    expect(result.skipped).toEqual([{ clientId: 'c1', reason: 'already-generated' }])
  })

  it('says why when the client is not on file at all', async () => {
    await seedBillableWorkspace()
    const result = await store.generateInvoicesForPeriod(period, { clientId: 'ghost' })
    expect(result.created).toHaveLength(0)
    expect(result.skipped).toEqual([{ clientId: 'ghost', reason: 'no-such-client' }])
  })

  it('still builds every billable client when no clientId is given', async () => {
    await seedBillableWorkspace()

    const result = await store.generateInvoicesForPeriod(period)

    expect(result.created.map((entry) => entry.clientId).sort()).toEqual(['c1', 'c2'])
    // The month run passes prospects over in silence; only c3 (nothing to bill)
    // is worth a reason.
    expect(result.skipped).toEqual([{ clientId: 'c3', reason: 'nothing-to-bill' }])
  })

  /** Retire a seeded client without disturbing anything else about them. */
  async function retire(clientId) {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.clients.find((entry) => entry.id === clientId).lifecycleStage = 'inactive'
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
  }

  it('skips a retired client on the month run, even with billable time', async () => {
    await seedBillableWorkspace()
    await retire('c1')

    const result = await store.generateInvoicesForPeriod(period)

    // c1 has two hours of billable time and would otherwise have invoiced.
    expect(result.created.map((entry) => entry.clientId)).toEqual(['c2'])
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    expect(data.invoices.map((entry) => entry.clientId)).toEqual(['c2'])
  })

  it('names the retirement, not "not billable yet", when asked for that client', async () => {
    await seedBillableWorkspace()
    await retire('c1')

    const result = await store.generateInvoicesForPeriod(period, { clientId: 'c1' })

    expect(result.created).toHaveLength(0)
    expect(result.skipped).toEqual([{ clientId: 'c1', reason: 'client-inactive' }])
  })

  /** Switch a seeded client to billed-outside-the-app, nothing else. */
  async function optOut(clientId) {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.clients.find((entry) => entry.id === clientId).platformInvoicingOptOut = true
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
  }

  it('builds nothing for a client billed outside the app', async () => {
    await seedBillableWorkspace()
    await optOut('c1')

    const result = await store.generateInvoicesForPeriod(period, { clientId: 'c1' })

    expect(result.created).toHaveLength(0)
    expect(result.skipped).toEqual([{ clientId: 'c1', reason: 'opted-out' }])
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    expect(data.invoices).toEqual([])
  })

  // Said OUT LOUD on the month run, unlike the lifecycle reasons. Silence would
  // have the never-generates detector report this client as unbilled every
  // month forever, when the absence is the setting working.
  it('reports the opt-out on the month run too, and bills nobody else differently', async () => {
    await seedBillableWorkspace()
    await optOut('c1')

    const result = await store.generateInvoicesForPeriod(period)

    expect(result.created.map((entry) => entry.clientId)).toEqual(['c2'])
    expect(result.skipped).toEqual(
      expect.arrayContaining([{ clientId: 'c1', reason: 'opted-out' }]),
    )
  })

  // The opt-out is the standing decision; the lifecycle will move. But an
  // invoice that already EXISTS is still the more useful answer — it was built
  // before the toggle went on and is sitting on her screen.
  it('names the existing invoice, not the opt-out, when both apply', async () => {
    await seedBillableWorkspace()
    await store.generateInvoicesForPeriod(period, { clientId: 'c1' })
    await optOut('c1')

    const result = await store.generateInvoicesForPeriod(period, { clientId: 'c1' })

    expect(result.skipped).toEqual([{ clientId: 'c1', reason: 'already-generated' }])
  })

  it('refuses a retainer for a client billed outside the app', async () => {
    await seedBillableWorkspace()
    await optOut('c1')

    expect(await store.createRetainerInvoice({ clientId: 'c1', amount: 500 })).toBeNull()
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    expect(data.invoices).toEqual([])
  })

  it('leaves a retired client’s existing invoices untouched', async () => {
    await seedBillableWorkspace()
    await store.generateInvoicesForPeriod(period, { clientId: 'c1' })
    const before = JSON.parse(await readFile(localDataPath, 'utf8')).invoices
    await retire('c1')

    await store.generateInvoicesForPeriod(period)

    const after = JSON.parse(await readFile(localDataPath, 'utf8')).invoices
    expect(after.filter((entry) => entry.clientId === 'c1')).toEqual(
      before.filter((entry) => entry.clientId === 'c1'),
    )
  })

  it('invoices the client again once they are reactivated', async () => {
    await seedBillableWorkspace()
    await retire('c1')
    expect(await store.generateInvoicesForPeriod(period, { clientId: 'c1' })).toMatchObject({
      created: [],
    })

    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.clients.find((entry) => entry.id === 'c1').lifecycleStage = 'active'
    await writeFile(localDataPath, JSON.stringify(data, null, 2))

    const result = await store.generateInvoicesForPeriod(period, { clientId: 'c1' })
    expect(result.created).toHaveLength(1)
    expect(result.created[0].clientId).toBe('c1')
  })
})

/**
 * THE PAYMENT WINDOW on a generated invoice (Alex, 2026-09-15).
 *
 * Every invoice is due thirty days after the day it is ISSUED. This is the
 * end-to-end version of that rule: the two client records that used to produce
 * a doomed due date — one saying "Due on receipt", one saying nothing at all —
 * going through the real generator. Before the change the first was due on the
 * last day of the month it billed for, so an invoice emailed on Sept 1 for
 * August arrived already past due, and the second was due Sept 30, a day short
 * of a month after it was sent.
 */
describe('the payment window on generated invoices (file backend)', () => {
  const period = '2026-08'

  async function seedTermsWorkspace() {
    await store.write(
      workspace({
        clients: [
          { id: 'c1', name: 'Acme', billingMode: 'hourly', hourlyRate: 100, paymentTerms: 'Due on receipt' },
          { id: 'c2', name: 'Globex', billingMode: 'hourly', hourlyRate: 100, paymentTerms: '' },
          { id: 'c3', name: 'Initech', billingMode: 'hourly', hourlyRate: 100, paymentTerms: 'Net 60' },
        ],
        employees: [{ id: 'emp-1', name: 'Lisa', role: 'bookkeeper', billRate: 100 }],
        timeEntries: [
          { id: 't1', clientId: 'c1', employeeId: 'emp-1', date: `${period}-04`, minutes: 120, billable: true },
          { id: 't2', clientId: 'c2', employeeId: 'emp-1', date: `${period}-05`, minutes: 60, billable: true },
          { id: 't3', clientId: 'c3', employeeId: 'emp-1', date: `${period}-06`, minutes: 60, billable: true },
        ],
      }),
    )
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices = []
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
  }

  it('dates every invoice thirty days from the day it is issued', async () => {
    await seedTermsWorkspace()

    const result = await store.generateInvoicesForPeriod(period, { issueDate: '2026-10-01' })

    const dueByClient = Object.fromEntries(
      result.created.map((invoice) => [invoice.clientId, invoice.dueDate]),
    )
    expect(dueByClient.c1).toBe('2026-10-31')
    expect(dueByClient.c2).toBe('2026-10-31')
    // The one contractual window longer than the firm’s survives untouched.
    expect(dueByClient.c3).toBe('2026-11-30')
  })
})

/**
 * Stage validation. `lifecycle_stage` decides whether a client appears in ANY
 * picker in the app, so a value neither backend recognizes is a client who
 * silently disappears — or a retirement that silently undoes itself on the
 * next save. One `coerceLifecycleStage` guards all three write paths.
 */
describe('lifecycle stage validation (file backend)', () => {
  // These fixtures replace the whole workspace, so they start from none: a bulk
  // save refuses to drop a stored client that has time entries or invoices.
  beforeEach(() => rm(localDataPath, { force: true }))
  it('accepts all four real stages through a bulk save', async () => {
    await store.write(
      workspace({
        clients: [
          { id: 'c1', name: 'Prospect', billingMode: 'hourly', lifecycleStage: 'proposal' },
          { id: 'c2', name: 'Starting', billingMode: 'hourly', lifecycleStage: 'onboarding' },
          { id: 'c3', name: 'Working', billingMode: 'hourly', lifecycleStage: 'active' },
          { id: 'c4', name: 'Former', billingMode: 'hourly', lifecycleStage: 'inactive' },
        ],
      }),
    )

    const data = await store.read()
    expect(data.clients.map((entry) => entry.lifecycleStage)).toEqual([
      'proposal',
      'onboarding',
      'active',
      'inactive',
    ])
  })

  it('clamps a garbage stage to active rather than hiding the client', async () => {
    await store.write(
      workspace({
        clients: [
          { id: 'c1', name: 'Acme', billingMode: 'hourly', lifecycleStage: 'retired' },
          { id: 'c2', name: 'Globex', billingMode: 'hourly', lifecycleStage: null },
        ],
      }),
    )

    const data = await store.read()
    expect(data.clients.map((entry) => entry.lifecycleStage)).toEqual(['active', 'active'])
  })

  it('leaves a client with no stage field alone — absent already reads as active', async () => {
    await store.write(
      workspace({ clients: [{ id: 'c1', name: 'Acme', billingMode: 'hourly' }] }),
    )

    const data = await store.read()
    expect(data.clients[0].lifecycleStage).toBeUndefined()
  })

  it('setClientLifecycleStage retires and reactivates, touching nothing else', async () => {
    await store.write(
      workspace({
        clients: [
          {
            id: 'c1',
            name: 'Acme',
            billingMode: 'hourly',
            hourlyRate: 125,
            planIds: ['plan-1'],
            assignedBookkeeperIds: ['emp-1'],
          },
        ],
        plans: [{ id: 'plan-1', name: 'Classic', monthlyFee: 500 }],
        employees: [{ id: 'emp-1', name: 'Lisa', role: 'bookkeeper' }],
      }),
    )
    const before = (await store.read()).clients[0]

    const retired = await store.setClientLifecycleStage('c1', 'inactive')
    expect(retired.lifecycleStage).toBe('inactive')
    // Everything that decides how this client is worked survives the round trip.
    expect(retired).toMatchObject({
      hourlyRate: before.hourlyRate,
      planIds: before.planIds,
      assignedBookkeeperIds: before.assignedBookkeeperIds,
    })

    const back = await store.setClientLifecycleStage('c1', 'active')
    expect({ ...back, lifecycleStage: before.lifecycleStage }).toEqual(before)
  })

  it('setClientLifecycleStage refuses a stage that is not real', async () => {
    await store.write(
      workspace({ clients: [{ id: 'c1', name: 'Acme', billingMode: 'hourly' }] }),
    )

    // Rejected outright rather than coerced to 'active': a silent coercion here
    // would look like a retirement that succeeded and did nothing.
    expect(await store.setClientLifecycleStage('c1', 'archived')).toBeNull()
    expect((await store.read()).clients[0].lifecycleStage).toBeUndefined()
  })

  it('setClientLifecycleStage returns null for a client that is not on file', async () => {
    await store.write(workspace({ clients: [] }))
    expect(await store.setClientLifecycleStage('ghost', 'inactive')).toBeNull()
  })
})

/**
 * "Just spitballing" brainstorm sessions.
 *
 * The client reported that the assistant "stops partway through a brainstorming
 * session, and its memory does not persist across separate conversations". The
 * modal held the whole conversation in React state, so closing the window threw
 * it away. The conversation now lives in `spitball_sessions`; these pin the
 * store contract both backends implement.
 */
describe('spitball sessions (file backend)', () => {
  beforeEach(async () => {
    // These share the one real tmp/auth-state.json, so clear the slice first —
    // otherwise an earlier test's active session leaks into the next one.
    if (existsSync(localAuthPath)) {
      const auth = JSON.parse(await readFile(localAuthPath, 'utf8'))
      auth.spitballSessions = []
      await writeFile(localAuthPath, JSON.stringify(auth, null, 2))
    }
  })

  it('creates exactly one active session per user and reuses it', async () => {
    expect(await store.getActiveSpitballSession('emp-patrice')).toBeNull()

    const first = await store.ensureActiveSpitballSession('emp-patrice')
    expect(first.status).toBe('active')
    expect(first.messages).toEqual([])

    const second = await store.ensureActiveSpitballSession('emp-patrice')
    expect(second.id).toBe(first.id)

    // A second owner gets her own, not Brittany's.
    const other = await store.ensureActiveSpitballSession('emp-alex')
    expect(other.id).not.toBe(first.id)
  })

  it('round-trips a turn — the conversation survives a fresh store instance', async () => {
    const session = await store.ensureActiveSpitballSession('emp-patrice')
    await store.appendSpitballTurn(session.id, [
      { role: 'user', text: 'what if clients could see their own checklist' },
      { role: 'assistant', text: 'Ooh — who would use it?' },
    ])

    // A brand new store reading the same files is the closest stand-in for
    // "she closed the window and came back".
    const reopened = new AppDataStore()
    await reopened.initialize()
    const loaded = await reopened.getActiveSpitballSession('emp-patrice')

    expect(loaded.id).toBe(session.id)
    expect(loaded.messages.map((m) => m.role)).toEqual(['user', 'assistant'])
    expect(loaded.messages[0].text).toContain('own checklist')
    expect(loaded.messages[0].at).toBeTruthy()
  })

  it('refuses to append to an archived session', async () => {
    const session = await store.ensureActiveSpitballSession('emp-patrice')
    await store.appendSpitballTurn(session.id, [{ role: 'user', text: 'an idea' }])
    await store.archiveSpitballSession(session.id, 'She wants client-visible checklists.')

    expect(await store.appendSpitballTurn(session.id, [{ role: 'user', text: 'more' }])).toBeNull()
  })

  it('compaction keeps the recent turns verbatim and folds the rest into a summary', async () => {
    const session = await store.ensureActiveSpitballSession('emp-patrice')
    const turns = Array.from({ length: 32 }, (_, index) => ({
      role: index % 2 === 0 ? 'user' : 'assistant',
      text: `turn ${index}`,
    }))
    await store.appendSpitballTurn(session.id, turns)

    const compacted = await store.compactSpitballSession(session.id, {
      summary: 'She is circling client-visible checklists.',
      keepRecent: 12,
    })

    expect(compacted.summary).toBe('She is circling client-visible checklists.')
    expect(compacted.messages).toHaveLength(12)
    // The RECENT end is what survives verbatim — turns 20..31.
    expect(compacted.messages[0].text).toBe('turn 20')
    expect(compacted.messages[11].text).toBe('turn 31')
  })

  it('archives with a summary and recalls it, newest first', async () => {
    const first = await store.ensureActiveSpitballSession('emp-patrice')
    await store.appendSpitballTurn(first.id, [{ role: 'user', text: 'idea one' }])
    await store.archiveSpitballSession(first.id, 'Session one: client-visible checklists.')

    const second = await store.ensureActiveSpitballSession('emp-patrice')
    expect(second.id).not.toBe(first.id)
    await store.appendSpitballTurn(second.id, [{ role: 'user', text: 'idea two' }])
    await store.archiveSpitballSession(second.id, 'Session two: reminder emails.')

    const summaries = await store.listSpitballSummaries('emp-patrice', 5)
    expect(summaries.map((entry) => entry.summary)).toEqual([
      'Session two: reminder emails.',
      'Session one: client-visible checklists.',
    ])
  })

  it('skips archived sessions that have no summary — there is nothing to recall', async () => {
    const session = await store.ensureActiveSpitballSession('emp-patrice')
    await store.appendSpitballTurn(session.id, [{ role: 'user', text: 'idea' }])
    await store.archiveSpitballSession(session.id, '')

    expect(await store.listSpitballSummaries('emp-patrice', 5)).toEqual([])
  })

  it('survives a bulk save — the session is not part of the workspace payload', async () => {
    const session = await store.ensureActiveSpitballSession('emp-patrice')
    await store.appendSpitballTurn(session.id, [{ role: 'user', text: 'mid-brainstorm' }])

    // Exactly the write that wiped the historical import: a full workspace
    // save. A live brainstorm must be untouched by it.
    await store.write(workspace())

    const after = await store.getActiveSpitballSession('emp-patrice')
    expect(after.id).toBe(session.id)
    expect(after.messages[0].text).toBe('mid-brainstorm')
  })

  it('is not part of the staleness fingerprint', async () => {
    const before = await store.computeWorkspaceVersion()
    const session = await store.ensureActiveSpitballSession('emp-patrice')
    await store.appendSpitballTurn(session.id, [{ role: 'user', text: 'typing away' }])

    // Brainstorming while another tab is open must not invalidate that tab for
    // writes — same reasoning as `invoices` (invoicing-handoff, gotcha #3).
    expect(await store.computeWorkspaceVersion()).toBe(before)
    expect(BULK_SAVE_TABLES).not.toContain('spitball_sessions')
    expect(workspaceVersionSql()).not.toMatch(/spitball/i)
  })
})

/**
 * A recorder pool for the spitball statements. `fakePostgres` above answers
 * every select with no rows, which would make `ensureActiveSpitballSession`
 * look like a lost insert race; this one lets a test script the reads.
 */
function fakeSpitballPostgres(responder = () => null) {
  const statements = []
  const pool = {
    async query(text, params) {
      const trimmed = String(text).trim()
      statements.push({ text: trimmed, params })
      return responder(trimmed, params) ?? { rows: [], rowCount: 0 }
    },
  }
  return {
    pool,
    statements,
    matching: (pattern) => statements.filter((s) => pattern.test(s.text)),
  }
}

const spitballRow = (overrides = {}) => ({
  id: 'spit-1',
  user_id: 'emp-patrice',
  status: 'active',
  messages: [{ role: 'user', text: 'an idea', at: '2026-08-11T12:00:00.000Z' }],
  summary: null,
  created_at: new Date('2026-08-11T12:00:00.000Z'),
  updated_at: new Date('2026-08-11T12:00:00.000Z'),
  ...overrides,
})

/**
 * Production is Postgres, so the file tests above cannot prove the shipped
 * path. These pin the SQL shapes that matter — the ones a rolled-back
 * validation against production then confirms for real (HANDOFF §4).
 */
describe('spitball sessions (postgres branch)', () => {
  it('inserts against the PARTIAL unique index, and re-reads the winner on a race', async () => {
    let selects = 0
    const fake = fakeSpitballPostgres((text) => {
      if (/^select\b[\s\S]*from spitball_sessions/i.test(text)) {
        selects += 1
        // First read: no session. Second read (after the lost insert race):
        // whatever the other tab created.
        return selects === 1 ? { rows: [], rowCount: 0 } : { rows: [spitballRow()], rowCount: 1 }
      }
      // The insert loses the race.
      return { rows: [], rowCount: 0 }
    })

    const session = await postgresStore(fake).ensureActiveSpitballSession('emp-patrice')

    const insert = fake.matching(/^insert into spitball_sessions/i)[0]
    expect(insert.text).toMatch(/on conflict \(user_id\) where status = 'active' do nothing/i)
    expect(session.id).toBe('spit-1')
  })

  it('appends IN the row, so two turns in flight cannot clobber each other', async () => {
    const fake = fakeSpitballPostgres(() => ({ rows: [spitballRow()], rowCount: 1 }))

    await postgresStore(fake).appendSpitballTurn('spit-1', [
      { role: 'user', text: 'an idea' },
      { role: 'assistant', text: 'say more?' },
    ])

    const update = fake.matching(/^update spitball_sessions/i)[0]
    expect(update.text).toMatch(/set messages = messages \|\| \$2::jsonb/i)
    expect(update.text).toMatch(/where id = \$1 and status = 'active'/i)
    expect(JSON.parse(update.params[1])).toHaveLength(2)
  })

  it('compacts by trimming the row in SQL, not by rewriting a stale array', async () => {
    const fake = fakeSpitballPostgres(() => ({ rows: [spitballRow()], rowCount: 1 }))

    await postgresStore(fake).compactSpitballSession('spit-1', {
      summary: 'the gist so far',
      keepRecent: 12,
    })

    const update = fake.matching(/^update spitball_sessions/i)[0]
    expect(update.text).toMatch(/jsonb_array_elements\(spitball_sessions\.messages\)/i)
    expect(update.text).toMatch(/with ordinality as t\(elem, ord\)/i)
    expect(update.params).toEqual(['spit-1', 'the gist so far', 12])
  })

  it('archives the active session and prunes the old end of the archive', async () => {
    const fake = fakeSpitballPostgres(() => ({
      rows: [spitballRow({ status: 'archived', summary: 'the gist' })],
      rowCount: 1,
    }))

    await postgresStore(fake).archiveSpitballSession('spit-1', 'the gist')

    expect(fake.matching(/^update spitball_sessions/i)[0].text).toMatch(
      /set status = 'archived', summary = \$2/i,
    )
    expect(fake.matching(/^delete from spitball_sessions/i)).toHaveLength(1)
  })

  it('recalls only archived sessions that actually carry a summary', async () => {
    const fake = fakeSpitballPostgres(() => ({ rows: [], rowCount: 0 }))

    await postgresStore(fake).listSpitballSummaries('emp-patrice', 5)

    const select = fake.matching(/^select\b[\s\S]*from spitball_sessions/i)[0]
    expect(select.text).toMatch(/status = 'archived'/i)
    expect(select.text).toMatch(/summary is not null/i)
    expect(select.params).toEqual(['emp-patrice', 5])
  })

  it('the bulk save never touches the table', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).write(workspace())
    expect(fake.matching(/spitball_sessions/i)).toHaveLength(0)
  })
})

/**
 * The two-party waiting-on hand-off, end to end on the file backend.
 *
 * Her report (featreq-b05a2f3a): "A received the notification and clicked
 * Confirmed on the waiting task and it disappeared." These tests pin the half
 * of that which lives in the store — CONFIRMING IS NOT A DELETE. The record has
 * to survive `waiting → resolved → verified` with every name and date on it,
 * because those five fields are the whole receipt for a hand-off between two
 * people.
 *
 * Cancel is the deliberate exception and is pinned here too, so the difference
 * between "this finished" and "this never needed to happen" can't blur.
 */
const WAITING_WORKSPACE = {
  clients: [{ id: 'c1', name: 'Acme' }],
  employees: [
    { id: 'emp-brit', name: 'Brittany', role: 'owner' },
    { id: 'emp-lisa', name: 'Lisa', role: 'bookkeeper' },
  ],
  checklists: [
    {
      id: 'cl-1',
      title: 'August close',
      clientId: 'c1',
      items: [
        { id: 'it-1', label: 'Reconcile the operating account', done: false },
        {
          id: 'it-2',
          label: 'Payroll',
          done: false,
          subItems: [{ id: 'sub-1', title: 'Confirm the hours', done: false }],
        },
      ],
    },
  ],
}

/** The one entry on a node, straight off a fresh read. */
async function readWaitingOns(store, { itemId, subItemId }) {
  const data = await store.read()
  const item = data.checklists.find((c) => c.id === 'cl-1').items.find((i) => i.id === itemId)
  const node = subItemId ? item.subItems.find((s) => s.id === subItemId) : item
  return node.waitingOns ?? []
}

describe('the waiting-on hand-off round-trips (file backend)', () => {
  beforeEach(async () => {
    await store.write(workspace(WAITING_WORKSPACE))
  })

  it('keeps the record through both stages, with every name and date', async () => {
    const added = await store.addWaitingOn(
      'cl-1',
      { itemId: 'it-1' },
      { blockerId: 'emp-lisa', requestedBy: 'emp-brit', note: 'the bank statements' },
    )
    expect(added.entry.id).toMatch(/^wo-/)

    await store.markWaitingOnDone('cl-1', added.entry.id, { userId: 'emp-lisa' })
    const afterDone = await readWaitingOns(store, { itemId: 'it-1' })
    // Stage 1 already used to delete this. It must not.
    expect(afterDone).toHaveLength(1)
    expect(afterDone[0]).toMatchObject({ resolvedBy: 'emp-lisa', blockerId: 'emp-lisa' })
    expect(afterDone[0].verifiedAt).toBeUndefined()

    await store.markWaitingOnVerified('cl-1', added.entry.id, { userId: 'emp-brit' })
    const afterVerify = await readWaitingOns(store, { itemId: 'it-1' })

    // THE regression: confirming keeps the row. It is the record of who did the
    // check, and it is what the step renders as a completed sub-item.
    expect(afterVerify).toHaveLength(1)
    expect(afterVerify[0]).toMatchObject({
      id: added.entry.id,
      blockerId: 'emp-lisa',
      requestedBy: 'emp-brit',
      note: 'the bank statements',
      resolvedBy: 'emp-lisa',
      verifiedBy: 'emp-brit',
    })
    expect(typeof afterVerify[0].createdAt).toBe('string')
    expect(typeof afterVerify[0].resolvedAt).toBe('string')
    expect(typeof afterVerify[0].verifiedAt).toBe('string')
  })

  it('never touches the step it was blocking — confirming is not completing', async () => {
    const added = await store.addWaitingOn(
      'cl-1',
      { itemId: 'it-1' },
      { blockerId: 'emp-lisa', requestedBy: 'emp-brit' },
    )
    await store.markWaitingOnDone('cl-1', added.entry.id, { userId: 'emp-lisa' })
    await store.markWaitingOnVerified('cl-1', added.entry.id, { userId: 'emp-brit' })

    const data = await store.read()
    const item = data.checklists.find((c) => c.id === 'cl-1').items.find((i) => i.id === 'it-1')
    expect(item.done).toBe(false)
  })

  it('round-trips on a SUB-item too (it rides the parent item, not its own column)', async () => {
    const added = await store.addWaitingOn(
      'cl-1',
      { itemId: 'it-2', subItemId: 'sub-1' },
      { blockerId: 'emp-lisa', requestedBy: 'emp-brit' },
    )
    await store.markWaitingOnDone('cl-1', added.entry.id, { userId: 'emp-lisa' })
    await store.markWaitingOnVerified('cl-1', added.entry.id, { userId: 'emp-brit' })

    const entries = await readWaitingOns(store, { itemId: 'it-2', subItemId: 'sub-1' })
    expect(entries).toHaveLength(1)
    expect(entries[0]).toMatchObject({ resolvedBy: 'emp-lisa', verifiedBy: 'emp-brit' })
  })

  it('closes a CLIENT wait in one press, straight to verified', async () => {
    const added = await store.addWaitingOn(
      'cl-1',
      { itemId: 'it-1' },
      { blockerId: 'c1', requestedBy: 'emp-brit', blockerType: 'client' },
    )
    // No second party exists to hand back to, so Done carries `alsoVerify`.
    await store.markWaitingOnDone('cl-1', added.entry.id, {
      userId: 'emp-brit',
      alsoVerify: true,
    })

    const entries = await readWaitingOns(store, { itemId: 'it-1' })
    expect(entries).toHaveLength(1)
    expect(entries[0]).toMatchObject({ blockerType: 'client', verifiedBy: 'emp-brit' })
  })

  /**
   * Her fifth round: "User should not be able to remove the information once it
   * is saved." Cancel used to delete the row outright; the store now has no way
   * to remove one at all, which is what makes the server-side refusal more than
   * a hidden button.
   */
  it('has no removal path left — the record cannot be deleted', async () => {
    expect(store.resolveWaitingOn).toBeUndefined()

    const added = await store.addWaitingOn(
      'cl-1',
      { itemId: 'it-1' },
      { blockerId: 'emp-lisa', requestedBy: 'emp-brit' },
    )
    // The walk that every stage transition rides refuses to drop an entry, so a
    // future mutation that returns nothing fails loudly instead of erasing it.
    await expect(
      store._mutateWaitingOn('cl-1', added.entry.id, () => null),
    ).rejects.toThrow(/never removed/)

    expect(await readWaitingOns(store, { itemId: 'it-1' })).toHaveLength(1)
  })

  it('keeps the record through a send-back and back again', async () => {
    const added = await store.addWaitingOn(
      'cl-1',
      { itemId: 'it-1' },
      { blockerId: 'emp-lisa', requestedBy: 'emp-brit', note: 'the bank statements' },
    )
    await store.markWaitingOnDone('cl-1', added.entry.id, { userId: 'emp-lisa' })
    await store.markWaitingOnSentBack('cl-1', added.entry.id, {
      userId: 'emp-brit',
      note: 'the March page is missing',
    })
    // Sent back = the blocker's move again. Locking deletion must not wedge it.
    const midFlight = await readWaitingOns(store, { itemId: 'it-1' })
    expect(midFlight).toHaveLength(1)
    expect(midFlight[0].resolvedAt).toBeUndefined()
    expect(midFlight[0].sendBacks).toHaveLength(1)

    await store.markWaitingOnDone('cl-1', added.entry.id, { userId: 'emp-lisa' })
    await store.markWaitingOnVerified('cl-1', added.entry.id, { userId: 'emp-brit' })

    const closed = await readWaitingOns(store, { itemId: 'it-1' })
    expect(closed).toHaveLength(1)
    expect(closed[0]).toMatchObject({
      note: 'the bank statements',
      resolvedBy: 'emp-lisa',
      verifiedBy: 'emp-brit',
    })
    expect(closed[0].sendBacks).toHaveLength(1)
  })
})

/**
 * THE invariant. Client assignment was stored twice — `assigned_bookkeeper_ids`
 * and the `client_assignments` table — and only the first gated visibility, so
 * the two could disagree without anything failing. They are one value now, and
 * every mutation path has to keep them one value.
 *
 * On the file backend below, this alone does NOT catch a reintroduced second
 * source: `read()` maps every client through `normalizeClientProfile`, which
 * assigns one computed value to both `assignedBookkeeperIds` and
 * `assignedEmployeeIds` unconditionally, so the two names are trivially equal
 * here no matter what a regression wrote. The real regression power is each
 * test's companion assertion on the actual value (e.g.
 * `assignedBookkeeperIds` equals what was set) — never add a test that calls
 * this helper without one.
 */
const expectOneTeamSource = (client) => {
  expect(client).toBeTruthy()
  expect(client.assignedEmployeeIds).toEqual(client.assignedBookkeeperIds)
}

describe('one source of truth for a client team (file backend)', () => {
  const teamWorkspace = () =>
    workspace({
      clients: [{ id: 'c1', name: 'Acme', assignedBookkeeperIds: ['emp-1'] }],
      employees: [
        { id: 'emp-1', name: 'Lisa', role: 'bookkeeper' },
        { id: 'emp-2', name: 'Dana', role: 'bookkeeper' },
      ],
    })

  const clientFromDisk = async (id = 'c1') => {
    const data = await store.read()
    return data.clients.find((c) => c.id === id)
  }

  beforeEach(async () => {
    await store.write(teamWorkspace())
  })

  it('holds after a bulk-save round trip', async () => {
    expectOneTeamSource(await clientFromDisk())
    expect((await clientFromDisk()).assignedBookkeeperIds).toEqual(['emp-1'])
  })

  it('holds after createClient', async () => {
    const created = await store.createClient({
      name: 'Northwind',
      contact: 'Dana',
      assignedEmployeeIds: ['emp-2'],
    })
    expectOneTeamSource(await clientFromDisk(created.id))
    expect((await clientFromDisk(created.id)).assignedBookkeeperIds).toEqual(['emp-2'])
  })

  it('holds after setClientAssignedTeam', async () => {
    await store.setClientAssignedTeam('c1', ['emp-2'])
    expectOneTeamSource(await clientFromDisk())
    expect((await clientFromDisk()).assignedBookkeeperIds).toEqual(['emp-2'])
  })

  // FLIPPED by the 2026-09-04 team/visibility split. This used to pin that a
  // task assignment ADDED the person to the client's team; that write is what
  // made "assigned team" mean "everyone who ever held work here" and put
  // clients' invoices in front of staff who were never put on them. The method
  // is now a deliberate no-op and the team must be exactly what an owner
  // picked. docs/plans/team-visibility-split-2026-09.md.
  it('is unmoved by grantClientVisibility, which no longer writes', async () => {
    expect(await store.grantClientVisibility('c1', 'emp-2')).toBeNull()
    const client = await clientFromDisk()
    expectOneTeamSource(client)
    expect(client.assignedBookkeeperIds).toEqual(['emp-1'])
  })

  // CARDINAL RULE 1: the no-op has to be a no-op on the PRODUCTION backend
  // too. A file-only no-op would go green in CI while Postgres kept widening
  // real team lists — exactly the shape of bug this repo has been bitten by.
  it('issues no SQL at all on the Postgres backend either', async () => {
    const fake = fakePostgres()
    expect(await postgresStore(fake).grantClientVisibility('c1', 'emp-2')).toBeNull()
    expect(fake.matching(/update clients/i)).toEqual([])
    expect(fake.matching(/from users/i)).toEqual([])
  })

  it('holds after a bulk save carrying a STALE alias', async () => {
    // The shape that used to cause the divergence: a payload whose alias
    // disagrees with the canonical field. The canonical field must win.
    await store.write(
      workspace({
        clients: [
          {
            id: 'c1',
            name: 'Acme',
            assignedBookkeeperIds: ['emp-2'],
            assignedEmployeeIds: ['emp-1'],
          },
        ],
      }),
    )
    const client = await clientFromDisk()
    expectOneTeamSource(client)
    expect(client.assignedBookkeeperIds).toEqual(['emp-2'])
  })

  it('holds after deactivateUser removes someone from the team', async () => {
    await store.setClientAssignedTeam('c1', ['emp-1', 'emp-2'])

    // The plan docs refer to this cleanup informally as "deactivateUser"; the
    // actual store method is `deleteTeamMember(userId, ownerId)` (db/store.js)
    // — same behavior (soft-deactivates, strips the user from every client's
    // assigned team), different name. It needs a real, ACTIVE user in the auth
    // file to act on, and emp-2 is not one of the seeded auth users, so add it
    // here. This suite's top-level beforeAll/afterAll already snapshot and
    // restore tmp/auth-state.json around the whole file, so no extra cleanup
    // is needed beyond what's already in place.
    const authState = JSON.parse(await readFile(localAuthPath, 'utf8'))
    if (!authState.users.some((user) => user.id === 'emp-2')) {
      authState.users.push({
        id: 'emp-2',
        name: 'Dana',
        email: 'dana@pbj.local',
        staffRole: 'Bookkeeper',
        role: 'bookkeeper',
      })
      await writeFile(localAuthPath, JSON.stringify(authState, null, 2))
    }

    const result = await store.deleteTeamMember('emp-2', 'owner-1')
    expect(result).toEqual({ ok: true })

    const client = await clientFromDisk()
    expectOneTeamSource(client)
    expect(client.assignedBookkeeperIds).not.toContain('emp-2')
  })
})

/**
 * SEND BACK — "a button to not approve and send back with another note"
 * (featreq-b05a2f3a, the firm owner's fourth round on the waiting-on flow).
 *
 * The transition that makes the hand-off a loop rather than a line:
 *
 *   waiting --B's Done--> resolved --A's Send back--> waiting --B's Done--> ...
 *
 * What makes it safe is that it MOVES rather than deletes. `resolvedAt` /
 * `resolvedBy` have to be cleared or the wait would still read as `resolved`
 * and never return to B's queue — so they are stashed on the `sendBacks[]`
 * event that cleared them, alongside A's new note. The ORIGINAL note, the
 * requester and the creation date are never touched.
 *
 * File backend here; the Postgres statement shape is pinned separately below.
 */
describe('markWaitingOnSentBack (file backend)', () => {
  const ASKED = 'emp-brit' // A, who asked
  const BLOCKER = 'emp-lisa' // B, who was waited on

  const seedWait = async (overrides = {}) => {
    await store.write(
      workspace({
        employees: [
          { id: ASKED, name: 'Brittany', role: 'owner' },
          { id: BLOCKER, name: 'Lisa', role: 'bookkeeper' },
        ],
        checklists: [
          {
            id: 'cl-1',
            clientId: 'c1',
            title: 'August close',
            items: [
              {
                id: 'it-1',
                label: 'Bank rec',
                done: false,
                assigneeId: ASKED,
                waitingOns: [
                  {
                    id: 'wo-1',
                    blockerId: BLOCKER,
                    requestedBy: ASKED,
                    note: 'the bank statements',
                    createdAt: '2026-08-05T15:00:00.000Z',
                    ...overrides,
                  },
                ],
                subItems: [],
              },
            ],
          },
        ],
      }),
    )
  }

  const RESOLVED = { resolvedAt: '2026-08-07T15:00:00.000Z', resolvedBy: BLOCKER }

  const entryFromDisk = async () => {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    return data.checklists[0].items[0].waitingOns[0]
  }

  it('returns a resolved wait to the blocker and keeps BOTH notes', async () => {
    await seedWait(RESOLVED)

    const result = await store.markWaitingOnSentBack('cl-1', 'wo-1', {
      userId: ASKED,
      note: 'the March page is missing',
    })
    expect(result).not.toBeNull()

    const entry = await entryFromDisk()
    // Back to B's move.
    expect(entry.resolvedAt).toBeUndefined()
    expect(entry.resolvedBy).toBeUndefined()
    expect(entry.verifiedAt).toBeUndefined()
    // The original note is NOT overwritten — that was the whole instruction.
    expect(entry.note).toBe('the bank statements')
    expect(entry.requestedBy).toBe(ASKED)
    expect(entry.createdAt).toBe('2026-08-05T15:00:00.000Z')
    // ...and the rejected resolution survives on the event that cleared it.
    expect(entry.sendBacks).toHaveLength(1)
    expect(entry.sendBacks[0]).toMatchObject({
      by: ASKED,
      note: 'the March page is missing',
      resolvedAt: RESOLVED.resolvedAt,
      resolvedBy: BLOCKER,
    })
    expect(typeof entry.sendBacks[0].at).toBe('string')
  })

  it('appends on every lap, oldest first', async () => {
    await seedWait(RESOLVED)
    await store.markWaitingOnSentBack('cl-1', 'wo-1', { userId: ASKED, note: 'first pass' })
    await store.markWaitingOnDone('cl-1', 'wo-1', { userId: BLOCKER })
    await store.markWaitingOnSentBack('cl-1', 'wo-1', { userId: ASKED, note: 'second pass' })

    const entry = await entryFromDisk()
    expect(entry.sendBacks.map((event) => event.note)).toEqual(['first pass', 'second pass'])
    expect(entry.note).toBe('the bank statements')
  })

  it('survives the read() round-trip — normalizeWaitingOns must not eat it', async () => {
    await seedWait(RESOLVED)
    await store.markWaitingOnSentBack('cl-1', 'wo-1', { userId: ASKED, note: 'not yet' })

    // read() re-normalizes every node and writes its materialized output back;
    // a field the normalizer drops is erased on the next page load.
    const data = await store.read()
    const entry = data.checklists[0].items[0].waitingOns[0]
    expect(entry.sendBacks).toEqual([
      expect.objectContaining({ by: ASKED, note: 'not yet', resolvedBy: BLOCKER }),
    ])
    expect(entry.resolvedAt).toBeUndefined()
  })

  it('closes out normally after the lap, keeping the whole history', async () => {
    await seedWait(RESOLVED)
    await store.markWaitingOnSentBack('cl-1', 'wo-1', { userId: ASKED, note: 'redo it' })
    await store.markWaitingOnDone('cl-1', 'wo-1', { userId: BLOCKER })
    await store.markWaitingOnVerified('cl-1', 'wo-1', { userId: ASKED })

    const entry = await entryFromDisk()
    expect(entry.verifiedBy).toBe(ASKED)
    expect(entry.resolvedBy).toBe(BLOCKER)
    expect(entry.note).toBe('the bank statements')
    expect(entry.sendBacks).toHaveLength(1)
  })

  it('never touches the step own done flag', async () => {
    await seedWait(RESOLVED)
    await store.markWaitingOnSentBack('cl-1', 'wo-1', { userId: ASKED, note: 'again please' })

    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    expect(data.checklists[0].items[0].done).toBe(false)
  })

  it('returns null for a wait that is not there', async () => {
    await seedWait()
    expect(
      await store.markWaitingOnSentBack('cl-1', 'wo-nope', { userId: ASKED, note: 'x' }),
    ).toBeNull()
  })
})

/**
 * The same transition's POSTGRES shape — the branch production runs.
 *
 * NO new statement is introduced: send-back rides the existing
 * `_persistItemWaitingOns` update, the same one Done and Approve use. What IS
 * new is a key inside that JSONB payload (`sendBacks[]`), and a JSONB field the
 * normalizer doesn't carry is erased on the next read — which is why this
 * asserts on the parameter, not just the SQL text. (The update now runs inside
 * the transaction that locked the step's row; its order is pinned further down,
 * with the other waiting-on writers.)
 */
describe('markWaitingOnSentBack statement shape (postgres branch)', () => {
  const ASKED = 'emp-brit'
  const BLOCKER = 'emp-lisa'

  const resolvedEntry = () => ({
    id: 'wo-1',
    blockerId: BLOCKER,
    requestedBy: ASKED,
    note: 'the bank statements',
    createdAt: '2026-08-05T15:00:00.000Z',
    resolvedAt: '2026-08-07T15:00:00.000Z',
    resolvedBy: BLOCKER,
  })

  /** `_mutateWaitingOn` reads through `read()`; stub it to the row under test. */
  function pgStoreFor(items) {
    const fake = fakePostgres()
    const pgStore = postgresStore(fake)
    pgStore.read = async () => ({
      checklists: [{ id: 'cl-1', clientId: 'c1', title: 'August close', items }],
    })
    // The write itself starts with the step's own row, read `for update`. Taken
    // from a copy made now: `read()` hands the same objects to the method, which
    // changes them in memory, and the database row is not that object.
    const rows = items.map((item) => lockedRowOf(structuredClone(item)))
    answerLockedChecklistItem(fake, (_checklistId, itemId) => rows.find((row) => row.id === itemId) ?? null)
    return { fake, pgStore }
  }

  const itemLevel = () => [
    {
      id: 'it-1',
      label: 'Bank rec',
      done: false,
      assigneeId: ASKED,
      waitingOns: [resolvedEntry()],
      subItems: [],
    },
  ]

  it('writes through the existing waiting_ons update — no new statement', async () => {
    const { fake, pgStore } = pgStoreFor(itemLevel())
    await pgStore.markWaitingOnSentBack('cl-1', 'wo-1', { userId: ASKED, note: 'the March page' })

    const updates = fake.matching(/^update checklist_items set waiting_ons = \$3::jsonb/i)
    expect(updates).toHaveLength(1)
    expect(updates[0].params.slice(0, 2)).toEqual(['cl-1', 'it-1'])
    // Nothing else in the schema is touched by a send-back.
    expect(fake.matching(/^update checklist_items set sub_items/i)).toHaveLength(0)
  })

  it('carries sendBacks[] into the JSONB, with the resolution it cleared', async () => {
    const { fake, pgStore } = pgStoreFor(itemLevel())
    await pgStore.markWaitingOnSentBack('cl-1', 'wo-1', { userId: ASKED, note: 'the March page' })

    const written = JSON.parse(
      fake.matching(/^update checklist_items set waiting_ons/i)[0].params[2],
    )
    expect(written).toHaveLength(1)
    expect(written[0].note).toBe('the bank statements')
    expect(written[0].resolvedAt).toBeUndefined()
    expect(written[0].resolvedBy).toBeUndefined()
    expect(written[0].sendBacks).toEqual([
      expect.objectContaining({
        by: ASKED,
        note: 'the March page',
        resolvedAt: '2026-08-07T15:00:00.000Z',
        resolvedBy: BLOCKER,
      }),
    ])
  })

  it('rewrites the sub_items JSONB instead when the wait is on a sub-item', async () => {
    const { fake, pgStore } = pgStoreFor([
      {
        id: 'it-1',
        label: 'Bank rec',
        done: false,
        assigneeId: ASKED,
        waitingOns: [],
        subItems: [
          {
            id: 'sub-1',
            title: 'Pull statements',
            done: false,
            waitingOns: [resolvedEntry()],
          },
        ],
      },
    ])
    await pgStore.markWaitingOnSentBack('cl-1', 'wo-1', { userId: ASKED, note: 'the March page' })

    const updates = fake.matching(/^update checklist_items set sub_items = \$3::jsonb/i)
    expect(updates).toHaveLength(1)
    const subItems = JSON.parse(updates[0].params[2])
    expect(subItems[0].waitingOns[0].sendBacks).toHaveLength(1)
    expect(subItems[0].waitingOns[0].resolvedAt).toBeUndefined()
  })
})

/**
 * `created_at` through the bulk save.
 *
 * Every re-insert in the Postgres branch used to OMIT `created_at`, so the
 * column's `default now()` fired again on each wipe-and-rewrite. In production
 * that meant all 753 checklists claimed to have been created on the day of the
 * most recent owner autosave — the creation dates were being destroyed on a
 * schedule, silently, and the historical ones are gone for good.
 *
 * The fix is the technique the invoice restore already used: snapshot inside the
 * transaction BEFORE the deletes, then supply the value. Deliberately NOT taken
 * from the payload — `read()` does not even send most of these, and a stale tab
 * that did carry one could rewrite history.
 *
 * These are STATEMENT-SHAPE tests. The file backend cannot see this bug at all
 * (it re-writes whole records and has no column defaults), so a shape assertion
 * on what the transaction issues is the only guard CI can offer.
 */
describe('bulk save preserves created_at (postgres branch)', () => {
  const ORIGINAL = new Date('2026-01-15T10:00:00.000Z')

  /** One row per created_at-carrying table, all claiming the same old date. */
  const snapshotRows = {
    subscription_plans: [{ id: 'plan-1', created_at: ORIGINAL }],
    contacts: [{ id: 'contact-1', created_at: ORIGINAL }],
    clients: [{ id: 'c1', created_at: ORIGINAL }],
    reimbursements: [{ id: 'reim-1', created_at: ORIGINAL }],
    recurring_reimbursements: [{ id: 'rec-1', created_at: ORIGINAL }],
    checklist_templates: [{ id: 'tpl-1', created_at: ORIGINAL }],
    checklist_template_items: [{ id: 'tpl-item-1', created_at: ORIGINAL }],
    checklists: [{ id: 'cl-1', created_at: ORIGINAL }],
    checklist_items: [{ id: 'item-1', created_at: ORIGINAL }],
  }

  /** A payload carrying exactly one row for each of those tables. */
  const historyWorkspace = () =>
    workspace({
      clients: [{ id: 'c1', name: 'Acme' }],
      plans: [{ id: 'plan-1', name: 'Basic', templateIds: [] }],
      contacts: [{ id: 'contact-1', name: 'Pat' }],
      reimbursements: [
        { id: 'reim-1', clientId: 'c1', date: '2026-02-01', description: 'Stamps', amount: 10 },
      ],
      recurringReimbursements: [
        {
          id: 'rec-1',
          clientId: 'c1',
          description: 'Software',
          amount: 20,
          frequency: 'monthly',
          startDate: '2026-01-01',
        },
      ],
      checklistTemplates: [
        {
          id: 'tpl-1',
          title: 'Monthly close',
          clientId: 'c1',
          assigneeId: 'emp-1',
          frequency: 'monthly',
          nextDueDate: '2026-02-28',
          active: true,
          stages: [
            {
              id: 'stage-1',
              name: 'Stage 1',
              assigneeId: 'emp-1',
              offsetDays: 0,
              items: [{ id: 'tpl-item-1', label: 'Reconcile' }],
            },
          ],
        },
      ],
      checklists: [
        {
          id: 'cl-1',
          title: 'January close',
          clientId: 'c1',
          assigneeId: 'emp-1',
          dueDate: '2026-01-31',
          items: [{ id: 'item-1', label: 'Reconcile', done: false }],
        },
      ],
    })

  it('snapshots every affected table BEFORE the first delete', async () => {
    const fake = fakePostgres({ createdAtRows: snapshotRows })
    await postgresStore(fake).write(historyWorkspace())

    const firstDeleteAt = fake.indexOf(/^delete from /i)
    expect(firstDeleteAt).toBeGreaterThan(-1)
    for (const table of CREATED_AT_PRESERVED_TABLES) {
      const at = fake.indexOf(new RegExp(`^select id, created_at from ${table}$`, 'i'))
      expect(at, `${table} is never snapshotted`).toBeGreaterThan(-1)
      expect(at, `${table} is snapshotted after the wipe`).toBeLessThan(firstDeleteAt)
    }
  })

  it('names created_at on the re-insert for every one of them', async () => {
    const fake = fakePostgres({ createdAtRows: snapshotRows })
    await postgresStore(fake).write(historyWorkspace())

    for (const table of CREATED_AT_PRESERVED_TABLES) {
      const inserts = fake.matching(new RegExp(`^insert into ${table}\\b`, 'i'))
      expect(inserts.length, `${table} never re-inserted by this payload`).toBeGreaterThan(0)
      // The column has to be NAMED — omitting it is exactly the bug, and the
      // `default now()` behind it makes the omission invisible at runtime.
      expect(inserts[0].text, `${table} insert omits created_at`).toMatch(/\bcreated_at\b/)
    }
  })

  it('supplies the ORIGINAL timestamp, not the default', async () => {
    const fake = fakePostgres({ createdAtRows: snapshotRows })
    await postgresStore(fake).write(historyWorkspace())

    for (const table of CREATED_AT_PRESERVED_TABLES) {
      const row = insertedRows(fake.statements, table)[0]
      expect(row.created_at, `${table} lost its original created_at`).toBe(ORIGINAL)
    }
  })

  it('falls back to a fresh timestamp for a genuinely new row', async () => {
    // No snapshot at all: every row in this payload is new.
    const fake = fakePostgres()
    const before = Date.now()
    await postgresStore(fake).write(historyWorkspace())

    const supplied = insertedRows(fake.statements, 'checklists')[0].created_at
    expect(supplied).toBeInstanceOf(Date)
    expect(supplied.getTime()).toBeGreaterThanOrEqual(before)
  })

  it('ignores a createdAt the payload carries — a stale tab cannot rewrite history', async () => {
    const fake = fakePostgres({ createdAtRows: snapshotRows })
    const payload = historyWorkspace()
    payload.checklists[0].createdAt = '2019-01-01T00:00:00.000Z'
    await postgresStore(fake).write(payload)

    const row = insertedRows(fake.statements, 'checklists')[0]
    expect(row.created_at).toBe(ORIGINAL)
    expect(Object.values(row)).not.toContain('2019-01-01T00:00:00.000Z')
  })
})

/**
 * `checklist_items.completed_at` — the record of WHEN a step was finished.
 *
 * `done` is a bare boolean and always was, so nothing in the product recorded
 * the moment anything was completed. The Completed tasks tab is an audit
 * surface, so the rule has to hold in both directions: a completion is stamped,
 * an un-tick clears the stamp, and no unrelated write may invent or erase one.
 */
describe('completed_at on checklist items (postgres branch)', () => {
  const itemRow = (over = {}) => ({
    id: 'item-1',
    checklist_id: 'cl-1',
    label: 'Reconcile',
    done: false,
    sub_items: [],
    ...over,
  })

  /**
   * A Postgres store whose per-item read returns `row`, so the read-modify-write
   * toggle path has something to toggle. Everything else falls through to the
   * recording fake.
   */
  function pgStoreWithItem(row) {
    const fake = fakePostgres()
    const store = postgresStore(fake)
    const inner = fake.pool.query.bind(fake.pool)
    fake.pool.query = async (text, params) => {
      const result = await inner(text, params)
      if (/^select (id, (checklist_id, label, |label, )?done|done|sub_items).*from checklist_items/is.test(String(text).trim())) {
        return { rows: [row], rowCount: 1 }
      }
      return result
    }
    // The toggle reads and writes on ONE connection inside a transaction; that
    // connection answers through the same (patched) query.
    fake.pool.connect = async () => ({
      query: (text, params) => fake.pool.query(text, params),
      release() {},
    })
    return { fake, store }
  }

  it('stamps the completion in the same UPDATE that sets done', async () => {
    const { fake, store } = pgStoreWithItem(itemRow())
    await store.toggleChecklistItem('cl-1', 'item-1')

    const update = fake.matching(/^update checklist_items\s+set done = \$3/i)[0]
    expect(update).toBeDefined()
    expect(update.text).toMatch(
      /completed_at = case when \$3 then coalesce\(completed_at, now\(\)\)/,
    )
    expect(update.text).toMatch(/else null end/)
    // $3 is the new `done` — the one expression covers both directions.
    expect(update.params[2]).toBe(true)
  })

  it('clears it when the step is un-ticked', async () => {
    const { fake, store } = pgStoreWithItem(itemRow({ done: true }))
    await store.toggleChecklistItem('cl-1', 'item-1')

    const update = fake.matching(/^update checklist_items\s+set done = \$3/i)[0]
    expect(update.params[2]).toBe(false)
    expect(update.text).toMatch(/else null end/)
  })

  it('answers null, not a silent success, when the UPDATE touches no row (Postgres)', async () => {
    const { fake, store } = pgStoreWithItem(itemRow())
    const inner = fake.pool.query.bind(fake.pool)
    fake.pool.query = async (text, params) => {
      const result = await inner(text, params)
      if (/^update checklist_items\s+set done = \$3/i.test(String(text).trim())) {
        return { rows: [], rowCount: 0 }
      }
      return result
    }

    expect(await store.toggleChecklistItem('cl-1', 'item-1')).toBeNull()
    expect(fake.matching(/^update checklist_items\s+set done = \$3/i)).toHaveLength(1)
  })

  it('follows the roll-up when a sub-item is added', async () => {
    // Every sub-item write recomputes the parent `done`; the stamp has to move
    // with it or a task can be "complete" with no completion date.
    const { fake, store } = pgStoreWithItem(itemRow({ done: true }))
    await store.addChecklistSubItem('cl-1', 'item-1', 'Pull statements')

    const update = fake.matching(
      /^update checklist_items\s+set sub_items = \$3::jsonb, done = \$4/i,
    )[0]
    expect(update).toBeDefined()
    expect(update.text).toMatch(/completed_at = case when \$4 then/)
  })

  it('bulk save keeps the stored stamp and ignores the payload', async () => {
    const stamped = new Date('2026-03-02T15:30:00.000Z')
    const fake = fakePostgres({
      priorItemRows: [{ id: 'item-1', done: true, completed_at: stamped }],
    })
    await postgresStore(fake).write(
      workspace({
        clients: [{ id: 'c1', name: 'Acme' }],
        checklists: [
          {
            id: 'cl-1',
            title: 'January close',
            clientId: 'c1',
            assigneeId: 'emp-1',
            dueDate: '2026-01-31',
            items: [
              {
                id: 'item-1',
                label: 'Reconcile',
                done: true,
                // A stale tab's idea of when this finished. Must not win.
                completedAt: '2019-01-01T00:00:00.000Z',
              },
            ],
          },
        ],
      }),
    )

    const insert = fake.matching(/^insert into checklist_items\b/i)[0]
    expect(insert.text).toMatch(/\bcompleted_at\b/)
    const [row] = insertedRows(fake.statements, 'checklist_items')
    expect(row.completed_at).toBe(stamped)
    expect(Object.values(row)).not.toContain('2019-01-01T00:00:00.000Z')
  })

  it('bulk save writes null for a step that is not done', async () => {
    const fake = fakePostgres({
      priorItemRows: [
        { id: 'item-1', done: true, completed_at: new Date('2026-03-02T15:30:00.000Z') },
      ],
    })
    await postgresStore(fake).write(
      workspace({
        clients: [{ id: 'c1', name: 'Acme' }],
        checklists: [
          {
            id: 'cl-1',
            title: 'January close',
            clientId: 'c1',
            assigneeId: 'emp-1',
            dueDate: '2026-01-31',
            items: [{ id: 'item-1', label: 'Reconcile', done: false }],
          },
        ],
      }),
    )

    expect(insertedRows(fake.statements, 'checklist_items')[0].completed_at).toBeNull()
  })

  it('leaves a legacy complete-but-unstamped row unstamped rather than backdating it', async () => {
    // The row was already done before the column existed. Stamping it now would
    // put today's date on work finished months ago, on an AUDIT screen.
    const fake = fakePostgres({
      priorItemRows: [{ id: 'item-1', done: true, completed_at: null }],
    })
    await postgresStore(fake).write(
      workspace({
        clients: [{ id: 'c1', name: 'Acme' }],
        checklists: [
          {
            id: 'cl-1',
            title: 'January close',
            clientId: 'c1',
            assigneeId: 'emp-1',
            dueDate: '2026-01-31',
            items: [{ id: 'item-1', label: 'Reconcile', done: true }],
          },
        ],
      }),
    )

    expect(insertedRows(fake.statements, 'checklist_items')[0].completed_at).toBeNull()
  })
})

/**
 * Column parity between the checklist-item SELECT and its row mapper — the same
 * guard, and for the same reason, as the invoice one above. `completed_at` is
 * the newest column on `checklist_items`; left out of the select it would read
 * as `undefined` on Postgres and correctly on the file backend, so every test
 * here would pass while production showed no completion dates at all.
 */
describe('read() selects every column mapChecklistItemRow reads', () => {
  it('has no column the mapper reads but the select omits', () => {
    const readColumns = new Set()
    mapChecklistItemRow(
      new Proxy(
        {},
        {
          get(_target, key) {
            if (typeof key === 'string') readColumns.add(key)
            return undefined
          },
        },
      ),
    )

    const selected = new Set(
      CHECKLIST_ITEM_SELECT_COLUMNS.split(',')
        .map((column) => column.trim())
        .filter(Boolean),
    )

    expect(readColumns.size).toBeGreaterThan(8)
    expect([...readColumns].filter((column) => !selected.has(column))).toEqual([])
    expect(selected.has('completed_at')).toBe(true)
  })

  it('emits completedAt only when the row carries one', () => {
    const stamped = mapChecklistItemRow({
      id: 'item-1',
      label: 'Reconcile',
      done: true,
      completed_at: new Date('2026-03-02T15:30:00.000Z'),
    })
    expect(stamped.completedAt).toBe('2026-03-02T15:30:00.000Z')

    const legacy = mapChecklistItemRow({
      id: 'item-2',
      label: 'Reconcile',
      done: true,
      completed_at: null,
    })
    expect(legacy).not.toHaveProperty('completedAt')
  })
})

/**
 * The FILE backend's half of the same two contracts (cardinal rule 1).
 *
 * This backend re-writes each record WHOLE, which is often assumed to be
 * protection in itself. It is not: whatever the payload omits is gone, and
 * whatever it carries is believed. So the same rule is enforced here — the
 * persisted value wins over the payload's, and only a step this save actually
 * completes gets a fresh stamp.
 */
describe('bulk save preserves checklist history (file backend)', () => {
  const checklistWith = (items, over = {}) => ({
    id: 'cl-1',
    title: 'January close',
    clientId: 'c1',
    assigneeId: 'emp-1',
    dueDate: '2026-01-31',
    items,
    ...over,
  })

  const persisted = async () => JSON.parse(await readFile(localDataPath, 'utf8'))

  it('keeps a checklist createdAt the payload dropped', async () => {
    await store.write(
      workspace({
        checklists: [
          checklistWith([{ id: 'item-1', label: 'Reconcile', done: false }], {
            createdAt: '2026-01-02T09:00:00.000Z',
          }),
        ],
      }),
    )

    // The next save has no createdAt at all — the shape `read()` actually sends.
    await store.write(
      workspace({
        checklists: [checklistWith([{ id: 'item-1', label: 'Reconcile', done: false }])],
      }),
    )

    expect((await persisted()).checklists[0].createdAt).toBe('2026-01-02T09:00:00.000Z')
  })

  it('stamps a completion, and keeps it across the next bulk save', async () => {
    await store.write(
      workspace({
        checklists: [checklistWith([{ id: 'item-1', label: 'Reconcile', done: false }])],
      }),
    )
    await store.toggleChecklistItem('cl-1', 'item-1')

    const stamped = (await persisted()).checklists[0].items[0].completedAt
    expect(stamped).toBeTruthy()

    // A save whose payload carries a DIFFERENT stamp must not rewrite it.
    await store.write(
      workspace({
        checklists: [
          checklistWith([
            {
              id: 'item-1',
              label: 'Reconcile',
              done: true,
              completedAt: '2019-01-01T00:00:00.000Z',
            },
          ]),
        ],
      }),
    )

    expect((await persisted()).checklists[0].items[0].completedAt).toBe(stamped)
  })

  it('clears the stamp when the step is un-ticked', async () => {
    await store.write(
      workspace({
        checklists: [checklistWith([{ id: 'item-1', label: 'Reconcile', done: false }])],
      }),
    )
    await store.toggleChecklistItem('cl-1', 'item-1')
    expect((await persisted()).checklists[0].items[0].completedAt).toBeTruthy()

    await store.toggleChecklistItem('cl-1', 'item-1')
    const item = (await persisted()).checklists[0].items[0]
    expect(item.done).toBe(false)
    expect(item).not.toHaveProperty('completedAt')
  })

  it('does not backdate a step that was already done before stamps existed', async () => {
    // The legacy state, written straight to the file: complete, never stamped.
    // (It cannot be produced through `write()` — that path stamps a new item
    // arriving complete, which is the right answer for a NEW item.)
    await writeFile(
      localDataPath,
      JSON.stringify(
        workspace({
          checklists: [checklistWith([{ id: 'item-1', label: 'Reconcile', done: true }])],
        }),
        null,
        2,
      ),
    )

    // Still done, still unstamped — a bulk save is not a completion event, and
    // today's date on work finished months ago would be a lie on an audit view.
    await store.write(
      workspace({
        checklists: [checklistWith([{ id: 'item-1', label: 'Reconcile', done: true }])],
      }),
    )

    expect((await persisted()).checklists[0].items[0]).not.toHaveProperty('completedAt')
  })

  it('stamps a step the bulk save itself completes', async () => {
    await store.write(
      workspace({
        checklists: [checklistWith([{ id: 'item-1', label: 'Reconcile', done: false }])],
      }),
    )
    await store.write(
      workspace({
        checklists: [checklistWith([{ id: 'item-1', label: 'Reconcile', done: true }])],
      }),
    )

    expect((await persisted()).checklists[0].items[0].completedAt).toBeTruthy()
  })
})

/**
 * Statement dates box (featreq-11ffb3a6) — the FILE backend, end to end.
 *
 * Reference-only per-client list: an account name and the day of the month
 * its statement usually appears. Cardinal rule 1: this half proves the shape
 * both branches implement (a whole-list replace, validated and capped); the
 * Postgres half below pins the delete + insert transaction and its params.
 */
describe('statement dates box (file backend)', () => {
  const authPersisted = async () => JSON.parse(await readFile(localAuthPath, 'utf8'))

  it('starts empty for a client with no rows saved yet', async () => {
    expect(await store.listClientStatementAccounts('c-stmt-empty')).toEqual([])
  })

  it('saves a list and lists it back in saved order with minted ids', async () => {
    const saved = await store.saveClientStatementAccounts('c-stmt-1', [
      { name: 'TD Bank 4920', dayOfMonth: 12 },
      { name: 'Amex 1108', dayOfMonth: 3 },
    ])
    expect(saved.map((row) => row.name)).toEqual(['TD Bank 4920', 'Amex 1108'])
    expect(saved.map((row) => row.sortOrder)).toEqual([0, 1])
    expect(saved.every((row) => row.id.startsWith('stmt-'))).toBe(true)

    const listed = await store.listClientStatementAccounts('c-stmt-1')
    expect(listed.map((row) => row.name)).toEqual(['TD Bank 4920', 'Amex 1108'])
  })

  it('lists rows that share a sort order in id order, and the stale check agrees with the list', async () => {
    const authState = JSON.parse(await readFile(localAuthPath, 'utf8'))
    authState.clientStatementAccounts = [
      { id: 'stmt-bbbbbbbb', clientId: 'c-stmt-tie', name: 'B', dayOfMonth: 2, sortOrder: 0 },
      { id: 'stmt-aaaaaaaa', clientId: 'c-stmt-tie', name: 'A', dayOfMonth: 1, sortOrder: 0 },
    ]
    await writeFile(localAuthPath, JSON.stringify(authState, null, 2))

    const listed = await store.listClientStatementAccounts('c-stmt-tie')
    expect(listed.map((row) => row.id)).toEqual(['stmt-aaaaaaaa', 'stmt-bbbbbbbb'])
    // A tab that saves with the version it was just handed is not refused.
    await expect(
      store.saveClientStatementAccounts(
        'c-stmt-tie',
        [{ id: 'stmt-aaaaaaaa', name: 'A', dayOfMonth: 1 }],
        statementAccountsVersion(listed),
      ),
    ).resolves.toHaveLength(1)
  })

  it('replaces the whole list — a second save drops rows left out of it', async () => {
    await store.saveClientStatementAccounts('c-stmt-2', [
      { name: 'TD Bank 4920', dayOfMonth: 12 },
      { name: 'Amex 1108', dayOfMonth: 3 },
    ])
    const second = await store.saveClientStatementAccounts('c-stmt-2', [
      { name: 'Amex 1108', dayOfMonth: 5 },
    ])
    expect(second).toHaveLength(1)
    const listed = await store.listClientStatementAccounts('c-stmt-2')
    expect(listed).toHaveLength(1)
    expect(listed[0].dayOfMonth).toBe(5)
  })

  it('keeps a row’s id across a re-save when the caller sends it back — an edit, not a new row', async () => {
    const [first] = await store.saveClientStatementAccounts('c-stmt-3', [
      { name: 'TD Bank 4920', dayOfMonth: 12 },
    ])
    const [second] = await store.saveClientStatementAccounts('c-stmt-3', [
      { id: first.id, name: 'TD Bank 4920', dayOfMonth: 15 },
    ])
    expect(second.id).toBe(first.id)
    expect(second.dayOfMonth).toBe(15)
  })

  it('never touches another client’s rows', async () => {
    await store.saveClientStatementAccounts('c-stmt-4a', [{ name: 'A', dayOfMonth: 1 }])
    await store.saveClientStatementAccounts('c-stmt-4b', [{ name: 'B', dayOfMonth: 2 }])
    await store.saveClientStatementAccounts('c-stmt-4a', [{ name: 'A2', dayOfMonth: 3 }])
    expect((await store.listClientStatementAccounts('c-stmt-4b'))[0].name).toBe('B')
  })

  it('drops a row with a blank name, or a day outside 1..31', async () => {
    const saved = await store.saveClientStatementAccounts('c-stmt-5', [
      { name: '  ', dayOfMonth: 5 },
      { name: 'ZeroDay', dayOfMonth: 0 },
      { name: 'TooLate', dayOfMonth: 32 },
      { name: 'NotANumber', dayOfMonth: Number.NaN },
      { name: 'Kept', dayOfMonth: 10 },
    ])
    expect(saved.map((row) => row.name)).toEqual(['Kept'])
  })

  it('trims a name and caps it at 120 characters', async () => {
    const long = 'x'.repeat(200)
    const [saved] = await store.saveClientStatementAccounts('c-stmt-6', [
      { name: `  ${long}  `, dayOfMonth: 9 },
    ])
    expect(saved.name).toBe(long.slice(0, 120))
  })

  it('caps the list at 60 rows', async () => {
    const rows = Array.from({ length: 65 }, (_, index) => ({
      name: `Acct ${index}`,
      dayOfMonth: 1,
    }))
    const saved = await store.saveClientStatementAccounts('c-stmt-7', rows)
    expect(saved).toHaveLength(60)
  })

  it('persists in auth-state, not app-data — endpoint-managed like client notes', async () => {
    await store.saveClientStatementAccounts('c-stmt-8', [{ name: 'X', dayOfMonth: 1 }])
    const authState = await authPersisted()
    expect(authState.clientStatementAccounts.some((row) => row.clientId === 'c-stmt-8')).toBe(
      true,
    )
    const appData = JSON.parse(await readFile(localDataPath, 'utf8'))
    expect(appData.clientStatementAccounts).toBeUndefined()
  })

  // Minor 4: a client-supplied id is only trusted in the exact shape the store
  // mints (`stmt-<8 hex>`) and only once per payload — anything else is a bug
  // (or a replayed chip click) that would otherwise let two rows fight over
  // one id.
  it('mints a fresh id rather than trusting one that does not match stmt-<8 hex>', async () => {
    const [saved] = await store.saveClientStatementAccounts('c-stmt-9', [
      { id: 'not-a-real-id', name: 'TD Bank 4920', dayOfMonth: 12 },
    ])
    expect(saved.id).not.toBe('not-a-real-id')
    expect(saved.id).toMatch(/^stmt-[0-9a-f]{8}$/)
  })

  it('mints a fresh id for the second row when a client-supplied id repeats in the same payload', async () => {
    const [existing] = await store.saveClientStatementAccounts('c-stmt-10', [
      { name: 'TD Bank 4920', dayOfMonth: 12 },
    ])
    const saved = await store.saveClientStatementAccounts('c-stmt-10', [
      { id: existing.id, name: 'TD Bank 4920', dayOfMonth: 12 },
      { id: existing.id, name: 'Amex 1108', dayOfMonth: 3 },
    ])
    expect(saved[0].id).toBe(existing.id)
    expect(saved[1].id).not.toBe(existing.id)
    expect(saved[1].id).toMatch(/^stmt-[0-9a-f]{8}$/)
  })

  // N7: a well-formed id that is not one of THIS client's current ids (here,
  // another client's row) would hit the primary key — mint a fresh one.
  it('mints a fresh id for a well-formed id that belongs to another client’s row', async () => {
    const [other] = await store.saveClientStatementAccounts('c-stmt-10-other', [
      { name: 'Chase 7712', dayOfMonth: 5 },
    ])
    const [saved] = await store.saveClientStatementAccounts('c-stmt-10-mine', [
      { id: other.id, name: 'TD Bank 4920', dayOfMonth: 12 },
    ])
    expect(saved.id).not.toBe(other.id)
    expect(saved.id).toMatch(/^stmt-[0-9a-f]{8}$/)
    // The other client's row is untouched.
    const theirs = await store.listClientStatementAccounts('c-stmt-10-other')
    expect(theirs.map((row) => row.id)).toEqual([other.id])
  })

  // Important 2a: the stale-tab guard. `statementAccountsVersion` is a pure
  // hash of the ordered rows — same value for the same list, different value
  // once it changes.
  describe('the version fingerprint and the staleness guard', () => {
    it('is the same for the same ordered list and changes when the list does', async () => {
      const saved = await store.saveClientStatementAccounts('c-stmt-11', [
        { name: 'TD Bank 4920', dayOfMonth: 12 },
      ])
      const v1 = statementAccountsVersion(saved)
      expect(statementAccountsVersion(await store.listClientStatementAccounts('c-stmt-11'))).toBe(
        v1,
      )
      const saved2 = await store.saveClientStatementAccounts('c-stmt-11', [
        { id: saved[0].id, name: 'TD Bank 4920', dayOfMonth: 15 },
      ])
      expect(statementAccountsVersion(saved2)).not.toBe(v1)
    })

    it('refuses a save whose expectedVersion no longer matches the stored list, and writes nothing', async () => {
      await store.saveClientStatementAccounts('c-stmt-12', [
        { name: 'TD Bank 4920', dayOfMonth: 12 },
      ])
      const staleVersion = 'not-the-current-version'
      await expect(
        store.saveClientStatementAccounts(
          'c-stmt-12',
          [{ name: 'Amex 1108', dayOfMonth: 3 }],
          staleVersion,
        ),
      ).rejects.toThrow(StaleStatementAccountsError)
      // Nothing was written — the original row is still there.
      const listed = await store.listClientStatementAccounts('c-stmt-12')
      expect(listed.map((row) => row.name)).toEqual(['TD Bank 4920'])
    })

    // N1, file backend: the compare and the write are one queue slot, so two
    // saves holding the same version cannot both pass.
    it('lets only one of two concurrent saves holding the same version win', async () => {
      const first = await store.saveClientStatementAccounts('c-stmt-12b', [
        { name: 'TD Bank 4920', dayOfMonth: 12 },
      ])
      const version = statementAccountsVersion(first)
      const results = await Promise.allSettled([
        store.saveClientStatementAccounts('c-stmt-12b', [{ name: 'Amex 1108', dayOfMonth: 3 }], version),
        store.saveClientStatementAccounts('c-stmt-12b', [{ name: 'Chase 7712', dayOfMonth: 5 }], version),
      ])
      expect(results.map((result) => result.status)).toEqual(['fulfilled', 'rejected'])
      expect(results[1].reason).toBeInstanceOf(StaleStatementAccountsError)
      const listed = await store.listClientStatementAccounts('c-stmt-12b')
      expect(listed.map((row) => row.name)).toEqual(['Amex 1108'])
    })

    it('hashes a list of tuples, so a delimiter inside a name cannot collide with another list', () => {
      const a = [{ id: 'stmt-11111111', name: 'a|b', dayOfMonth: 1 }]
      const b = [{ id: 'stmt-11111111|a', name: 'b', dayOfMonth: 1 }]
      expect(statementAccountsVersion(a)).not.toBe(statementAccountsVersion(b))
    })

    it('skips the check when no expectedVersion is sent, so the API stays usable', async () => {
      await store.saveClientStatementAccounts('c-stmt-13', [
        { name: 'TD Bank 4920', dayOfMonth: 12 },
      ])
      const saved = await store.saveClientStatementAccounts('c-stmt-13', [
        { name: 'Amex 1108', dayOfMonth: 3 },
      ])
      expect(saved.map((row) => row.name)).toEqual(['Amex 1108'])
    })

    it('accepts a save whose expectedVersion matches the currently stored list', async () => {
      const first = await store.saveClientStatementAccounts('c-stmt-14', [
        { name: 'TD Bank 4920', dayOfMonth: 12 },
      ])
      const matching = statementAccountsVersion(first)
      const saved = await store.saveClientStatementAccounts(
        'c-stmt-14',
        [{ id: first[0].id, name: 'TD Bank 4920', dayOfMonth: 15 }],
        matching,
      )
      expect(saved[0].dayOfMonth).toBe(15)
    })
  })
})

/**
 * Statement dates box — the POSTGRES branch: the delete + insert transaction
 * and the params it sends, exactly what the file-backend half above cannot
 * exercise (cardinal rule 1).
 */
describe('statement dates box (postgres branch)', () => {
  it('replaces the whole list in one transaction: delete then insert, keyed by client_id', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).saveClientStatementAccounts('c1', [
      { name: 'TD Bank 4920', dayOfMonth: 12 },
      { name: 'Amex 1108', dayOfMonth: 3 },
    ])

    const beginAt = fake.indexOf(/^begin$/i)
    const deleteAt = fake.indexOf(
      /^delete from client_statement_accounts where client_id = \$1$/i,
    )
    const inserts = fake.matching(/^insert into client_statement_accounts/i)
    const commitAt = fake.indexOf(/^commit$/i)

    expect(beginAt).toBeGreaterThan(-1)
    expect(deleteAt).toBeGreaterThan(beginAt)
    expect(inserts).toHaveLength(2)
    expect(fake.statements.indexOf(inserts[0])).toBeGreaterThan(deleteAt)
    expect(commitAt).toBeGreaterThan(fake.statements.indexOf(inserts[1]))

    const [deleteStatement] = fake.matching(/^delete from client_statement_accounts/i)
    expect(deleteStatement.params).toEqual(['c1'])
    // params: id, client_id, name, day_of_month, sort_order
    expect(inserts[0].params[1]).toBe('c1')
    expect(inserts[0].params[2]).toBe('TD Bank 4920')
    expect(inserts[0].params[3]).toBe(12)
    expect(inserts[0].params[4]).toBe(0)
    expect(inserts[1].params[3]).toBe(3)
    expect(inserts[1].params[4]).toBe(1)
  })

  it('rolls back rather than leaving a half-replaced list when a write fails', async () => {
    const fake = fakePostgres()
    const realConnect = fake.pool.connect.bind(fake.pool)
    fake.pool.connect = async () => {
      const client = await realConnect()
      const realQuery = client.query.bind(client)
      return {
        ...client,
        query: async (text, params) => {
          if (/^insert into client_statement_accounts/i.test(String(text).trim())) {
            throw new Error('boom')
          }
          return realQuery(text, params)
        },
      }
    }

    await expect(
      postgresStore(fake).saveClientStatementAccounts('c1', [{ name: 'X', dayOfMonth: 1 }]),
    ).rejects.toThrow('boom')
    expect(fake.matching(/^rollback$/i)).toHaveLength(1)
    expect(fake.matching(/^commit$/i)).toHaveLength(0)
  })

  it('reads the list back ordered by sort_order, scoped to one client', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).listClientStatementAccounts('c1')

    const [statement] = fake.matching(
      /^select id, client_id, name, day_of_month, sort_order/i,
    )
    expect(statement).toBeTruthy()
    // The id breaks a tie, so two rows with one sort order always list (and
    // version) the same way - no spurious stale-version 409.
    expect(statement.text).toMatch(/where client_id = \$1\s+order by sort_order asc, id asc/i)
    expect(statement.params).toEqual(['c1'])
  })

  it('reads the stored rows inside the save with the same tie-breaking order', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).saveClientStatementAccounts('c1', [{ name: 'TD', dayOfMonth: 4 }])
    const inTransaction = fake
      .matching(/^select id, client_id, name, day_of_month, sort_order/i)
      .find((statement) => /order by/i.test(statement.text))
    expect(inTransaction.text).toMatch(/order by sort_order asc, id asc/i)
  })

  it('a failing rollback does not hide the real error from a failed save', async () => {
    const fake = fakePostgres({
      failOn: { pattern: /^delete from client_statement_accounts/i, error: new Error('real failure') },
    })
    const realConnect = fake.pool.connect.bind(fake.pool)
    fake.pool.connect = async () => {
      const client = await realConnect()
      return {
        ...client,
        query: async (text, params) => {
          if (/^rollback$/i.test(String(text).trim())) throw new Error('connection gone')
          return client.query(text, params)
        },
      }
    }
    await expect(
      postgresStore(fake).saveClientStatementAccounts('c1', [{ name: 'TD', dayOfMonth: 4 }]),
    ).rejects.toThrow('real failure')
  })

  /** Answers the in-transaction select of this client's stored rows with
   *  `rows`, leaving every other statement on the real fake so it still gets
   *  recorded into `fake.statements` (the select itself is recorded too). */
  function withStoredRows(fake, rows) {
    const realConnect = fake.pool.connect.bind(fake.pool)
    fake.pool.connect = async () => {
      const client = await realConnect()
      const realQuery = client.query.bind(client)
      return {
        ...client,
        query: async (text, params) => {
          const result = await realQuery(text, params)
          if (/^select id, client_id, name, day_of_month, sort_order/i.test(String(text).trim())) {
            return { rows }
          }
          return result
        },
      }
    }
  }

  const storedRow = (id, name, day, order = 0) => ({
    id,
    client_id: 'c1',
    name,
    day_of_month: day,
    sort_order: order,
  })

  it('mints a fresh id rather than trusting a malformed, repeated or foreign client-supplied one', async () => {
    const fake = fakePostgres()
    withStoredRows(fake, [storedRow('stmt-aaaaaaaa', 'Existing', 1)])
    await postgresStore(fake).saveClientStatementAccounts('c1', [
      { id: 'not-a-real-id', name: 'TD Bank 4920', dayOfMonth: 12 },
      { id: 'stmt-aaaaaaaa', name: 'Amex 1108', dayOfMonth: 3 },
      { id: 'stmt-aaaaaaaa', name: 'Chase 7712', dayOfMonth: 5 },
      // Well-formed but not one of c1's current ids (another client's row).
      { id: 'stmt-bbbbbbbb', name: 'Visa 0042', dayOfMonth: 9 },
    ])
    const inserts = fake.matching(/^insert into client_statement_accounts/i)
    expect(inserts).toHaveLength(4)
    expect(inserts[0].params[0]).toMatch(/^stmt-[0-9a-f]{8}$/)
    expect(inserts[0].params[0]).not.toBe('not-a-real-id')
    expect(inserts[1].params[0]).toBe('stmt-aaaaaaaa')
    expect(inserts[2].params[0]).not.toBe('stmt-aaaaaaaa')
    expect(inserts[2].params[0]).toMatch(/^stmt-[0-9a-f]{8}$/)
    expect(inserts[3].params[0]).not.toBe('stmt-bbbbbbbb')
    expect(inserts[3].params[0]).toMatch(/^stmt-[0-9a-f]{8}$/)
  })

  // N1: the stale-tab guard runs INSIDE the transaction, behind a per-client
  // advisory lock, so two tabs holding the same version cannot both pass. A
  // bare pool query before `begin` (the old shape) let both through.
  describe('the staleness guard', () => {
    const stored = storedRow('stmt-11111111', 'TD Bank 4920', 12)

    it('locks, re-selects inside the transaction, and rolls back with no delete or insert on a stale version', async () => {
      const fake = fakePostgres()
      withStoredRows(fake, [stored])

      await expect(
        postgresStore(fake).saveClientStatementAccounts(
          'c1',
          [{ name: 'Amex 1108', dayOfMonth: 3 }],
          'not-the-current-version',
        ),
      ).rejects.toThrow(StaleStatementAccountsError)

      const beginAt = fake.indexOf(/^begin$/i)
      const lockAt = fake.indexOf(/pg_advisory_xact_lock\(hashtext\(\$1\)\)/i)
      const selectAt = fake.indexOf(/^select id, client_id, name, day_of_month, sort_order/i)
      const rollbackAt = fake.indexOf(/^rollback$/i)
      expect(beginAt).toBeGreaterThan(-1)
      expect(lockAt).toBeGreaterThan(beginAt)
      expect(fake.statements[lockAt].params[0]).toContain('c1')
      expect(selectAt).toBeGreaterThan(lockAt)
      expect(fake.statements[selectAt].params).toEqual(['c1'])
      expect(rollbackAt).toBeGreaterThan(selectAt)
      expect(fake.matching(/^delete from client_statement_accounts/i)).toHaveLength(0)
      expect(fake.matching(/^insert into client_statement_accounts/i)).toHaveLength(0)
      expect(fake.matching(/^commit$/i)).toHaveLength(0)
    })

    it('does the version check on the transaction client, never on the pool', async () => {
      const fake = fakePostgres()
      withStoredRows(fake, [stored])
      const poolQuery = vi.spyOn(fake.pool, 'query')
      await postgresStore(fake)
        .saveClientStatementAccounts('c1', [{ name: 'Amex 1108', dayOfMonth: 3 }], 'nope')
        .catch(() => {})
      expect(poolQuery).not.toHaveBeenCalled()
    })

    it('proceeds with the transaction when expectedVersion matches the stored list', async () => {
      const fake = fakePostgres()
      withStoredRows(fake, [stored])
      const matching = statementAccountsVersion([
        { id: 'stmt-11111111', name: 'TD Bank 4920', dayOfMonth: 12 },
      ])

      await postgresStore(fake).saveClientStatementAccounts(
        'c1',
        [{ name: 'Amex 1108', dayOfMonth: 3 }],
        matching,
      )
      expect(fake.matching(/^begin$/i)).toHaveLength(1)
      expect(fake.matching(/^commit$/i)).toHaveLength(1)
      expect(fake.matching(/^delete from client_statement_accounts/i)).toHaveLength(1)
    })

    it('locks even when no version is sent, and when the stored list is empty', async () => {
      const fake = fakePostgres()
      await postgresStore(fake).saveClientStatementAccounts('c1', [
        { name: 'Amex 1108', dayOfMonth: 3 },
      ])
      expect(fake.indexOf(/pg_advisory_xact_lock/i)).toBeGreaterThan(fake.indexOf(/^begin$/i))
      expect(fake.matching(/^commit$/i)).toHaveLength(1)
    })
  })

  it('creates the table (with its 1..31 check) and the client_id index in initialize()', async () => {
    const fake = fakePostgres()
    await postgresStore(fake)
      .initialize()
      .catch(() => {})

    const [created] = fake.matching(/create table if not exists client_statement_accounts/i)
    expect(created).toBeTruthy()
    expect(created.text).toMatch(/check \(day_of_month between 1 and 31\)/i)

    const [indexed] = fake.matching(
      /create index if not exists client_statement_accounts_client_idx/i,
    )
    expect(indexed).toBeTruthy()
    expect(indexed.text).toMatch(/on client_statement_accounts \(client_id\)/i)
  })
})

/**
 * Pending notes for future recurring checklists (featreq-b688e73c) — the FILE
 * backend, end to end: create/list/delete and the 90-day history window.
 * The attach pass (the part that moves a note onto the next checklist that
 * populates) gets its own describe block below, because it needs full
 * checklist fixtures rather than just the notes table.
 */
describe('pending client notes (file backend)', () => {
  const authPersisted = async () => JSON.parse(await readFile(localAuthPath, 'utf8'))

  it('starts empty for a client with no notes yet', async () => {
    expect(await store.listClientPendingNotes('c-pn-empty')).toEqual([])
  })

  it('creates a note and lists it back newest first, unattached', async () => {
    const first = await store.createClientPendingNote('c-pn-1', {
      templateId: 'tpl-payroll',
      kind: 'task',
      body: 'New hire starting — add onboarding paperwork',
      authorId: 'emp-lisa',
      authorName: 'Lisa',
    })
    // 12 hex chars: a task-kind note's checklist item id is derived from it.
    expect(first.id).toMatch(/^pnote-[0-9a-f]{12}$/)
    expect(first.attachedChecklistId).toBeNull()

    const second = await store.createClientPendingNote('c-pn-1', {
      templateId: 'tpl-payroll',
      kind: 'note',
      body: 'Second note',
      authorId: 'emp-lisa',
      authorName: 'Lisa',
    })
    // Two creates this close together can land in the same millisecond, which
    // would make "newest first" untestable by timing alone — force a gap the
    // same way the 90-day-window test below forces an age.
    const authState = await authPersisted()
    const secondRow = authState.clientPendingNotes.find((entry) => entry.id === second.id)
    secondRow.createdAt = new Date(new Date(first.createdAt).getTime() + 1000).toISOString()
    await writeFile(localAuthPath, JSON.stringify(authState, null, 2))

    const listed = await store.listClientPendingNotes('c-pn-1')
    expect(listed.map((note) => note.id)).toEqual([second.id, first.id])
  })

  it('rejects a missing template, an invalid kind, or a blank body', async () => {
    expect(
      await store.createClientPendingNote('c-pn-2', {
        templateId: '',
        kind: 'task',
        body: 'x',
      }),
    ).toBeNull()
    expect(
      await store.createClientPendingNote('c-pn-2', {
        templateId: 'tpl-1',
        kind: 'reminder',
        body: 'x',
      }),
    ).toBeNull()
    expect(
      await store.createClientPendingNote('c-pn-2', {
        templateId: 'tpl-1',
        kind: 'task',
        body: '   ',
      }),
    ).toBeNull()
  })

  it('trims the body and caps it at 2000 characters', async () => {
    const long = 'x'.repeat(2100)
    const note = await store.createClientPendingNote('c-pn-3', {
      templateId: 'tpl-1',
      kind: 'note',
      body: `  ${long}  `,
    })
    expect(note.body).toBe(long.slice(0, 2000))
  })

  it('deletes a note by id', async () => {
    const note = await store.createClientPendingNote('c-pn-4', {
      templateId: 'tpl-1',
      kind: 'note',
      body: 'x',
    })
    expect(await store.deleteClientPendingNote(note.id)).toBe(true)
    expect(await store.listClientPendingNotes('c-pn-4')).toEqual([])
    expect(await store.deleteClientPendingNote(note.id)).toBe(false)
  })

  it('never touches another client’s notes', async () => {
    await store.createClientPendingNote('c-pn-5a', { templateId: 'tpl-1', kind: 'note', body: 'A' })
    await store.createClientPendingNote('c-pn-5b', { templateId: 'tpl-1', kind: 'note', body: 'B' })
    const listed = await store.listClientPendingNotes('c-pn-5a')
    expect(listed).toHaveLength(1)
    expect(listed[0].body).toBe('A')
  })

  it('persists in auth-state, not app-data — endpoint-managed like client notes', async () => {
    await store.createClientPendingNote('c-pn-6', { templateId: 'tpl-1', kind: 'note', body: 'X' })
    const authState = await authPersisted()
    expect(authState.clientPendingNotes.some((note) => note.clientId === 'c-pn-6')).toBe(true)
    const appData = JSON.parse(await readFile(localDataPath, 'utf8'))
    expect(appData.clientPendingNotes).toBeUndefined()
  })

  it('lists an attached note within the last 90 days, and drops it once older', async () => {
    const note = await store.createClientPendingNote('c-pn-7', {
      templateId: 'tpl-1',
      kind: 'note',
      body: 'X',
    })
    // Stamp it attached directly (bypassing the attach pass — that's tested on
    // its own below) so this test is only about the 90-day window.
    const authState = await authPersisted()
    const row = authState.clientPendingNotes.find((entry) => entry.id === note.id)
    row.attachedChecklistId = 'chk-somewhere'
    row.attachedAt = new Date(Date.now() - 10 * 24 * 60 * 60 * 1000).toISOString()
    await writeFile(localAuthPath, JSON.stringify(authState, null, 2))
    expect((await store.listClientPendingNotes('c-pn-7')).map((entry) => entry.id)).toEqual([
      note.id,
    ])

    row.attachedAt = new Date(Date.now() - 120 * 24 * 60 * 60 * 1000).toISOString()
    await writeFile(localAuthPath, JSON.stringify(authState, null, 2))
    expect(await store.listClientPendingNotes('c-pn-7')).toEqual([])
  })
})

/**
 * The attach pass (`attachPendingClientNotes`) — the FILE backend. This is
 * the part the pure materializer cannot do itself: it runs independently of
 * `read()` here so each test can hand it exact `createdAt`/`dueDate` values
 * (a materializer-spawned checklist carries neither by default). The wiring
 * that decides WHEN this runs relative to `read()` is pinned separately below.
 */
describe('pending client notes — attach pass (file backend)', () => {
  // These fixtures replace the whole workspace, so they start from none: a bulk
  // save refuses to drop a stored client that has time entries or invoices. The
  // file has to exist afterwards, with nothing in it.
  beforeEach(async () => {
    await rm(localDataPath, { force: true })
    await store.write(workspace({ clients: [], timeEntries: [] }))
  })
  const persisted = async () => JSON.parse(await readFile(localDataPath, 'utf8'))

  const checklistFixture = (id, { createdAt, dueDate, deletedAt, skippedAt, clientId = 'c1' }) => ({
    id,
    title: 'Payroll',
    clientId,
    assigneeId: 'emp-1',
    templateId: 'tpl-pn',
    dueDate,
    createdAt,
    viewerIds: [],
    editorIds: [],
    items: [{ id: 'item-existing', label: 'Existing step', done: false }],
    ...(deletedAt ? { deletedAt } : {}),
    ...(skippedAt ? { skippedAt } : {}),
  })

  it('picks the earliest later checklist, ignoring earlier, deleted and skipped ones', async () => {
    const note = await store.createClientPendingNote('c1', {
      templateId: 'tpl-pn',
      kind: 'task',
      body: 'New hire starting',
      authorId: 'emp-lisa',
      authorName: 'Lisa',
    })
    const t = new Date(note.createdAt).getTime()
    const iso = (offsetMs) => new Date(t + offsetMs).toISOString()

    await store.write(
      workspace({
        checklists: [
          checklistFixture('chk-earlier', { createdAt: iso(-1000), dueDate: '2026-08-01' }),
          checklistFixture('chk-deleted', {
            createdAt: iso(1000),
            dueDate: '2026-09-01',
            deletedAt: iso(2000),
          }),
          checklistFixture('chk-skipped', {
            createdAt: iso(1000),
            dueDate: '2026-09-05',
            skippedAt: iso(2000),
          }),
          checklistFixture('chk-later-far', { createdAt: iso(2000), dueDate: '2026-10-01' }),
          checklistFixture('chk-later-near', { createdAt: iso(1000), dueDate: '2026-09-10' }),
          // A different client's checklist of the same template must never match.
          checklistFixture('chk-other-client', {
            createdAt: iso(1000),
            dueDate: '2026-09-02',
            clientId: 'c-other',
          }),
        ],
      }),
    )

    const attachedCount = await store.attachPendingClientNotes({ clientId: 'c1' })
    expect(attachedCount).toBe(1)

    const updated = await store.getClientPendingNote(note.id)
    expect(updated.attachedChecklistId).toBe('chk-later-near')
    const expectedItemId = `item-pn-${note.id.replace(/^pnote-/, '')}`
    expect(updated.attachedItemId).toBe(expectedItemId)
    expect(updated.attachedAt).toBeTruthy()

    const target = (await persisted()).checklists.find((c) => c.id === 'chk-later-near')
    expect(target.items.at(-1)).toMatchObject({
      id: expectedItemId,
      label: 'New hire starting',
      done: false,
    })
    // The other candidates were left alone.
    for (const id of ['chk-earlier', 'chk-deleted', 'chk-skipped', 'chk-later-far']) {
      const checklist = (await persisted()).checklists.find((c) => c.id === id)
      expect(checklist.items).toHaveLength(1)
    }
  })

  it("ignores a split push's new checklist: the note waits for the next real occurrence", async () => {
    const note = await store.createClientPendingNote('c-pn-split', {
      templateId: 'tpl-pn',
      kind: 'task',
      body: 'New hire starting',
    })
    const t = new Date(note.createdAt).getTime()
    const iso = (offsetMs) => new Date(t + offsetMs).toISOString()
    await store.write(
      workspace({
        clients: [{ id: 'c-pn-split', name: 'Split' }],
        checklists: [
          // The split's new row: created NOW for an OLD occurrence, due sooner
          // than the real next one - the earliest-created-after rule alone
          // would pick it.
          checklistFixture('chk-split-new', {
            createdAt: iso(1000),
            dueDate: '2026-09-05',
            clientId: 'c-pn-split',
          }),
          checklistFixture('chk-real-next', {
            createdAt: iso(2000),
            dueDate: '2026-10-01',
            clientId: 'c-pn-split',
          }),
        ],
      }),
    )
    // A bulk save never authors the push stamps, so stamp the row as the split
    // would have.
    const data = await persisted()
    data.checklists.find((c) => c.id === 'chk-split-new').pushedFromChecklistId = 'chk-old-occurrence'
    await writeFile(localDataPath, JSON.stringify(data, null, 2))

    expect(await store.attachPendingClientNotes({ clientId: 'c-pn-split' })).toBe(1)

    const updated = await store.getClientPendingNote(note.id)
    expect(updated.attachedChecklistId).toBe('chk-real-next')
    const after = await persisted()
    expect(after.checklists.find((c) => c.id === 'chk-split-new').items).toHaveLength(1)
    expect(after.checklists.find((c) => c.id === 'chk-real-next').items).toHaveLength(2)
  })

  it('is idempotent: a second pass attaches nothing more and does not duplicate the item', async () => {
    // Its own client: a note an earlier test attached to a checklist this
    // workspace no longer holds is pending AGAIN (by decision), and would
    // otherwise attach here too.
    const note = await store.createClientPendingNote('c-pn-idem', {
      templateId: 'tpl-pn',
      kind: 'task',
      body: 'New hire starting',
    })
    const later = new Date(new Date(note.createdAt).getTime() + 1000).toISOString()
    await store.write(
      workspace({
        clients: [{ id: 'c-pn-idem', name: 'Idem' }],
        checklists: [
          checklistFixture('chk-pn-idem', {
            createdAt: later,
            dueDate: '2026-09-10',
            clientId: 'c-pn-idem',
          }),
        ],
      }),
    )

    expect(await store.attachPendingClientNotes({ clientId: 'c-pn-idem' })).toBe(1)
    expect(await store.attachPendingClientNotes({ clientId: 'c-pn-idem' })).toBe(0)

    const target = (await persisted()).checklists.find((c) => c.id === 'chk-pn-idem')
    expect(target.items).toHaveLength(2)
  })

  it('kind "note" only stamps the checklist id — no item is inserted', async () => {
    const note = await store.createClientPendingNote('c-pn-note', {
      templateId: 'tpl-pn',
      kind: 'note',
      body: 'Heads up for next cycle',
    })
    const later = new Date(new Date(note.createdAt).getTime() + 1000).toISOString()
    await store.write(
      workspace({
        clients: [{ id: 'c-pn-note', name: 'Note' }],
        checklists: [
          checklistFixture('chk-pn-note', {
            createdAt: later,
            dueDate: '2026-09-10',
            clientId: 'c-pn-note',
          }),
        ],
      }),
    )

    await store.attachPendingClientNotes({ clientId: 'c-pn-note' })

    const updated = await store.getClientPendingNote(note.id)
    expect(updated.attachedChecklistId).toBe('chk-pn-note')
    expect(updated.attachedItemId).toBeNull()
    const target = (await persisted()).checklists.find((c) => c.id === 'chk-pn-note')
    expect(target.items).toHaveLength(1)

    const notesForChecklist = await store.listPendingNotesForChecklists(['chk-pn-note', 'chk-other'])
    expect(notesForChecklist.map((entry) => entry.id)).toEqual([note.id])
  })

  it('does nothing when no checklist of that template exists yet for this client', async () => {
    // A client of its own, untouched by the other tests' checklist fixtures —
    // so this only exercises "nothing matches", not test ordering.
    const note = await store.createClientPendingNote('c-pn-nomatch', {
      templateId: 'tpl-pn',
      kind: 'task',
      body: 'x',
    })
    expect(await store.attachPendingClientNotes({ clientId: 'c-pn-nomatch' })).toBe(0)
    expect((await store.getClientPendingNote(note.id)).attachedChecklistId).toBeNull()
  })

  it('cheap no-op with nothing pending: touches neither app-data nor auth-state', async () => {
    // Scoped to a client that has never had a pending note in this run, so the
    // "nothing pending" fast path is exercised regardless of what other tests
    // in this file left unattached.
    const before = await persisted()
    expect(await store.attachPendingClientNotes({ clientId: 'c-pn-truly-empty' })).toBe(0)
    expect(await persisted()).toEqual(before)
  })

  it('refuses a save built from a pre-attachment payload - the attached item survives', async () => {
    const note = await store.createClientPendingNote('c-pn-stale', {
      templateId: 'tpl-pn',
      kind: 'task',
      body: 'Add the new hire',
    })
    const later = new Date(new Date(note.createdAt).getTime() + 1000).toISOString()
    const tabPayload = () =>
      workspace({
        clients: [{ id: 'c-pn-stale', name: 'Stale' }],
        checklists: [
          checklistFixture('chk-pn-stale', {
            createdAt: later,
            dueDate: '2026-09-10',
            clientId: 'c-pn-stale',
          }),
        ],
      })
    await store.write(tabPayload())
    // What the owner's tab was served: the workspace BEFORE the attachment.
    const tabVersion = await store.computeWorkspaceVersion()

    expect(await store.attachPendingClientNotes({ clientId: 'c-pn-stale' })).toBe(1)
    expect(await store.computeWorkspaceVersion()).not.toBe(tabVersion)

    // The tab's next autosave still holds the pre-attachment payload (no
    // item-pn row) under the version it was served. It must be refused, not
    // allowed to delete-and-reinsert the checklist's items without the new one.
    await expect(
      store.write(tabPayload(), { expectedVersion: tabVersion }),
    ).rejects.toBeInstanceOf(StaleWorkspaceError)

    const target = (await persisted()).checklists.find((c) => c.id === 'chk-pn-stale')
    const itemId = `item-pn-${note.id.replace(/^pnote-/, '')}`
    expect(target.items.some((item) => item.id === itemId)).toBe(true)
  })

  it('a note whose attached checklist was deleted becomes pending again, then attaches to the next live one', async () => {
    const note = await store.createClientPendingNote('c-pn-del', {
      templateId: 'tpl-pn',
      kind: 'task',
      body: 'New hire starting',
    })
    const later = new Date(new Date(note.createdAt).getTime() + 1000).toISOString()
    const withChecklists = (checklists, recycledChecklists = []) =>
      workspace({
        clients: [{ id: 'c-pn-del', name: 'Del' }],
        checklists,
        recycledChecklists,
      })
    const first = checklistFixture('chk-del-1', {
      createdAt: later,
      dueDate: '2026-09-10',
      clientId: 'c-pn-del',
    })
    await store.write(withChecklists([first]))
    expect(await store.attachPendingClientNotes({ clientId: 'c-pn-del' })).toBe(1)
    expect((await store.getClientPendingNote(note.id)).attachedChecklistId).toBe('chk-del-1')

    // The checklist is deleted (recycled): the note is waiting again.
    await store.write(
      withChecklists([], [{ ...first, deletedAt: new Date().toISOString() }]),
    )
    expect(await store.attachPendingClientNotes({ clientId: 'c-pn-del' })).toBe(0)
    expect(await store.getClientPendingNote(note.id)).toMatchObject({
      attachedChecklistId: null,
      attachedItemId: null,
      attachedAt: null,
    })
    expect((await store.listClientPendingNotes('c-pn-del')).map((entry) => entry.id)).toEqual([
      note.id,
    ])

    // The next live checklist of the template picks it up.
    const second = checklistFixture('chk-del-2', {
      createdAt: later,
      dueDate: '2026-10-10',
      clientId: 'c-pn-del',
    })
    await store.write(
      withChecklists([second], [{ ...first, deletedAt: new Date().toISOString() }]),
    )
    expect(await store.attachPendingClientNotes({ clientId: 'c-pn-del' })).toBe(1)
    expect((await store.getClientPendingNote(note.id)).attachedChecklistId).toBe('chk-del-2')
    const target = (await persisted()).checklists.find((c) => c.id === 'chk-del-2')
    expect(target.items.at(-1).id).toBe(`item-pn-${note.id.replace(/^pnote-/, '')}`)
  })

  it('a note whose attached checklist has vanished entirely is pending again too', async () => {
    const note = await store.createClientPendingNote('c-pn-gone', {
      templateId: 'tpl-pn',
      kind: 'note',
      body: 'Heads up',
    })
    const later = new Date(new Date(note.createdAt).getTime() + 1000).toISOString()
    await store.write(
      workspace({
        clients: [{ id: 'c-pn-gone', name: 'Gone' }],
        checklists: [
          checklistFixture('chk-gone-1', {
            createdAt: later,
            dueDate: '2026-09-10',
            clientId: 'c-pn-gone',
          }),
        ],
      }),
    )
    expect(await store.attachPendingClientNotes({ clientId: 'c-pn-gone' })).toBe(1)

    await store.write(workspace({ clients: [{ id: 'c-pn-gone', name: 'Gone' }], checklists: [] }))
    expect(await store.attachPendingClientNotes({ clientId: 'c-pn-gone' })).toBe(0)
    expect((await store.getClientPendingNote(note.id)).attachedChecklistId).toBeNull()
  })

  it('only a first-stage checklist qualifies - a stage-advance spawn never takes the note', async () => {
    const note = await store.createClientPendingNote('c-pn-stage', {
      templateId: 'tpl-pn',
      kind: 'note',
      body: 'For the next cycle',
    })
    const later = new Date(new Date(note.createdAt).getTime() + 1000).toISOString()
    await store.write(
      workspace({
        clients: [{ id: 'c-pn-stage', name: 'Stage' }],
        checklists: [
          {
            ...checklistFixture('chk-stage-1', {
              createdAt: later,
              dueDate: '2026-09-05',
              clientId: 'c-pn-stage',
            }),
            stageIndex: 1,
            stageCount: 2,
          },
          {
            ...checklistFixture('chk-stage-0', {
              createdAt: later,
              dueDate: '2026-09-20',
              clientId: 'c-pn-stage',
            }),
            stageIndex: 0,
            stageCount: 2,
          },
        ],
      }),
    )
    expect(await store.attachPendingClientNotes({ clientId: 'c-pn-stage' })).toBe(1)
    expect((await store.getClientPendingNote(note.id)).attachedChecklistId).toBe('chk-stage-0')
  })

  it('one note failing to attach does not stop the rest, and the failure is logged', async () => {
    const logged = vi.spyOn(console, 'error').mockImplementation(() => {})
    const failing = vi.spyOn(store, '_attachTaskKindPendingNote').mockRejectedValueOnce(new Error('boom'))
    try {
      const first = await store.createClientPendingNote('c-pn-fail', {
        templateId: 'tpl-pn',
        kind: 'task',
        body: 'Fails to attach',
      })
      const second = await store.createClientPendingNote('c-pn-fail', {
        templateId: 'tpl-pn',
        kind: 'note',
        body: 'Attaches fine',
      })
      const later = new Date(Date.now() + 5000).toISOString()
      await store.write(
        workspace({
          clients: [{ id: 'c-pn-fail', name: 'Fail' }],
          checklists: [
            checklistFixture('chk-fail-1', {
              createdAt: later,
              dueDate: '2026-09-10',
              clientId: 'c-pn-fail',
            }),
          ],
        }),
      )

      expect(await store.attachPendingClientNotes({ clientId: 'c-pn-fail' })).toBe(1)
      expect((await store.getClientPendingNote(first.id)).attachedChecklistId).toBeNull()
      expect((await store.getClientPendingNote(second.id)).attachedChecklistId).toBe('chk-fail-1')
      expect(logged).toHaveBeenCalled()
    } finally {
      failing.mockRestore()
      logged.mockRestore()
    }
  })

  it('counts an attachment, and broadcasts, only when the stamp changed a row', async () => {
    const hook = vi.fn()
    store.onPendingNotesAttached = hook
    const stamp = vi.spyOn(store, '_attachNoteKindPendingNote').mockResolvedValueOnce(false)
    try {
      const note = await store.createClientPendingNote('c-pn-count', {
        templateId: 'tpl-pn',
        kind: 'note',
        body: 'Heads up',
      })
      const later = new Date(new Date(note.createdAt).getTime() + 1000).toISOString()
      await store.write(
        workspace({
          clients: [{ id: 'c-pn-count', name: 'Count' }],
          checklists: [
            checklistFixture('chk-count-1', {
              createdAt: later,
              dueDate: '2026-09-10',
              clientId: 'c-pn-count',
            }),
          ],
        }),
      )

      // Someone else won the stamp: nothing attached, nobody pinged.
      expect(await store.attachPendingClientNotes({ clientId: 'c-pn-count' })).toBe(0)
      expect(hook).not.toHaveBeenCalled()

      // The real stamp changes a row: counted, and the open tabs are told.
      expect(await store.attachPendingClientNotes({ clientId: 'c-pn-count' })).toBe(1)
      expect(hook).toHaveBeenCalledTimes(1)
    } finally {
      stamp.mockRestore()
      store.onPendingNotesAttached = undefined
    }
  })
  it('an item id already used by ANOTHER checklist (recycled ones included) gets this checklist id appended', async () => {
    const note = await store.createClientPendingNote('c-pn-sfx', {
      templateId: 'tpl-pn',
      kind: 'task',
      body: 'New hire starting',
    })
    const plainItemId = `item-pn-${note.id.replace(/^pnote-/, '')}`
    const later = new Date(new Date(note.createdAt).getTime() + 1000).toISOString()
    // The note's first checklist was deleted and still holds its item row, so
    // the plain id is TAKEN when the note attaches again.
    const recycled = {
      ...checklistFixture('check-sfx-old', {
        createdAt: later,
        dueDate: '2026-09-10',
        clientId: 'c-pn-sfx',
        deletedAt: new Date().toISOString(),
      }),
      items: [{ id: plainItemId, label: 'New hire starting', done: false }],
    }
    await store.write(
      workspace({
        clients: [{ id: 'c-pn-sfx', name: 'Sfx' }],
        checklists: [
          checklistFixture('check-sfx-live', {
            createdAt: later,
            dueDate: '2026-10-10',
            clientId: 'c-pn-sfx',
          }),
        ],
        recycledChecklists: [recycled],
      }),
    )

    expect(await store.attachPendingClientNotes({ clientId: 'c-pn-sfx' })).toBe(1)

    const finalItemId = `${plainItemId}-sfx-live`
    expect((await store.getClientPendingNote(note.id)).attachedItemId).toBe(finalItemId)
    const target = (await persisted()).checklists.find((c) => c.id === 'check-sfx-live')
    expect(target.items.at(-1)).toMatchObject({ id: finalItemId, label: 'New hire starting' })

    // And a second pass is still idempotent.
    expect(await store.attachPendingClientNotes({ clientId: 'c-pn-sfx' })).toBe(0)
    expect(
      (await persisted()).checklists
        .find((c) => c.id === 'check-sfx-live')
        .items.filter((item) => item.id === finalItemId),
    ).toHaveLength(1)
  })
})

/**
 * `read()`'s pending-notes attach pass wiring: the pass runs only when its
 * guarded materializer write-back actually SUCCEEDS, never when the write-back
 * is refused as stale — otherwise a note could attach against a checklist that
 * was never actually persisted (`attachPendingClientNotes`'s own doc comment).
 * Reuses the exact interleaving technique the write-back guard tests above use.
 */
describe("read()'s pending-notes attach pass wiring (file backend)", () => {
  afterEach(() => {
    vi.restoreAllMocks()
  })

  const utcDaysAgo = (days) =>
    new Date(Date.now() - days * 24 * 60 * 60 * 1000).toISOString().slice(0, 10)

  const spawnableWorkspace = () =>
    workspace({
      clients: [{ id: 'c1', name: 'Acme' }],
      checklists: [
        {
          id: 'chk-1',
          title: 'Existing task',
          clientId: 'c1',
          assigneeId: 'emp-1',
          templateId: null,
          frequency: 'once',
          dueDate: utcDaysAgo(1),
          caseId: 'chk-1',
          stageId: null,
          stageIndex: 0,
          stageCount: 1,
          items: [{ id: 'item-1', label: 'Reconcile the bank feed', done: false }],
        },
      ],
      checklistTemplates: [
        {
          id: 'tpl-1',
          title: 'Monthly bookkeeping',
          clientId: 'c1',
          assigneeId: 'emp-1',
          frequency: 'monthly',
          nextDueDate: utcDaysAgo(1),
          active: true,
          isStandard: false,
          viewerIds: [],
          editorIds: [],
          stages: [
            {
              id: 'stage-1',
              name: 'Stage 1',
              assigneeId: 'emp-1',
              offsetDays: 0,
              viewerIds: [],
              editorIds: [],
              items: [{ id: 'ti-1', label: 'Close the month' }],
            },
          ],
        },
      ],
    })

  it('runs the attach pass once, after a successful materializer write-back', async () => {
    await store.write(spawnableWorkspace())
    const attachSpy = vi.spyOn(store, 'attachPendingClientNotes')

    await store.read()

    expect(attachSpy).toHaveBeenCalledTimes(1)
  })

  it('a materializer write-back that fails leaves pending notes exactly pending — no phantom attachment', async () => {
    await store.write(spawnableWorkspace())
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {})
    const attachSpy = vi.spyOn(store, 'attachPendingClientNotes')

    // Same deterministic interleaving as "refuses the write-back when a wait
    // was saved mid-read" above: land an unrelated change the instant read()
    // hands its materialized snapshot to write(), so THIS write-back is
    // refused as stale.
    const realWrite = AppDataStore.prototype.write
    let interleaved = false
    vi.spyOn(store, 'write').mockImplementation(async function (data, options) {
      if (!interleaved) {
        interleaved = true
        await store.addWaitingOn(
          'chk-1',
          { itemId: 'item-1' },
          { blockerId: 'emp-1', requestedBy: 'emp-1', note: 'client statements' },
        )
      }
      return realWrite.call(store, data, options)
    })

    await store.read()

    expect(attachSpy).not.toHaveBeenCalled()
    expect(warn).toHaveBeenCalled()
  })

  it('read() returns the workspace WITH an attached task item - the served data and the version agree', async () => {
    await store.write(spawnableWorkspace())
    const note = await store.createClientPendingNote('c1', {
      templateId: 'tpl-1',
      kind: 'task',
      body: 'New hire this cycle',
    })
    // The spawn's createdAt has to land strictly after the note's.
    await new Promise((resolve) => setTimeout(resolve, 5))

    const served = await store.read()
    const itemId = `item-pn-${note.id.replace(/^pnote-/, '')}`
    const spawned = served.checklists.find((c) => c.templateId === 'tpl-1')
    expect(spawned.items.some((item) => item.id === itemId)).toBe(true)

    // The version the GET handler computes next describes exactly this data: a
    // save built from what was served passes the guard and keeps the item.
    const version = await store.computeWorkspaceVersion()
    await expect(store.write(served, { expectedVersion: version })).resolves.toBeUndefined()
    const onDisk = JSON.parse(await readFile(localDataPath, 'utf8')).checklists.find(
      (c) => c.templateId === 'tpl-1',
    )
    expect(onDisk.items.some((item) => item.id === itemId)).toBe(true)
    // The file backend persists what the materializer stamped, so the attach
    // rule matches on createdAt exactly as the Postgres column does.
    expect(typeof onDisk.createdAt).toBe('string')
  })
})

/**
 * Pending client notes — the POSTGRES branch: the statements the simple CRUD
 * methods send (mirroring the statement-dates-box Postgres suite above), plus
 * the table/index creation. The attach pass gets its own fully-behavioral fake
 * pool below it, because pinning its several statements individually would not
 * prove the ORDER/matching logic the file-backend suite above already pins.
 */
describe('pending client notes (postgres branch)', () => {
  it('inserts a note with the given fields', async () => {
    const fake = fakePostgres()
    const note = await postgresStore(fake).createClientPendingNote('c1', {
      templateId: 'tpl-payroll',
      kind: 'task',
      body: 'New hire starting',
      authorId: 'emp-lisa',
      authorName: 'Lisa',
    })
    const [insert] = fake.matching(/^insert into client_pending_notes/i)
    expect(insert).toBeTruthy()
    expect(insert.params).toEqual([
      note.id,
      'c1',
      'tpl-payroll',
      'task',
      'New hire starting',
      'emp-lisa',
      'Lisa',
    ])
  })

  it('lists a client’s notes, pending or attached within 90 days', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).listClientPendingNotes('c1')
    const [select] = fake.matching(/^select id, client_id, template_id, kind, body/i)
    expect(select).toBeTruthy()
    expect(select.text).toMatch(/where client_id = \$1/i)
    expect(select.text).toMatch(/attached_checklist_id is null or attached_at > now\(\) - interval '90 days'/i)
    expect(select.params).toEqual(['c1'])
  })

  it('deletes a note by id', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).deleteClientPendingNote('pnote-1')
    const [del] = fake.matching(/^delete from client_pending_notes where id = \$1$/i)
    expect(del).toBeTruthy()
    expect(del.params).toEqual(['pnote-1'])
  })

  it('creates the table (with its task/note check), the client_id index, and the checklist reads it depends on', async () => {
    const fake = fakePostgres()
    await postgresStore(fake)
      .initialize()
      .catch(() => {})

    const [created] = fake.matching(/create table if not exists client_pending_notes/i)
    expect(created).toBeTruthy()
    expect(created.text).toMatch(/check \(kind in \('task', 'note'\)\)/i)

    const [indexed] = fake.matching(/create index if not exists client_pending_notes_client_idx/i)
    expect(indexed).toBeTruthy()
    expect(indexed.text).toMatch(/on client_pending_notes \(client_id\)/i)
  })
})

/**
 * The JavaScript twin of the "is this step still open" expression in the
 * next-checklist lookup's SQL (`_findNextChecklistsForPendingNotes`), written
 * from the statement, arm for arm: a step with sub-steps is open when any
 * sub-step is (a sub-step with sub-sub-steps by THEM, otherwise by its own
 * `done`); a flat step is open when its own `done` is not true. The fake cannot
 * run SQL, so the test below pins this twin to `rollUpItemDone` over every shape.
 */
function stepIsOpenBySql(item) {
  const subItems = Array.isArray(item.sub_items) ? item.sub_items : []
  if (subItems.length > 0) {
    return subItems.some((sub) => {
      const subSubs = Array.isArray(sub.subItems) ? sub.subItems : []
      return subSubs.length > 0 ? subSubs.some((ss) => ss.done !== true) : sub.done !== true
    })
  }
  return !item.done
}

/**
 * The attach pass on Postgres — a small, self-contained in-memory fake (not
 * the shared `fakePostgres()`, which has no branches for these tables) so the
 * matching/idempotency/transaction behavior can be proven end to end, the same
 * way the file-backend suite above proves it, rather than only pinning SQL
 * text. `begin`/`commit` are tracked so the task-kind item-insert + note-stamp
 * pair is provably ONE transaction.
 */
function fakePendingNotesPostgres({ notes = [], checklists = [], items = [] } = {}) {
  const statements = []
  // Params of each next-checklist lookup, so a test can count them.
  const lookups = []
  let inTransaction = false
  const run = (text, params = []) => {
    const trimmed = String(text).trim()
    statements.push({ text: trimmed, params, inTransaction })

    if (/^begin$/i.test(trimmed)) {
      inTransaction = true
      return { rows: [] }
    }
    if (/^commit$/i.test(trimmed) || /^rollback$/i.test(trimmed)) {
      inTransaction = false
      return { rows: [] }
    }
    // Dismissing a copy: the ONE guarded update. Each condition is honored only when
    // the SQL names it, so the pins prove the clause rather than the fixture.
    if (/^update client_pending_notes set dismissed_at = now\(\)/i.test(trimmed)) {
      const note = notes.find(
        (entry) =>
          entry.id === params[0] &&
          (!/repeat_of is not null/i.test(trimmed) || Boolean(entry.repeat_of)) &&
          (!/kind = 'note'/i.test(trimmed) || entry.kind === 'note') &&
          (!/attached_checklist_id is not null/i.test(trimmed) || Boolean(entry.attached_checklist_id)) &&
          (!/dismissed_at is null/i.test(trimmed) || !entry.dismissed_at),
      )
      if (note) note.dismissed_at = new Date()
      return { rows: note ? [{ id: note.id }] : [], rowCount: note ? 1 : 0 }
    }
    // The follow-up that names why the guarded update changed nothing.
    if (/^select repeat_of, kind, attached_checklist_id, dismissed_at\s+from client_pending_notes where id = \$1$/i.test(trimmed)) {
      const note = notes.find((entry) => entry.id === params[0])
      return { rows: note ? [note] : [], rowCount: note ? 1 : 0 }
    }
    // The two reads that SHOW notes: a dismissed row is left out only when the SQL says so.
    if (/^select id, client_id, template_id, kind, body, author_id, author_name,\s+created_at, attached_checklist_id[\s\S]*from client_pending_notes\s+where attached_checklist_id = any\(\$1::text\[\]\)/i.test(trimmed)) {
      const rows = notes
        .filter((entry) => params[0].includes(entry.attached_checklist_id))
        .filter((entry) => !/and dismissed_at is null/i.test(trimmed) || !entry.dismissed_at)
      return { rows, rowCount: rows.length }
    }
    if (/^select id, client_id, template_id, kind, body, author_id, author_name,\s+created_at, attached_checklist_id[\s\S]*from client_pending_notes\s+where client_id = \$1/i.test(trimmed)) {
      const rows = notes
        .filter((entry) => entry.client_id === params[0])
        .filter((entry) => !/and dismissed_at is null/i.test(trimmed) || !entry.dismissed_at)
      return { rows, rowCount: rows.length }
    }
    if (/^select id, client_id, template_id, kind, body, author_id, author_name,\s+created_at, attached_checklist_id[\s\S]*from client_pending_notes where id = \$1$/i.test(trimmed)) {
      const note = notes.find((entry) => entry.id === params[0])
      return { rows: note ? [note] : [], rowCount: note ? 1 : 0 }
    }
    // The copy a repeating note leaves on one checklist (its own, already attached row).
    if (/^insert into client_pending_notes\s+\(id, client_id, template_id, kind, body, author_id, author_name, created_at,\s+attached_checklist_id/i.test(trimmed)) {
      const [id, clientId, templateId, kind, body, authorId, authorName, checklistId, itemId, repeatOf] = params
      notes.push({
        id,
        client_id: clientId,
        template_id: templateId,
        kind,
        body,
        author_id: authorId,
        author_name: authorName,
        created_at: new Date(),
        attached_checklist_id: checklistId,
        attached_item_id: itemId,
        attached_at: new Date(),
        repeat_of: repeatOf,
      })
      return { rows: [], rowCount: 1 }
    }
    if (/^insert into client_pending_notes/i.test(trimmed)) {
      // The cap rides in the same statement as the insert: it inserts nothing
      // (rowCount 0) when the client already holds 100 unattached notes.
      if (/select count\(\*\) from client_pending_notes/i.test(trimmed)) {
        const waiting = notes.filter(
          (note) => note.client_id === params[1] && note.attached_checklist_id === null,
        ).length
        if (waiting >= 100) return { rows: [], rowCount: 0 }
      }
      notes.push({
        id: params[0],
        client_id: params[1],
        template_id: params[2],
        kind: params[3],
        body: params[4],
        author_id: params[5],
        author_name: params[6],
        created_at: new Date(),
        attached_checklist_id: null,
        attached_item_id: null,
        attached_at: null,
        // Honored only when the statement names the column, so a one-time insert stays one-time.
        repeats: /created_at, repeats\)/i.test(trimmed) ? true : null,
      })
      return { rows: [] }
    }
    if (/^select n\.id, n\.client_id[\s\S]*from client_pending_notes n\s+left join checklists c on c\.id = n\.attached_checklist_id/i.test(trimmed)) {
      // Pending notes, plus notes whose attached checklist is gone or deleted
      // (flagged stale so the caller clears the stamp).
      const clientId = /and n\.client_id = \$1/i.test(trimmed) ? params[0] : null
      const rows = notes
        .filter((note) => !clientId || note.client_id === clientId)
        .filter((note) => !/and n\.repeat_of is null/i.test(trimmed) || !note.repeat_of)
        .filter((note) => {
          if (note.attached_checklist_id === null) return true
          const checklist = checklists.find((entry) => entry.id === note.attached_checklist_id)
          return !checklist || Boolean(checklist.deleted_at) || Boolean(checklist.skipped_at)
        })
        .map((note) => ({
          ...note,
          was_attached: note.attached_checklist_id !== null,
          was_released: Boolean(note.released_at),
        }))
      return { rows }
    }
    if (/^update client_pending_notes\s+set attached_checklist_id = null/i.test(trimmed)) {
      const ids = params[0]
      // The statement's own guard: a stamp whose checklist is live again (it was
      // restored between the select and this update) is not cleared.
      const guarded = /and not exists \(\s*select 1 from checklists c/i.test(trimmed)
      const liveAgain = (note) => {
        const checklist = checklists.find((entry) => entry.id === note.attached_checklist_id)
        return Boolean(checklist) && !checklist.deleted_at && !checklist.skipped_at
      }
      // The release stamp rides in the same statement, only when the SQL asks.
      const stampsRelease = /released_at = now\(\)/i.test(trimmed)
      const clearedIds = []
      for (const note of notes) {
        if (ids.includes(note.id) && !(guarded && liveAgain(note))) {
          note.attached_checklist_id = null
          note.attached_item_id = null
          note.attached_at = null
          if (stampsRelease) note.released_at = new Date()
          clearedIds.push(note.id)
        }
      }
      return {
        rows: /returning id\s*$/i.test(trimmed) ? clearedIds.map((id) => ({ id })) : [],
        rowCount: clearedIds.length,
      }
    }
    // The attach pass's ONE lookup for every pending note: an unnest of the
    // notes cross-joined to a lateral pick of each one's next checklist.
    if (/^select n\.id as note_id, found\.id as checklist_id\s+from unnest\(/i.test(trimmed)) {
      lookups.push(params)
      const [ids, templateIds, clientIds, createdAts, createdDates, stales, lastDues, lastIds] = params
      const afterLast = (c, index) =>
        !/n\.last_checklist_id is null/i.test(trimmed) ||
        !lastIds?.[index] ||
        (String(c.due_date) >= String(lastDues[index]) && String(c.id) !== String(lastIds[index]))
      // The statement's own "no second copy on one checklist" clause.
      const holdsCopy = (c, noteId) =>
        /p\.repeat_of = n\.id and p\.attached_checklist_id = c\.id/i.test(trimmed) &&
        notes.some((p) => p.repeat_of === noteId && p.attached_checklist_id === c.id)
      const rows = []
      ids.forEach((noteId, index) => {
        const picks = checklists
          .filter(
            (c) =>
              c.template_id === templateIds[index] &&
              c.client_id === clientIds[index] &&
              !c.deleted_at &&
              !c.skipped_at &&
              // Honored only when the SQL actually asks for it, so each pin
              // below proves the clause, not the fixture.
              (!/coalesce\(c\.stage_index, 0\) = 0/i.test(trimmed) || (c.stage_index ?? 0) === 0) &&
              (!/c\.pushed_from_checklist_id is null/i.test(trimmed) || !c.pushed_from_checklist_id) &&
              (!/c\.pushed_to_checklist_id is null/i.test(trimmed) || !c.pushed_to_checklist_id) &&
              (!/not n\.stale/i.test(trimmed) ||
                !stales[index] ||
                !(
                  items.some((item) => item.checklist_id === c.id) &&
                  !items
                    .filter((item) => item.checklist_id === c.id)
                    .some((item) =>
                      // The roll-up arm is honored only when the SQL spells it out.
                      /jsonb_array_elements\(i\.sub_items\)/i.test(trimmed)
                        ? stepIsOpenBySql(item)
                        : !item.done,
                    )
                )) &&
              afterLast(c, index) &&
              !holdsCopy(c, noteId) &&
              (c.created_at ? c.created_at > createdAts[index] : c.due_date > createdDates[index]),
          )
          .sort(
            (a, b) =>
              String(a.due_date).localeCompare(String(b.due_date)) || String(a.id).localeCompare(String(b.id)),
          )
        if (picks.length > 0) rows.push({ note_id: noteId, checklist_id: picks[0].id })
      })
      return { rows, rowCount: rows.length }
    }
    // The task-kind attach's lock on its target.
    if (/^select 1 from checklists\s+where id = \$1 and deleted_at is null and skipped_at is null\s+and pushed_to_checklist_id is null\s+for update$/i.test(trimmed)) {
      const target = checklists.find((entry) => entry.id === params[0])
      const ok = Boolean(target) && !target.deleted_at && !target.skipped_at && !target.pushed_to_checklist_id
      return { rows: ok ? [{}] : [], rowCount: ok ? 1 : 0 }
    }
    if (/^select coalesce\(max\(sort_order\), -1\) as max_order\s+from checklist_items/i.test(trimmed)) {
      const checklistId = params[0]
      const existing = items.filter((item) => item.checklist_id === checklistId)
      const max = existing.reduce((acc, item) => Math.max(acc, item.sort_order ?? -1), -1)
      return { rows: [{ max_order: max }] }
    }
    if (/^select checklist_id from checklist_items where id = \$1/i.test(trimmed)) {
      const found = items.find((item) => item.id === params[0])
      return { rows: found ? [{ checklist_id: found.checklist_id }] : [] }
    }
    if (/^insert into checklist_items/i.test(trimmed)) {
      const [id, checklistId, label, sortOrder] = params
      if (!items.some((item) => item.id === id)) {
        items.push({ id, checklist_id: checklistId, label, sort_order: sortOrder })
      }
      return { rows: [] }
    }
    // The claim transaction's re-check: does this checklist already hold a copy?
    if (/^select 1 from client_pending_notes where repeat_of = \$1 and attached_checklist_id = \$2$/i.test(trimmed)) {
      const there = notes.some((p) => p.repeat_of === params[0] && p.attached_checklist_id === params[1])
      return { rows: there ? [{}] : [], rowCount: there ? 1 : 0 }
    }
    if (/^update client_pending_notes\s+set last_attached_checklist_id = \$2/i.test(trimmed)) {
      const [id, checklistId, previous] = params
      const note = notes.find(
        (entry) =>
          entry.id === id &&
          entry.repeats === true &&
          entry.attached_checklist_id === null &&
          (entry.last_attached_checklist_id ?? null) === (previous ?? null),
      )
      if (!note) return { rows: [], rowCount: 0 }
      note.last_attached_checklist_id = checklistId
      note.last_attached_due_date = checklists.find((entry) => entry.id === checklistId)?.due_date ?? null
      return {
        rows: [{ author_id: note.author_id ?? null, author_name: note.author_name ?? null }],
        rowCount: 1,
      }
    }
    if (/^update client_pending_notes\s+set attached_checklist_id = \$2/i.test(trimmed)) {
      const [id, checklistId, itemId] = params
      // Honored only when the SQL actually asks for it, so the pins prove the clause.
      const targetLive = () => {
        const target = checklists.find((entry) => entry.id === checklistId)
        return Boolean(target) && !target.deleted_at && !target.skipped_at && !target.pushed_to_checklist_id
      }
      const guardedByTarget =
        /and exists \(\s*select 1 from checklists\s+where id = \$2 and deleted_at is null and skipped_at is null\s+and pushed_to_checklist_id is null\s*\)/i.test(
          trimmed,
        )
      const note = notes.find(
        (entry) =>
          entry.id === id && entry.attached_checklist_id === null && (!guardedByTarget || targetLive()),
      )
      if (note) {
        note.attached_checklist_id = checklistId
        note.attached_item_id = itemId ?? null
        note.attached_at = new Date()
        if (/released_at = null/i.test(trimmed)) note.released_at = null
      }
      return { rows: [], rowCount: note ? 1 : 0 }
    }
    return { rows: [] }
  }
  const client = { async query(text, params) { return run(text, params) }, release() {} }
  const pool = {
    async connect() { return client },
    async query(text, params) { return run(text, params) },
  }
  const matching = (pattern) => statements.filter((s) => pattern.test(s.text))
  return { pool, statements, matching, notes, checklists, items, lookups }
}

describe('pending client notes — attach pass (postgres branch)', () => {
  it('picks the earliest later checklist and attaches a task-kind note in one transaction', async () => {
    const fake = fakePendingNotesPostgres({
      notes: [
        {
          id: 'pnote-1',
          client_id: 'c1',
          template_id: 'tpl-pn',
          kind: 'task',
          body: 'New hire starting',
          created_at: '2026-09-01T00:00:00.000Z',
          attached_checklist_id: null,
        },
      ],
      checklists: [
        {
          id: 'chk-earlier',
          template_id: 'tpl-pn',
          client_id: 'c1',
          due_date: '2026-08-01',
          created_at: '2026-08-25T00:00:00.000Z',
        },
        {
          id: 'chk-later-far',
          template_id: 'tpl-pn',
          client_id: 'c1',
          due_date: '2026-10-01',
          created_at: '2026-09-05T00:00:00.000Z',
        },
        {
          id: 'chk-later-near',
          template_id: 'tpl-pn',
          client_id: 'c1',
          due_date: '2026-09-10',
          created_at: '2026-09-05T00:00:00.000Z',
        },
      ],
    })

    const attachedCount = await postgresStore(fake).attachPendingClientNotes({ clientId: 'c1' })
    expect(attachedCount).toBe(1)

    const note = fake.notes.find((entry) => entry.id === 'pnote-1')
    expect(note.attached_checklist_id).toBe('chk-later-near')
    expect(note.attached_item_id).toBe('item-pn-1')

    const item = fake.items.find((entry) => entry.checklist_id === 'chk-later-near')
    expect(item).toMatchObject({ id: 'item-pn-1', label: 'New hire starting' })

    // One transaction: begin, the insert and the stamp both issued while
    // inside it, then commit.
    const insertItem = fake.matching(/^insert into checklist_items/i)[0]
    const stamp = fake.matching(/^update client_pending_notes/i)[0]
    expect(insertItem.inTransaction).toBe(true)
    expect(stamp.inTransaction).toBe(true)
    expect(fake.matching(/^begin$/i)).toHaveLength(1)
    expect(fake.matching(/^commit$/i)).toHaveLength(1)
  })

  it("never attaches to a split push's new checklist (pushed_from_checklist_id is set)", async () => {
    const fake = fakePendingNotesPostgres({
      notes: [
        {
          id: 'pnote-split',
          client_id: 'c1',
          template_id: 'tpl-pn',
          kind: 'note',
          body: 'Heads up',
          created_at: '2026-09-01T00:00:00.000Z',
          attached_checklist_id: null,
        },
      ],
      checklists: [
        {
          id: 'chk-split-new',
          template_id: 'tpl-pn',
          client_id: 'c1',
          due_date: '2026-09-05',
          created_at: '2026-09-20T00:00:00.000Z',
          pushed_from_checklist_id: 'chk-old-occurrence',
        },
        {
          id: 'chk-real-next',
          template_id: 'tpl-pn',
          client_id: 'c1',
          due_date: '2026-10-01',
          created_at: '2026-09-21T00:00:00.000Z',
        },
      ],
    })

    expect(await postgresStore(fake).attachPendingClientNotes({ clientId: 'c1' })).toBe(1)
    expect(fake.notes[0].attached_checklist_id).toBe('chk-real-next')
    // The clause is in the SQL itself, not only in the fixture.
    const [lookup] = fake.matching(/^select n\.id as note_id, found\.id as checklist_id/i)
    expect(lookup.text).toMatch(/pushed_from_checklist_id is null/i)
  })

  it('is idempotent: on conflict do nothing on the item insert, second pass attaches nothing', async () => {
    const fake = fakePendingNotesPostgres({
      notes: [
        {
          id: 'pnote-2',
          client_id: 'c1',
          template_id: 'tpl-pn',
          kind: 'task',
          body: 'X',
          created_at: '2026-09-01T00:00:00.000Z',
          attached_checklist_id: null,
        },
      ],
      checklists: [
        {
          id: 'chk-1',
          template_id: 'tpl-pn',
          client_id: 'c1',
          due_date: '2026-09-10',
          created_at: '2026-09-05T00:00:00.000Z',
        },
      ],
    })
    const store2 = postgresStore(fake)
    expect(await store2.attachPendingClientNotes({ clientId: 'c1' })).toBe(1)
    expect(await store2.attachPendingClientNotes({ clientId: 'c1' })).toBe(0)
    expect(fake.items).toHaveLength(1)

    const insertStatements = fake.matching(/^insert into checklist_items/i)
    expect(insertStatements).toHaveLength(1)
    expect(insertStatements[0].text).toMatch(/on conflict \(id\) do nothing/i)
  })

  it('note-kind stamps the checklist id only — no checklist_items insert', async () => {
    const fake = fakePendingNotesPostgres({
      notes: [
        {
          id: 'pnote-3',
          client_id: 'c1',
          template_id: 'tpl-pn',
          kind: 'note',
          body: 'Heads up',
          created_at: '2026-09-01T00:00:00.000Z',
          attached_checklist_id: null,
        },
      ],
      checklists: [
        {
          id: 'chk-1',
          template_id: 'tpl-pn',
          client_id: 'c1',
          due_date: '2026-09-10',
          created_at: '2026-09-05T00:00:00.000Z',
        },
      ],
    })
    await postgresStore(fake).attachPendingClientNotes({ clientId: 'c1' })
    expect(fake.notes[0].attached_checklist_id).toBe('chk-1')
    expect(fake.notes[0].attached_item_id).toBeNull()
    expect(fake.items).toHaveLength(0)
  })

  it('a note whose attached checklist was deleted is pending again: stamp cleared, re-attached to the next live checklist under a fresh item id', async () => {
    const fake = fakePendingNotesPostgres({
      notes: [
        {
          id: 'pnote-9',
          client_id: 'c1',
          template_id: 'tpl-pn',
          kind: 'task',
          body: 'New hire starting',
          created_at: '2026-09-01T00:00:00.000Z',
          attached_checklist_id: 'check-gone',
          attached_item_id: 'item-pn-9',
          attached_at: '2026-09-06T00:00:00.000Z',
        },
      ],
      checklists: [
        {
          id: 'check-gone',
          template_id: 'tpl-pn',
          client_id: 'c1',
          due_date: '2026-09-10',
          created_at: '2026-09-05T00:00:00.000Z',
          deleted_at: '2026-09-08T00:00:00.000Z',
        },
        {
          id: 'check-live',
          template_id: 'tpl-pn',
          client_id: 'c1',
          due_date: '2026-10-10',
          created_at: '2026-09-20T00:00:00.000Z',
        },
      ],
      // The deleted checklist keeps its rows, so the old item id is TAKEN.
      items: [{ id: 'item-pn-9', checklist_id: 'check-gone', sort_order: 0 }],
    })

    expect(await postgresStore(fake).attachPendingClientNotes({ clientId: 'c1' })).toBe(1)

    const [cleared] = fake.matching(/^update client_pending_notes\s+set attached_checklist_id = null/i)
    expect(cleared.params).toEqual([['pnote-9']])
    expect(fake.notes[0].attached_checklist_id).toBe('check-live')
    // The conflict-skipped insert would have attached the note to a checklist
    // that never got the item; the id carries the new checklist instead.
    expect(fake.notes[0].attached_item_id).toBe('item-pn-9-live')
    expect(fake.items.find((item) => item.checklist_id === 'check-live')).toMatchObject({
      id: 'item-pn-9-live',
      label: 'New hire starting',
    })
  })

  it('a note attached to a live checklist is left alone (no clearing update)', async () => {
    const fake = fakePendingNotesPostgres({
      notes: [
        {
          id: 'pnote-10',
          client_id: 'c1',
          template_id: 'tpl-pn',
          kind: 'note',
          body: 'x',
          created_at: '2026-09-01T00:00:00.000Z',
          attached_checklist_id: 'check-live',
        },
      ],
      checklists: [{ id: 'check-live', template_id: 'tpl-pn', client_id: 'c1' }],
    })
    expect(await postgresStore(fake).attachPendingClientNotes({ clientId: 'c1' })).toBe(0)
    expect(fake.matching(/^update client_pending_notes/i)).toHaveLength(0)
  })

  it('only first-stage checklists qualify: the SQL asks for it, and a stage-advance spawn is skipped', async () => {
    const fake = fakePendingNotesPostgres({
      notes: [
        {
          id: 'pnote-11',
          client_id: 'c1',
          template_id: 'tpl-pn',
          kind: 'note',
          body: 'x',
          created_at: '2026-09-01T00:00:00.000Z',
          attached_checklist_id: null,
        },
      ],
      checklists: [
        {
          id: 'check-s1',
          template_id: 'tpl-pn',
          client_id: 'c1',
          due_date: '2026-09-10',
          created_at: '2026-09-05T00:00:00.000Z',
          stage_index: 1,
        },
        {
          id: 'check-s0',
          template_id: 'tpl-pn',
          client_id: 'c1',
          due_date: '2026-09-20',
          created_at: '2026-09-05T00:00:00.000Z',
          stage_index: 0,
        },
      ],
    })
    await postgresStore(fake).attachPendingClientNotes({ clientId: 'c1' })
    const [select] = fake.matching(/^select n\.id as note_id, found\.id as checklist_id/i)
    expect(select.text).toMatch(/coalesce\(c\.stage_index, 0\) = 0/i)
    expect(fake.notes[0].attached_checklist_id).toBe('check-s0')
  })

  it('a stamp that changed no row rolls the item insert back and counts nothing', async () => {
    const fake = fakePendingNotesPostgres({
      notes: [
        {
          id: 'pnote-12',
          client_id: 'c1',
          template_id: 'tpl-pn',
          kind: 'task',
          body: 'x',
          created_at: '2026-09-01T00:00:00.000Z',
          attached_checklist_id: null,
        },
      ],
      checklists: [
        {
          id: 'check-1',
          template_id: 'tpl-pn',
          client_id: 'c1',
          due_date: '2026-09-10',
          created_at: '2026-09-05T00:00:00.000Z',
        },
      ],
    })
    const pgStore = postgresStore(fake)
    const hook = vi.fn()
    pgStore.onPendingNotesAttached = hook
    // Another pass stamps the note between our list and our stamp.
    const realList = pgStore._listUnattachedPendingNotes.bind(pgStore)
    vi.spyOn(pgStore, '_listUnattachedPendingNotes').mockImplementation(async (...args) => {
      const rows = await realList(...args)
      fake.notes[0].attached_checklist_id = 'check-other'
      return rows
    })

    expect(await pgStore.attachPendingClientNotes({ clientId: 'c1' })).toBe(0)
    expect(fake.matching(/^rollback$/i)).toHaveLength(1)
    expect(fake.matching(/^commit$/i)).toHaveLength(0)
    expect(hook).not.toHaveBeenCalled()
  })

  it('one note failing to attach does not stop the rest', async () => {
    const logged = vi.spyOn(console, 'error').mockImplementation(() => {})
    const fake = fakePendingNotesPostgres({
      notes: [
        {
          id: 'pnote-13',
          client_id: 'c1',
          template_id: 'tpl-pn',
          kind: 'task',
          body: 'fails',
          created_at: '2026-09-01T00:00:00.000Z',
          attached_checklist_id: null,
        },
        {
          id: 'pnote-14',
          client_id: 'c1',
          template_id: 'tpl-pn',
          kind: 'note',
          body: 'fine',
          created_at: '2026-09-01T00:00:00.000Z',
          attached_checklist_id: null,
        },
      ],
      checklists: [
        {
          id: 'check-1',
          template_id: 'tpl-pn',
          client_id: 'c1',
          due_date: '2026-09-10',
          created_at: '2026-09-05T00:00:00.000Z',
        },
      ],
    })
    const pgStore = postgresStore(fake)
    const failing = vi.spyOn(pgStore, '_attachTaskKindPendingNote').mockRejectedValueOnce(new Error('boom'))
    try {
      expect(await pgStore.attachPendingClientNotes({ clientId: 'c1' })).toBe(1)
      expect(fake.notes.find((note) => note.id === 'pnote-13').attached_checklist_id).toBeNull()
      expect(fake.notes.find((note) => note.id === 'pnote-14').attached_checklist_id).toBe('check-1')
      expect(logged).toHaveBeenCalled()
    } finally {
      failing.mockRestore()
      logged.mockRestore()
    }
  })

  it('lists the notes attached to a whole page of checklists in one query', async () => {
    const fake = fakePostgres()
    const pgStore = postgresStore(fake)
    await pgStore.listPendingNotesForChecklists(['check-a', 'check-b', 'check-a'])
    const [select] = fake.matching(/^select id, client_id, template_id, kind, body/i)
    expect(select.text).toMatch(/where attached_checklist_id = any\(\$1::text\[\]\)/i)
    expect(select.params).toEqual([['check-a', 'check-b']])

    const before = fake.statements.length
    expect(await pgStore.listPendingNotesForChecklists([])).toEqual([])
    expect(fake.statements).toHaveLength(before)
  })
  it('the stale-stamp clearing update is guarded: a checklist restored in between keeps its note', async () => {
    // The select sees the checklist as deleted; by the time the clearing update
    // runs it is live again (a restore from the bin landed in between).
    let reads = 0
    const restored = {
      id: 'check-restored',
      template_id: 'tpl-pn',
      client_id: 'c1',
      due_date: '2026-09-10',
      created_at: '2026-09-05T00:00:00.000Z',
      get deleted_at() {
        reads += 1
        return reads <= 1 ? '2026-09-08T00:00:00.000Z' : null
      },
    }
    const fake = fakePendingNotesPostgres({
      notes: [
        {
          id: 'pnote-20',
          client_id: 'c1',
          template_id: 'tpl-pn',
          kind: 'note',
          body: 'x',
          created_at: '2026-09-01T00:00:00.000Z',
          attached_checklist_id: 'check-restored',
          attached_item_id: null,
          attached_at: '2026-09-06T00:00:00.000Z',
        },
      ],
      checklists: [restored],
    })

    await postgresStore(fake).attachPendingClientNotes({ clientId: 'c1' })

    const [cleared] = fake.matching(/^update client_pending_notes\s+set attached_checklist_id = null/i)
    expect(cleared.text).toMatch(
      /and not exists \(\s*select 1 from checklists c\s+where c\.id = client_pending_notes\.attached_checklist_id\s+and c\.deleted_at is null\s+and c\.skipped_at is null\s*\)/i,
    )
    expect(fake.notes[0].attached_checklist_id).toBe('check-restored')
  })
})

/**
 * read() and the attach pass (Postgres): a task-kind attachment inserts an item
 * AFTER the snapshot read() holds was taken, and the GET handler computes the
 * workspace version from the persisted state AFTER read() returns. So when the
 * pass attached anything, read() has to hand back what is persisted - never the
 * pre-attach snapshot under the post-attach version.
 */
describe("read()'s attach pass hands back the persisted workspace (postgres branch)", () => {
  afterEach(() => {
    vi.restoreAllMocks()
  })

  const utcDaysAgo = (days) =>
    new Date(Date.now() - days * 24 * 60 * 60 * 1000).toISOString().slice(0, 10)

  const template = (nextDueDate) => ({
    id: 'tpl-1',
    title: 'Monthly bookkeeping',
    clientId: 'c1',
    assigneeId: 'emp-1',
    frequency: 'monthly',
    nextDueDate,
    active: true,
    isStandard: false,
    viewerIds: [],
    editorIds: [],
    stages: [
      {
        id: 'stage-1',
        name: 'Stage 1',
        assigneeId: 'emp-1',
        offsetDays: 0,
        viewerIds: [],
        editorIds: [],
        items: [{ id: 'ti-1', label: 'Close the month' }],
      },
    ],
  })
  const spawnable = () => ({
    clients: [{ id: 'c1', name: 'Acme' }],
    checklists: [],
    recycledChecklists: [],
    checklistTemplates: [template(utcDaysAgo(1))],
  })
  // The workspace as persisted after the spawn AND the attachment.
  const persistedAfterAttach = () => ({
    clients: [{ id: 'c1', name: 'Acme' }],
    recycledChecklists: [],
    checklistTemplates: [template('2099-01-01')],
    checklists: [
      {
        id: 'check-spawned',
        title: 'Monthly bookkeeping',
        clientId: 'c1',
        assigneeId: 'emp-1',
        templateId: 'tpl-1',
        dueDate: utcDaysAgo(1),
        caseId: 'case-1',
        stageId: 'stage-1',
        stageIndex: 0,
        stageCount: 1,
        items: [{ id: 'item-pn-1', label: 'New hire', done: false }],
      },
    ],
  })

  it('re-reads after an attachment, so the served data carries the attached item', async () => {
    const pgStore = postgresStore(fakePostgres())
    const reader = vi
      .spyOn(pgStore, '_readPostgresWorkspace')
      .mockResolvedValueOnce(spawnable())
      .mockResolvedValueOnce(spawnable())
      .mockResolvedValue(persistedAfterAttach())
    vi.spyOn(pgStore, 'write').mockResolvedValue(undefined)
    const attach = vi.spyOn(pgStore, 'attachPendingClientNotes').mockResolvedValue(1)

    const served = await pgStore.read()

    expect(attach).toHaveBeenCalledTimes(1)
    expect(reader).toHaveBeenCalledTimes(3)
    expect(served.checklists[0].items.map((item) => item.id)).toContain('item-pn-1')
  })

  it('re-reads after a write-back even when nothing attached, so the version matches the data', async () => {
    const pgStore = postgresStore(fakePostgres())
    const reader = vi
      .spyOn(pgStore, '_readPostgresWorkspace')
      .mockResolvedValueOnce(spawnable())
      .mockResolvedValueOnce(spawnable())
      .mockResolvedValue(persistedAfterAttach())
    vi.spyOn(pgStore, 'write').mockResolvedValue(undefined)
    vi.spyOn(pgStore, 'attachPendingClientNotes').mockResolvedValue(0)

    const served = await pgStore.read()

    // The write-back moved the persisted state past the snapshot we hold, and
    // the version handed out has to be one captured before the state served.
    expect(reader).toHaveBeenCalledTimes(3)
    expect(served.checklists.some((c) => c.templateId === 'tpl-1')).toBe(true)
  })
})

/**
 * `generateChecklistFromTemplate` (the "Generate a task now" / onboarding
 * spawn path) is the third attach-pass call site — the one outside `read()`
 * and outside the bulk PUT. FILE backend: a generated instance carries a
 * `createdAt` (same as a materializer spawn), so the match goes through it
 * rather than the `dueDate` fallback; the future due date in the first case
 * is incidental.
 */
describe('generateChecklistFromTemplate runs the pending-notes attach pass (file backend)', () => {
  const genTemplate = {
    id: 'tpl-pn-gen',
    title: 'Payroll',
    clientId: 'c1',
    assigneeId: 'emp-1',
    frequency: 'monthly',
    nextDueDate: '2026-10-15',
    active: true,
    isStandard: false,
    viewerIds: [],
    editorIds: [],
    stages: [
      {
        id: 'stage-1',
        name: 'Stage 1',
        assigneeId: 'emp-1',
        offsetDays: 0,
        viewerIds: [],
        editorIds: [],
        items: [{ id: 'ti-1', label: 'Run payroll' }],
      },
    ],
  }

  it('attaches a pending note to the checklist it just generated', async () => {
    await store.write(workspace({ checklistTemplates: [genTemplate] }))
    const note = await store.createClientPendingNote('c1', {
      templateId: 'tpl-pn-gen',
      kind: 'task',
      body: 'New hire this cycle',
    })

    const created = await store.generateChecklistFromTemplate('tpl-pn-gen', {
      dueDate: '2026-10-15',
    })
    expect(created).toBeTruthy()

    const updated = await store.getClientPendingNote(note.id)
    expect(updated.attachedChecklistId).toBe(created.id)
  })

  it('stamps createdAt on the generated checklist and matches on it, not on the due date', async () => {
    await store.write(workspace({ checklistTemplates: [{ ...genTemplate, id: 'tpl-pn-gen2' }] }))
    const note = await store.createClientPendingNote('c1', {
      templateId: 'tpl-pn-gen2',
      kind: 'note',
      body: 'For the next one',
    })
    // The spawn's createdAt has to land strictly after the note's.
    await new Promise((resolve) => setTimeout(resolve, 5))

    // A due date long BEFORE the note was written: the due-date fallback could
    // never match it, so only the createdAt stamp can attach this.
    const created = await store.generateChecklistFromTemplate('tpl-pn-gen2', {
      dueDate: '2020-01-15',
    })
    expect(typeof created.createdAt).toBe('string')
    expect(created.createdAt > note.createdAt).toBe(true)
    expect((await store.getClientPendingNote(note.id)).attachedChecklistId).toBe(created.id)
  })
})

/**
 * Quiet skip — the FILE backend, end to end.
 *
 * Cardinal rule 1: `db/store.js` has two backends and any persisted change must
 * touch both. This half proves the shape both branches implement (the marker on
 * the checklist row, the record in its own store, and the review stamp). The
 * Postgres half is the statement-shape suite below, plus the rolled-back
 * production validation that runs before shipping (HANDOFF §4).
 */
describe('quiet skip (file backend)', () => {
  const persisted = async () => JSON.parse(await readFile(localDataPath, 'utf8'))
  const authPersisted = async () => JSON.parse(await readFile(localAuthPath, 'utf8'))

  const skippableTemplate = {
    id: 'tmpl-skip',
    title: 'Monthly close',
    clientId: 'c1',
    assigneeId: 'emp-1',
    frequency: 'monthly',
    nextDueDate: '2026-08-31',
    active: true,
    skipAllowed: true,
    viewerIds: [],
    editorIds: [],
    stages: [],
  }

  const instance = (over = {}) => ({
    id: 'cl-1',
    title: 'Monthly close',
    clientId: 'c1',
    assigneeId: 'emp-1',
    templateId: 'tmpl-skip',
    dueDate: '2026-08-31',
    viewerIds: [],
    editorIds: [],
    items: [{ id: 'item-1', label: 'Reconcile', done: false }],
    ...over,
  })

  beforeEach(async () => {
    await store.write(
      workspace({ checklists: [instance()], checklistTemplates: [skippableTemplate] }),
    )
  })

  it('round-trips skipAllowed on the template', async () => {
    expect((await persisted()).checklistTemplates[0].skipAllowed).toBe(true)
  })

  it('stamps the instance without soft-deleting it', async () => {
    const updated = await store.skipChecklistInstance('cl-1', 'emp-1')
    expect(updated.skippedAt).toBeTruthy()
    expect(updated.skippedBy).toBe('emp-1')

    const row = (await persisted()).checklists.find((entry) => entry.id === 'cl-1')
    expect(row.skippedAt).toBeTruthy()
    // NOT a soft delete: the row must stay in the active list so the
    // materializer's identity tuple still sees it and does not respawn the
    // cycle that was deliberately stepped past.
    expect(row.deletedAt ?? null).toBeNull()
  })

  it('refuses to skip the same occurrence twice', async () => {
    expect(await store.skipChecklistInstance('cl-1', 'emp-1')).not.toBeNull()
    expect(await store.skipChecklistInstance('cl-1', 'emp-1')).toBeNull()
  })

  it('survives a bulk save — an autosave must not un-skip a task', async () => {
    await store.skipChecklistInstance('cl-1', 'emp-1')
    const stamped = (await persisted()).checklists[0].skippedAt

    // The owner's tab round-trips the workspace it was served.
    await store.write(
      workspace({
        checklists: [instance({ skippedAt: stamped, skippedBy: 'emp-1' })],
        checklistTemplates: [skippableTemplate],
      }),
    )

    expect((await persisted()).checklists[0].skippedAt).toBe(stamped)
  })

  it.each(['me', 'colleague', 'client'])(
    'persists the %s category with its note',
    async (category) => {
      const record = await store.createChecklistSkip({
        checklistId: 'cl-1',
        templateId: 'tmpl-skip',
        clientId: 'c1',
        title: 'Monthly close',
        skippedBy: 'emp-1',
        skippedByName: 'Lisa Chen',
        reasonCategory: category,
        reasonNote: 'Bank feed was down.',
      })

      const stored = (await authPersisted()).checklistSkips.find((entry) => entry.id === record.id)
      expect(stored.reasonCategory).toBe(category)
      expect(stored.reasonNote).toBe('Bank feed was down.')
      expect(stored.reviewedAt).toBeNull()
    },
  )

  it('lists skips newest first', async () => {
    const older = await store.createChecklistSkip({
      checklistId: 'cl-1',
      title: 'Older',
      reasonCategory: 'me',
      reasonNote: 'a',
    })
    // The file backend stamps from the clock, so force a distinguishable order.
    const authState = await authPersisted()
    const olderRecord = authState.checklistSkips.find((entry) => entry.id === older.id)
    olderRecord.skippedAt = '2026-01-01T00:00:00.000Z'
    await writeFile(localAuthPath, JSON.stringify(authState, null, 2))

    const newer = await store.createChecklistSkip({
      checklistId: 'cl-1',
      title: 'Newer',
      reasonCategory: 'client',
      reasonNote: 'b',
    })

    // Filtered to this test's two records: the auth-state file accumulates the
    // records earlier tests in this suite filed, and their order is not what
    // this test is about.
    const list = (await store.listChecklistSkips()).filter((entry) =>
      [older.id, newer.id].includes(entry.id),
    )
    expect(list.map((entry) => entry.id)).toEqual([newer.id, older.id])
  })

  it('reviewing stamps the record and keeps it forever', async () => {
    const record = await store.createChecklistSkip({
      checklistId: 'cl-1',
      title: 'Monthly close',
      reasonCategory: 'client',
      reasonNote: 'No statements.',
    })

    const reviewed = await store.reviewChecklistSkip(record.id, 'emp-owner')
    expect(reviewed.reviewedBy).toBe('emp-owner')
    expect(reviewed.reviewedAt).toBeTruthy()

    // Still there. Reviewing clears it from the DASHBOARD, never from the trail.
    const list = await store.listChecklistSkips()
    expect(list.find((entry) => entry.id === record.id)).toBeTruthy()
  })

  it('refuses to re-review a decision that was already made', async () => {
    const record = await store.createChecklistSkip({
      checklistId: 'cl-1',
      title: 'Monthly close',
      reasonCategory: 'me',
      reasonNote: 'Ran out of week.',
    })
    await store.reviewChecklistSkip(record.id, 'emp-owner')
    expect(await store.reviewChecklistSkip(record.id, 'emp-other')).toBeNull()
  })

  // ---- Push (featreq-68638ed2): the same row, moved instead of closed out ----

  it('moves the due date and stamps the cycle it came from', async () => {
    const result = await store.pushChecklistInstance('cl-1', 'emp-1', '2026-09-30')
    expect(result.completed).toBeNull()
    const updated = result.checklist
    expect(updated.dueDate).toBe('2026-09-30')
    // The date it was ORIGINALLY due — this is what identity reads, and losing
    // it would let the materializer respawn the cycle it was pushed out of.
    expect(updated.cycleDueDate).toBe('2026-08-31')
    expect(updated.pushedAt).toBeTruthy()
    expect(updated.pushedBy).toBe('emp-1')

    const row = (await persisted()).checklists.find((entry) => entry.id === 'cl-1')
    expect(row.dueDate).toBe('2026-09-30')
    expect(row.cycleDueDate).toBe('2026-08-31')
    // Not skipped and not deleted: a push closes nothing.
    expect(row.skippedAt ?? null).toBeNull()
    expect(row.deletedAt ?? null).toBeNull()
  })

  it('keeps the FIRST cycle date when a task is pushed a second time', async () => {
    await store.pushChecklistInstance('cl-1', 'emp-1', '2026-09-30')
    const twice = (await store.pushChecklistInstance('cl-1', 'emp-1', '2026-10-31')).checklist
    expect(twice.dueDate).toBe('2026-10-31')
    // Still the original. The row belongs to the cycle it was born in however
    // many times it moves.
    expect(twice.cycleDueDate).toBe('2026-08-31')
  })

  it('refuses to push an occurrence that was skipped — it is closed out', async () => {
    await store.skipChecklistInstance('cl-1', 'emp-1')
    expect(await store.pushChecklistInstance('cl-1', 'emp-1', '2026-09-30')).toBeNull()
  })

  // Push is offered on EVERY task now, one-offs included (featreq-68638ed2 —
  // the `skipAllowed` gate hid it on 95% of them). Nothing in the write reads
  // the template, so the only question is whether a null `templateId` is
  // tolerated: the cycle stamp is inert on a row the materializer never looks at.
  it('pushes a ONE-OFF task — no template, no cycle to keep a place in', async () => {
    await store.write(
      workspace({
        checklists: [instance({ id: 'cl-oneoff', templateId: null, dueDate: '2026-08-31' })],
        checklistTemplates: [],
      }),
    )

    const updated = (await store.pushChecklistInstance('cl-oneoff', 'emp-1', '2026-09-30'))
      .checklist
    expect(updated.dueDate).toBe('2026-09-30')
    expect(updated.pushedBy).toBe('emp-1')
    // Stamped harmlessly: with no template there is no identity tuple reading it.
    expect(updated.cycleDueDate).toBe('2026-08-31')

    const row = (await persisted()).checklists.find((entry) => entry.id === 'cl-oneoff')
    expect(row.dueDate).toBe('2026-09-30')
    expect(row.templateId ?? null).toBeNull()
  })

  // ---- Split push (featreq-fbab3370): done steps stay, open steps move ----

  it('refuses a push when every step is already done — nothing to carry forward', async () => {
    await store.write(
      workspace({
        checklists: [
          instance({ id: 'cl-alldone', items: [{ id: 'item-1', label: 'Reconcile', done: true }] }),
        ],
        checklistTemplates: [skippableTemplate],
      }),
    )

    await expect(store.pushChecklistInstance('cl-alldone', 'emp-1', '2026-09-30')).rejects.toThrow(
      NothingToPushError,
    )
    await expect(store.pushChecklistInstance('cl-alldone', 'emp-1', '2026-09-30')).rejects.toThrow(
      'Everything here is done. Nothing to push.',
    )
    // Refused, not silently accepted: the row is untouched.
    const row = (await persisted()).checklists.find((entry) => entry.id === 'cl-alldone')
    expect(row.dueDate).toBe('2026-08-31')
    expect(row.pushedAt ?? null).toBeNull()
  })

  it('refuses to push the completed record a split left behind, even with a step un-checked', async () => {
    await store.write(
      workspace({
        checklists: [
          instance({
            id: 'cl-mixed-rec',
            items: [
              { id: 'item-done', label: 'Reconcile', done: true },
              { id: 'item-open', label: 'Send statements', done: false },
            ],
          }),
        ],
        checklistTemplates: [skippableTemplate],
      }),
    )
    const { checklist: live, completed } = await store.pushChecklistInstance(
      'cl-mixed-rec',
      'emp-1',
      '2026-09-30',
    )
    // Someone un-checks the done step on the RECORD: it now has an open step.
    await store.toggleChecklistItem('cl-mixed-rec', 'item-done')
    const before = await persisted()

    await expect(
      store.pushChecklistInstance(completed.id, 'emp-1', '2026-10-31'),
    ).rejects.toBeInstanceOf(PushedRecordError)
    await expect(store.pushChecklistInstance(completed.id, 'emp-1', '2026-10-31')).rejects.toThrow(
      'This is the completed record of a pushed checklist. Push the live copy instead.',
    )
    // Untouched: no second split, no moved date.
    expect(await persisted()).toEqual(before)
    expect(
      before.checklists.filter((entry) => entry.pushedFromChecklistId === completed.id),
    ).toHaveLength(1)
    // The live copy is still pushable.
    await expect(store.pushChecklistInstance(live.id, 'emp-1', '2026-10-31')).resolves.toBeTruthy()
  })

  it('splits a MIXED push: done steps stay, open steps (with sub-items and waits) move', async () => {
    await store.write(
      workspace({
        checklists: [
          instance({
            id: 'cl-mixed',
            items: [
              { id: 'item-done', label: 'Reconcile', done: true },
              {
                id: 'item-open',
                label: 'Send statements',
                done: false,
                waiting: true,
                subItems: [{ id: 'sub-1', title: 'Draft the email', done: false }],
              },
            ],
          }),
        ],
        checklistTemplates: [skippableTemplate],
      }),
    )

    const { checklist: moved, completed } = await store.pushChecklistInstance(
      'cl-mixed',
      'emp-1',
      '2026-09-30',
    )

    // The new checklist carries only the open step, whole — sub-items and the
    // wait flag included — and this occurrence's cycle identity.
    expect(moved.id).not.toBe('cl-mixed')
    expect(moved.items.map((item) => item.id)).toEqual(['item-open'])
    expect(moved.items[0].waiting).toBe(true)
    expect(moved.items[0].subItems).toEqual([{ id: 'sub-1', title: 'Draft the email', done: false }])
    expect(moved.dueDate).toBe('2026-09-30')
    expect(moved.cycleDueDate).toBe('2026-08-31')
    expect(moved.pushedFromChecklistId).toBe('cl-mixed')
    // Identity fields copied, so the new row is recognizably the same task.
    expect(moved.title).toBe('Monthly close')
    expect(moved.clientId).toBe('c1')
    expect(moved.templateId).toBe('tmpl-skip')

    // The original keeps only its done step — it now reads complete — and
    // hands its identity off to the new row.
    expect(completed.id).toBe('cl-mixed')
    expect(completed.items.map((item) => item.id)).toEqual(['item-done'])
    expect(completed.pushedToChecklistId).toBe(moved.id)
    expect(completed.dueDate).toBe('2026-08-31')

    const persistedData = await persisted()
    const movedRow = persistedData.checklists.find((entry) => entry.id === moved.id)
    const originalRow = persistedData.checklists.find((entry) => entry.id === 'cl-mixed')
    expect(movedRow.items).toHaveLength(1)
    expect(originalRow.items).toHaveLength(1)
    expect(originalRow.pushedToChecklistId).toBe(moved.id)
    expect(movedRow.pushedFromChecklistId).toBe('cl-mixed')
  })

  it('survives a bulk save — pushedFromChecklistId / pushedToChecklistId round-trip', async () => {
    await store.write(
      workspace({
        checklists: [
          instance({
            id: 'cl-mixed2',
            items: [
              { id: 'item-done', label: 'Reconcile', done: true },
              { id: 'item-open', label: 'Send statements', done: false },
            ],
          }),
        ],
        checklistTemplates: [skippableTemplate],
      }),
    )
    const { checklist: moved } = await store.pushChecklistInstance('cl-mixed2', 'emp-1', '2026-09-30')

    // The owner's tab round-trips BOTH rows the split left behind — neither
    // row's link field is something the UI edits.
    const persistedBefore = await persisted()
    const originalRow = persistedBefore.checklists.find((entry) => entry.id === 'cl-mixed2')
    const movedRow = persistedBefore.checklists.find((entry) => entry.id === moved.id)
    await store.write(
      workspace({
        checklists: [originalRow, movedRow],
        checklistTemplates: [skippableTemplate],
      }),
    )

    const after = await persisted()
    expect(after.checklists.find((entry) => entry.id === 'cl-mixed2').pushedToChecklistId).toBe(
      moved.id,
    )
    expect(after.checklists.find((entry) => entry.id === moved.id).pushedFromChecklistId).toBe(
      'cl-mixed2',
    )
  })

  it('carries the onboarding link and creator onto the new row and stamps createdAt', async () => {
    await store.write(
      workspace({
        checklists: [
          instance({
            id: 'cl-meta',
            onboardingForClientId: 'c1',
            createdBy: 'emp-9',
            items: [
              { id: 'item-done', label: 'Reconcile', done: true },
              { id: 'item-open', label: 'Send statements', done: false },
            ],
          }),
        ],
        checklistTemplates: [skippableTemplate],
      }),
    )
    const { checklist: moved } = await store.pushChecklistInstance('cl-meta', 'emp-1', '2026-09-30')
    expect(moved.onboardingForClientId).toBe('c1')
    expect(moved.createdBy).toBe('emp-9')
    expect(moved.createdAt).toBeTruthy()
    const row = (await persisted()).checklists.find((entry) => entry.id === moved.id)
    expect(row.onboardingForClientId).toBe('c1')
    expect(row.createdBy).toBe('emp-9')
    expect(row.createdAt).toBeTruthy()
  })

  it('moves pending requests on the MOVED steps (and task-level edits) to the new checklist', async () => {
    await store.write(
      workspace({
        checklists: [
          instance({
            id: 'cl-req',
            items: [
              { id: 'item-done', label: 'Reconcile', done: true },
              { id: 'item-open', label: 'Send statements', done: false },
            ],
          }),
        ],
        checklistTemplates: [skippableTemplate],
      }),
    )
    const authState = await authPersisted()
    authState.itemDeletionRequests = [
      { id: 'idr-open', clientId: 'c1', checklistId: 'cl-req', itemId: 'item-open', label: 'x' },
      { id: 'idr-done', clientId: 'c1', checklistId: 'cl-req', itemId: 'item-done', label: 'y' },
      { id: 'idr-other', clientId: 'c1', checklistId: 'cl-else', itemId: 'item-open', label: 'z' },
    ]
    authState.pendingTaskEdits = [
      { id: 'pte-open', checklistId: 'cl-req', itemId: 'item-open', scope: 'item', proposed: {} },
      { id: 'pte-done', checklistId: 'cl-req', itemId: 'item-done', scope: 'item', proposed: {} },
      { id: 'pte-details', checklistId: 'cl-req', itemId: null, scope: 'details', proposed: {} },
      { id: 'pte-add', checklistId: 'cl-req', itemId: null, scope: 'add_item', proposed: {} },
    ]
    await writeFile(localAuthPath, JSON.stringify(authState, null, 2))

    const { checklist: moved } = await store.pushChecklistInstance('cl-req', 'emp-1', '2026-09-30')

    const after = await authPersisted()
    const idr = Object.fromEntries(after.itemDeletionRequests.map((req) => [req.id, req.checklistId]))
    expect(idr['idr-open']).toBe(moved.id)
    // A request about a step that STAYED stays with it; one about another
    // checklist is nobody's business here.
    expect(idr['idr-done']).toBe('cl-req')
    expect(idr['idr-other']).toBe('cl-else')
    const pte = Object.fromEntries(after.pendingTaskEdits.map((req) => [req.id, req.checklistId]))
    expect(pte['pte-open']).toBe(moved.id)
    expect(pte['pte-done']).toBe('cl-req')
    expect(pte['pte-details']).toBe(moved.id)
    expect(pte['pte-add']).toBe(moved.id)
  })

  it('moves attached client-page notes with the open work (task notes by item, note-kind notes always)', async () => {
    await store.write(
      workspace({
        checklists: [
          instance({
            id: 'cl-notes',
            items: [
              { id: 'item-done', label: 'Reconcile', done: true },
              { id: 'item-pn-done', label: 'A task note already finished', done: true },
              { id: 'item-open', label: 'Send statements', done: false },
              { id: 'item-pn-open', label: 'A task note still open', done: false },
            ],
          }),
        ],
        checklistTemplates: [skippableTemplate],
      }),
    )
    const note = (id, over) => ({
      id,
      clientId: 'c1',
      templateId: 'tmpl-skip',
      kind: 'note',
      body: id,
      attachedChecklistId: 'cl-notes',
      attachedItemId: null,
      ...over,
    })
    const authState = await authPersisted()
    authState.clientPendingNotes = [
      note('pn-task-open', { kind: 'task', attachedItemId: 'item-pn-open' }),
      note('pn-task-done', { kind: 'task', attachedItemId: 'item-pn-done' }),
      note('pn-note', {}),
      note('pn-elsewhere', { attachedChecklistId: 'cl-else' }),
      note('pn-pending', { attachedChecklistId: null }),
    ]
    await writeFile(localAuthPath, JSON.stringify(authState, null, 2))

    const { checklist: moved } = await store.pushChecklistInstance('cl-notes', 'emp-1', '2026-09-30')

    const after = Object.fromEntries(
      (await authPersisted()).clientPendingNotes.map((entry) => [entry.id, entry.attachedChecklistId]),
    )
    expect(after['pn-task-open']).toBe(moved.id)
    // The finished task note's item stayed on the done-only record, so it stays.
    expect(after['pn-task-done']).toBe('cl-notes')
    // A note-kind note has no item: it belongs with the live work.
    expect(after['pn-note']).toBe(moved.id)
    expect(after['pn-elsewhere']).toBe('cl-else')
    expect(after['pn-pending']).toBeNull()
  })

  it('re-points waits held by steps elsewhere (items and sub-steps) at the new checklist', async () => {
    await store.write(
      workspace({
        checklists: [
          instance({
            id: 'cl-target',
            items: [
              { id: 'item-done', label: 'Reconcile', done: true },
              { id: 'item-open', label: 'Send statements', done: false },
            ],
          }),
          instance({
            id: 'cl-waiter',
            templateId: null,
            items: [
              { id: 'w-item', label: 'Wait item', done: false },
              { id: 'w-parent', label: 'Wait parent', done: false },
            ],
          }),
        ],
        checklistTemplates: [skippableTemplate],
      }),
    )
    // Written straight to the file: a bulk save would (rightly) refuse to author
    // a wait, and this test is about what the PUSH does with existing ones.
    const data = await persisted()
    const waiter = data.checklists.find((entry) => entry.id === 'cl-waiter')
    waiter.items[0].waiting = true
    waiter.items[0].waitingForChecklistId = 'cl-target'
    waiter.items[1].subItems = [
      {
        id: 'w-sub',
        title: 'Sub',
        done: false,
        waiting: true,
        waitingForChecklistId: 'cl-target',
        subItems: [
          { id: 'w-subsub', title: 'SubSub', done: false, waiting: true, waitingForChecklistId: 'cl-target' },
          { id: 'w-subsub2', title: 'Other', done: false, waiting: true, waitingForChecklistId: 'cl-else' },
        ],
      },
    ]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))

    const { checklist: moved } = await store.pushChecklistInstance('cl-target', 'emp-1', '2026-09-30')

    const after = (await persisted()).checklists.find((entry) => entry.id === 'cl-waiter')
    expect(after.items[0].waitingForChecklistId).toBe(moved.id)
    expect(after.items[1].subItems[0].waitingForChecklistId).toBe(moved.id)
    expect(after.items[1].subItems[0].subItems[0].waitingForChecklistId).toBe(moved.id)
    // A wait on some OTHER task is not this push's to move.
    expect(after.items[1].subItems[0].subItems[1].waitingForChecklistId).toBe('cl-else')
  })

  it('also re-points waits held by steps on a RECYCLED checklist, as the Postgres update does', async () => {
    await store.write(
      workspace({
        checklists: [
          instance({
            id: 'cl-target',
            items: [
              { id: 'item-done', label: 'Reconcile', done: true },
              { id: 'item-open', label: 'Send statements', done: false },
            ],
          }),
        ],
        checklistTemplates: [skippableTemplate],
      }),
    )
    const data = await persisted()
    data.recycledChecklists = [
      {
        ...instance({
          id: 'cl-bin',
          templateId: null,
          items: [
            { id: 'b-item', label: 'Wait item', done: false, waiting: true, waitingForChecklistId: 'cl-target' },
            {
              id: 'b-parent',
              label: 'Wait parent',
              done: false,
              subItems: [{ id: 'b-sub', title: 'Sub', done: false, waiting: true, waitingForChecklistId: 'cl-target' }],
            },
          ],
        }),
        deletedAt: '2026-09-01T00:00:00.000Z',
      },
    ]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))

    const { checklist: moved } = await store.pushChecklistInstance('cl-target', 'emp-1', '2026-09-30')

    const bin = (await persisted()).recycledChecklists.find((entry) => entry.id === 'cl-bin')
    expect(bin.items[0].waitingForChecklistId).toBe(moved.id)
    expect(bin.items[1].subItems[0].waitingForChecklistId).toBe(moved.id)
  })

  it('a done-only original does not spawn the next stage when a step is re-checked', async () => {
    const stagedTemplate = {
      ...skippableTemplate,
      id: 'tmpl-staged',
      stages: [
        { id: 'st-0', name: 'Prep', assigneeId: 'emp-1', offsetDays: 0, items: [{ id: 'ti-0', label: 'a' }] },
        { id: 'st-1', name: 'Review', assigneeId: 'emp-1', offsetDays: 3, items: [{ id: 'ti-1', label: 'b' }] },
      ],
    }
    await store.write(
      workspace({
        checklists: [
          instance({
            id: 'cl-staged',
            templateId: 'tmpl-staged',
            stageId: 'st-0',
            stageIndex: 0,
            stageCount: 2,
            items: [
              { id: 'item-done', label: 'Reconcile', done: true },
              { id: 'item-open', label: 'Send statements', done: false },
            ],
          }),
        ],
        checklistTemplates: [stagedTemplate],
      }),
    )
    await store.pushChecklistInstance('cl-staged', 'emp-1', '2026-09-30')

    // Un-check then re-check the done step on the original: it is all done
    // again, but it is a completed RECORD now - the pushed copy carries the stage.
    await store.toggleChecklistItem('cl-staged', 'item-done')
    const result = await store.toggleChecklistItem('cl-staged', 'item-done')
    expect(result.spawned).toBeNull()
    const stageOnes = (await persisted()).checklists.filter(
      (entry) => entry.templateId === 'tmpl-staged' && entry.stageIndex === 1,
    )
    expect(stageOnes).toHaveLength(0)
  })

  it('files a one-off push on the review trail with a null template id', async () => {
    const record = await store.createChecklistSkip({
      checklistId: 'cl-oneoff',
      templateId: null,
      clientId: 'c1',
      title: 'Clean up the 2025 books',
      skippedBy: 'emp-1',
      skippedByName: 'Lisa Chen',
      reasonCategory: 'client',
      reasonNote: 'They have not sent the statements yet.',
      kind: 'push',
      newDueDate: '2026-09-30',
    })

    const stored = (await authPersisted()).checklistSkips.find((entry) => entry.id === record.id)
    expect(stored.templateId).toBeNull()
    expect(stored.kind).toBe('push')
    expect(stored.newDueDate).toBe('2026-09-30')
  })

  it('survives a bulk save — an autosave must not un-push a task', async () => {
    await store.pushChecklistInstance('cl-1', 'emp-1', '2026-09-30')
    const stamped = (await persisted()).checklists[0].pushedAt

    // The owner's tab round-trips the workspace it was served.
    await store.write(
      workspace({
        checklists: [
          instance({
            dueDate: '2026-09-30',
            cycleDueDate: '2026-08-31',
            pushedAt: stamped,
            pushedBy: 'emp-1',
          }),
        ],
        checklistTemplates: [skippableTemplate],
      }),
    )

    const row = (await persisted()).checklists[0]
    expect(row.cycleDueDate).toBe('2026-08-31')
    expect(row.pushedAt).toBe(stamped)
  })

  it('ignores the push stamps a bulk save carries — stored wins', async () => {
    await store.pushChecklistInstance('cl-1', 'emp-1', '2026-09-30')
    const stamped = (await persisted()).checklists[0].pushedAt

    // A tab that loaded before the push, or one that mangled the field on the
    // way back up: a cycle date that is not this row's, and stamps that are not
    // its own. `cycle_due_date` is the identity the materializer reads — in
    // Postgres a wrong one collides on the unique index and takes the whole
    // checklist out of the save — so the payload never gets a vote.
    await store.write(
      workspace({
        checklists: [
          instance({
            dueDate: '2026-09-30',
            cycleDueDate: '2026-12-31',
            pushedAt: '2020-01-01T00:00:00.000Z',
            pushedBy: 'emp-9',
          }),
        ],
        checklistTemplates: [skippableTemplate],
      }),
    )

    const row = (await persisted()).checklists[0]
    expect(row.cycleDueDate).toBe('2026-08-31')
    expect(row.pushedAt).toBe(stamped)
    expect(row.pushedBy).toBe('emp-1')
  })

  it('does not let a bulk save invent a push on a task that was never pushed', async () => {
    await store.write(
      workspace({
        checklists: [instance({ cycleDueDate: '2026-12-31', pushedBy: 'emp-9' })],
        checklistTemplates: [skippableTemplate],
      }),
    )

    const row = (await persisted()).checklists[0]
    expect(row.cycleDueDate ?? null).toBeNull()
    expect(row.pushedAt ?? null).toBeNull()
    expect(row.pushedBy ?? null).toBeNull()
  })

  it('files a push record on the same trail, naming the date it moved to', async () => {
    const record = await store.createChecklistSkip({
      checklistId: 'cl-1',
      templateId: 'tmpl-skip',
      clientId: 'c1',
      title: 'Monthly close',
      skippedBy: 'emp-1',
      skippedByName: 'Lisa Chen',
      reasonCategory: 'client',
      reasonNote: 'Statements are late.',
      kind: 'push',
      newDueDate: '2026-09-30',
    })

    const stored = (await authPersisted()).checklistSkips.find((entry) => entry.id === record.id)
    expect(stored.kind).toBe('push')
    expect(stored.newDueDate).toBe('2026-09-30')

    // And it reaches the owner's queue through the same list as a skip.
    const listed = (await store.listChecklistSkips()).find((entry) => entry.id === record.id)
    expect(listed.kind).toBe('push')
    expect(listed.newDueDate).toBe('2026-09-30')
  })

  it('reads an ordinary skip record as a skip, with no date', async () => {
    const record = await store.createChecklistSkip({
      checklistId: 'cl-1',
      title: 'Monthly close',
      reasonCategory: 'me',
      reasonNote: 'Ran out of week.',
    })
    const listed = (await store.listChecklistSkips()).find((entry) => entry.id === record.id)
    expect(listed.kind).toBe('skip')
    expect(listed.newDueDate).toBeNull()
  })
})

/**
 * Quiet skip — the POSTGRES branch, at statement level.
 *
 * NEW SQL SHAPES, flagged for the rolled-back production validation:
 *   - alter table checklist_templates add column if not exists skip_allowed
 *       boolean not null default false
 *   - alter table checklists add column if not exists skipped_at timestamptz
 *   - alter table checklists add column if not exists skipped_by text
 *   - create table if not exists checklist_skips (...) + checklist_skips_skipped_at_idx
 *
 * The file backend cannot regress the two things pinned here — it has no
 * columns and no WHERE clause — so only a statement-level test catches them:
 * the skip UPDATE must be guarded on `skipped_at is null` (or a double-submit
 * files two records for one cycle), and the review UPDATE must be guarded on
 * `reviewed_at is null` (or a second owner overwrites the first one's decision).
 */
describe('quiet skip (postgres branch)', () => {
  it('guards the skip UPDATE so one cycle can only be skipped once', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).skipChecklistInstance('cl-1', 'emp-1')

    const [statement] = fake.matching(/^update checklists set skipped_at/i)
    expect(statement).toBeTruthy()
    expect(statement.text).toMatch(/skipped_at is null/i)
    // And never touches a row already in the recycle bin.
    expect(statement.text).toMatch(/deleted_at is null/i)
    expect(statement.params).toEqual(['cl-1', 'emp-1'])
  })

  it('inserts the audit record into checklist_skips with its category and note', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).createChecklistSkip({
      checklistId: 'cl-1',
      templateId: 'tmpl-skip',
      clientId: 'c1',
      title: 'Monthly close',
      skippedBy: 'emp-1',
      skippedByName: 'Lisa Chen',
      reasonCategory: 'client',
      reasonNote: 'No statements.',
    })

    const [statement] = fake.matching(/insert into checklist_skips/i)
    expect(statement).toBeTruthy()
    expect(statement.params).toContain('client')
    expect(statement.params).toContain('No statements.')
    expect(statement.params).toContain('Monthly close')
  })

  it('guards the review UPDATE so a decision cannot be overwritten', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).reviewChecklistSkip('skip-1', 'emp-owner')

    const [statement] = fake.matching(/^update checklist_skips set reviewed_by/i)
    expect(statement).toBeTruthy()
    expect(statement.text).toMatch(/reviewed_at is null/i)
    expect(statement.params).toEqual(['skip-1', 'emp-owner'])
  })

  it('never issues a DELETE against checklist_skips — the trail is permanent', async () => {
    const fake = fakePostgres()
    const pgStore = postgresStore(fake)
    await pgStore.createChecklistSkip({
      checklistId: 'cl-1',
      title: 'Monthly close',
      reasonCategory: 'me',
      reasonNote: 'Ran out of week.',
    })
    await pgStore.reviewChecklistSkip('skip-1', 'emp-owner')

    expect(fake.matching(/delete from checklist_skips/i)).toHaveLength(0)
  })

  // ---- Push (featreq-68638ed2) ----
  //
  // NEW SQL SHAPES, flagged for the rolled-back production validation:
  //   - alter table checklists add column if not exists cycle_due_date date
  //   - alter table checklists add column if not exists pushed_at timestamptz
  //   - alter table checklists add column if not exists pushed_by text
  //   - alter table checklist_skips add column if not exists kind text
  //       not null default 'skip'  /  new_due_date date
  //   - create unique index checklists_template_instance_uniq_v2 on
  //       checklists (template_id, coalesce(cycle_due_date, due_date), stage_index)
  //       where deleted_at is null and template_id is not null
  //     then drop index checklists_template_instance_uniq

  it('stamps the ORIGINAL cycle date once, and only ever moves due_date', async () => {
    // No item rows (default `pushItemRows: []`) ⇒ no done steps ⇒ the plain
    // no-split move, exactly like before the split existed.
    const fake = fakePostgres({
      pushChecklistRows: [{ id: 'cl-1', due_date: '2026-08-31', cycle_due_date: null }],
    })
    await postgresStore(fake).pushChecklistInstance('cl-1', 'emp-1', '2026-09-30')

    const [statement] = fake.matching(/^update checklists\s+set cycle_due_date/i)
    expect(statement).toBeTruthy()
    // `coalesce` is the whole rule: a second push must not overwrite the date
    // the occurrence was born on, because that is its identity.
    expect(statement.text).toMatch(/cycle_due_date = coalesce\(cycle_due_date, due_date\)/i)
    expect(statement.text).toMatch(/due_date = \$3/i)
    // A skipped or recycled occurrence is closed out and cannot be pushed.
    expect(statement.text).toMatch(/skipped_at is null/i)
    expect(statement.text).toMatch(/deleted_at is null/i)
    expect(statement.params).toEqual(['cl-1', 'emp-1', '2026-09-30'])
    // The update never mentions template_id, which is why a ONE-OFF task
    // (featreq-68638ed2) pushes on Postgres exactly as it does on the file
    // backend — there is no per-template gate left in the write.
    expect(statement.text).not.toMatch(/template_id/i)
  })

  // ---- Split push (featreq-fbab3370), Postgres statement shapes ----

  it('refuses in one transaction when every step is already done — no write at all', async () => {
    const fake = fakePostgres({
      pushChecklistRows: [{ id: 'cl-done', due_date: '2026-08-31', cycle_due_date: null }],
      pushItemRows: [{ id: 'item-1', checklist_id: 'cl-done', label: 'Reconcile', done: true }],
    })

    await expect(
      postgresStore(fake).pushChecklistInstance('cl-done', 'emp-1', '2026-09-30'),
    ).rejects.toThrow(NothingToPushError)

    expect(fake.matching(/^begin$/i)).toHaveLength(1)
    expect(fake.matching(/^rollback$/i)).toHaveLength(1)
    expect(fake.matching(/^commit$/i)).toHaveLength(0)
    // Refused before any write: neither an UPDATE nor an INSERT ever touched
    // the checklists table.
    expect(fake.matching(/^update checklists\b/i)).toHaveLength(0)
    expect(fake.matching(/^insert into checklists\b/i)).toHaveLength(0)
  })

  const splitPushRow = {
    id: 'cl-mixed',
    title: 'Monthly close',
    client_id: 'c1',
    assignee_id: 'emp-1',
    template_id: 'tmpl-skip',
    frequency: 'monthly',
    due_date: '2026-08-31',
    viewer_ids: [],
    editor_ids: [],
    case_id: 'cl-mixed',
    stage_id: null,
    stage_index: 0,
    stage_count: 1,
    category_id: null,
    cycle_due_date: null,
    identity_date: '2026-08-31',
    pushed_to_checklist_id: null,
    period_label: null,
    onboarding_for_client_id: 'c1',
    created_by: 'emp-9',
  }
  const splitPushItems = [
    { id: 'item-done', checklist_id: 'cl-mixed', label: 'Reconcile', done: true, sort_order: 0 },
    { id: 'item-open', checklist_id: 'cl-mixed', label: 'Send statements', done: false, sort_order: 1 },
  ]

  // The statement order of a split, as labels. This is the production-only
  // failure (23505) the file backend cannot see: the original must hand its
  // identity off BEFORE the new row is inserted.
  const splitStatementOrder = (fake) =>
    fake.statements
      .map((statement) => {
        const text = statement.text
        if (/^begin$/i.test(text)) return 'begin'
        if (/^commit$/i.test(text)) return 'commit'
        if (/^rollback$/i.test(text)) return 'rollback'
        if (/^select id, client_id, title, assignee_id[\s\S]*from checklists[\s\S]*for update$/i.test(text)) {
          return 'lock-checklist'
        }
        if (/^select id, checklist_id, label[\s\S]*from checklist_items[\s\S]*for update$/i.test(text)) {
          return 'lock-items'
        }
        if (/^update checklists\s+set pushed_at = now\(\), pushed_by = \$2, pushed_to_checklist_id/i.test(text)) {
          return 'handoff'
        }
        if (/^insert into checklists \(/i.test(text)) return 'insert'
        if (/^update checklist_items set checklist_id/i.test(text)) return 'reparent'
        if (/^update item_deletion_requests/i.test(text)) return 'repoint-deletions'
        if (/^update pending_task_edits/i.test(text)) return 'repoint-edits'
        if (/^update client_pending_notes/i.test(text)) return 'repoint-notes'
        if (/^update checklist_items set waiting_for_checklist_id/i.test(text)) return 'repoint-waits'
        if (/^select id, sub_items from checklist_items/i.test(text)) return 'find-sub-waits'
        if (/^update checklist_items set sub_items/i.test(text)) return 'repoint-sub-waits'
        return null
      })
      .filter(Boolean)

  it('splits in one transaction: the original hands off its identity BEFORE the new row is inserted', async () => {
    const fake = fakePostgres({
      simulateChecklistUniqueness: true,
      pushChecklistRows: [splitPushRow],
      pushItemRows: splitPushItems,
    })

    await postgresStore(fake).pushChecklistInstance('cl-mixed', 'emp-1', '2026-09-30')

    // The exact order. begin, lock, lock, HAND-OFF, insert, re-parent, requests,
    // waits, commit. Nothing may be inserted while the original still holds the
    // occurrence's identity.
    expect(splitStatementOrder(fake)).toEqual([
      'begin',
      'lock-checklist',
      'lock-items',
      'handoff',
      'insert',
      'reparent',
      'repoint-deletions',
      'repoint-edits',
      'repoint-notes',
      'repoint-waits',
      'find-sub-waits',
      'commit',
    ])
    expect(fake.matching(/^rollback$/i)).toHaveLength(0)

    const [insert] = fake.matching(/^insert into checklists \(/i)
    const [handoff] = fake.matching(/^update checklists\s+set pushed_at = now\(\), pushed_by/i)
    expect(handoff.text).toMatch(/pushed_to_checklist_id = \$3/i)
    expect(handoff.params[0]).toBe('cl-mixed')
    // The hand-off names the id the INSERT then creates.
    expect(handoff.params[2]).toBe(insertedRows(fake.statements, 'checklists')[0].id)

    expect(insert.text).toMatch(/pushed_from_checklist_id/i)
    // The new row's cycle_due_date inherits exactly what the no-split branch
    // would have stamped onto the original: coalesce(cycle_due_date, due_date).
    const [pushed] = insertedRows(fake.statements, 'checklists')
    expect(Object.values(pushed)).toContain('2026-08-31')
    // ...and it is the STRING the lock select's to_char produced, never a Date.
    expect(pushed.cycle_due_date).toBe('2026-08-31')
    expect(Object.values(pushed).some((value) => value instanceof Date)).toBe(false)
    const [lock] = fake.matching(/^select id, client_id, title, assignee_id[\s\S]*for update$/i)
    expect(lock.text).toMatch(
      /to_char\(coalesce\(cycle_due_date, due_date\), 'YYYY-MM-DD'\) as identity_date/,
    )
    expect(insert.params).toContain('cl-mixed') // pushed_from_checklist_id
    expect(insert.params).toContain('2026-09-30') // the new row's due_date
    // Onboarding link and creator ride along.
    expect(insert.params).toContain('emp-9')
    expect(insert.params.filter((value) => value === 'c1').length).toBeGreaterThanOrEqual(2)

    const reparented = fake.matching(/^update checklist_items set checklist_id = \$1/i)
    expect(reparented).toHaveLength(1)
    expect(reparented[0].params[2]).toBe('item-open')
    // The done step is never touched.
    expect(
      fake.statements.some(
        (statement) =>
          !/^select\b/i.test(statement.text) && statement.params?.includes('item-done'),
      ),
    ).toBe(false)

    // The item rows are locked before the open/done decision is made.
    const [itemLock] = fake.matching(/^select id, checklist_id, label[\s\S]*for update$/i)
    expect(itemLock).toBeTruthy()
  })

  it('re-points attached client-page notes in the same transaction as the split', async () => {
    const fake = fakePostgres({
      pushChecklistRows: [splitPushRow],
      pushItemRows: splitPushItems,
    })

    await postgresStore(fake).pushChecklistInstance('cl-mixed', 'emp-1', '2026-09-30')

    const [notes] = fake.matching(/^update client_pending_notes/i)
    // (The statement order test above pins that it runs between begin and commit.)
    // new id, original id, the ids of the items that moved.
    expect(notes.params).toEqual([insertedRows(fake.statements, 'checklists')[0].id, 'cl-mixed', ['item-open']])
    expect(notes.text).toMatch(/set attached_checklist_id = \$1/i)
    expect(notes.text).toMatch(/where attached_checklist_id = \$2/i)
    // Note-kind notes always follow; task-kind notes only when their item moved.
    expect(notes.text).toMatch(/kind = 'note' or attached_item_id = any\(\$3::text\[\]\)/i)
  })

  it('the fake REFUSES the old order — insert before hand-off raises 23505', async () => {
    // Guards the guard: if this stops throwing, the uniqueness simulation has
    // gone vacuous and the order test above proves nothing.
    const fake = fakePostgres({
      simulateChecklistUniqueness: true,
      pushChecklistRows: [splitPushRow],
      pushItemRows: splitPushItems,
    })
    const columns =
      'id, title, client_id, assignee_id, template_id, frequency, due_date, stage_index, cycle_due_date'
    await expect(
      fake.pool.query(
        `insert into checklists (${columns}) values ($1, $2, $3, $4, $5, $6, $7, $8, $9)`,
        ['cl-new', 't', 'c1', 'emp-1', 'tmpl-skip', 'monthly', '2026-09-30', 0, '2026-08-31'],
      ),
    ).rejects.toMatchObject({ code: '23505' })
    // And once the original has handed off, the same insert is accepted.
    await fake.pool.query(
      `update checklists set pushed_at = now(), pushed_by = $2, pushed_to_checklist_id = $3 where id = $1`,
      ['cl-mixed', 'emp-1', 'cl-new'],
    )
    await expect(
      fake.pool.query(
        `insert into checklists (${columns}) values ($1, $2, $3, $4, $5, $6, $7, $8, $9)`,
        ['cl-new', 't', 'c1', 'emp-1', 'tmpl-skip', 'monthly', '2026-09-30', 0, '2026-08-31'],
      ),
    ).resolves.toBeDefined()
  })

  it('rolls the whole split back when the INSERT throws mid-split', async () => {
    const fake = fakePostgres({
      pushChecklistRows: [splitPushRow],
      pushItemRows: splitPushItems,
      failOn: { pattern: /^insert into checklists \(/i, error: new Error('connection reset') },
    })

    await expect(
      postgresStore(fake).pushChecklistInstance('cl-mixed', 'emp-1', '2026-09-30'),
    ).rejects.toThrow('connection reset')

    expect(fake.matching(/^begin$/i)).toHaveLength(1)
    expect(fake.matching(/^rollback$/i)).toHaveLength(1)
    expect(fake.matching(/^commit$/i)).toHaveLength(0)
    // Nothing after the failed INSERT ran: no re-parent, no re-pointing.
    expect(fake.matching(/^update checklist_items\b/i)).toHaveLength(0)
    expect(fake.matching(/^update item_deletion_requests\b/i)).toHaveLength(0)
    expect(fake.matching(/^update pending_task_edits\b/i)).toHaveLength(0)
  })

  it('maps an unexpected unique violation (23505) from the split to a PushConflictError', async () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {})
    try {
      const fake = fakePostgres({
        pushChecklistRows: [splitPushRow],
        pushItemRows: splitPushItems,
        failOn: {
          pattern: /^insert into checklists \(/i,
          error: Object.assign(new Error('duplicate key'), {
            code: '23505',
            constraint: 'checklists_template_instance_uniq_v3',
            detail: 'Key (template_id, ...)=(tmpl-skip, ...) already exists.',
          }),
        },
      })

      const pushing = postgresStore(fake).pushChecklistInstance('cl-mixed', 'emp-1', '2026-09-30')
      await expect(pushing).rejects.toBeInstanceOf(PushConflictError)
      await expect(pushing).rejects.toThrow(
        'This checklist changed while you were pushing it. Reload and try again.',
      )
      expect(fake.matching(/^rollback$/i)).toHaveLength(1)
      expect(fake.matching(/^commit$/i)).toHaveLength(0)
      // The constraint that fired is logged, so a conflict is diagnosable.
      expect(warn).toHaveBeenCalledWith(
        '[push] unique violation',
        'checklists_template_instance_uniq_v3',
        'Key (template_id, ...)=(tmpl-skip, ...) already exists.',
      )
    } finally {
      warn.mockRestore()
    }
  })

  it('maps a deadlock (40P01) from the split to a PushConflictError too', async () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {})
    try {
      const fake = fakePostgres({
        pushChecklistRows: [splitPushRow],
        pushItemRows: splitPushItems,
        failOn: {
          pattern: /^update checklist_items set checklist_id/i,
          error: Object.assign(new Error('deadlock detected'), { code: '40P01' }),
        },
      })
      await expect(
        postgresStore(fake).pushChecklistInstance('cl-mixed', 'emp-1', '2026-09-30'),
      ).rejects.toBeInstanceOf(PushConflictError)
      expect(fake.matching(/^rollback$/i)).toHaveLength(1)
      expect(fake.matching(/^commit$/i)).toHaveLength(0)
      // Not a unique violation: nothing to log about a constraint.
      expect(warn).not.toHaveBeenCalled()
    } finally {
      warn.mockRestore()
    }
  })

  it('refuses the completed record a split left behind - no write, one rollback (Postgres)', async () => {
    const fake = fakePostgres({
      pushChecklistRows: [{ ...splitPushRow, pushed_to_checklist_id: 'cl-live' }],
      // One step was un-checked, so a naive count would call this pushable.
      pushItemRows: splitPushItems,
    })
    const pushing = postgresStore(fake).pushChecklistInstance('cl-mixed', 'emp-1', '2026-09-30')
    await expect(pushing).rejects.toBeInstanceOf(PushedRecordError)
    await expect(pushing).rejects.toThrow(
      'This is the completed record of a pushed checklist. Push the live copy instead.',
    )
    expect(fake.matching(/^begin$/i)).toHaveLength(1)
    expect(fake.matching(/^rollback$/i)).toHaveLength(1)
    expect(fake.matching(/^commit$/i)).toHaveLength(0)
    expect(fake.matching(/^update checklists\b/i)).toHaveLength(0)
    expect(fake.matching(/^insert into checklists\b/i)).toHaveLength(0)
    // Refused straight after the lock: the items were never even read.
    expect(fake.matching(/^select id, checklist_id, label/i)).toHaveLength(0)
  })

  it('inserts the occurrence date as the to_char string even when the column parses to a Date', async () => {
    // node-postgres hands a `date` column back as a LOCAL-midnight Date. Re-
    // binding it can land on the neighboring day when Node is not in UTC, so the
    // split must use the string the lock select formatted in SQL.
    const localMidnightPriorDay = new Date(2026, 7, 30) // Aug 30 local: the shifted day
    const fake = fakePostgres({
      pushChecklistRows: [
        { ...splitPushRow, cycle_due_date: localMidnightPriorDay, identity_date: '2026-08-31' },
      ],
      pushItemRows: splitPushItems,
    })
    await postgresStore(fake).pushChecklistInstance('cl-mixed', 'emp-1', '2026-09-30')

    const [pushed] = insertedRows(fake.statements, 'checklists')
    expect(pushed.cycle_due_date).toBe('2026-08-31')
    expect(Object.values(pushed).some((value) => value instanceof Date)).toBe(false)
  })

  it('locks the sub-step waiter rows it rewrites (for update)', async () => {
    const fake = fakePostgres({
      pushChecklistRows: [splitPushRow],
      pushItemRows: splitPushItems,
    })
    await postgresStore(fake).pushChecklistInstance('cl-mixed', 'emp-1', '2026-09-30')
    const [waiters] = fake.matching(/^select id, sub_items from checklist_items/i)
    expect(waiters.text).toMatch(/position\(\$1 in sub_items::text\) > 0\s+for update$/i)
  })

  it('re-points pending requests: moved steps and task-level edits follow, stayed steps do not', async () => {
    const fake = fakePostgres({
      pushChecklistRows: [splitPushRow],
      pushItemRows: splitPushItems,
    })
    await postgresStore(fake).pushChecklistInstance('cl-mixed', 'emp-1', '2026-09-30')

    const newId = insertedRows(fake.statements, 'checklists')[0].id
    const [deletions] = fake.matching(/^update item_deletion_requests\b/i)
    expect(deletions.text).toMatch(/set checklist_id = \$1/i)
    expect(deletions.text).toMatch(/item_id = any\(\$3::text\[\]\)/i)
    // Only the OPEN step's id is offered; the done step stays where it is.
    expect(deletions.params).toEqual([newId, 'cl-mixed', ['item-open']])

    const [edits] = fake.matching(/^update pending_task_edits\b/i)
    expect(edits.text).toMatch(/set checklist_id = \$1/i)
    expect(edits.text).toMatch(/scope in \('details', 'add_item'\)/i)
    expect(edits.text).toMatch(/item_id = any\(\$3::text\[\]\)/i)
    expect(edits.params).toEqual([newId, 'cl-mixed', ['item-open']])
  })

  it('re-points waits elsewhere: the step column in SQL, sub-step waits inside sub_items', async () => {
    const fake = fakePostgres({
      pushChecklistRows: [splitPushRow],
      pushItemRows: splitPushItems,
      subWaiterRows: [
        {
          id: 'w-parent',
          sub_items: [
            {
              id: 'w-sub',
              title: 'Sub',
              waiting: true,
              waitingForChecklistId: 'cl-mixed',
              subItems: [
                { id: 'w-subsub', title: 'SubSub', waiting: true, waitingForChecklistId: 'cl-mixed' },
                { id: 'w-other', title: 'Other', waiting: true, waitingForChecklistId: 'cl-else' },
              ],
            },
          ],
        },
        // Mentions the id in some other field: nothing to re-point, no write.
        { id: 'w-noop', sub_items: [{ id: 'n1', title: 'cl-mixed in a title', done: false }] },
      ],
    })
    await postgresStore(fake).pushChecklistInstance('cl-mixed', 'emp-1', '2026-09-30')

    const newId = insertedRows(fake.statements, 'checklists')[0].id
    const [waits] = fake.matching(/^update checklist_items set waiting_for_checklist_id/i)
    expect(waits.params).toEqual([newId, 'cl-mixed'])

    const subWrites = fake.matching(/^update checklist_items set sub_items/i)
    expect(subWrites).toHaveLength(1)
    expect(subWrites[0].params[0]).toBe('w-parent')
    const written = JSON.parse(subWrites[0].params[1])
    expect(written[0].waitingForChecklistId).toBe(newId)
    expect(written[0].subItems[0].waitingForChecklistId).toBe(newId)
    expect(written[0].subItems[1].waitingForChecklistId).toBe('cl-else')
  })

  it('files a ONE-OFF push with a null template_id — the column is nullable', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).createChecklistSkip({
      checklistId: 'cl-oneoff',
      templateId: null,
      clientId: 'c1',
      title: 'Clean up the 2025 books',
      skippedBy: 'emp-1',
      skippedByName: 'Lisa Chen',
      reasonCategory: 'client',
      reasonNote: 'They have not sent the statements yet.',
      kind: 'push',
      newDueDate: '2026-09-30',
    })

    const [statement] = fake.matching(/insert into checklist_skips/i)
    expect(statement).toBeTruthy()
    // params: id, checklist_id, template_id, client_id, ...
    expect(statement.params[2]).toBeNull()
    expect(statement.params).toContain('push')
    expect(statement.params).toContain('2026-09-30')
  })

  it('files the push on the same trail, with its kind and its new date', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).createChecklistSkip({
      checklistId: 'cl-1',
      title: 'Monthly close',
      reasonCategory: 'client',
      reasonNote: 'Statements are late.',
      kind: 'push',
      newDueDate: '2026-09-30',
    })

    const [statement] = fake.matching(/insert into checklist_skips/i)
    expect(statement.text).toMatch(/kind, new_due_date/i)
    expect(statement.params).toContain('push')
    expect(statement.params).toContain('2026-09-30')
  })

  it('keys the duplicate backstop on the CYCLE date, replacing the old index', async () => {
    const fake = fakePostgres()
    // `initialize()` runs the whole DDL and then seeds users, which the fake
    // cannot answer (it returns no rows for a count). The DDL is long finished
    // by then and every statement is already recorded, so the seed's failure is
    // swallowed rather than worked around with a richer fake.
    await postgresStore(fake)
      .initialize()
      .catch(() => {})

    const [created] = fake.matching(/create unique index if not exists checklists_template_instance_uniq_v2/i)
    expect(created).toBeTruthy()
    // An index on `due_date` would refuse the default push — which lands on
    // exactly the next occurrence's date — and would stop recognizing the cycle
    // the pushed row came from.
    expect(created.text).toMatch(
      /on checklists \(template_id, coalesce\(cycle_due_date, due_date\), stage_index\)/i,
    )
    expect(created.text).toMatch(/where deleted_at is null and template_id is not null/i)

    // The old one goes, but only AFTER the new one exists — so a database too
    // dirty to build v2 keeps a backstop instead of ending up with none.
    const [dropped] = fake.matching(/^drop index if exists checklists_template_instance_uniq$/i)
    expect(dropped).toBeTruthy()
    expect(fake.statements.indexOf(created)).toBeLessThan(fake.statements.indexOf(dropped))
  })

  it('does not rebuild the v2 instance index once v3 exists, and still swaps v2 away', async () => {
    const fake = fakePostgres({ checklistIndexV3Exists: true })
    await postgresStore(fake)
      .initialize()
      .catch(() => {})

    expect(fake.matching(/to_regclass\('checklists_template_instance_uniq_v3'\)/i)).toHaveLength(1)
    expect(fake.matching(/create unique index if not exists checklists_template_instance_uniq_v2/i)).toEqual([])
    expect(fake.matching(/^drop index if exists checklists_template_instance_uniq$/i)).toEqual([])
    // A boot that died between the two swaps left v2 beside v3: v3's own swap
    // still removes it.
    expect(fake.matching(/^drop index if exists checklists_template_instance_uniq_v2$/i)).toHaveLength(1)
  })

  it('runs the v2 block only after the probe says v3 is missing', async () => {
    const fake = fakePostgres()
    await postgresStore(fake)
      .initialize()
      .catch(() => {})

    const probeAt = fake.indexOf(/to_regclass\('checklists_template_instance_uniq_v3'\)/i)
    const v2At = fake.indexOf(/create unique index if not exists checklists_template_instance_uniq_v2/i)
    expect(probeAt).toBeGreaterThan(-1)
    expect(v2At).toBeGreaterThan(probeAt)
  })

  it('reads cycle_due_date / pushed_at / pushed_by back out of checklists', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).read()

    const [statement] = fake.matching(/^select id, title, client_id[\s\S]*from checklists/i)
    expect(statement).toBeTruthy()
    // The file backend cannot see this, and it is the path that would erase
    // every push in silence: a column missing from the READ comes back to the
    // owner's tab as undefined and goes straight back down the bulk save as
    // null. Losing `cycle_due_date` hands the row to the materializer under
    // the WRONG identity and respawns the cycle it was pushed out of.
    expect(statement.text).toMatch(/cycle_due_date, pushed_at, pushed_by/i)
    // Same failure mode for the split link (featreq-fbab3370): missing it from
    // the read loses the hand-off the moment the row round-trips.
    expect(statement.text).toMatch(/pushed_from_checklist_id, pushed_to_checklist_id/i)
  })

  it('writes the STORED cycle_due_date / pushed_at / pushed_by through the bulk save', async () => {
    const fake = fakePostgres({
      priorChecklistRows: [
        {
          id: 'cl-1',
          cycle_due_date: '2026-08-31',
          pushed_at: '2026-08-20T10:00:00.000Z',
          pushed_by: 'emp-1',
        },
      ],
    })
    await postgresStore(fake).write(
      workspace({
        checklists: [
          {
            id: 'cl-1',
            title: 'Monthly close',
            clientId: 'c1',
            assigneeId: 'emp-1',
            dueDate: '2026-09-30',
            items: [],
            // What a stale tab hands back: a cycle date that is not this row's
            // and no stamps at all.
            cycleDueDate: '2026-12-31',
          },
        ],
      }),
    )

    // The snapshot has to be taken BEFORE the wipe, or there is nothing left to
    // preserve from.
    const snapshotAt = fake.indexOf(
      /^select id, cycle_due_date, pushed_at, pushed_by, pushed_from_checklist_id, pushed_to_checklist_id from checklists$/i,
    )
    expect(snapshotAt).toBeGreaterThan(-1)
    expect(snapshotAt).toBeLessThan(fake.indexOf(/^delete from checklists$/i))

    const [statement] = fake.matching(/insert into checklists \(/i)
    const [stored] = insertedRows(fake.statements, 'checklists')
    expect(statement.text).toMatch(/cycle_due_date, pushed_at, pushed_by/i)
    // `cycle_due_date` is the row's identity and the insert is `on conflict do
    // nothing`: a payload's wrong cycle date does not merely lose a stamp, it
    // collides on the unique index and drops the checklist AND all of its items
    // with only a warn. So the payload's copy is ignored outright.
    expect(stored.cycle_due_date).toBe('2026-08-31')
    expect(stored.pushed_at).toBe('2026-08-20T10:00:00.000Z')
    expect(stored.pushed_by).toBe('emp-1')
    expect(Object.values(stored)).not.toContain('2026-12-31')
  })

  it('writes the STORED pushedFromChecklistId / pushedToChecklistId through the bulk save', async () => {
    const fake = fakePostgres({
      priorChecklistRows: [
        {
          id: 'cl-split',
          cycle_due_date: '2026-08-31',
          pushed_at: '2026-08-20T10:00:00.000Z',
          pushed_by: 'emp-1',
          pushed_from_checklist_id: 'cl-original',
          pushed_to_checklist_id: null,
        },
      ],
    })
    await postgresStore(fake).write(
      workspace({
        checklists: [
          {
            id: 'cl-split',
            title: 'Monthly close',
            clientId: 'c1',
            assigneeId: 'emp-1',
            dueDate: '2026-09-30',
            items: [],
            // A stale tab carries none of this — the split link is
            // endpoint-owned, like the push stamps above.
          },
        ],
      }),
    )

    const [statement] = fake.matching(/insert into checklists \(/i)
    expect(statement.text).toMatch(/pushed_from_checklist_id, pushed_to_checklist_id/i)
    expect(insertedRows(fake.statements, 'checklists')[0].pushed_from_checklist_id).toBe('cl-original')
  })

  it('carries skipped_at / skipped_by through the bulk save', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).write(
      workspace({
        checklists: [
          {
            id: 'cl-1',
            title: 'Monthly close',
            clientId: 'c1',
            assigneeId: 'emp-1',
            dueDate: '2026-08-31',
            items: [],
            skippedAt: '2026-08-14T10:00:00.000Z',
            skippedBy: 'emp-1',
          },
        ],
      }),
    )

    const [statement] = fake.matching(/insert into checklists \(/i)
    expect(statement.text).toMatch(/skipped_at, skipped_by/i)
    expect(insertedRows(fake.statements, 'checklists')[0].skipped_at).toBe('2026-08-14T10:00:00.000Z')
  })

  it('carries skip_allowed through the bulk save, defaulting to false', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).write(
      workspace({
        checklistTemplates: [
          {
            id: 'tmpl-a',
            title: 'On',
            clientId: 'c1',
            assigneeId: 'emp-1',
            frequency: 'monthly',
            nextDueDate: '2026-08-31',
            active: true,
            skipAllowed: true,
            stages: [],
          },
          {
            id: 'tmpl-b',
            title: 'Unset',
            clientId: 'c1',
            assigneeId: 'emp-1',
            frequency: 'monthly',
            nextDueDate: '2026-08-31',
            active: true,
            stages: [],
          },
        ],
      }),
    )

    expect(fake.matching(/insert into checklist_templates/i)[0].text).toMatch(/skip_allowed/i)
    // Read by COLUMN NAME, not by counting from the end: `params.at(-2)` once
    // quietly meant "skip_allowed is the second-to-last column" until two more
    // columns were added after it and the assertion read the wrong one.
    const inserts = insertedRows(fake.statements, 'checklist_templates')
    expect(inserts).toHaveLength(2)

    // Anything other than an explicit true is off — skipping is opt-in.
    expect(inserts[0].skip_allowed).toBe(true)
    expect(inserts[1].skip_allowed).toBe(false)
    // The period label is opt-in the same way, and its window is null until
    // she picks the dates.
    expect(inserts[0].period_label_enabled).toBe(false)
    expect(inserts[0].period_coverage_start).toBeNull()
    expect(inserts[0].period_coverage_end).toBeNull()
  })
})

/**
 * Ad hoc time and the ad hoc invoice line — the persistence half of
 * featreq-d0f2da14.
 *
 * The flag decides HOW a piece of time bills (its own line, at the employee's
 * rate, instead of inside the month's hours), so a backend that quietly drops
 * it changes money. Cardinal rule 1 applies in full: the file-backend contracts
 * are below, and the Postgres statement shapes are pinned underneath them,
 * because CI only ever runs the file branch.
 */
describe('ad hoc time entries (file backend)', () => {
  it('persists the flag and reads it back', async () => {
    const created = await store.createTimeEntry({
      employeeId: 'emp-1',
      clientId: 'c1',
      date: '2026-08-04',
      minutes: 30,
      description: 'Rush 1099 question',
      billable: true,
      isAdhoc: true,
      entryMethod: 'manual',
      manualReason: 'forgot the timer',
    })

    expect(created.isAdhoc).toBe(true)
    expect((await store.getTimeEntry(created.id)).isAdhoc).toBe(true)
    expect((await store.read()).timeEntries.find((e) => e.id === created.id).isAdhoc).toBe(true)
  })

  // Postgres has `not null default false`, so an entry logged without the flag
  // reads back as `false` there. The file backend has to say the same thing, or
  // a test passes on data production would never produce.
  it('stores a real false rather than nothing when the flag is not set', async () => {
    const created = await store.createTimeEntry({
      employeeId: 'emp-1',
      clientId: 'c1',
      date: '2026-08-04',
      minutes: 30,
      description: 'Scoped work',
      billable: true,
      entryMethod: 'timer',
    })
    expect(created.isAdhoc).toBe(false)
    expect((await store.getTimeEntry(created.id)).isAdhoc).toBe(false)
  })

  // The owner's backstop at review: flagging one that was missed, and taking
  // the flag off one that should never have had it.
  it('lets an update set and clear the flag', async () => {
    const created = await store.createTimeEntry({
      employeeId: 'emp-1',
      clientId: 'c1',
      date: '2026-08-04',
      minutes: 30,
      description: 'Scoped work',
      billable: true,
      entryMethod: 'timer',
    })

    expect((await store.updateTimeEntry(created.id, { isAdhoc: true })).isAdhoc).toBe(true)
    expect((await store.updateTimeEntry(created.id, { isAdhoc: false })).isAdhoc).toBe(false)
  })

  it('carries the flag onto every slice when the time is split across clients', async () => {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.clients = [
      { id: 'c1', name: 'Acme' },
      { id: 'c2', name: 'Beta' },
    ]
    data.timeEntries = [
      {
        id: 't-adhoc',
        employeeId: 'emp-1',
        clientId: 'c1',
        date: '2026-08-04',
        minutes: 60,
        description: 'One-off cleanup for two clients',
        billable: true,
        isAdhoc: true,
        approvalStatus: 'approved',
        entryMethod: 'timer',
        sessions: [],
      },
    ]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))

    const { created } = await store.splitTimeEntry(
      't-adhoc',
      [
        { clientId: 'c1', minutes: 30 },
        { clientId: 'c2', minutes: 30 },
      ],
      'emp-1',
      'grp-1',
      'even',
    )

    expect(created).toHaveLength(2)
    expect(created.every((slice) => slice.isAdhoc === true)).toBe(true)
  })
})

describe('ad hoc invoice lines (file backend)', () => {
  async function seedAdhocInvoice() {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices = [
      {
        id: 'inv-adhoc',
        clientId: 'c1',
        period: '2026-08',
        number: 'INV-2026-08-002',
        status: 'draft',
        lineItems: [
          { kind: 'hourly', label: 'Billable hours — Lisa', detail: '', amount: 200 },
          {
            kind: 'adhoc',
            label: 'Adhoc — Rush 1099 question',
            detail: 'Aug 4, 2026 · Lisa · 0.50h at $100.00/hr',
            amount: 50,
            adhocMode: 'billed',
            adhocAmount: 50,
          },
        ],
        subtotal: 250,
        total: 250,
        dueDate: '2026-09-30',
        blurb: '',
        scopeFlags: [],
        sentAt: null,
        paidAt: null,
        paymentMethod: null,
        createdAt: '2026-09-01T00:00:00.000Z',
        updatedAt: '2026-09-01T00:00:00.000Z',
      },
    ]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
  }

  it('keeps the kind and the choice through a save', async () => {
    await seedAdhocInvoice()
    const updated = await store.updateInvoice('inv-adhoc', {
      lineItems: [
        { kind: 'hourly', label: 'Billable hours — Lisa', detail: '', amount: 200 },
        {
          kind: 'adhoc',
          label: 'Adhoc — Rush 1099 question',
          detail: '',
          amount: 50,
          adhocMode: 'billed',
          adhocAmount: 50,
        },
      ],
    })

    expect(updated.lineItems[1]).toMatchObject({
      kind: 'adhoc',
      adhocMode: 'billed',
      adhocAmount: 50,
      amount: 50,
    })
    expect(updated.total).toBe(250)
  })

  // "Show detail only" — the line stays on the client's invoice, at nothing.
  it('zeroes a courtesy line and drops it out of the total', async () => {
    await seedAdhocInvoice()
    const updated = await store.updateInvoice('inv-adhoc', {
      lineItems: [
        { kind: 'hourly', label: 'Billable hours — Lisa', detail: '', amount: 200 },
        {
          kind: 'adhoc',
          label: 'Adhoc — Rush 1099 question',
          detail: '',
          amount: 50,
          adhocMode: 'courtesy',
          adhocAmount: 50,
        },
      ],
    })

    expect(updated.lineItems[1].amount).toBe(0)
    // Held in reserve, which is what makes the choice reversible.
    expect(updated.lineItems[1].adhocAmount).toBe(50)
    expect(updated.total).toBe(200)
  })

  // An omitted line is worth nothing and still has to SURVIVE, or she could
  // never put it back.
  it('keeps an omitted line on the draft at zero', async () => {
    await seedAdhocInvoice()
    const updated = await store.updateInvoice('inv-adhoc', {
      lineItems: [
        { kind: 'hourly', label: 'Billable hours — Lisa', detail: '', amount: 200 },
        {
          kind: 'adhoc',
          label: 'Adhoc — Rush 1099 question',
          detail: '',
          amount: 0,
          adhocMode: 'omitted',
          adhocAmount: 50,
        },
      ],
    })

    expect(updated.lineItems).toHaveLength(2)
    expect(updated.lineItems[1]).toMatchObject({ adhocMode: 'omitted', amount: 0, adhocAmount: 50 })
    expect(updated.total).toBe(200)
  })

  // She overtyped the figure. The reserve follows it, so flipping the line to
  // courtesy and back gives her number back rather than the rate calculation's.
  it('lets the owner overtype a billed amount, and remembers it', async () => {
    await seedAdhocInvoice()
    const overtyped = await store.updateInvoice('inv-adhoc', {
      lineItems: [
        {
          kind: 'adhoc',
          label: 'Adhoc — Rush 1099 question',
          detail: '',
          amount: 40,
          adhocMode: 'billed',
          adhocAmount: 50,
        },
      ],
    })
    expect(overtyped.lineItems[0]).toMatchObject({ amount: 40, adhocAmount: 40 })
  })

  // The line at $0.00 is $0.00 BY DECISION and still holds what it would
  // charge. Resting its survival on the label alone meant clearing that box
  // deleted the reserve for good.
  it('keeps a courtesy line whose label was cleared', async () => {
    await seedAdhocInvoice()
    const updated = await store.updateInvoice('inv-adhoc', {
      lineItems: [
        { kind: 'adhoc', label: '', detail: '', amount: 0, adhocMode: 'courtesy', adhocAmount: 50 },
      ],
    })

    expect(updated.lineItems).toHaveLength(1)
    expect(updated.lineItems[0].adhocAmount).toBe(50)
  })

  // ...but a genuinely empty row still goes, adhoc or not.
  it('still drops an adhoc row with nothing on it at all', async () => {
    await seedAdhocInvoice()
    const updated = await store.updateInvoice('inv-adhoc', {
      lineItems: [
        { kind: 'hourly', label: 'Billable hours — Lisa', detail: '', amount: 200 },
        { kind: 'adhoc', label: '', detail: '', amount: 0, adhocMode: 'omitted', adhocAmount: 0 },
      ],
    })

    expect(updated.lineItems).toHaveLength(1)
  })

  it('reads a line with no stated choice as billed', async () => {
    await seedAdhocInvoice()
    const updated = await store.updateInvoice('inv-adhoc', {
      lineItems: [{ kind: 'adhoc', label: 'Adhoc — legacy', detail: '', amount: 25 }],
    })
    expect(updated.lineItems[0]).toMatchObject({ adhocMode: 'billed', amount: 25, adhocAmount: 25 })
  })
})

describe('ad hoc time on the postgres branch', () => {
  it('writes is_adhoc on create', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).createTimeEntry({
      employeeId: 'emp-1',
      clientId: 'c1',
      date: '2026-08-04',
      minutes: 30,
      description: 'Rush 1099 question',
      billable: true,
      isAdhoc: true,
      entryMethod: 'timer',
    })

    expect(fake.matching(/insert into time_entries/i)[0].text).toMatch(/is_administrative,\s*is_adhoc/i)
    const inserts = insertedRows(fake.statements, 'time_entries')
    expect(inserts).toHaveLength(1)
    // Read by column. `toContain(true)` would pass on the fixture's
    // `billable: true` no matter where the flag actually landed.
    expect(inserts[0].is_adhoc).toBe(true)
  })

  it('writes is_adhoc on the bulk save, defaulting to false', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).write(
      workspace({
        timeEntries: [
          {
            id: 't1',
            employeeId: 'emp-1',
            clientId: 'c1',
            date: '2026-08-04',
            minutes: 30,
            isAdhoc: true,
          },
          {
            id: 't2',
            employeeId: 'emp-1',
            clientId: 'c1',
            date: '2026-08-05',
            minutes: 30,
          },
        ],
      }),
    )

    expect(fake.matching(/insert into time_entries/i)[0].text).toMatch(/is_administrative,\s*\n?\s*is_adhoc/i)
    const inserts = insertedRows(fake.statements, 'time_entries')
    expect(inserts).toHaveLength(2)
    // Read by column — the bug this catches is a value landing in the wrong
    // column when someone adds the next one.
    expect(inserts[0].is_adhoc).toBe(true)
    expect(inserts[1].is_adhoc).toBe(false)
  })

  it('sets is_adhoc when an update carries it', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).updateTimeEntry('t1', { isAdhoc: true })

    const updates = fake.matching(/update time_entries set/i)
    expect(updates).toHaveLength(1)
    expect(updates[0].text).toMatch(/is_adhoc = \$2/)
    expect(updates[0].params).toEqual(['t1', true])
  })
})

/**
 * Retainers — the invoice at the start of an engagement, and the credit that
 * gives it back at the end.
 *
 * Two invariants live here, and both are about a SECOND ROW rather than about
 * arithmetic (the arithmetic is pinned in lib/retainer-invoicing.test.mjs):
 *
 *   1. The unique index learned kinds. It used to say "one live invoice per
 *      (client, period)", which would have refused a retainer issued in a month
 *      the client already had an invoice for — and `_insertInvoice` reads a
 *      refusal as "someone else got there first", so it would have been silent.
 *   2. A retainer can be spent ONCE. The fact lives on the retainer row
 *      (`appliedToInvoiceId`), set and cleared by the save that adds or removes
 *      the credit line, so there is no window where the two disagree.
 */
describe('retainer invoices (file backend)', () => {
  const period = '2026-08'

  async function seedClients() {
    await store.write(
      workspace({
        clients: [
          {
            id: 'c1',
            name: 'Acme',
            billingMode: 'hourly',
            hourlyRate: 100,
            paymentTerms: 'Net 30',
          },
          { id: 'c2', name: 'Globex', billingMode: 'hourly', hourlyRate: 100 },
        ],
        timeEntries: [],
      }),
    )
  }

  async function storedInvoices() {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    return data.invoices ?? []
  }

  it('issues a draft with its own kind, number and line', async () => {
    await seedClients()
    const retainer = await store.createRetainerInvoice({
      clientId: 'c1',
      amount: 2500,
      note: 'Signed 2026-08-12',
      period,
    })

    expect(retainer).toMatchObject({
      clientId: 'c1',
      period,
      kind: 'retainer',
      status: 'draft',
      number: 'INV-RET-2026-001',
      subtotal: 2500,
      total: 2500,
      appliedToInvoiceId: null,
    })
    expect(retainer.lineItems).toEqual([
      { kind: 'retainer', label: 'Retainer', detail: 'Signed 2026-08-12', amount: 2500 },
    ])
  })

  // The default path is untouched by "record only": still a draft, nothing paid,
  // nothing sent, no audit event.
  it('leaves a default retainer a draft with no payment fields and no audit event', async () => {
    await seedClients()
    const retainer = await store.createRetainerInvoice({
      clientId: 'c1',
      amount: 2500,
      period,
      actorUserId: 'owner-1',
    })
    expect(retainer).toMatchObject({
      status: 'draft',
      sentAt: null,
      paidAt: null,
      paymentMethod: null,
    })
    expect(await store.listUnappliedRetainers()).toHaveLength(0)
    expect(await store.listInvoiceReviewEvents({ invoiceId: retainer.id })).toHaveLength(0)
  })

  // featreq-9d3721d4: a retainer already invoiced and paid OUTSIDE the app is
  // recorded directly as paid, so it is saved, visible and creditable later.
  it('records a retainer as already paid with recordOnly, creditable and audited', async () => {
    await seedClients()
    const retainer = await store.createRetainerInvoice({
      clientId: 'c1',
      amount: 2500,
      note: 'Paid by check in June',
      period,
      recordOnly: true,
      actorUserId: 'owner-1',
    })

    expect(retainer).toMatchObject({
      clientId: 'c1',
      kind: 'retainer',
      status: 'paid',
      paymentMethod: 'manual',
      total: 2500,
      appliedToInvoiceId: null,
    })
    expect(typeof retainer.paidAt).toBe('string')
    expect(typeof retainer.sentAt).toBe('string')

    // What was stored is the same record.
    const stored = (await storedInvoices()).find((invoice) => invoice.id === retainer.id)
    expect(stored).toMatchObject({ status: 'paid', paymentMethod: 'manual' })
    expect(stored.paidAt).toBe(retainer.paidAt)
    expect(stored.sentAt).toBe(retainer.sentAt)

    // Money on hand: the month run can offer it as a credit.
    const unapplied = await store.listUnappliedRetainers()
    expect(unapplied.map((invoice) => invoice.id)).toEqual([retainer.id])

    // One audit row, naming who recorded it.
    const events = await store.listInvoiceReviewEvents({ invoiceId: retainer.id })
    expect(events).toHaveLength(1)
    expect(events[0]).toMatchObject({
      event: 'retainer_recorded_paid',
      actorUserId: 'owner-1',
      clientId: 'c1',
      changes: { status: { before: null, after: 'paid' } },
    })
  })

  // A retainer paid by check in June must read June, not the month it was typed in.
  it('dates a recorded retainer to the day it was paid: stamps, period, due date', async () => {
    await seedClients()
    const retainer = await store.createRetainerInvoice({
      clientId: 'c1',
      amount: 1200,
      recordOnly: true,
      paidOn: '2026-06-10',
      actorUserId: 'owner-1',
    })
    expect(retainer).toMatchObject({
      status: 'paid',
      paymentMethod: 'manual',
      period: '2026-06',
      dueDate: '2026-07-10',
    })
    expect(retainer.paidAt.slice(0, 10)).toBe('2026-06-10')
    expect(retainer.sentAt.slice(0, 10)).toBe('2026-06-10')
    expect((await store.listUnappliedRetainers()).map((invoice) => invoice.id)).toEqual([
      retainer.id,
    ])
  })

  it('refuses a paid-on date in the future, before the floor, or that is not a date', async () => {
    await seedClients()
    // 0202 is what a date field emits while a year is being typed.
    for (const paidOn of ['2099-01-01', '2026-13-45', 'last June', '0202-06-10', '1999-12-31']) {
      expect(
        await store.createRetainerInvoice({ clientId: 'c1', amount: 500, recordOnly: true, paidOn }),
      ).toBeNull()
    }
    expect(await storedInvoices()).toHaveLength(0)
  })

  it('ignores paidOn on an ordinary issue: still a draft in the current month', async () => {
    await seedClients()
    const retainer = await store.createRetainerInvoice({
      clientId: 'c1',
      amount: 500,
      paidOn: '2026-06-10',
    })
    expect(retainer).toMatchObject({ status: 'draft', paidAt: null, sentAt: null })
    expect(retainer.period).not.toBe('2026-06')
  })

  // Undo would move a recorded retainer to 'sent' - a state that never happened.
  it('refuses to undo the manual payment of a retainer that was recorded, never sent', async () => {
    await seedClients()
    const retainer = await store.createRetainerInvoice({
      clientId: 'c1',
      amount: 500,
      recordOnly: true,
      period,
    })
    await expect(store.unmarkManualInvoicePayment(retainer.id, {})).rejects.toThrow(
      'This retainer was recorded as paid outside the app - void it instead.',
    )
    const stored = (await storedInvoices()).find((invoice) => invoice.id === retainer.id)
    expect(stored).toMatchObject({ status: 'paid', paymentMethod: 'manual' })
  })

  // featreq-22de88a5: a retainer recorded as paid outside the app is already in
  // QuickBooks, so it carries a durable marker the QBO export reads.
  it('marks a recorded retainer as recorded outside the app, and nothing else', async () => {
    await seedClients()
    const recorded = await store.createRetainerInvoice({
      clientId: 'c1',
      amount: 500,
      recordOnly: true,
      period,
    })
    const ordinary = await store.createRetainerInvoice({ clientId: 'c1', amount: 700, period })
    expect(recorded.recordedOutsideApp).toBe(true)
    expect(ordinary.recordedOutsideApp).toBe(false)

    const stored = await storedInvoices()
    expect(stored.find((invoice) => invoice.id === recorded.id).recordedOutsideApp).toBe(true)
    expect(stored.find((invoice) => invoice.id === ordinary.id).recordedOutsideApp).toBe(false)

    // Reading back answers the same boolean, and an ordinary paid-by-hand
    // retainer does not pick the marker up.
    await store.markInvoicePaidManually(ordinary.id, {})
    const listed = await store.listInvoices()
    expect(listed.find((invoice) => invoice.id === recorded.id).recordedOutsideApp).toBe(true)
    expect(listed.find((invoice) => invoice.id === ordinary.id).recordedOutsideApp).toBe(false)
  })

  it('answers recordedOutsideApp false for a stored invoice written before the marker existed', async () => {
    await seedClients()
    const retainer = await store.createRetainerInvoice({ clientId: 'c1', amount: 500, period })
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    delete data.invoices[0].recordedOutsideApp
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
    const listed = await store.listInvoices()
    expect(listed.find((invoice) => invoice.id === retainer.id).recordedOutsideApp).toBe(false)
  })

  // The marker is the fact; the sent-but-never-emailed heuristic is only the
  // fallback for rows recorded before the column existed.
  it('refuses the undo on the marker alone, even when the log shows a send', async () => {
    await seedClients()
    const retainer = await store.createRetainerInvoice({
      clientId: 'c1',
      amount: 500,
      recordOnly: true,
      period,
    })
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices[0].emailLog = [
      { ok: true, to: ['a@b.co'], sentAt: '2026-06-11T00:00:00.000Z' },
    ]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
    await expect(store.unmarkManualInvoicePayment(retainer.id, {})).rejects.toThrow(
      'This retainer was recorded as paid outside the app - void it instead.',
    )
  })

  it('still refuses the undo on a recorded retainer that has no marker (recorded before the column)', async () => {
    await seedClients()
    const retainer = await store.createRetainerInvoice({
      clientId: 'c1',
      amount: 500,
      recordOnly: true,
      period,
    })
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    delete data.invoices[0].recordedOutsideApp
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
    await expect(store.unmarkManualInvoicePayment(retainer.id, {})).rejects.toThrow(
      'This retainer was recorded as paid outside the app - void it instead.',
    )
  })

  // Undo is only refused where it would restore a Sent that never happened.
  it('un-marks a draft retainer that was marked paid by hand, back to reviewed', async () => {
    await seedClients()
    const retainer = await store.createRetainerInvoice({ clientId: 'c1', amount: 500, period })
    expect(retainer.sentAt).toBeNull()
    await store.markInvoicePaidManually(retainer.id, {})
    const restored = await store.unmarkManualInvoicePayment(retainer.id, {})
    expect(restored.status).toBe('reviewed')
  })

  it('un-marks a never-email client retainer whose send was logged as not-emailed', async () => {
    await seedClients()
    const retainer = await store.createRetainerInvoice({
      clientId: 'c1',
      amount: 500,
      recordOnly: true,
      period,
    })
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    const stored = data.invoices.find((invoice) => invoice.id === retainer.id)
    // The fallback case: a row the heuristic reads, with no marker on it - this
    // is a never-email client's retainer, not one recorded outside the app.
    stored.recordedOutsideApp = false
    stored.emailLog = [
      { ok: true, kind: 'not-emailed', to: [], subject: '', at: '2026-08-01T00:00:00.000Z' },
    ]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
    const restored = await store.unmarkManualInvoicePayment(retainer.id, {})
    expect(restored.status).toBe('sent')
  })

  it('still lets a retainer that really was emailed be un-marked', async () => {
    await seedClients()
    const retainer = await store.createRetainerInvoice({
      clientId: 'c1',
      amount: 500,
      recordOnly: true,
      period,
    })
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    const stored = data.invoices.find((invoice) => invoice.id === retainer.id)
    // A retainer that was really emailed is not one recorded outside the app.
    stored.recordedOutsideApp = false
    stored.emailLog = [
      { ok: true, to: ['pat@acme.test'], sentAt: '2026-08-01T00:00:00.000Z' },
    ]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
    const restored = await store.unmarkManualInvoicePayment(retainer.id, {})
    expect(restored.status).toBe('sent')
  })

  it('still refuses an opted-out client or a bad amount when recording only', async () => {
    await store.write(
      workspace({
        clients: [
          { id: 'c1', name: 'Acme', billingMode: 'hourly', hourlyRate: 100, platformInvoicingOptOut: true },
        ],
        timeEntries: [],
      }),
    )
    expect(
      await store.createRetainerInvoice({ clientId: 'c1', amount: 500, recordOnly: true }),
    ).toBeNull()
    expect(
      await store.createRetainerInvoice({ clientId: 'c1', amount: 0, recordOnly: true }),
    ).toBeNull()
    expect(await storedInvoices()).toHaveLength(0)
  })

  it('refuses an amount that is not real money', async () => {
    await seedClients()
    expect(await store.createRetainerInvoice({ clientId: 'c1', amount: 0 })).toBeNull()
    expect(await store.createRetainerInvoice({ clientId: 'c1', amount: -50 })).toBeNull()
    expect(await store.createRetainerInvoice({ clientId: 'c1', amount: 'lots' })).toBeNull()
    expect(await store.createRetainerInvoice({ clientId: 'ghost', amount: 500 })).toBeNull()
    expect(await storedInvoices()).toHaveLength(0)
  })

  it('continues the retainer sequence across clients and months', async () => {
    await seedClients()
    await store.createRetainerInvoice({ clientId: 'c1', amount: 500, period: '2026-08' })
    const second = await store.createRetainerInvoice({
      clientId: 'c2',
      amount: 500,
      period: '2026-09',
    })
    expect(second.number).toBe('INV-RET-2026-002')
  })

  // The landmine. Before the index learned kinds this insert came back null and
  // the retainer simply never appeared.
  it('coexists with the same client monthly invoice for the same month', async () => {
    await seedClients()
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices = [
      {
        id: 'inv-monthly',
        clientId: 'c1',
        period,
        number: 'INV-2026-08-001',
        kind: 'monthly',
        status: 'draft',
        lineItems: [{ kind: 'hourly', label: 'Billable hours', detail: '', amount: 400 }],
        subtotal: 400,
        total: 400,
        dueDate: null,
        blurb: '',
        scopeFlags: [],
        sentAt: null,
        paidAt: null,
        paymentMethod: null,
        appliedToInvoiceId: null,
        createdAt: '2026-08-31T00:00:00.000Z',
        updatedAt: '2026-08-31T00:00:00.000Z',
      },
    ]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))

    const retainer = await store.createRetainerInvoice({ clientId: 'c1', amount: 2500, period })
    expect(retainer).not.toBeNull()
    expect(await storedInvoices()).toHaveLength(2)
  })

  // A second engagement is a second retainer. Nothing about them is unique.
  it('allows two live retainers for one client', async () => {
    await seedClients()
    expect(
      await store.createRetainerInvoice({ clientId: 'c1', amount: 500, period }),
    ).not.toBeNull()
    expect(
      await store.createRetainerInvoice({ clientId: 'c1', amount: 750, period }),
    ).not.toBeNull()
    expect(await storedInvoices()).toHaveLength(2)
  })

  // The other half of the same rule: MONTHLY invoices are still unique, and a
  // retainer in the month must not be mistaken for one.
  it('still refuses a second live monthly invoice, and builds one beside a retainer', async () => {
    await store.write(
      workspace({
        clients: [{ id: 'c1', name: 'Acme', billingMode: 'hourly', hourlyRate: 100 }],
        employees: [{ id: 'emp-1', name: 'Lisa', role: 'bookkeeper', billRate: 100 }],
        timeEntries: [
          {
            id: 't1',
            employeeId: 'emp-1',
            clientId: 'c1',
            date: '2026-08-04',
            minutes: 120,
            billable: true,
            approvalStatus: 'approved',
          },
        ],
      }),
    )
    await store.createRetainerInvoice({ clientId: 'c1', amount: 2500, period })

    // The retainer does not count as "already billed for August".
    const first = await store.generateInvoicesForPeriod(period)
    expect(first.created).toHaveLength(1)
    expect(first.created[0].kind).toBe('monthly')

    // ...but the monthly invoice it just made does.
    const second = await store.generateInvoicesForPeriod(period)
    expect(second.created).toHaveLength(0)
    expect(second.skipped).toEqual([{ clientId: 'c1', reason: 'already-generated' }])
  })

  // "Void & regenerate" only rebuilds MONTHLY invoices, so voiding a hand-issued
  // retainer would throw it away with nothing to put it back.
  it('leaves a draft retainer alone when the month is regenerated', async () => {
    await seedClients()
    const retainer = await store.createRetainerInvoice({ clientId: 'c1', amount: 2500, period })

    const result = await store.voidUnsentInvoicesForPeriod(period)

    expect(result.voided).toBe(0)
    expect((await store.listInvoices()).find((i) => i.id === retainer.id).status).toBe('draft')
  })

  it('reads a row written before the columns existed as an unapplied monthly invoice', async () => {
    await seedClients()
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices = [
      {
        id: 'inv-legacy',
        clientId: 'c1',
        period,
        number: 'INV-2026-08-001',
        status: 'sent',
        lineItems: [],
        subtotal: 0,
        total: 0,
      },
    ]
    await writeFile(localDataPath, JSON.stringify(data, null, 2))

    const [legacy] = await store.listInvoices()
    expect(legacy.kind).toBe('monthly')
    expect(legacy.appliedToInvoiceId).toBeNull()
  })
})

describe('applying a retainer credit (file backend)', () => {
  const period = '2026-08'
  const hoursLine = { kind: 'hourly', label: 'Billable hours', detail: '', amount: 600 }

  function invoiceRow(id, overrides = {}) {
    return {
      id,
      clientId: 'c1',
      period,
      number: id,
      kind: 'monthly',
      status: 'draft',
      lineItems: [{ ...hoursLine }],
      subtotal: 600,
      total: 600,
      dueDate: null,
      blurb: '',
      scopeFlags: [],
      sentAt: null,
      paidAt: null,
      paymentMethod: null,
      appliedToInvoiceId: null,
      createdAt: '2026-08-31T00:00:00.000Z',
      updatedAt: '2026-08-31T00:00:00.000Z',
      ...overrides,
    }
  }

  function retainerRow(overrides = {}) {
    return invoiceRow('inv-ret', {
      kind: 'retainer',
      number: 'INV-RET-2026-001',
      status: 'paid',
      period: '2026-01',
      lineItems: [{ kind: 'retainer', label: 'Retainer', detail: '', amount: 500 }],
      subtotal: 500,
      total: 500,
      ...overrides,
    })
  }

  /** The line the editor sends. Its amount is a PREVIEW — the server re-sizes it. */
  function creditLine(amount = -500, retainerInvoiceId = 'inv-ret') {
    return {
      kind: 'retainer_credit',
      label: 'Retainer applied — credit',
      detail: 'Retainer INV-RET-2026-001',
      amount,
      retainerInvoiceId,
    }
  }

  async function seed(rows) {
    await store.write(
      workspace({
        clients: [
          { id: 'c1', name: 'Acme', billingMode: 'hourly', hourlyRate: 100 },
          { id: 'c2', name: 'Globex', billingMode: 'hourly', hourlyRate: 100 },
        ],
        timeEntries: [],
      }),
    )
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices = rows
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
  }

  const byId = async (id) => (await store.listInvoices()).find((invoice) => invoice.id === id)

  it('records the application on the retainer, not just on the lines', async () => {
    await seed([retainerRow(), invoiceRow('inv-final')])

    const updated = await store.updateInvoice('inv-final', {
      lineItems: [{ ...hoursLine }, creditLine()],
    })

    expect(updated.total).toBe(100)
    // The subtotal is what the month was WORTH; the credit sits outside it.
    expect(updated.subtotal).toBe(600)
    expect((await byId('inv-ret')).appliedToInvoiceId).toBe('inv-final')
  })

  // featreq-9d3721d4 (send-back): the client page shows the retainer position,
  // so it asks for ONE client's retainers, whatever their status, with what each
  // was credited for.
  it('lists one client retainers with the credit each gave back, and nothing else', async () => {
    await seed([
      retainerRow({ recordedOutsideApp: true, paidAt: '2026-01-10T12:00:00.000Z' }),
      retainerRow({ id: 'inv-ret2', number: 'INV-RET-2026-002', status: 'sent', total: 250 }),
      retainerRow({ id: 'inv-void', number: 'INV-RET-2026-003', status: 'void' }),
      retainerRow({ id: 'inv-other', clientId: 'c2', number: 'INV-RET-2026-004' }),
      invoiceRow('inv-final'),
    ])
    await store.updateInvoice('inv-final', { lineItems: [{ ...hoursLine }, creditLine()] })

    const listed = await store.listClientRetainers('c1')
    expect(listed.map((row) => row.id)).toEqual(['inv-ret', 'inv-ret2'])
    expect(listed[0]).toMatchObject({
      number: 'INV-RET-2026-001',
      status: 'paid',
      total: 500,
      recordedOutsideApp: true,
      appliedToInvoiceId: 'inv-final',
      credit: {
        invoiceId: 'inv-final',
        number: 'inv-final',
        period: '2026-08',
        status: 'draft',
        amount: 500,
      },
    })
    expect(listed[1]).toMatchObject({ status: 'sent', total: 250, appliedToInvoiceId: null, credit: null })
    // Money rows only: no lines, no send log.
    expect(listed[0]).not.toHaveProperty('lineItems')
    expect(await store.listClientRetainers('nobody')).toEqual([])
  })

  // The credit is what the INVOICE could take, which can be less than the
  // retainer held; the position must report the line, not the retainer.
  it('lists a partial credit at the line amount, not the retainer total', async () => {
    await seed([
      retainerRow(),
      invoiceRow('inv-small', {
        lineItems: [{ ...hoursLine, amount: 300 }],
        subtotal: 300,
        total: 300,
      }),
    ])
    await store.updateInvoice('inv-small', {
      lineItems: [{ ...hoursLine, amount: 300 }, creditLine(-500)],
    })
    const [row] = await store.listClientRetainers('c1')
    expect(row.total).toBe(500)
    expect(row.credit).toMatchObject({ invoiceId: 'inv-small', status: 'draft', amount: 300 })
  })

  it('carries the target status, and drops the credit when that invoice is void', async () => {
    await seed([retainerRow(), invoiceRow('inv-final')])
    await store.updateInvoice('inv-final', { lineItems: [{ ...hoursLine }, creditLine()] })
    const withTarget = async (status) => {
      const data = JSON.parse(await readFile(localDataPath, 'utf8'))
      data.invoices.find((invoice) => invoice.id === 'inv-final').status = status
      await writeFile(localDataPath, JSON.stringify(data, null, 2))
      return (await store.listClientRetainers('c1'))[0]
    }
    expect((await withTarget('reviewed')).credit.status).toBe('reviewed')
    expect((await withTarget('sent')).credit.status).toBe('sent')
    const voided = await withTarget('void')
    expect(voided.credit).toBeNull()
  })

  // Rows recorded before the marker column exist have it false; the undo
  // refusal reads the older never-emailed-send heuristic, and so must this.
  it('reads a recorded row that predates the marker as recorded outside the app', async () => {
    await seed([
      retainerRow({ id: 'inv-old', sentAt: '2026-01-10T12:00:00.000Z', paidAt: '2026-01-10T12:00:00.000Z' }),
      retainerRow({
        id: 'inv-mailed',
        number: 'INV-RET-2026-002',
        sentAt: '2026-02-10T12:00:00.000Z',
        emailLog: [{ ok: true, to: ['a@b.co'], sentAt: '2026-02-10T12:00:00.000Z' }],
      }),
      retainerRow({ id: 'inv-hand', number: 'INV-RET-2026-003', sentAt: null }),
    ])
    const listed = await store.listClientRetainers('c1')
    const byNumber = Object.fromEntries(listed.map((row) => [row.id, row.recordedOutsideApp]))
    expect(byNumber).toEqual({ 'inv-old': true, 'inv-mailed': false, 'inv-hand': false })
  })

  it('is offered only while it is unspent', async () => {
    await seed([retainerRow(), invoiceRow('inv-final')])
    expect(await store.listUnappliedRetainers()).toHaveLength(1)

    await store.updateInvoice('inv-final', { lineItems: [{ ...hoursLine }, creditLine()] })

    expect(await store.listUnappliedRetainers()).toHaveLength(0)
  })

  it('a retainer that was only SENT is not on offer, and cannot be credited', async () => {
    await seed([retainerRow({ status: 'sent' }), invoiceRow('inv-final')])
    expect(await store.listUnappliedRetainers()).toHaveLength(0)

    await expect(
      store.updateInvoice('inv-final', { lineItems: [{ ...hoursLine }, creditLine()] }),
    ).rejects.toThrow(/not been paid/i)
  })

  // NEVER TWICE. The second invoice's save is refused outright rather than
  // quietly crediting money that has already been given back.
  it('refuses a second invoice trying to spend the same retainer', async () => {
    await seed([retainerRow(), invoiceRow('inv-final'), invoiceRow('inv-other')])
    await store.updateInvoice('inv-final', { lineItems: [{ ...hoursLine }, creditLine()] })

    await expect(
      store.updateInvoice('inv-other', { lineItems: [{ ...hoursLine }, creditLine()] }),
    ).rejects.toThrow(/already been applied/i)

    // And nothing of that save survived.
    expect((await byId('inv-other')).total).toBe(600)
    expect((await byId('inv-ret')).appliedToInvoiceId).toBe('inv-final')
  })

  it('lets the SAME invoice be saved again without tripping the never-twice rule', async () => {
    await seed([retainerRow(), invoiceRow('inv-final')])
    await store.updateInvoice('inv-final', { lineItems: [{ ...hoursLine }, creditLine()] })

    const again = await store.updateInvoice('inv-final', {
      lineItems: [{ ...hoursLine }, creditLine()],
      blurb: 'Final invoice — thank you!',
    })

    expect(again.total).toBe(100)
    expect((await byId('inv-ret')).appliedToInvoiceId).toBe('inv-final')
  })

  // Removing the line hands the money back, on the same save. Symmetric with
  // applying it — she can change her mind about which invoice is the last one.
  it('frees the retainer when the credit line is removed', async () => {
    await seed([retainerRow(), invoiceRow('inv-final')])
    await store.updateInvoice('inv-final', { lineItems: [{ ...hoursLine }, creditLine()] })

    const cleared = await store.updateInvoice('inv-final', { lineItems: [{ ...hoursLine }] })

    expect(cleared.total).toBe(600)
    expect((await byId('inv-ret')).appliedToInvoiceId).toBeNull()
    expect(await store.listUnappliedRetainers()).toHaveLength(1)
  })

  // The floor, enforced server-side rather than trusted from the page.
  it('clamps the credit to what the invoice comes to', async () => {
    const small = { kind: 'hourly', label: 'Billable hours', detail: '', amount: 200 }
    await seed([
      retainerRow(),
      invoiceRow('inv-small', { lineItems: [{ ...small }], subtotal: 200, total: 200 }),
    ])

    const updated = await store.updateInvoice('inv-small', {
      lineItems: [{ ...small }, creditLine(-500)],
    })

    expect(updated.lineItems[1].amount).toBe(-200)
    expect(updated.total).toBe(0)
  })

  it('ignores an amount the page made up', async () => {
    await seed([retainerRow(), invoiceRow('inv-final')])

    const updated = await store.updateInvoice('inv-final', {
      lineItems: [{ ...hoursLine }, creditLine(-9999)],
    })

    expect(updated.lineItems[1].amount).toBe(-500)
    expect(updated.total).toBe(100)
  })

  it('refuses a retainer belonging to somebody else', async () => {
    await seed([retainerRow({ clientId: 'c2' }), invoiceRow('inv-final')])

    await expect(
      store.updateInvoice('inv-final', { lineItems: [{ ...hoursLine }, creditLine()] }),
    ).rejects.toThrow(/different client/i)
  })

  it('refuses a credit naming a retainer we do not hold', async () => {
    await seed([invoiceRow('inv-final')])

    await expect(
      store.updateInvoice('inv-final', {
        lineItems: [{ ...hoursLine }, creditLine(-500, 'inv-nope')],
      }),
    ).rejects.toThrow(/does not name a retainer/i)
  })

  it('refuses two credits on one invoice', async () => {
    await seed([retainerRow(), invoiceRow('inv-final')])

    await expect(
      store.updateInvoice('inv-final', {
        lineItems: [{ ...hoursLine }, creditLine(), creditLine()],
      }),
    ).rejects.toThrow(/only one retainer credit/i)
  })

  it('refuses a credit on an invoice with nothing left to credit', async () => {
    await seed([retainerRow(), invoiceRow('inv-empty', { lineItems: [], subtotal: 0, total: 0 })])

    await expect(
      store.updateInvoice('inv-empty', { lineItems: [creditLine()] }),
    ).rejects.toThrow(/nothing on this invoice left to credit/i)
    expect((await byId('inv-ret')).appliedToInvoiceId).toBeNull()
  })

  it('keeps the retainer id through a save, so removing the line can find it', async () => {
    await seed([retainerRow(), invoiceRow('inv-final')])

    const updated = await store.updateInvoice('inv-final', {
      lineItems: [{ ...hoursLine }, creditLine()],
    })

    expect(updated.lineItems[1].retainerInvoiceId).toBe('inv-ret')
  })
})

describe('listClientRetainers on the postgres branch', () => {
  const retainerRow = (overrides = {}) => ({
    ...existingInvoice,
    id: 'inv-ret',
    number: 'INV-RET-2026-001',
    kind: 'retainer',
    status: 'paid',
    period: '2026-06',
    line_items: [{ kind: 'retainer', label: 'Retainer', detail: '', amount: 500 }],
    subtotal: '500.00',
    total: '500.00',
    paid_at: new Date('2026-06-10T12:00:00.000Z'),
    payment_method: 'manual',
    applied_to_invoice_id: null,
    recorded_outside_app: true,
    ...overrides,
  })

  it('reads this client\'s retainers and only their credit targets, never the whole table', async () => {
    const target = {
      ...existingInvoice,
      id: 'inv-final',
      number: 'INV-2026-08-009',
      status: 'draft',
      line_items: [
        { kind: 'hourly', label: 'Hours', detail: '', amount: 300 },
        { kind: 'retainer_credit', label: 'Retainer applied', detail: '', amount: -300, retainerInvoiceId: 'inv-ret' },
      ],
    }
    const fake = fakePostgres({
      invoices: [retainerRow({ applied_to_invoice_id: 'inv-final' }), retainerRow({ id: 'inv-void', status: 'void' }), target],
    })
    const listed = await postgresStore(fake).listClientRetainers('c1')

    const reads = fake.matching(/^select\b[\s\S]*\bfrom invoices\b/i)
    expect(reads).toHaveLength(2)
    expect(reads[0].text).toMatch(/where client_id = \$1 and kind = 'retainer' and status <> 'void'/)
    expect(reads[0].params).toEqual(['c1'])
    expect(reads[1].text).toMatch(/where id = any\(\$1::text\[\]\)/)
    expect(reads[1].params).toEqual([['inv-final']])
    expect(listed.map((row) => row.id)).toEqual(['inv-ret'])
    expect(listed[0]).toMatchObject({
      recordedOutsideApp: true,
      credit: { invoiceId: 'inv-final', status: 'draft', amount: 300 },
    })
    expect(listed[0]).not.toHaveProperty('lineItems')
  })

  it('makes no second read when nothing is applied', async () => {
    const fake = fakePostgres({ invoices: [retainerRow()] })
    await postgresStore(fake).listClientRetainers('c1')
    expect(fake.matching(/^select\b[\s\S]*\bfrom invoices\b/i)).toHaveLength(1)
  })
})

describe('retainer writes on the postgres branch', () => {
  const finalRow = {
    id: 'inv-final',
    client_id: 'c1',
    period: '2026-08',
    number: 'INV-2026-08-001',
    kind: 'monthly',
    status: 'draft',
    line_items: [{ kind: 'hourly', label: 'Hours', detail: '', amount: 600 }],
    subtotal: 600,
    total: 600,
  }
  const retainerRow = {
    id: 'inv-ret',
    client_id: 'c1',
    period: '2026-01',
    number: 'INV-RET-2026-001',
    kind: 'retainer',
    status: 'paid',
    line_items: [{ kind: 'retainer', label: 'Retainer', detail: '', amount: 500 }],
    subtotal: 500,
    total: 500,
  }

  it('scopes the live-invoice index to monthly, dropping the old one first', async () => {
    const fake = fakePostgres()
    // `initialize()` issues the DDL and then seeds. The fake answers every
    // select with nothing, so the SEEDING half throws — by which point the DDL
    // has already been issued, and the DDL is the whole point here.
    await postgresStore(fake)
      .initialize()
      .catch(() => {})

    expect(fake.matching(/alter table invoices add column if not exists kind text/i)).toHaveLength(
      1,
    )
    expect(
      fake.matching(/alter table invoices add column if not exists applied_to_invoice_id/i),
    ).toHaveLength(1)
    // Order matters: a new index created while the strict one still exists
    // would never get a chance to be the rule.
    const dropped = fake.indexOf(/drop index if exists invoices_client_period_live/i)
    const created = fake.indexOf(
      /create unique index if not exists invoices_client_period_monthly_live/i,
    )
    expect(dropped).toBeGreaterThan(-1)
    expect(created).toBeGreaterThan(dropped)
    expect(fake.statements[created].text).toMatch(/where kind = 'monthly' and status <> 'void'/i)
  })

  it('names the same predicate on the insert, so a retainer can never conflict', async () => {
    const fake = fakePostgres()
    await postgresStore(fake)._insertInvoice({
      id: 'inv-ret',
      clientId: 'c1',
      period: '2026-08',
      number: 'INV-RET-2026-001',
      kind: 'retainer',
      status: 'draft',
      lineItems: [],
      subtotal: 500,
      total: 500,
      dueDate: null,
      blurb: '',
      scopeFlags: [],
    })

    const inserts = fake.matching(/insert into invoices/i)
    expect(inserts).toHaveLength(1)
    expect(inserts[0].text).toMatch(
      /on conflict \(client_id, period\) where kind = 'monthly' and status <> 'void'/i,
    )
    // Positional, one past `number` — the bug this catches is the kind landing
    // in the status column when someone adds the next one.
    expect(inserts[0].params[4]).toBe('retainer')
    // A draft is neither sent nor paid: sent_at, paid_at, payment_method are null.
    expect(inserts[0].params).toHaveLength(17)
    expect(inserts[0].params.slice(13)).toEqual([null, null, null, false])
  })

  it('marks the retainer inside the same transaction as the lines', async () => {
    const fake = fakePostgres({ invoices: [finalRow, retainerRow] })

    await postgresStore(fake).updateInvoice('inv-final', {
      lineItems: [
        { kind: 'hourly', label: 'Hours', detail: '', amount: 600 },
        {
          kind: 'retainer_credit',
          label: 'Retainer applied — credit',
          detail: '',
          amount: -500,
          retainerInvoiceId: 'inv-ret',
        },
      ],
    })

    const begin = fake.indexOf(/^BEGIN$/i)
    const applied = fake.indexOf(/set applied_to_invoice_id = \$2/i)
    const commit = fake.indexOf(/^COMMIT$/i)
    expect(begin).toBeGreaterThan(-1)
    expect(applied).toBeGreaterThan(begin)
    expect(commit).toBeGreaterThan(applied)
    // The never-twice rule as a WHERE clause: two racing saves both read the
    // column as null, and only the one that gets here first matches a row.
    expect(fake.statements[applied].text).toMatch(
      /applied_to_invoice_id is null or applied_to_invoice_id = \$2/i,
    )
    expect(fake.statements[applied].params).toEqual(['inv-ret', 'inv-final'])
  })

  // An ordinary edit used to be a single statement outside any transaction.
  // It is no longer, and the reason is the review-event capture: the record of
  // what she changed has to land with the change or not at all. What still
  // holds — and is what this test was really about — is that no RETAINER
  // statement is issued for an edit that moves no credit.
  it('moves no retainer on an ordinary edit, and records the edit with it', async () => {
    const fake = fakePostgres({ invoices: [finalRow] })

    await postgresStore(fake).updateInvoice('inv-final', { blurb: 'Thank you!' })

    expect(fake.matching(/set applied_to_invoice_id/i)).toHaveLength(0)
    const update = fake.indexOf(/^update invoices\s+set line_items/i)
    const event = fake.indexOf(/^insert into invoice_review_events/i)
    const commit = fake.indexOf(/^COMMIT$/i)
    expect(update).toBeGreaterThan(fake.indexOf(/^BEGIN$/i))
    expect(event).toBeGreaterThan(update)
    expect(commit).toBeGreaterThan(event)
  })

  // A save that rewrites the same values is not an edit. No event, and
  // therefore nothing needing a transaction — the single-statement path stays.
  it('leaves a no-op save as one statement, with no transaction at all', async () => {
    const fake = fakePostgres({ invoices: [finalRow] })

    await postgresStore(fake).updateInvoice('inv-final', {})

    expect(fake.matching(/^BEGIN$/i)).toHaveLength(0)
    expect(fake.matching(/^insert into invoice_review_events/i)).toHaveLength(0)
  })

  it('carries kind and the applied fact through the bulk-save restore', async () => {
    const fake = fakePostgres({
      invoices: [
        {
          ...retainerRow,
          scope_flags: [],
          email_log: [],
          applied_to_invoice_id: 'inv-final',
          created_at: '2026-01-05T00:00:00.000Z',
        },
      ],
    })
    await postgresStore(fake).write(workspace())

    const restores = fake.matching(/insert into invoices \(/i)
    expect(restores).toHaveLength(1)
    expect(restores[0].text).toMatch(/number, kind, status/i)
    expect(restores[0].text).toMatch(
      /email_log, applied_to_invoice_id, original_line_items, pay_token,\s*recorded_outside_app,\s*created_at/i,
    )
    // A retainer that came back as 'monthly' would collide with that client's
    // real invoice on the very next generate; one that came back unapplied
    // would be spendable a second time.
    const [restored] = insertedRows(fake.statements, 'invoices')
    expect(restored.kind).toBe('retainer')
    expect(restored.applied_to_invoice_id).toBe('inv-final')
  })
})

/**
 * The lifecycle edges of a retainer credit — what happens when the invoice
 * holding it, or the retainer behind it, moves on.
 *
 * The invariant is that a retainer is in exactly ONE of two states at all times:
 * on account, or spent on a live invoice. Every test here is a way the pair
 * could otherwise end up in a third state — spent on a document nobody is
 * paying, where the money is neither creditable nor recoverable and nothing on
 * screen would ever say so.
 */
describe('retainer credits at the lifecycle edges (file backend)', () => {
  const period = '2026-08'
  const hoursLine = { kind: 'hourly', label: 'Billable hours', detail: '', amount: 600 }

  function invoiceRow(id, overrides = {}) {
    return {
      id,
      clientId: 'c1',
      period,
      number: id,
      kind: 'monthly',
      status: 'draft',
      lineItems: [{ ...hoursLine }],
      subtotal: 600,
      total: 600,
      dueDate: null,
      blurb: '',
      scopeFlags: [],
      sentAt: null,
      paidAt: null,
      paymentMethod: null,
      appliedToInvoiceId: null,
      createdAt: '2026-08-31T00:00:00.000Z',
      updatedAt: '2026-08-31T00:00:00.000Z',
      ...overrides,
    }
  }

  function retainerRow(overrides = {}) {
    return invoiceRow('inv-ret', {
      kind: 'retainer',
      number: 'INV-RET-2026-001',
      status: 'paid',
      period: '2026-01',
      lineItems: [{ kind: 'retainer', label: 'Retainer', detail: '', amount: 500 }],
      subtotal: 500,
      total: 500,
      ...overrides,
    })
  }

  function creditLine(amount = -500, retainerInvoiceId = 'inv-ret') {
    return {
      kind: 'retainer_credit',
      label: 'Retainer applied — credit',
      detail: 'Retainer INV-RET-2026-001',
      amount,
      retainerInvoiceId,
    }
  }

  async function seed(rows) {
    await store.write(
      workspace({
        clients: [{ id: 'c1', name: 'Acme', billingMode: 'hourly', hourlyRate: 100 }],
        timeEntries: [],
      }),
    )
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices = rows
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
  }

  const byId = async (id) => (await store.listInvoices()).find((invoice) => invoice.id === id)

  // ---- Voiding the invoice hands the retainer back -------------------------

  it('frees the retainer when the invoice holding it is voided', async () => {
    await seed([retainerRow(), invoiceRow('inv-final')])
    await store.updateInvoice('inv-final', { lineItems: [{ ...hoursLine }, creditLine()] })
    expect(await store.listUnappliedRetainers()).toHaveLength(0)

    await store.updateInvoice('inv-final', { status: 'void' })

    expect((await byId('inv-ret')).appliedToInvoiceId).toBeNull()
    expect(await store.listUnappliedRetainers()).toHaveLength(1)
  })

  // The likeliest way a credited invoice gets voided: she rebuilds the month.
  it('frees the retainer when the month is voided and regenerated', async () => {
    await seed([retainerRow(), invoiceRow('inv-final')])
    await store.updateInvoice('inv-final', { lineItems: [{ ...hoursLine }, creditLine()] })

    const result = await store.voidUnsentInvoicesForPeriod(period)

    expect(result.voided).toBe(1)
    expect((await byId('inv-ret')).appliedToInvoiceId).toBeNull()
    expect(await store.listUnappliedRetainers()).toHaveLength(1)
  })

  it('leaves a retainer spent on an invoice in ANOTHER month alone', async () => {
    await seed([
      retainerRow(),
      invoiceRow('inv-july', { period: '2026-07' }),
      invoiceRow('inv-final'),
    ])
    await store.updateInvoice('inv-july', { lineItems: [{ ...hoursLine }, creditLine()] })

    await store.voidUnsentInvoicesForPeriod(period)

    expect((await byId('inv-ret')).appliedToInvoiceId).toBe('inv-july')
  })

  // ---- Review comes before the money moves ---------------------------------

  it('refuses a NEW credit on an invoice that has already gone out', async () => {
    await seed([retainerRow(), invoiceRow('inv-sent', { status: 'sent' })])

    await expect(
      store.updateInvoice('inv-sent', { lineItems: [{ ...hoursLine }, creditLine()] }),
    ).rejects.toThrow(/draft or reviewed/i)
    expect((await byId('inv-ret')).appliedToInvoiceId).toBeNull()
  })

  // ...but a credit that was applied BEFORE the invoice went out travels with
  // it. Re-checking the status on every later save would make a legitimately
  // credited invoice unsaveable the moment it was sent.
  it('keeps saving an invoice that already carried its credit when it went out', async () => {
    await seed([
      retainerRow({ appliedToInvoiceId: 'inv-sent' }),
      invoiceRow('inv-sent', {
        status: 'sent',
        lineItems: [{ ...hoursLine }, creditLine()],
        total: 100,
      }),
    ])

    const updated = await store.updateInvoice('inv-sent', {
      lineItems: [{ ...hoursLine }, creditLine()],
      blurb: 'Thanks for a great year.',
    })

    expect(updated.total).toBe(100)
    expect((await byId('inv-ret')).appliedToInvoiceId).toBe('inv-sent')
  })

  // Same rule, the other side: the RETAINER's own status is only a bar to
  // spending it, not to saving an invoice that already spent it.
  it('keeps saving a credited invoice after the retainer’s status moves on', async () => {
    await seed([
      retainerRow({ appliedToInvoiceId: 'inv-final', status: 'overdue' }),
      invoiceRow('inv-final', { lineItems: [{ ...hoursLine }, creditLine()], total: 100 }),
    ])

    const updated = await store.updateInvoice('inv-final', {
      lineItems: [{ ...hoursLine }, creditLine()],
    })

    expect(updated.total).toBe(100)
    expect((await byId('inv-ret')).appliedToInvoiceId).toBe('inv-final')
  })

  // ---- An unrelated PATCH is not a statement about the credit --------------

  it('marks a credited invoice reviewed even when its retainer was voided', async () => {
    await seed([
      retainerRow({ appliedToInvoiceId: 'inv-final', status: 'void' }),
      invoiceRow('inv-final', { lineItems: [{ ...hoursLine }, creditLine()], total: 100 }),
    ])

    const updated = await store.updateInvoice('inv-final', {
      blurb: 'Final invoice — thank you!',
    })

    expect(updated.blurb).toBe('Final invoice — thank you!')
    expect(updated.total).toBe(100)
    expect((await byId('inv-ret')).appliedToInvoiceId).toBe('inv-final')
  })

  it('still settles the credit when the save DOES carry lines', async () => {
    await seed([retainerRow(), invoiceRow('inv-final')])

    await store.updateInvoice('inv-final', { lineItems: [{ ...hoursLine }, creditLine()] })

    expect((await byId('inv-ret')).appliedToInvoiceId).toBe('inv-final')
  })

  // ---- Voiding a spent retainer is refused, with somewhere to go -----------

  it('refuses to void a retainer that has been given back, and says where', async () => {
    await seed([
      retainerRow({ appliedToInvoiceId: 'inv-final' }),
      invoiceRow('inv-final', { number: 'INV-2026-08-004' }),
    ])

    await expect(store.updateInvoice('inv-ret', { status: 'void' })).rejects.toThrow(
      /applied to INV-2026-08-004 — remove the credit from that invoice first/i,
    )
    expect((await byId('inv-ret')).status).toBe('paid')
  })

  it('voids a retainer that is still on account', async () => {
    await seed([retainerRow()])
    expect((await store.updateInvoice('inv-ret', { status: 'void' })).status).toBe('void')
  })

  // ---- Kinds that do not belong on this document --------------------------

  it('will not let a monthly invoice claim a retainer LINE', async () => {
    await seed([invoiceRow('inv-final')])

    const updated = await store.updateInvoice('inv-final', {
      lineItems: [{ kind: 'retainer', label: 'Retainer', detail: '', amount: 2500 }],
    })

    // Demoted, not dropped — the charge survives as an ordinary line rather
    // than the save failing on her.
    expect(updated.lineItems[0]).toMatchObject({ kind: 'custom', amount: 2500 })
  })

  // Seeded as a DRAFT deliberately. What this pins is the line-kind sanitizer —
  // that 'retainer' survives on a retainer invoice where a monthly one demotes
  // it — and `retainerRow()` merely happens to default to paid because that is
  // the realistic state to find one in. Since the paid lock (featreq-ead3a215)
  // that default would refuse the save before the sanitizer ever ran, and the
  // test would be passing for the wrong reason. The paid case is its own test
  // below.
  it('keeps the retainer line on an actual retainer invoice', async () => {
    await seed([retainerRow({ appliedToInvoiceId: null, status: 'draft' })])

    const updated = await store.updateInvoice('inv-ret', {
      lineItems: [{ kind: 'retainer', label: 'Retainer', detail: 'Signed', amount: 2500 }],
    })

    expect(updated.lineItems[0].kind).toBe('retainer')
  })

  /**
   * The retainer half of Brittany's rule, and the reason it needed no separate
   * calculation. A retainer must be PAID before it can be credited anywhere
   * (`listUnappliedRetainers`), and this is what stops its total moving after
   * that — so the credit on the final invoice can never drift away from the
   * money that actually came in.
   */
  it('refuses to re-price a retainer once it has been paid', async () => {
    await seed([retainerRow({ appliedToInvoiceId: null })])

    await expect(
      store.updateInvoice('inv-ret', {
        lineItems: [{ kind: 'retainer', label: 'Retainer', detail: '', amount: 2000 }],
      }),
    ).rejects.toBeInstanceOf(InvoiceLockedError)

    // The figure a future credit would be sized from is untouched.
    expect((await byId('inv-ret')).total).toBe(500)
  })

  it('refuses to credit a retainer against another retainer', async () => {
    await seed([
      retainerRow(),
      retainerRow({ id: 'inv-ret-2', number: 'INV-RET-2026-002', status: 'draft' }),
    ])

    await expect(
      store.updateInvoice('inv-ret-2', {
        lineItems: [
          { kind: 'retainer', label: 'Retainer', detail: '', amount: 500 },
          creditLine(),
        ],
      }),
    ).rejects.toThrow(/belongs on a monthly invoice/i)
  })
})

describe('retainer lifecycle edges on the postgres branch', () => {
  it('swaps the index inside one transaction, so uniqueness is never off', async () => {
    const fake = fakePostgres()
    // See the sibling DDL test: the seeding half of initialize() throws against
    // a fake that answers every select with nothing. The DDL has already run.
    await postgresStore(fake)
      .initialize()
      .catch(() => {})

    const dropped = fake.indexOf(/drop index if exists invoices_client_period_live/i)
    const created = fake.indexOf(
      /create unique index if not exists invoices_client_period_monthly_live/i,
    )
    expect(dropped).toBeGreaterThan(-1)
    // ADJACENT, not merely ordered: between the drop and the create there is no
    // index enforcing one live invoice per client per month, and this is the
    // invoice of record. `create index` is transactional in Postgres, so the gap
    // can simply be closed — and nothing may be issued inside it.
    expect(fake.statements[dropped - 1].text).toMatch(/^BEGIN$/i)
    expect(created).toBe(dropped + 1)
    expect(fake.statements[created + 1].text).toMatch(/^COMMIT$/i)
  })

  it('frees the stranded retainers in the same transaction as the voids', async () => {
    const fake = fakePostgres({ invoices: [{ id: 'inv-final' }] })
    await postgresStore(fake).voidUnsentInvoicesForPeriod('2026-08')

    const voided = fake.indexOf(/set status = 'void'/i)
    const freed = fake.indexOf(/set applied_to_invoice_id = null/i)
    const begin = fake.indexOf(/^BEGIN$/i)
    const commit = fake.indexOf(/^COMMIT$/i)

    expect(begin).toBeLessThan(voided)
    expect(freed).toBeGreaterThan(voided)
    expect(commit).toBeGreaterThan(freed)
    // Scoped to exactly the ids that were just voided — a retainer spent on a
    // live invoice in another month must not be handed back.
    expect(fake.statements[freed].text).toMatch(/applied_to_invoice_id = any\(\$1::text\[\]\)/i)
    expect(fake.statements[freed].params).toEqual([['inv-final']])
  })

  it('does not run the freeing statement when nothing was voided', async () => {
    const fake = fakePostgres()
    await postgresStore(fake).voidUnsentInvoicesForPeriod('2026-08')

    expect(fake.matching(/set applied_to_invoice_id = null/i)).toHaveLength(0)
  })
})

/**
 * A bank payment that is still clearing cannot be voided — the Postgres half of
 * the rule the file-backend lock tests pin (cardinal rule 1: both backends).
 */
describe('voiding while a bank payment is clearing (postgres branch)', () => {
  const processing = { ...existingInvoice, status: 'processing' }

  it('refuses the void and issues no write at all', async () => {
    const fake = fakePostgres({ invoices: [{ ...processing }] })

    const error = await postgresStore(fake)
      .updateInvoice('inv-1', { status: 'void' })
      .then(() => null, (thrown) => thrown)

    expect(error).toBeInstanceOf(InvoicePaymentProcessingError)
    expect(error.code).toBe('invoice_payment_processing')
    expect(error.message).toBe(
      'A bank payment is still clearing on this invoice. Wait until it is paid or fails, then void it.',
    )
    // Nothing written: no UPDATE, no transaction, no ledger release.
    expect(fake.matching(/^update\b/i)).toHaveLength(0)
    expect(fake.matching(/^(begin|commit)$/i)).toHaveLength(0)
    expect(fake.matching(/^(insert|delete)\b/i)).toHaveLength(0)
  })

  it('still voids a paid invoice', async () => {
    const fake = fakePostgres({ invoices: [{ ...existingInvoice, status: 'paid' }] })

    await postgresStore(fake).updateInvoice('inv-1', { status: 'void' })

    const [write] = fake.matching(/^update invoices\s+set line_items/i)
    expect(write).toBeTruthy()
    expect(write.params[0]).toBe('inv-1')
    expect(write.params[6]).toBe('void')
  })

  it('leaves a clearing invoice out of the month void and counts it', async () => {
    const fake = fakePostgres({ invoices: [{ ...processing }] })

    const result = await postgresStore(fake).voidUnsentInvoicesForPeriod('2026-08')

    expect(result.clearing).toBe(1)
    // The void statement itself still names only draft and reviewed.
    const [voidStatement] = fake.matching(/set status = 'void'/i)
    expect(voidStatement.text).toMatch(/status in \('draft', 'reviewed'\)/i)
  })

  it('hands back the checkout sessions of the invoices it voided, off the void itself', async () => {
    const fake = fakePostgres({
      invoices: [
        { id: 'inv-final', stripe_checkout_session_id: 'cs_ach_1', stripe_card_session_id: 'cs_card_1' },
        { id: 'inv-ach', stripe_checkout_session_id: 'cs_ach_2', stripe_card_session_id: null },
        { id: 'inv-bare', stripe_checkout_session_id: null, stripe_card_session_id: null },
      ],
    })

    const result = await postgresStore(fake).voidUnsentInvoicesForPeriod('2026-08')

    expect(result.sessions).toEqual([
      { invoiceId: 'inv-final', sessionId: 'cs_ach_1' },
      { invoiceId: 'inv-final', sessionId: 'cs_card_1' },
      { invoiceId: 'inv-ach', sessionId: 'cs_ach_2' },
    ])
    // One statement, not two: the sessions ride the void's own RETURNING.
    const [voidStatement] = fake.matching(/set status = 'void'/i)
    expect(voidStatement.text.replace(/\s+/g, ' ')).toBe(
      "update invoices set status = 'void', updated_at = now() where period = $1 and kind = 'monthly' and status in ('draft', 'reviewed') returning id, stripe_checkout_session_id, stripe_card_session_id",
    )
    expect(voidStatement.params).toEqual(['2026-08'])
    expect(fake.matching(/^select stripe_checkout_session_id/i)).toHaveLength(0)
  })
})

/**
 * A save that races a payment is refused instead of overwriting it. The write
 * names the status the save READ (`and status = $8`); a Stripe webhook that
 * moved the invoice to processing or paid in between leaves it matching no row,
 * and the store re-reads to tell "gone" (null, the route's 404) from "moved"
 * (`InvoiceChangedError`). The fake REPRODUCES the guard (see `fakePostgres`),
 * so deleting `and status = $8` fails these.
 */
describe('a save that races a payment (postgres branch)', () => {
  const lines = [{ kind: 'plan', label: 'August work', detail: 'Monthly service', amount: 250 }]
  const flat = (text) => text.replace(/\s+/g, ' ').trim()

  /** A store whose FIRST invoice read is followed by `afterRead` — the window a webhook lands in. */
  function raced(fake, afterRead) {
    const store = postgresStore(fake)
    const original = store.listInvoices.bind(store)
    vi.spyOn(store, 'listInvoices').mockImplementationOnce(async (...args) => {
      const rows = await original(...args)
      afterRead()
      return rows
    })
    return store
  }

  it('writes an ordinary save exactly as before, plus the status it read', async () => {
    const fake = fakePostgres({ invoices: [{ ...existingInvoice }] })

    await postgresStore(fake).updateInvoice('inv-1', {})

    const writes = fake.matching(/^update invoices\s+set line_items/i)
    expect(writes).toHaveLength(1)
    expect(flat(writes[0].text)).toBe(
      'update invoices set line_items = $2::jsonb, subtotal = $3, total = $4, due_date = $5, blurb = $6, status = $7, updated_at = now() where id = $1 and status = $8',
    )
    expect(writes[0].params).toEqual([
      'inv-1',
      JSON.stringify(lines),
      250,
      250,
      '2026-09-30',
      '',
      'sent',
      'sent',
    ])
    // The re-read exists only for a write that matched nothing.
    expect(fake.matching(/^select 1 as present from invoices/i)).toHaveLength(0)
  })

  it('writes an edit inside its transaction with the same guarded statement', async () => {
    const fake = fakePostgres({ invoices: [{ ...existingInvoice }] })

    await postgresStore(fake).updateInvoice('inv-1', { blurb: 'Thanks!' })

    const writes = fake.matching(/^update invoices\s+set line_items/i)
    expect(writes).toHaveLength(1)
    expect(flat(writes[0].text)).toMatch(/where id = \$1 and status = \$8$/)
    expect(writes[0].params).toEqual([
      'inv-1',
      JSON.stringify(lines),
      250,
      250,
      '2026-09-30',
      'Thanks!',
      'sent',
      'sent',
    ])
    expect(fake.matching(/^COMMIT$/i)).toHaveLength(1)
    expect(fake.matching(/^insert into invoice_review_events/i)).toHaveLength(1)
  })

  it('refuses a single-statement save when a payment moved the status, and writes nothing else', async () => {
    const row = { ...existingInvoice }
    const fake = fakePostgres({ invoices: [row] })
    const store = raced(fake, () => {
      row.status = 'processing'
    })

    const error = await store.updateInvoice('inv-1', {}).then(() => null, (thrown) => thrown)

    expect(error).toBeInstanceOf(InvoiceChangedError)
    expect(error.message).toBe(INVOICE_CHANGED_MESSAGE)
    expect(error.message).toBe(
      'This invoice changed while you were working. It has been refreshed — check it and make your change again.',
    )
    expect(fake.matching(/^update invoices\s+set line_items/i)).toHaveLength(1)
    expect(fake.matching(/^select 1 as present from invoices where id = \$1$/i)[0].params).toEqual([
      'inv-1',
    ])
    expect(fake.matching(/^(insert|delete)\b/i)).toHaveLength(0)
    expect(row.status).toBe('processing')
  })

  it('refuses a void that lands on an invoice being paid, and rolls the whole transaction back', async () => {
    const row = { ...existingInvoice }
    const fake = fakePostgres({ invoices: [row] })
    const store = raced(fake, () => {
      row.status = 'paid'
    })

    await expect(store.updateInvoice('inv-1', { status: 'void' })).rejects.toBeInstanceOf(
      InvoiceChangedError,
    )

    expect(fake.matching(/^BEGIN$/i)).toHaveLength(1)
    expect(fake.matching(/^ROLLBACK$/i).length).toBeGreaterThanOrEqual(1)
    expect(fake.matching(/^COMMIT$/i)).toHaveLength(0)
    // No review event, no retainer or ledger write, no tag write: the guarded
    // UPDATE is the first write and nothing runs after it.
    expect(fake.matching(/^insert into invoice_review_events/i)).toHaveLength(0)
    expect(fake.matching(/set applied_to_invoice_id/i)).toHaveLength(0)
    expect(fake.matching(/^update time_entries/i)).toHaveLength(0)
    expect(fake.matching(/^(insert|delete)\b/i)).toHaveLength(0)
    expect(fake.matching(/^update invoices\b/i)).toHaveLength(1)
    // The ROLLBACK is issued before the throw, after the re-read.
    expect(fake.indexOf(/^ROLLBACK$/i)).toBeGreaterThan(fake.indexOf(/^select 1 as present/i))
  })

  it('refuses an ordinary edit of a sent invoice that a payment moved, instead of writing sent back over it', async () => {
    const row = { ...existingInvoice }
    const fake = fakePostgres({ invoices: [row] })
    const store = raced(fake, () => {
      row.status = 'processing'
    })

    await expect(store.updateInvoice('inv-1', { blurb: 'Thanks!' })).rejects.toBeInstanceOf(
      InvoiceChangedError,
    )

    expect(fake.matching(/^insert into invoice_review_events/i)).toHaveLength(0)
    expect(fake.matching(/^COMMIT$/i)).toHaveLength(0)
    expect(row.status).toBe('processing')
  })

  it('still answers null (the route 404) when the invoice is gone, on both write paths', async () => {
    for (const patch of [{}, { blurb: 'Thanks!' }]) {
      const rows = [{ ...existingInvoice }]
      const fake = fakePostgres({ invoices: rows })
      const store = raced(fake, () => {
        rows.splice(0, rows.length)
      })

      expect(await store.updateInvoice('inv-1', patch)).toBeNull()
      expect(fake.matching(/^COMMIT$/i)).toHaveLength(0)
      expect(fake.matching(/^insert into invoice_review_events/i)).toHaveLength(0)
    }
  })
})

/**
 * The same refusal on the FILE backend: the row as it is on disk, read for the
 * write, has to still carry the status the save read.
 */
describe('a save that races a payment (file backend)', () => {
  function invoice(overrides = {}) {
    return {
      id: 'inv-race',
      clientId: 'c1',
      period: '2026-08',
      number: 'INV-2026-08-001',
      status: 'sent',
      lineItems: [{ kind: 'custom', label: 'Bookkeeping', detail: '', amount: 400 }],
      subtotal: 400,
      total: 400,
      dueDate: '2026-09-15',
      blurb: '',
      scopeFlags: [],
      sentAt: '2026-09-01T00:00:00.000Z',
      paidAt: null,
      paymentMethod: null,
      createdAt: '2026-08-01T00:00:00.000Z',
      updatedAt: '2026-08-01T00:00:00.000Z',
      ...overrides,
    }
  }

  async function seed(rows) {
    const data = JSON.parse(await readFile(localDataPath, 'utf8'))
    data.invoices = rows
    await writeFile(localDataPath, JSON.stringify(data, null, 2))
  }

  async function stored() {
    return JSON.parse(await readFile(localDataPath, 'utf8')).invoices
  }

  /** The window a webhook lands in: after the save's first read, before its write. */
  function webhookLandsAfterFirstRead(status) {
    const original = store.listInvoices.bind(store)
    vi.spyOn(store, 'listInvoices').mockImplementationOnce(async (...args) => {
      const rows = await original(...args)
      await seed((await stored()).map((entry) => ({ ...entry, status })))
      return rows
    })
  }

  afterEach(() => {
    vi.restoreAllMocks()
  })

  it('refuses an edit when the status moved between the read and the write, and writes nothing', async () => {
    await seed([invoice()])
    webhookLandsAfterFirstRead('processing')

    const error = await store
      .updateInvoice('inv-race', { blurb: 'Thanks!' })
      .then(() => null, (thrown) => thrown)

    expect(error).toBeInstanceOf(InvoiceChangedError)
    expect(error.message).toBe(INVOICE_CHANGED_MESSAGE)
    const [row] = await stored()
    expect(row.status).toBe('processing')
    expect(row.blurb).toBe('')
    expect(await store.listInvoiceReviewEvents({ invoiceId: 'inv-race' })).toEqual([])
  })

  it('refuses a void that would land on an invoice that has just been paid', async () => {
    await seed([invoice()])
    webhookLandsAfterFirstRead('paid')

    await expect(store.updateInvoice('inv-race', { status: 'void' })).rejects.toBeInstanceOf(
      InvoiceChangedError,
    )
    expect((await stored())[0].status).toBe('paid')
  })

  it('writes an ordinary save as before when nothing raced it', async () => {
    await seed([invoice()])

    const saved = await store.updateInvoice('inv-race', { blurb: 'Thanks!' })

    expect(saved.blurb).toBe('Thanks!')
    expect(saved.status).toBe('sent')
    expect((await stored())[0].blurb).toBe('Thanks!')
  })
})

