/**
 * CARRIED ITEM 2 — a client that BECOMES Hourly is pinned at save time.
 *
 * The boot backfill pins any unpinned hourly client at the June 2026 cutover, so
 * a subscription client switched to Hourly through the bulk save would bill at
 * rates a year and a half old. `write()` defaults the null to THIS month on both
 * backends. It is a default for a null, not the payload's value — a pin that is
 * stored still wins outright.
 */
describe('a client that becomes Hourly is pinned at save time (file backend)', () => {
  // These fixtures replace the whole workspace, so they start from none: a bulk
  // save refuses to drop a stored client that has time entries or invoices.
  beforeEach(() => rm(localDataPath, { force: true }))
  const thisMonth = () => firmToday().slice(0, 7)

  it('pins a subscription client that is saved again as Hourly', async () => {
    await store.write(
      workspace({
        clients: [{ id: 'c-sub', name: 'Sub Co', billingMode: 'subscription', monthlyRate: 500 }],
        timeEntries: [],
      }),
    )
    await store.write(
      workspace({
        clients: [{ id: 'c-sub', name: 'Sub Co', billingMode: 'hourly', hourlyRate: 100 }],
        timeEntries: [],
      }),
    )
    const data = await store.read()
    const client = data.clients.find((entry) => entry.id === 'c-sub')
    expect(client.hourlyRatePeriod).toBe(thisMonth())
    expect(client.hourlyRateHistory).toEqual([])
  })

  it('discards a pin and a ledger a save invented for a client it has never seen', async () => {
    // FILE BACKEND ONLY by nature: Postgres never reads the payload's copy of
    // either column, so there is nothing to discard over there. Here the merge
    // used to restore the stored value only for ids already on disk, which let
    // a bulk save carrying a brand-new client id persist whatever pin and
    // ledger it had invented. Both are endpoint-owned; a client this file has
    // never seen gets the save-time default, exactly as the Postgres insert
    // binds it.
    await store.write(
      workspace({
        clients: [
          {
            id: 'c-invented',
            name: 'Invented Co',
            billingMode: 'hourly',
            hourlyRate: 100,
            hourlyRatePeriod: '2030-01',
            hourlyRateHistory: [
              {
                from: '2030-01',
                to: '2030-01',
                changedAt: '2030-01-01T00:00:00.000Z',
                changedBy: 'nobody',
              },
            ],
          },
        ],
        timeEntries: [],
      }),
    )
    const client = (await store.read()).clients.find((entry) => entry.id === 'c-invented')
    expect(client.hourlyRatePeriod).toBe(thisMonth())
    expect(client.hourlyRateHistory).toEqual([])
  })

  it('leaves a client that is not Hourly unpinned', async () => {
    await store.write(
      workspace({
        clients: [{ id: 'c-sub', name: 'Sub Co', billingMode: 'subscription', monthlyRate: 500 }],
        timeEntries: [],
      }),
    )
    const data = await store.read()
    expect(data.clients.find((entry) => entry.id === 'c-sub').hourlyRatePeriod ?? null).toBeNull()
  })

  it('keeps the stored pin and ledger when the best-effort block throws', async () => {
    // The merge that applies the stored pin runs OUTSIDE the best-effort
    // try/catch, so its snapshot has to be taken outside it too. A checklist
    // item whose `subItems` carries a null makes `rollUpItemDone` throw inside
    // that block — the cheapest deterministic trip there is. With the snapshot
    // still inside, the map would be empty by the time the merge ran and this
    // client would come back out re-pinned at this month with its ledger gone,
    // which is the data loss the whole feature exists to prevent.
    await store.write(
      workspace({
        clients: [{ id: 'c1', name: 'Acme', billingMode: 'hourly', hourlyRate: 100 }],
        timeEntries: [],
      }),
    )
    const seeded = JSON.parse(await readFile(localDataPath, 'utf8'))
    seeded.clients[0].hourlyRatePeriod = '2025-01'
    seeded.clients[0].hourlyRateHistory = [
      { from: '2024-06', to: '2025-01', changedAt: '2025-01-02T00:00:00.000Z', changedBy: 'u' },
    ]
    await writeFile(localDataPath, JSON.stringify(seeded, null, 2))

    await store.write(
      workspace({
        clients: [
          {
            id: 'c1',
            name: 'Acme',
            billingMode: 'hourly',
            hourlyRate: 110,
            hourlyRatePeriod: '2030-01',
            hourlyRateHistory: [],
          },
        ],
        timeEntries: [],
        checklists: [
          {
            id: 'ck1',
            clientId: 'c1',
            title: 'Monthly',
            items: [{ id: 'i1', label: 'Step', subItems: [null] }],
          },
        ],
      }),
    )

    const client = (await store.read()).clients.find((entry) => entry.id === 'c1')
    expect(client.hourlyRatePeriod).toBe('2025-01')
    expect(client.hourlyRateHistory.map((entry) => entry.to)).toEqual(['2025-01'])
  })

  it('never overwrites a pin that is already stored', async () => {
    await store.write(
      workspace({
        clients: [{ id: 'c1', name: 'Acme', billingMode: 'hourly', hourlyRate: 100 }],
        timeEntries: [],
      }),
    )
    await store.setClientHourlyRatePeriod({ clientId: 'c1', period: '2025-03', actingUserId: 'u' })
    await store.write(
      workspace({
        clients: [{ id: 'c1', name: 'Acme', billingMode: 'hourly', hourlyRate: 110 }],
        timeEntries: [],
      }),
    )
    const data = await store.read()
    expect(data.clients.find((entry) => entry.id === 'c1').hourlyRatePeriod).toBe('2025-03')
  })
})

