  describe('the two halves of a split push are one occurrence, not "later" than each other', () => {
    // A split push leaves the done steps on a record (original due date) and moves
    // the open steps to a live copy (due date moved forward, same cycle date). The
    // live copy's moved due date is after the record's, but both belong to the
    // September occurrence, so a series delete from either half must leave the
    // other alone and still reach the genuinely later October checklist.
    const splitPair = async () => {
      await seed([
        checklist('cl-sep', '2026-09-30', [
          step('s1', 'Reconcile', { done: true }),
          step('s2', 'Send report'),
          step('s3', 'Reconcile'),
        ]),
        checklist('cl-oct', '2026-10-31', [step('o1', 'Reconcile'), step('o2', 'Send report')]),
      ])
      const { checklist: live, completed } = await store.pushChecklistInstance('cl-sep', 'emp-1', '2026-10-10')
      expect(completed.pushedToChecklistId).toBe(live.id)
      expect(live.pushedFromChecklistId).toBe(completed.id)
      return { live, completed }
    }

    it('started from the completed record, leaves the live copy alone and removes the later copy', async () => {
      const { live, completed } = await splitPair()
      const result = await store.deleteChecklistItemFromSeries(completed.id, 's1')
      expect(result).toEqual({ removedFromTemplate: true, removedFromChecklists: ['cl-oct'], keptOnChecklists: [], keptReasons: [] })
      expect(await itemsOf(completed.id)).toEqual([])
      // The live copy's untouched same-label step is NOT a "later" copy.
      expect(await itemsOf(live.id)).toEqual(['s2', 's3'])
      expect(await itemsOf('cl-oct')).toEqual(['o2'])
    })

    it('started from the live copy, neither removes from nor reports the completed record', async () => {
      const { live, completed } = await splitPair()
      const result = await store.deleteChecklistItemFromSeries(live.id, 's3')
      expect(result).toEqual({ removedFromTemplate: true, removedFromChecklists: ['cl-oct'], keptOnChecklists: [], keptReasons: [] })
      expect(await itemsOf(live.id)).toEqual(['s2'])
      // The record's done copy stays, and is not reported as "kept because it carries work".
      expect(await itemsOf(completed.id)).toEqual(['s1'])
      expect(await itemsOf('cl-oct')).toEqual(['o2'])
    })
  })

  describe('a later copy that carries work is never removed', () => {
    const carrying = {
      'a done copy': step('c1', 'Reconcile', { done: true }),
      'a done sub-step': step('c1', 'Reconcile', { subItems: [{ id: 'u1', title: 'u', done: true }] }),
      'a done sub-sub-step': step('c1', 'Reconcile', {
        subItems: [{ id: 'u1', title: 'u', done: false, subItems: [{ id: 'v1', title: 'v', done: true }] }],
      }),
      'a live wait flag': step('c1', 'Reconcile', { waiting: true }),
      'a waiting note': step('c1', 'Reconcile', { waitingOn: 'bank statements' }),
      'a saved wait entry': step('c1', 'Reconcile', { waitingOns: [wait] }),
      'a verified wait entry': step('c1', 'Reconcile', {
        waitingOns: [{ ...wait, resolvedAt: '2026-09-02T00:00:00.000Z', verifiedAt: '2026-09-03T00:00:00.000Z' }],
      }),
      'a link to the task it waits on': step('c1', 'Reconcile', { waitingForChecklistId: 'cl-other' }),
      'a waiting sub-step': step('c1', 'Reconcile', { subItems: [{ id: 'u1', title: 'u', done: false, waiting: true }] }),
      'a sub-sub-step with a saved wait': step('c1', 'Reconcile', {
        subItems: [{ id: 'u1', title: 'u', done: false, subItems: [{ id: 'v1', title: 'v', done: false, waitingOns: [wait] }] }],
      }),
    }
    // Why each kept copy stays: only a SAVED wait that is still open is "an open wait".
    const openWaitCases = new Set(['a saved wait entry', 'a sub-sub-step with a saved wait'])
    for (const [name, copy] of Object.entries(carrying)) {
      it(`keeps ${name} and reports the checklist`, async () => {
        await seed([
          checklist('cl-sep', '2026-09-30', [step('s1', 'Reconcile')]),
          checklist('cl-oct', '2026-10-31', [copy, step('c2', 'Send report')]),
          checklist('cl-nov', '2026-11-30', [step('n1', 'Reconcile')]),
        ])
        const stored = async () => (await persisted()).checklists.find((entry) => entry.id === 'cl-oct').items[0]
        const before = await stored()
        const result = await store.deleteChecklistItemFromSeries('cl-sep', 's1')
        expect(result).toEqual({
          removedFromTemplate: true,
          removedFromChecklists: ['cl-nov'],
          keptOnChecklists: ['cl-oct'],
          keptReasons: [
            {
              checklistId: 'cl-oct',
              reason: openWaitCases.has(name) ? 'open_wait' : 'work_started',
              label: 'October 2026',
              occurrence: '2026-10-31',
            },
          ],
        })
        expect(await itemsOf('cl-oct')).toEqual(['c1', 'c2'])
        // The kept copy is exactly what it was.
        expect(await stored()).toEqual(before)
      })
    }
  })

